CREATE OR REPLACE FUNCTION public.aka_agent_list_message_opt_out_customers(p_staff_id bigint, p_organization_id bigint, p_auth_username text, p_auth_password text, p_search text DEFAULT ''::text, p_page integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '10s'
AS $function$
DECLARE
  v_search text := left(btrim(COALESCE(p_search, '')), 200);
  v_pattern text;
  v_page integer := greatest(1, least(COALESCE(p_page, 1), 1000000));
  v_total bigint;
  v_items jsonb;
BEGIN
  PERFORM public.auto_assert_automation_identity(p_staff_id, p_organization_id, p_auth_username, p_auth_password);
  IF NOT EXISTS (SELECT 1 FROM public.org_staff WHERE id = p_staff_id AND organization_id = p_organization_id
    AND is_active = true AND deleted_at IS NULL) THEN
    RAISE EXCEPTION 'Không có quyền truy cập danh sách.';
  END IF;
  v_pattern := '%' || replace(replace(replace(v_search, E'\\', E'\\\\'), '%', E'\\%'), '_', E'\\_') || '%';
  SELECT count(*) INTO v_total FROM public.auto_zalo_message_opt_outs o
  WHERE o.staff_id = p_staff_id AND o.organization_id = p_organization_id AND o.confirmed_at IS NOT NULL
    AND (v_search = '' OR o.zalo_name ILIKE v_pattern OR o.phone ILIKE v_pattern OR o.email ILIKE v_pattern
      OR o.zalo_global_id ILIKE v_pattern OR o.source_campaign_name ILIKE v_pattern);
  v_page := least(v_page, greatest(1, ceil(v_total::numeric / 50)::integer));
  SELECT COALESCE(jsonb_agg(x.item ORDER BY x.confirmed_at DESC, x.id DESC), '[]'::jsonb) INTO v_items
  FROM (
    SELECT o.id, o.confirmed_at, jsonb_build_object(
      'id', o.id, 'phone', o.phone, 'email', o.email, 'zaloGlobalId', o.zalo_global_id,
      'zaloName', o.zalo_name, 'zaloAvatar', o.zalo_avatar, 'confirmedAt', o.confirmed_at,
      'sourceCampaignId', o.source_campaign_id, 'sourceCampaignName', o.source_campaign_name,
      'sourceDetailId', o.source_detail_id, 'sourceSentAt', o.source_sent_at,
      'sourceActionName', o.source_action_name, 'sourceStatus', o.source_status
    ) AS item
    FROM public.auto_zalo_message_opt_outs o
    WHERE o.staff_id = p_staff_id AND o.organization_id = p_organization_id AND o.confirmed_at IS NOT NULL
      AND (v_search = '' OR o.zalo_name ILIKE v_pattern OR o.phone ILIKE v_pattern OR o.email ILIKE v_pattern
        OR o.zalo_global_id ILIKE v_pattern OR o.source_campaign_name ILIKE v_pattern)
    ORDER BY o.confirmed_at DESC, o.id DESC LIMIT 50 OFFSET (v_page - 1) * 50
  ) x;
  RETURN jsonb_build_object('items', v_items, 'total', v_total, 'page', v_page, 'pageSize', 50);
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_mark_email_click(p_click_token text, p_user_agent text DEFAULT NULL::text)
 RETURNS TABLE(ok boolean, message_tracking_id bigint, link_tracking_id bigint, original_url text, click_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_link public.auto_email_link_trackings%ROWTYPE;
  v_message public.auto_email_message_trackings%ROWTYPE;
  v_now timestamptz := now();
  v_user_agent text := NULLIF(left(COALESCE(p_user_agent, ''), 1000), '');
  v_raw_token text := trim(COALESCE(p_click_token, ''));
  v_click_token uuid;
BEGIN
  IF v_raw_token !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RETURN QUERY SELECT false, NULL::bigint, NULL::bigint, NULL::text, 0;
    RETURN;
  END IF;

  v_click_token := v_raw_token::uuid;

  SELECT *
  INTO v_link
  FROM public.auto_email_link_trackings
  WHERE click_token = v_click_token
    AND is_delete = false
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, NULL::bigint, NULL::bigint, NULL::text, 0;
    RETURN;
  END IF;

  SELECT *
  INTO v_message
  FROM public.auto_email_message_trackings
  WHERE id = v_link.message_tracking_id
    AND is_delete = false
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, NULL::bigint, v_link.id, NULL::text, 0;
    RETURN;
  END IF;

  UPDATE public.auto_email_link_trackings AS link_tracking
  SET click_count = link_tracking.click_count + 1,
      first_clicked_at = COALESCE(link_tracking.first_clicked_at, v_now),
      last_clicked_at = v_now,
      last_click_user_agent = v_user_agent,
      updated_at = v_now
  WHERE link_tracking.id = v_link.id
  RETURNING link_tracking.* INTO v_link;

  UPDATE public.auto_email_message_trackings AS message_tracking
  SET click_count = message_tracking.click_count + 1,
      first_clicked_at = COALESCE(message_tracking.first_clicked_at, v_now),
      last_clicked_at = v_now,
      first_opened_at = COALESCE(message_tracking.first_opened_at, v_now),
      last_opened_at = COALESCE(message_tracking.last_opened_at, v_now),
      open_count = GREATEST(message_tracking.open_count, 1),
      last_click_user_agent = v_user_agent,
      updated_at = v_now
  WHERE message_tracking.id = v_message.id
  RETURNING message_tracking.* INTO v_message;

  IF v_message.campaign_detail_id IS NOT NULL THEN
    -- Policy-managed results keep their original main result, log, quota and
    -- report group. A later real observation only changes the secondary ID.
    UPDATE public.auto_campaign_details d
    SET sub_status_id=s.id
    FROM public.auto_status s
    WHERE d.id=v_message.campaign_detail_id AND d.action_code='email_send'
      AND d.status_id IS NOT NULL AND d.policy_snapshot->>'operationState'='committed' AND NOT d.is_delete
      AND s.code='campaign_detail_clicked' AND s.component_type='campaign_detail'
      AND d.sub_status_id IS DISTINCT FROM s.id
      ;
    UPDATE public.auto_campaign_details
    SET status = 'đã click'
    WHERE id = v_message.campaign_detail_id
      AND action_code = 'email_send'
      AND status IN ('thành công', 'đã xem')
      AND status_id IS NULL
      AND is_delete = false;
  END IF;

  RETURN QUERY SELECT true, v_message.id, v_link.id, v_link.original_url, v_link.click_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_mark_email_open(p_open_token text, p_user_agent text DEFAULT NULL::text)
 RETURNS TABLE(ok boolean, message_tracking_id bigint, campaign_detail_id bigint, open_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_message public.auto_email_message_trackings%ROWTYPE;
  v_now timestamptz := now();
  v_user_agent text := NULLIF(left(COALESCE(p_user_agent, ''), 1000), '');
  v_raw_token text := trim(COALESCE(p_open_token, ''));
  v_open_token uuid;
BEGIN
  IF v_raw_token !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RETURN QUERY SELECT false, NULL::bigint, NULL::bigint, 0;
    RETURN;
  END IF;

  v_open_token := v_raw_token::uuid;

  SELECT *
  INTO v_message
  FROM public.auto_email_message_trackings
  WHERE open_token = v_open_token
    AND is_delete = false
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, NULL::bigint, NULL::bigint, 0;
    RETURN;
  END IF;

  UPDATE public.auto_email_message_trackings AS message_tracking
  SET open_count = message_tracking.open_count + 1,
      first_opened_at = COALESCE(message_tracking.first_opened_at, v_now),
      last_opened_at = v_now,
      last_open_user_agent = v_user_agent,
      updated_at = v_now
  WHERE message_tracking.id = v_message.id
  RETURNING message_tracking.* INTO v_message;

  IF v_message.campaign_detail_id IS NOT NULL THEN
    -- Policy-managed results keep their original main result, log, quota and
    -- report group. A later real observation only changes the secondary ID.
    UPDATE public.auto_campaign_details d
    SET sub_status_id=s.id
    FROM public.auto_status s
    WHERE d.id=v_message.campaign_detail_id AND d.action_code='email_send'
      AND d.status_id IS NOT NULL AND d.policy_snapshot->>'operationState'='committed' AND NOT d.is_delete
      AND s.code='campaign_detail_viewed' AND s.component_type='campaign_detail'
      AND d.sub_status_id IS DISTINCT FROM s.id
      AND NOT EXISTS (SELECT 1 FROM public.auto_status old WHERE old.id=d.sub_status_id AND old.code='campaign_detail_clicked');
    UPDATE public.auto_campaign_details
    SET status = 'đã xem'
    WHERE id = v_message.campaign_detail_id
      AND action_code = 'email_send'
      AND status = 'thành công'
      AND status_id IS NULL
      AND is_delete = false;
  END IF;

  RETURN QUERY SELECT true, v_message.id, v_message.campaign_detail_id, v_message.open_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_merge_sms_voice_device_info(p_account_id bigint, p_device_info jsonb, p_preserve_server_voice_state boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_current jsonb;
  v_current_voice jsonb;
  v_incoming jsonb := COALESCE(p_device_info, '{}'::jsonb);
  v_incoming_voice jsonb;
  v_merged jsonb;
BEGIN
  IF p_account_id IS NULL OR jsonb_typeof(v_incoming) <> 'object' THEN
    RAISE EXCEPTION 'invalid_device_info';
  END IF;

  SELECT COALESCE(account.mobile_device_info, '{}'::jsonb)
  INTO v_current
  FROM public.auto_accounts AS account
  WHERE account.id = p_account_id
    AND account.flatform_type = 'sms'
    AND COALESCE(account.is_delete, false) = false
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'sms_account_not_found';
  END IF;

  IF jsonb_typeof(v_current) <> 'object' THEN v_current := '{}'::jsonb; END IF;
  v_current_voice := CASE
    WHEN jsonb_typeof(v_current->'voiceCall') = 'object' THEN v_current->'voiceCall'
    ELSE '{}'::jsonb
  END;
  v_incoming_voice := CASE
    WHEN jsonb_typeof(v_incoming->'voiceCall') = 'object' THEN v_incoming->'voiceCall'
    ELSE '{}'::jsonb
  END;

  -- Once claim has evaluated the installed dialer/profile, generic app
  -- heartbeats must not replace that authoritative decision with their local
  -- fallback guess. A later claim passes preserve=false and can atomically
  -- replace these fields after re-evaluating the current device facts.
  IF COALESCE(p_preserve_server_voice_state, true)
    AND v_current_voice ? 'capabilityCheckedAt'
  THEN
    v_incoming_voice := v_incoming_voice
      - 'capabilityStatus'
      - 'status'
      - 'blockedReason'
      - 'profileKey'
      - 'profileVersion'
      - 'answerDetectionMode'
      - 'fallbackDelaySeconds'
      - 'capabilityCheckedAt';
  END IF;

  v_merged := (v_current || (v_incoming - 'voiceCall'))
    || jsonb_build_object('voiceCall', v_current_voice || v_incoming_voice);

  UPDATE public.auto_accounts
  SET
    mobile_device_info = v_merged,
    mobile_device_last_seen_at = now()
  WHERE id = p_account_id;

  RETURN v_merged;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_move_data_group_members(p_staff_id bigint, p_organization_id bigint, p_request_id text, p_group_id bigint, p_membership_ids bigint[], p_target_group_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_source_group public.auto_account_contact_groups%ROWTYPE;
  v_target_group public.auto_account_contact_groups%ROWTYPE;
  v_batch public.auto_data_ingest_batches%ROWTYPE;
  v_request_hash text;
  v_requested integer;
  v_count integer := 0;
  v_source_member record;
  v_target_member public.auto_account_contact_group_members%ROWTYPE;
  v_target_primary_before bigint;
  v_bound_source record;
  v_result jsonb;
BEGIN
  PERFORM public.aka_agent_internal_require_staff_tenant(p_staff_id, p_organization_id);
  IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
    OR p_group_id IS NOT DISTINCT FROM p_target_group_id
    OR COALESCE(cardinality(p_membership_ids), 0) = 0
    OR EXISTS (SELECT 1 FROM unnest(p_membership_ids) AS value(id) WHERE id IS NULL OR id <= 0)
  THEN RAISE EXCEPTION 'invalid_data_group_member_move'; END IF;
  SELECT count(DISTINCT id)::integer INTO v_requested FROM unnest(p_membership_ids) AS value(id);

  -- Stable lock order avoids inverse source/destination move deadlocks.
  PERFORM contact_group.id
  FROM public.auto_account_contact_groups AS contact_group
  WHERE contact_group.id IN (p_group_id, p_target_group_id)
  ORDER BY contact_group.id
  FOR UPDATE;

  SELECT * INTO v_source_group
  FROM public.auto_account_contact_groups AS contact_group
  WHERE contact_group.id = p_group_id AND contact_group.staff_id = p_staff_id
    AND contact_group.organization_id = p_organization_id
    AND contact_group.purpose = 'data_group' AND contact_group.is_delete = false;
  SELECT * INTO v_target_group
  FROM public.auto_account_contact_groups AS contact_group
  WHERE contact_group.id = p_target_group_id AND contact_group.staff_id = p_staff_id
    AND contact_group.organization_id = p_organization_id
    AND contact_group.purpose = 'data_group' AND contact_group.is_delete = false;
  IF v_source_group.id IS NULL OR v_target_group.id IS NULL THEN
    RAISE EXCEPTION 'data_group_not_found';
  END IF;

  IF v_target_group.data_type_category_item_id IS NOT NULL
    AND EXISTS (
      SELECT 1
      FROM public.auto_account_contact_group_members AS member
      WHERE member.group_id = v_source_group.id
        AND member.id = ANY(p_membership_ids)
        AND member.is_delete = false
        AND (
          NOT EXISTS (
            SELECT 1
            FROM public.auto_account_contact_group_member_origins AS origin
            WHERE origin.membership_id = member.id
              AND origin.is_current = true
          )
          OR EXISTS (
            SELECT 1
            FROM public.auto_account_contact_group_member_origins AS origin
            WHERE origin.membership_id = member.id
              AND origin.is_current = true
              AND origin.data_type_category_item_id IS DISTINCT FROM
                v_target_group.data_type_category_item_id
          )
        )
    )
  THEN
    RAISE EXCEPTION 'data_group_move_semantic_type_mismatch';
  END IF;

  v_request_hash := md5(jsonb_build_object(
    'operation', 'move_members', 'groupId', p_group_id,
    'targetGroupId', p_target_group_id,
    'membershipIds', (SELECT jsonb_agg(id ORDER BY id) FROM (
      SELECT DISTINCT id FROM unnest(p_membership_ids) AS value(id)
    ) AS sorted)
  )::text);
  INSERT INTO public.auto_data_ingest_batches (
    request_id, operation, group_id, target_group_id, kind, request_hash,
    status, staff_id, organization_id
  ) VALUES (
    btrim(p_request_id), 'move_members', p_group_id, p_target_group_id, 'manual',
    v_request_hash, 'processing', p_staff_id, p_organization_id
  ) ON CONFLICT (staff_id, organization_id, request_id) DO NOTHING
  RETURNING * INTO v_batch;
  IF NOT FOUND THEN
    SELECT * INTO v_batch FROM public.auto_data_ingest_batches
    WHERE staff_id = p_staff_id AND organization_id = p_organization_id
      AND request_id = btrim(p_request_id)
    FOR UPDATE;
    IF v_batch.operation <> 'move_members' OR v_batch.request_hash <> v_request_hash THEN
      RAISE EXCEPTION 'data_group_request_id_conflict';
    END IF;
    IF v_batch.result IS NOT NULL THEN RETURN v_batch.result; END IF;
    RAISE EXCEPTION 'data_group_request_incomplete';
  END IF;

  IF (
    SELECT count(DISTINCT member.id)
    FROM public.auto_account_contact_group_members AS member
    WHERE member.group_id = v_source_group.id AND member.id = ANY(p_membership_ids)
  ) <> v_requested THEN
    RAISE EXCEPTION 'data_group_membership_not_found';
  END IF;
  SELECT count(*)::integer INTO v_count
  FROM public.auto_account_contact_group_members AS member
  WHERE member.group_id = v_source_group.id AND member.id = ANY(p_membership_ids)
    AND member.is_delete = false;

  IF v_count > 0 THEN
    UPDATE public.auto_account_contact_groups
    SET revision = revision + 1, updated_at = now()
    WHERE id = v_target_group.id RETURNING * INTO v_target_group;
    UPDATE public.auto_account_contact_groups
    SET revision = revision + 1, updated_at = now()
    WHERE id = v_source_group.id RETURNING * INTO v_source_group;

    -- Activate destination memberships and provenance first.
    FOR v_source_member IN
      SELECT member.*
      FROM public.auto_account_contact_group_members AS member
      WHERE member.group_id = v_source_group.id
        AND member.id = ANY(p_membership_ids) AND member.is_delete = false
      ORDER BY member.id
    LOOP
      SELECT member.primary_origin_id
      INTO v_target_primary_before
      FROM public.auto_account_contact_group_members AS member
      WHERE member.group_id = v_target_group.id
        AND member.contact_id = v_source_member.contact_id
      FOR UPDATE;

      INSERT INTO public.auto_account_contact_group_members AS existing_member (
        group_id, contact_id, is_delete, change_revision, created_at, updated_at
      ) VALUES (
        v_target_group.id, v_source_member.contact_id, false,
        v_target_group.revision, now(), now()
      )
      ON CONFLICT (group_id, contact_id) DO UPDATE SET
        is_delete = false,
        change_revision = EXCLUDED.change_revision,
        updated_at = now()
      RETURNING * INTO v_target_member;

      INSERT INTO public.auto_account_contact_group_member_origins (
        membership_id, kind, dataset_id, batch_id, source_account_id, automation_detail_id,
        source_name_snapshot, relationship_kind, data_type_category_item_id, is_current, created_at, updated_at
      )
      SELECT
        v_target_member.id, origin.kind, origin.dataset_id, origin.batch_id,
        origin.source_account_id, origin.automation_detail_id,
        origin.source_name_snapshot, origin.relationship_kind, origin.data_type_category_item_id, true, now(), now()
      FROM public.auto_account_contact_group_member_origins AS origin
      WHERE origin.membership_id = v_source_member.id AND origin.is_current = true
      ON CONFLICT DO NOTHING;

      PERFORM public.aka_agent_sync_copied_data_group_origins(
        v_source_member.id,
        v_target_member.id,
        v_target_primary_before IS NULL
      );

      INSERT INTO public.auto_account_contact_group_member_origins (
        membership_id, kind, batch_id, source_name_snapshot, is_current,
        data_type_category_item_id
      ) VALUES (
        v_target_member.id, 'manual', v_batch.id,
        'move:' || v_source_group.name, true,
        (
          SELECT min(origin.data_type_category_item_id)
          FROM public.auto_account_contact_group_member_origins AS origin
          WHERE origin.membership_id = v_source_member.id
            AND origin.is_current = true
          HAVING count(*) > 0
            AND count(origin.data_type_category_item_id) = count(*)
            AND count(DISTINCT origin.data_type_category_item_id) = 1
        )
      ) ON CONFLICT DO NOTHING;

      FOR v_bound_source IN
        SELECT source.id FROM public.auto_campaign_data_group_sources AS source
        WHERE source.group_id = v_target_group.id AND source.status IN ('baselining', 'active')
        ORDER BY source.campaign_id
      LOOP
        PERFORM public.aka_agent_internal_route_data_group_member(
          v_bound_source.id, v_target_member.id, v_batch.id, v_target_group.revision
        );
      END LOOP;
    END LOOP;

    -- Source is soft-deleted only after all destination activations/fanout.
    UPDATE public.auto_account_contact_group_members
    SET is_delete = true, change_revision = v_source_group.revision, updated_at = now()
    WHERE group_id = v_source_group.id AND id = ANY(p_membership_ids) AND is_delete = false;
    UPDATE public.auto_account_contact_group_member_origins AS origin
    SET is_current = false, updated_at = now()
    FROM public.auto_account_contact_group_members AS member
    WHERE member.group_id = v_source_group.id AND member.id = ANY(p_membership_ids)
      AND origin.membership_id = member.id AND origin.is_current = true;
  END IF;

  v_result := jsonb_build_object(
    'success', true, 'count', v_count, 'group_revision', v_source_group.revision,
    'target_group_revision', v_target_group.revision
  );
  UPDATE public.auto_data_ingest_batches
  SET status = 'completed', result = v_result, updated_at = now()
  WHERE id = v_batch.id;
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_preflight_campaign_data_group_change(p_staff_id bigint, p_organization_id bigint, p_campaign_id bigint, p_group_id bigint, p_auth_username text, p_auth_password text)
 RETURNS TABLE(allowed boolean, reason text, canonical_count bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_previous_target text := current_setting(
    'aka_agent.zalo_runtime_target', true
  );
  v_runtime_target text := 'desktop';
BEGIN
  PERFORM public.auto_assert_automation_identity(
    p_staff_id, p_organization_id, p_auth_username, p_auth_password
  );

  SELECT CASE
    WHEN lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
      AND COALESCE(account.is_zalo_show_web, false) = false
      AND COALESCE(account.is_zalo_server, false) = true
    THEN 'server'
    ELSE 'desktop'
  END
  INTO v_runtime_target
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id
   AND account.staff_id = campaign.staff_id
  WHERE campaign.id = p_campaign_id
    AND campaign.staff_id = p_staff_id
    AND campaign.organization_id = p_organization_id
    AND COALESCE(campaign.is_delete, false) = false
    AND (account.organization_id IS NULL
      OR account.organization_id = p_organization_id)
    AND COALESCE(account.is_delete, false) = false;

  v_runtime_target := COALESCE(v_runtime_target, 'desktop');
  PERFORM set_config(
    'aka_agent.zalo_runtime_target', v_runtime_target, true
  );
  BEGIN
    RETURN QUERY
    SELECT *
    FROM public.aka_agent_preflight_campaign_data_group_change(
      p_staff_id, p_organization_id, p_campaign_id, p_group_id
    );
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config(
      'aka_agent.zalo_runtime_target', COALESCE(v_previous_target, ''), true
    );
    RAISE;
  END;
  PERFORM set_config(
    'aka_agent.zalo_runtime_target', COALESCE(v_previous_target, ''), true
  );
  RETURN;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_preflight_campaign_data_group_change(p_staff_id bigint, p_organization_id bigint, p_campaign_id bigint, p_group_id bigint)
 RETURNS TABLE(allowed boolean, reason text, canonical_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_campaign public.auto_campaigns%ROWTYPE;
  v_source public.auto_campaign_data_group_sources%ROWTYPE;
  v_runtime_target text := CASE
    WHEN NULLIF(btrim(COALESCE(
      current_setting('aka_agent.zalo_runtime_target', true), ''
    )), '') = 'desktop' THEN 'desktop'
    ELSE 'server'
  END;
BEGIN
  PERFORM public.aka_agent_internal_require_staff_tenant(
    p_staff_id, p_organization_id
  );
  canonical_count := 0;

  SELECT campaign.* INTO v_campaign
  FROM public.auto_campaigns AS campaign
  WHERE campaign.id = p_campaign_id
    AND campaign.staff_id = p_staff_id
    AND campaign.organization_id = p_organization_id;
  IF NOT FOUND OR COALESCE(v_campaign.is_delete, false) THEN
    allowed := false;
    reason := 'data_group_campaign_not_found';
    RETURN NEXT;
    RETURN;
  END IF;

  -- Ownership precedes every early-return branch, including `unchanged`, so a
  -- service caller cannot reuse a source after its Zalo account becomes local.
  IF NOT EXISTS (
    SELECT 1
    FROM public.auto_accounts AS account
    WHERE account.id = v_campaign.account_id
      AND account.staff_id = p_staff_id
      AND (account.organization_id IS NULL OR account.organization_id = p_organization_id)
      AND COALESCE(account.is_delete, false) = false
      AND (
        COALESCE(account.flatform_type, '') <> 'zalo'
        OR (
          account.organization_id = p_organization_id
          AND (
            (
              v_runtime_target = 'desktop'
              AND COALESCE(account.is_zalo_server, false) = false
            )
            OR (
              v_runtime_target = 'server'
              AND COALESCE(account.is_zalo_show_web, false) = false
              AND COALESCE(account.is_zalo_server, false) = true
              AND COALESCE(account.is_active, true) = true
            )
          )
        )
      )
  ) THEN
    allowed := false;
    reason := 'data_group_campaign_account_not_found';
    RETURN NEXT;
    RETURN;
  END IF;

  SELECT count(*)::bigint INTO canonical_count
  FROM public.auto_campaign_input_data AS input_row
  WHERE input_row.campaign_id = v_campaign.id
    AND input_row.canonical_target_key IS NOT NULL
    AND COALESCE(input_row.is_delete, false) = false;

  IF p_group_id IS NULL OR p_group_id <= 0 OR NOT EXISTS (
    SELECT 1
    FROM public.auto_account_contact_groups AS contact_group
    WHERE contact_group.id = p_group_id
      AND private.can_read_data_group(contact_group.id,p_staff_id,p_organization_id)
      AND contact_group.organization_id = p_organization_id
      AND contact_group.purpose = 'data_group'
      AND contact_group.is_delete = false
  ) THEN
    allowed := false;
    reason := 'data_group_not_found';
    RETURN NEXT;
    RETURN;
  END IF;

  IF v_campaign.data_target_source_mode = 'data_group'
    AND v_campaign.data_group_id IS NOT DISTINCT FROM p_group_id
  THEN
    allowed := true;
    reason := 'unchanged';
    RETURN NEXT;
    RETURN;
  END IF;

  IF v_campaign.status IN ('đang chạy', 'hoàn thành')
    OR (v_campaign.schedule_end_date IS NOT NULL
      AND v_campaign.schedule_end_date <= now())
  THEN
    allowed := false;
    reason := 'data_group_campaign_not_bindable';
    RETURN NEXT;
    RETURN;
  END IF;
  IF v_campaign.action_id NOT IN (
    'facebook_group_post', 'facebook_join_group', 'facebook_message_uid',
    'facebook_find_data_group', 'facebook_find_data_search',
    'facebook_comment_seeding', 'facebook_comment_seeding_post',
    'zalo_message_phone', 'zalo_join_group_link', 'email_send',
    'facebook_message_friend', 'facebook_group_invite', 'facebook_page_post',
    'zalo_message_friend', 'zalo_message_group_member',
    'zalo_message_remarketing_customer', 'zalo_message_group',
    'zalo_add_group_member'
  ) THEN
    allowed := false;
    reason := 'data_group_campaign_action_incompatible';
    RETURN NEXT;
    RETURN;
  END IF;
  IF canonical_count > 0 THEN
    allowed := false;
    reason := 'campaign_data_group_source_immutable_after_intake';
    RETURN NEXT;
    RETURN;
  END IF;

  SELECT source.* INTO v_source
  FROM public.auto_campaign_data_group_sources AS source
  WHERE source.campaign_id = v_campaign.id
    AND source.staff_id = p_staff_id
    AND source.organization_id = p_organization_id;
  IF FOUND AND v_source.bundle_id IS NOT NULL THEN
    allowed := false;
    reason := 'campaign_data_group_source_immutable';
    RETURN NEXT;
    RETURN;
  END IF;

  allowed := true;
  reason := 'allowed';
  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_prepare_automation_detail_schedule()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_rule public.auto_automation%ROWTYPE;
  v_event_at timestamptz := COALESCE(NEW.created_at, clock_timestamp());
  v_delay_floor timestamptz;
  v_local_event timestamp without time zone;
  v_local_floor timestamp without time zone;
  v_local_schedule timestamp without time zone;
  v_schedule_policy text;
BEGIN
  SELECT *
  INTO v_rule
  FROM public.auto_automation AS automation
  WHERE automation.id = NEW.automation_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'automation_not_found';
  END IF;

  CASE v_rule.schedule_mode
    WHEN 'immediate' THEN
      NEW.scheduled_at := v_event_at;
      v_schedule_policy := 'immediate';
    WHEN 'after_delay' THEN
      v_delay_floor := CASE v_rule.delay_unit
        WHEN 'minute' THEN v_event_at + make_interval(mins => v_rule.delay_value)
        WHEN 'hour' THEN v_event_at + make_interval(hours => v_rule.delay_value)
        WHEN 'day' THEN v_event_at + make_interval(days => v_rule.delay_value)
        ELSE NULL
      END;

      IF v_delay_floor IS NULL THEN
        RAISE EXCEPTION 'invalid_delay_schedule';
      END IF;

      IF v_rule.delay_exact_time IS NULL THEN
        NEW.scheduled_at := v_delay_floor;
        v_schedule_policy := 'after_delay';
      ELSE
        v_local_floor := v_delay_floor AT TIME ZONE 'Asia/Ho_Chi_Minh';
        v_local_schedule := v_local_floor::date + v_rule.delay_exact_time;

        -- Equality remains on the same date. A strictly earlier candidate is
        -- moved to the following date so the full delay is never shortened.
        IF v_local_schedule < v_local_floor THEN
          v_local_schedule := v_local_schedule + interval '1 day';
        END IF;

        NEW.scheduled_at := v_local_schedule AT TIME ZONE 'Asia/Ho_Chi_Minh';
        v_schedule_policy := 'first_wall_clock_at_or_after_delay_v1';
      END IF;
    WHEN 'daily_time' THEN
      v_local_event := v_event_at AT TIME ZONE 'Asia/Ho_Chi_Minh';
      v_local_schedule := v_local_event::date + v_rule.daily_time;

      IF v_local_event > v_local_schedule THEN
        v_local_schedule := v_local_schedule + interval '1 day';
      END IF;

      NEW.scheduled_at := v_local_schedule AT TIME ZONE 'Asia/Ho_Chi_Minh';
      v_schedule_policy := 'nearest_daily_time_v1';
    WHEN 'fixed_at' THEN
      NEW.scheduled_at := v_rule.fixed_at;
      v_schedule_policy := 'fixed_at_legacy';
    ELSE
      RAISE EXCEPTION 'invalid_automation_schedule';
  END CASE;

  -- The worker still claims immediately; the target input schedule gates B.
  NEW.next_attempt_at := v_event_at;

  NEW.config_snapshot := COALESCE(NEW.config_snapshot, '{}'::jsonb)
    || jsonb_build_object(
      'schedule_mode', v_rule.schedule_mode,
      'delay_days', v_rule.delay_days,
      'delay_hours', v_rule.delay_hours,
      'delay_value', v_rule.delay_value,
      'delay_unit', v_rule.delay_unit,
      'delay_exact_time', v_rule.delay_exact_time,
      'delay_floor_at', v_delay_floor,
      'daily_time', v_rule.daily_time,
      'fixed_at', v_rule.fixed_at,
      'schedule_policy', v_schedule_policy,
      'schedule_time_zone', 'Asia/Ho_Chi_Minh',
      'scheduled_at', NEW.scheduled_at
    );

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_prepare_device_change(p_username text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE s public.org_staff%ROWTYPE;
BEGIN
  SELECT * INTO s FROM public.org_staff WHERE username = btrim(p_username);
  IF NOT FOUND THEN RETURN jsonb_build_object('code', 'not_found'); END IF;
  IF NOT s.is_active THEN RETURN jsonb_build_object('code', 'inactive'); END IF;
  RETURN jsonb_build_object('code', 'prepared', 'binding', jsonb_build_object(
    'staffId', s.id::text, 'hash', s.device_fingerprint_hash, 'boundAt', s.device_bound_at));
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_prepare_device_change_v2(p_username text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE s public.org_staff%ROWTYPE; revision text;
BEGIN
  SELECT * INTO s FROM public.org_staff WHERE username = btrim(p_username) FOR SHARE;
  IF NOT FOUND THEN RETURN jsonb_build_object('code', 'not_found'); END IF;
  IF NOT s.is_active THEN RETURN jsonb_build_object('code', 'inactive'); END IF;
  SELECT xmin::text INTO revision FROM public.org_staff WHERE id=s.id;
  RETURN jsonb_build_object('code', 'prepared', 'binding', jsonb_build_object(
    'staffId', s.id::text, 'hash', s.aka_agent_device_fingerprint_hash, 'revision', revision, 'version', 2));
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_process_data_group_dynamic_filters(p_staff_id bigint, p_organization_id bigint, p_limit integer, p_auth_username text, p_auth_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
BEGIN
  PERFORM public.auto_assert_automation_identity(
    p_staff_id, p_organization_id, p_auth_username, p_auth_password
  );

  RETURN public.aka_agent_process_data_group_dynamic_filters_core(
    p_staff_id, p_organization_id, p_limit
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_process_data_group_dynamic_filters_core(p_staff_id bigint, p_organization_id bigint, p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_limit integer := LEAST(500, GREATEST(1, COALESCE(p_limit, 200)));
  v_queue record;
  v_filter record;
  v_group public.auto_account_contact_groups%ROWTYPE;
  v_member_id bigint;
  v_origin_current boolean;
  v_was_member boolean;
  v_enter boolean;
  v_leave boolean;
  v_should_be_member boolean;
  v_processed integer := 0;
  v_pairs integer := 0;
  v_entered integer := 0;
  v_exited integer := 0;
  v_remaining bigint := 0;
  v_touched_filter_ids bigint[] := ARRAY[]::bigint[];
  v_changed_group_ids bigint[] := ARRAY[]::bigint[];
BEGIN
  IF NOT pg_catalog.pg_try_advisory_xact_lock(
    pg_catalog.hashtextextended('data-group-dynamic-filter:' || p_staff_id::text, 0)
  ) THEN
    RETURN jsonb_build_object(
      'processed_contact_count', 0,
      'evaluated_pair_count', 0,
      'entered_count', 0,
      'exited_count', 0,
      'remaining_queue_count', (
        SELECT count(*) FROM public.auto_account_contact_dynamic_filter_queue AS queue
        WHERE queue.staff_id = p_staff_id AND queue.organization_id = p_organization_id
      ),
      'busy', true
    );
  END IF;

  FOR v_queue IN
    SELECT queue.contact_id, queue.last_event_at
    FROM public.auto_account_contact_dynamic_filter_queue AS queue
    WHERE queue.staff_id = p_staff_id
      AND queue.organization_id = p_organization_id
      AND queue.queued_at <= clock_timestamp()
    ORDER BY queue.queued_at, queue.contact_id
    FOR UPDATE SKIP LOCKED
    LIMIT v_limit
  LOOP
    BEGIN
      FOR v_filter IN
        SELECT dynamic_filter.id, dynamic_filter.group_id
        FROM public.auto_account_contact_group_dynamic_filters AS dynamic_filter
        JOIN public.auto_account_contact_groups AS contact_group
          ON contact_group.id = dynamic_filter.group_id
         AND contact_group.staff_id = p_staff_id
         AND contact_group.organization_id = p_organization_id
         AND contact_group.purpose = 'data_group'
         AND contact_group.is_delete = false
        JOIN public.category_item AS data_type
          ON data_type.id = contact_group.data_type_category_item_id
         AND data_type.code = 'zalo_person'
        WHERE dynamic_filter.staff_id = p_staff_id
          AND dynamic_filter.organization_id = p_organization_id
          AND dynamic_filter.is_enabled = true
          AND dynamic_filter.effective_from_at <= v_queue.last_event_at
          AND EXISTS (
            SELECT 1
            FROM public.auto_account_contact_group_dynamic_filter_rules AS rule
            JOIN public.category_item AS scope_item ON scope_item.id = rule.scope_category_item_id
            WHERE rule.dynamic_filter_id = dynamic_filter.id
              AND scope_item.code = 'enter'
          )
        ORDER BY dynamic_filter.id
      LOOP
        v_member_id := NULL;
        v_origin_current := false;
        v_was_member := false;
        v_pairs := v_pairs + 1;
        IF NOT v_filter.id = ANY (v_touched_filter_ids) THEN
          v_touched_filter_ids := pg_catalog.array_append(v_touched_filter_ids, v_filter.id);
          UPDATE public.auto_account_contact_group_dynamic_filters
          SET last_entered_count = 0, last_exited_count = 0
          WHERE id = v_filter.id;
        END IF;

        SELECT contact_group.* INTO v_group
        FROM public.auto_account_contact_groups AS contact_group
        WHERE contact_group.id = v_filter.group_id
        FOR UPDATE;

        IF v_group.bound_zalo_account_id IS NOT NULL AND (
          NOT public.aka_agent_data_group_account_available(v_group.bound_zalo_account_id,p_staff_id,p_organization_id)
          OR NOT EXISTS(SELECT 1 FROM public.auto_account_contacts WHERE id=v_queue.contact_id AND account_id=v_group.bound_zalo_account_id)
        ) THEN CONTINUE; END IF;
        IF EXISTS (
          SELECT 1 FROM public.auto_account_contacts AS contact
          WHERE contact.id = v_queue.contact_id
            AND contact.staff_id = p_staff_id
            AND contact.organization_id = p_organization_id
            AND contact.flatform_type = 'zalo'
            AND contact.contact_type = 'person'
            AND contact.is_delete = false
        ) THEN
          v_enter := public.aka_agent_data_group_dynamic_scope_matches(
            v_filter.id, v_queue.contact_id, 'enter'
          );
          v_leave := public.aka_agent_data_group_dynamic_scope_matches(
            v_filter.id, v_queue.contact_id, 'leave'
          );
          v_should_be_member := v_enter AND NOT v_leave;
        ELSE
          v_should_be_member := false;
        END IF;

        SELECT member.id, member.is_delete = false
        INTO v_member_id, v_was_member
        FROM public.auto_account_contact_group_members AS member
        WHERE member.group_id = v_filter.group_id
          AND member.contact_id = v_queue.contact_id
        FOR UPDATE;

        SELECT origin.is_current INTO v_origin_current
        FROM public.auto_account_contact_group_member_origins AS origin
        WHERE origin.membership_id = v_member_id
          AND origin.dynamic_filter_id = v_filter.id;

        IF v_should_be_member THEN
          INSERT INTO public.auto_account_contact_group_members (
            group_id, contact_id, is_delete, change_revision, updated_at
          ) VALUES (
            v_filter.group_id, v_queue.contact_id, false, v_group.revision + 1, clock_timestamp()
          )
          ON CONFLICT (group_id, contact_id) DO UPDATE SET
            is_delete = false,
            change_revision = v_group.revision + 1,
            updated_at = clock_timestamp()
          RETURNING id INTO v_member_id;

          INSERT INTO public.auto_account_contact_group_member_origins (
            membership_id, kind, dynamic_filter_id, source_account_id,
            source_name_snapshot, is_current, data_type_category_item_id, updated_at
          )
          SELECT
            v_member_id, 'dynamic_filter', v_filter.id, contact.account_id::bigint,
            'Bộ lọc động', true, v_group.data_type_category_item_id, clock_timestamp()
          FROM public.auto_account_contacts AS contact
          WHERE contact.id = v_queue.contact_id
          ON CONFLICT (membership_id, dynamic_filter_id)
            WHERE dynamic_filter_id IS NOT NULL
          DO UPDATE SET
            source_account_id = EXCLUDED.source_account_id,
            source_name_snapshot = EXCLUDED.source_name_snapshot,
            is_current = true,
            data_type_category_item_id = EXCLUDED.data_type_category_item_id,
            updated_at = clock_timestamp();

          IF NOT COALESCE(v_origin_current, false) THEN
            UPDATE public.auto_account_contact_group_dynamic_filters
            SET matched_count = matched_count + 1
            WHERE id = v_filter.id;
          END IF;

          IF NOT COALESCE(v_was_member, false) THEN
            v_entered := v_entered + 1;
            v_changed_group_ids := pg_catalog.array_append(v_changed_group_ids, v_filter.group_id);
            UPDATE public.auto_account_contact_group_dynamic_filters
            SET last_entered_count = last_entered_count + 1
            WHERE id = v_filter.id;
          END IF;
        ELSE
          IF COALESCE(v_origin_current, false) THEN
            UPDATE public.auto_account_contact_group_member_origins
            SET is_current = false, updated_at = clock_timestamp()
            WHERE membership_id = v_member_id
              AND dynamic_filter_id = v_filter.id
              AND is_current = true;

            UPDATE public.auto_account_contact_group_dynamic_filters
            SET matched_count = GREATEST(0, matched_count - 1)
            WHERE id = v_filter.id;

            IF COALESCE(v_was_member, false) AND NOT EXISTS (
              SELECT 1
              FROM public.auto_account_contact_group_member_origins AS origin
              WHERE origin.membership_id = v_member_id
                AND origin.is_current = true
            ) THEN
              UPDATE public.auto_account_contact_group_members
              SET is_delete = true,
                  primary_origin_id = NULL,
                  change_revision = v_group.revision + 1,
                  updated_at = clock_timestamp()
              WHERE id = v_member_id;
              v_exited := v_exited + 1;
              v_changed_group_ids := pg_catalog.array_append(v_changed_group_ids, v_filter.group_id);
              UPDATE public.auto_account_contact_group_dynamic_filters
              SET last_exited_count = last_exited_count + 1
              WHERE id = v_filter.id;
            END IF;
          END IF;
        END IF;
      END LOOP;

      DELETE FROM public.auto_account_contact_dynamic_filter_queue
      WHERE contact_id = v_queue.contact_id;
      v_processed := v_processed + 1;
    EXCEPTION WHEN OTHERS THEN
      UPDATE public.auto_account_contact_dynamic_filter_queue
      SET attempt_count = attempt_count + 1,
          last_error = left(SQLERRM, 1000),
          queued_at = clock_timestamp() + make_interval(
            secs => CASE
              WHEN attempt_count >= 8 THEN 3600
              ELSE 5 * (attempt_count + 1) * (attempt_count + 1)
            END
          )
      WHERE contact_id = v_queue.contact_id;
    END;
  END LOOP;

  IF pg_catalog.array_length(v_changed_group_ids, 1) IS NOT NULL THEN
    UPDATE public.auto_account_contact_groups AS contact_group
    SET revision = contact_group.revision + 1,
        updated_at = clock_timestamp()
    WHERE contact_group.id = ANY (v_changed_group_ids);
  END IF;

  IF pg_catalog.array_length(v_touched_filter_ids, 1) IS NOT NULL THEN
    UPDATE public.auto_account_contact_group_dynamic_filters AS dynamic_filter
    SET last_evaluated_at = clock_timestamp(),
        next_evaluation_at = NULL,
        updated_at = clock_timestamp()
    WHERE dynamic_filter.id = ANY (v_touched_filter_ids);
  END IF;

  SELECT count(*)::bigint INTO v_remaining
  FROM public.auto_account_contact_dynamic_filter_queue AS queue
  WHERE queue.staff_id = p_staff_id
    AND queue.organization_id = p_organization_id
    AND queue.queued_at <= clock_timestamp();

  RETURN jsonb_build_object(
    'processed_contact_count', v_processed,
    'evaluated_pair_count', v_pairs,
    'entered_count', v_entered,
    'exited_count', v_exited,
    'remaining_queue_count', v_remaining,
    'busy', false
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_propagate_campaign_origin_semantic_type()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_category_item_id bigint;
  v_existing_category_item_id bigint;
  v_action_id text;
  v_input_has_valid_phone boolean := false;
BEGIN
  IF NEW.group_id IS NOT NULL THEN
    SELECT
      campaign.action_id,
      NULLIF(public.aka_agent_internal_normalize_phone(COALESCE(
        input_data.phone, ''
      )), '') IS NOT NULL
    INTO v_action_id, v_input_has_valid_phone
    FROM public.auto_campaign_input_data AS input_data
    JOIN public.auto_campaigns AS campaign
      ON campaign.id = input_data.campaign_id
    WHERE input_data.id = NEW.input_data_id;

    IF v_action_id IS NULL
      OR NOT public.aka_agent_data_group_type_compatible(
        NEW.group_id, v_action_id
      )
    THEN
      RAISE EXCEPTION 'data_group_campaign_semantic_type_incompatible';
    END IF;

    IF v_action_id IN ('zalo_message_phone', 'zalo_add_group_member')
      AND v_input_has_valid_phone
    THEN
      -- v228: the materialized phone determines semantic identity. Never copy
      -- an unrelated source group's/contact's semantic type onto this input.
      v_category_item_id :=
        public.aka_agent_data_type_category_item_id('phone');
    ELSE
      SELECT contact_group.data_type_category_item_id
      INTO v_category_item_id
      FROM public.auto_account_contact_groups AS contact_group
      WHERE contact_group.id = NEW.group_id;
    END IF;
  END IF;

  IF v_category_item_id IS NULL AND NEW.membership_id IS NOT NULL THEN
    v_category_item_id :=
      public.aka_agent_membership_semantic_type(NEW.membership_id);
  END IF;

  IF v_category_item_id IS NULL
    AND NEW.automation_detail_id IS NOT NULL
  THEN
    SELECT detail.data_type_category_item_id
    INTO v_category_item_id
    FROM public.auto_automation_detail AS detail
    WHERE detail.id = NEW.automation_detail_id;
  END IF;

  IF v_category_item_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT input_data.data_type_category_item_id
  INTO v_existing_category_item_id
  FROM public.auto_campaign_input_data AS input_data
  WHERE input_data.id = NEW.input_data_id
  FOR UPDATE;

  IF v_existing_category_item_id IS NULL THEN
    UPDATE public.auto_campaign_input_data
    SET data_type_category_item_id = v_category_item_id
    WHERE id = NEW.input_data_id
      AND data_type_category_item_id IS NULL;
  ELSIF v_existing_category_item_id IS DISTINCT FROM v_category_item_id THEN
    RAISE EXCEPTION 'campaign_input_semantic_type_conflict';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_reactivate_campaign_data_group_source(p_staff_id bigint, p_organization_id bigint, p_campaign_id bigint, p_request_id text, p_reason text, p_auth_username text, p_auth_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_previous_target text := current_setting(
    'aka_agent.zalo_runtime_target', true
  );
  v_runtime_target text := 'desktop';
  v_result jsonb;
BEGIN
  PERFORM public.auto_assert_automation_identity(
    p_staff_id, p_organization_id, p_auth_username, p_auth_password
  );

  SELECT CASE
    WHEN lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
      AND COALESCE(account.is_zalo_show_web, false) = false
      AND COALESCE(account.is_zalo_server, false) = true
    THEN 'server'
    ELSE 'desktop'
  END
  INTO v_runtime_target
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id
   AND account.staff_id = campaign.staff_id
  WHERE campaign.id = p_campaign_id
    AND campaign.staff_id = p_staff_id
    AND campaign.organization_id = p_organization_id
    AND COALESCE(campaign.is_delete, false) = false
    AND (account.organization_id IS NULL
      OR account.organization_id = p_organization_id)
    AND COALESCE(account.is_delete, false) = false;

  v_runtime_target := COALESCE(v_runtime_target, 'desktop');
  PERFORM set_config(
    'aka_agent.zalo_runtime_target', v_runtime_target, true
  );
  BEGIN
    v_result := public.aka_agent_reactivate_campaign_data_group_source(
      p_staff_id, p_organization_id, p_campaign_id, p_request_id, p_reason
    );
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config(
      'aka_agent.zalo_runtime_target', COALESCE(v_previous_target, ''), true
    );
    RAISE;
  END;
  PERFORM set_config(
    'aka_agent.zalo_runtime_target', COALESCE(v_previous_target, ''), true
  );
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_reactivate_campaign_data_group_source(p_staff_id bigint, p_organization_id bigint, p_campaign_id bigint, p_request_id text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_source public.auto_campaign_data_group_sources%ROWTYPE;
  v_campaign public.auto_campaigns%ROWTYPE;
  v_group public.auto_account_contact_groups%ROWTYPE;
  v_batch public.auto_data_ingest_batches%ROWTYPE;
  v_hash text;
  v_runtime_target text := CASE
    WHEN NULLIF(btrim(COALESCE(
      current_setting('aka_agent.zalo_runtime_target', true), ''
    )), '') = 'desktop' THEN 'desktop'
    ELSE 'server'
  END;
BEGIN
  PERFORM public.aka_agent_internal_require_staff_tenant(p_staff_id, p_organization_id);
  IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL THEN
    RAISE EXCEPTION 'invalid_data_group_source_request';
  END IF;

  SELECT * INTO v_source
  FROM public.auto_campaign_data_group_sources AS source
  WHERE source.campaign_id = p_campaign_id AND source.staff_id = p_staff_id
    AND source.organization_id = p_organization_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'campaign_data_group_source_not_found'; END IF;
  SELECT * INTO v_group
  FROM public.auto_account_contact_groups AS contact_group
  WHERE contact_group.id = v_source.group_id AND private.can_read_data_group(contact_group.id,p_staff_id,p_organization_id)
    AND contact_group.organization_id = p_organization_id
    AND contact_group.purpose = 'data_group' AND contact_group.is_delete = false
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data_group_not_found'; END IF;

  -- Reactivation routes the existing group snapshot after locking campaign and
  -- source rows. Join the common campaign/input barrier before either of those
  -- row locks so the nested legacy router can re-enter it without inversion.
  PERFORM public.aka_agent_lock_campaign_input_serialization(p_campaign_id);

  SELECT campaign.* INTO v_campaign
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account ON account.id = campaign.account_id
  WHERE campaign.id = p_campaign_id AND campaign.staff_id = p_staff_id
    AND campaign.organization_id = p_organization_id
    AND account.staff_id = p_staff_id
    AND (account.organization_id IS NULL OR account.organization_id = p_organization_id)
    AND COALESCE(account.is_delete, false) = false
      AND (
        COALESCE(account.flatform_type, '') <> 'zalo'
        OR (
          account.organization_id = p_organization_id
          AND (
            (
              v_runtime_target = 'desktop'
              AND COALESCE(account.is_zalo_server, false) = false
            )
            OR (
              v_runtime_target = 'server'
              AND COALESCE(account.is_zalo_show_web, false) = false
              AND COALESCE(account.is_zalo_server, false) = true
              AND COALESCE(account.is_active, true) = true
            )
          )
        )
      )
  FOR UPDATE OF campaign, account;
  IF NOT FOUND OR COALESCE(v_campaign.is_delete, false)
    OR v_campaign.data_group_id IS DISTINCT FROM v_source.group_id
    OR v_campaign.data_target_source_mode <> 'data_group'
    OR (v_campaign.schedule_end_date IS NOT NULL AND v_campaign.schedule_end_date <= now()) THEN
    RAISE EXCEPTION 'data_group_campaign_terminal';
  END IF;
  -- Re-lock in the shared group -> campaign -> source order used by bind and
  -- intake, then verify the optimistic source read did not change underneath.
  SELECT * INTO v_source
  FROM public.auto_campaign_data_group_sources AS source
  WHERE source.id = v_source.id
    AND source.campaign_id = p_campaign_id
    AND source.group_id = v_group.id
    AND source.staff_id = p_staff_id
    AND source.organization_id = p_organization_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'campaign_data_group_source_changed'; END IF;
  IF v_source.status <> 'stopped' THEN RETURN to_jsonb(v_source); END IF;

  v_hash := md5(jsonb_build_object(
    'operation', 'reactivate_source', 'campaignId', p_campaign_id,
    'groupId', v_source.group_id
  )::text);
  INSERT INTO public.auto_data_ingest_batches (
    request_id, operation, group_id, request_hash, status, staff_id, organization_id
  ) VALUES (
    btrim(p_request_id), 'reactivate_source', v_source.group_id, v_hash,
    'processing', p_staff_id, p_organization_id
  ) ON CONFLICT (staff_id, organization_id, request_id) DO NOTHING
  RETURNING * INTO v_batch;
  IF NOT FOUND THEN
    SELECT * INTO v_batch FROM public.auto_data_ingest_batches
    WHERE staff_id = p_staff_id AND organization_id = p_organization_id
      AND request_id = btrim(p_request_id)
    FOR UPDATE;
    IF v_batch.operation <> 'reactivate_source' OR v_batch.request_hash <> v_hash THEN
      RAISE EXCEPTION 'data_group_request_id_conflict';
    END IF;
    IF v_batch.result IS NOT NULL THEN RETURN v_batch.result; END IF;
    RAISE EXCEPTION 'data_group_request_incomplete';
  END IF;

  UPDATE public.auto_campaign_data_group_sources
  SET status = 'baselining', stopped_at = NULL, stop_reason = NULL, updated_at = now()
  WHERE id = v_source.id RETURNING * INTO v_source;
  PERFORM public.aka_agent_internal_route_group_snapshot(
    v_source.id, v_batch.id, v_group.revision
  );
  UPDATE public.auto_campaign_data_group_sources
  SET status = 'active', baseline_revision = v_group.revision,
      started_at = COALESCE(started_at, now()), last_ingest_at = now(), updated_at = now()
  WHERE id = v_source.id RETURNING * INTO v_source;
  UPDATE public.auto_campaigns
  SET status = CASE WHEN status = 'hoàn thành' THEN 'chờ xử lý' ELSE status END,
      completed_at = CASE WHEN status = 'hoàn thành' THEN NULL ELSE completed_at END,
      note = CASE WHEN status = 'hoàn thành' THEN 'Chờ data mới' ELSE note END,
      updated_at = now()
  WHERE id = v_campaign.id;
  UPDATE public.auto_data_ingest_batches
  SET status = 'completed', result = to_jsonb(v_source), updated_at = now()
  WHERE id = v_batch.id;
  RETURN to_jsonb(v_source);
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_read_filtered_contacts_v1(p_staff_id bigint, p_organization_id bigint, p_auth_username text, p_auth_password text, p_source text, p_query jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE predicate text; sql text; result jsonb; page_limit integer; page_offset integer; key text; cursor_clause text:='true'; count_sql text;
BEGIN
 PERFORM public.auto_assert_automation_identity(p_staff_id,p_organization_id,p_auth_username,p_auth_password);
 IF p_source IS NULL OR p_source NOT IN ('contacts','upload','group_members') OR jsonb_typeof(p_query) IS DISTINCT FROM 'object' OR octet_length(p_query::text)>2097152 THEN RAISE EXCEPTION 'invalid_filter_query'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.org_staff s WHERE s.id=p_staff_id AND s.organization_id=p_organization_id AND s.is_active AND s.deleted_at IS NULL) OR NOT EXISTS(SELECT 1 FROM public.auto_accounts a WHERE a.id=(p_query->>'accountId')::bigint AND a.staff_id=p_staff_id AND a.organization_id=p_organization_id AND NOT a.is_delete) THEN RAISE EXCEPTION 'account_access_denied' USING ERRCODE='42501'; END IF;
 IF p_source='group_members' AND nullif(btrim(p_query->>'zaloGroupId'),'') IS NULL THEN RAISE EXCEPTION 'group_required'; END IF;
 IF p_query ? 'datasetId' AND NOT EXISTS(SELECT 1 FROM public.auto_account_contacts_dataset d WHERE d.id=(p_query->>'datasetId')::bigint AND d.staff_id=p_staff_id AND d.organization_id=p_organization_id AND d.account_id=(p_query->>'accountId')::bigint AND NOT d.is_delete AND (p_query->>'contactType' IS NULL OR d.contact_type=p_query->>'contactType')) THEN RAISE EXCEPTION 'dataset_access_denied' USING ERRCODE='42501'; END IF;
 IF p_query ? 'contactGroupId' AND NOT EXISTS(SELECT 1 FROM public.auto_account_contact_groups g WHERE g.id=(p_query->>'contactGroupId')::bigint AND g.staff_id=p_staff_id AND g.organization_id=p_organization_id AND g.account_id IS NULL AND g.contact_type IS NULL AND g.purpose='data_group' AND NOT g.is_delete) THEN RAISE EXCEPTION 'group_access_denied' USING ERRCODE='42501'; END IF;
 page_limit:=COALESCE((p_query->>'limit')::integer,100);page_offset:=COALESCE((p_query->>'offset')::integer,0);
