$function$

CREATE OR REPLACE FUNCTION public.aka_agent_stamp_dataset_semantic_type()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_context_type bigint :=
    public.aka_agent_current_data_type_category_item_id();
  v_context_present boolean :=
    public.aka_agent_data_type_context_present();
  v_group_type bigint;
BEGIN
  IF v_context_present THEN
    NEW.data_type_category_item_id := v_context_type;
  ELSIF NEW.data_type_category_item_id IS NULL THEN
    NEW.data_type_category_item_id :=
      public.aka_agent_derive_dataset_data_type(
        NEW.source,
        NEW.flatform_type,
        NEW.contact_type,
        NEW.scan_type,
        NEW.extra_data
      );
  END IF;

  IF NEW.data_type_category_item_id IS NOT NULL
    AND (
      TG_OP = 'INSERT'
      OR NEW.data_type_category_item_id IS DISTINCT FROM
        OLD.data_type_category_item_id
    )
    AND NOT public.aka_agent_is_data_type_category_item(
      NEW.data_type_category_item_id, true
    )
  THEN
    RAISE EXCEPTION 'invalid_data_type_category_item';
  END IF;

  IF NEW.group_id IS NOT NULL THEN
    SELECT contact_group.data_type_category_item_id
    INTO v_group_type
    FROM public.auto_account_contact_groups AS contact_group
    WHERE contact_group.id = NEW.group_id
      AND contact_group.staff_id = NEW.staff_id
      AND contact_group.organization_id = NEW.organization_id
      AND contact_group.purpose = 'data_group'
      AND contact_group.is_delete = false;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'data_group_not_found';
    END IF;
    IF v_group_type IS NOT NULL
      AND NEW.data_type_category_item_id IS DISTINCT FROM v_group_type
    THEN
      RAISE EXCEPTION 'data_group_dataset_semantic_type_mismatch';
    END IF;
  END IF;

  IF NEW.source = 'upload'
    AND NULLIF(btrim(COALESCE(
      NEW.extra_data ->> 'actionId',
      NEW.extra_data ->> 'action_id',
      ''
    )), '') = 'zalo_add_group_member'
    AND (
      lower(btrim(COALESCE(NEW.contact_type, ''))) <> 'phone'
      OR NEW.data_type_category_item_id IS DISTINCT FROM
        public.aka_agent_data_type_category_item_id('phone')
    )
  THEN
    RAISE EXCEPTION 'zalo_add_group_member_upload_requires_phone';
  END IF;
  IF NEW.source = 'upload'
    AND NULLIF(btrim(COALESCE(
      NEW.extra_data ->> 'actionId',
      NEW.extra_data ->> 'action_id',
      ''
    )), '') = 'facebook_comment_seeding'
    AND NEW.data_type_category_item_id IS NOT NULL
  THEN
    RAISE EXCEPTION 'facebook_comment_seeding_upload_must_be_unrestricted';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_stop_campaign_data_group_source(p_staff_id bigint, p_organization_id bigint, p_campaign_id bigint, p_request_id text, p_reason text, p_auth_username text, p_auth_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_previous_target text := current_setting(
    'aka_agent.zalo_runtime_target', true
  );
  v_runtime_target text := 'desktop';
  v_result jsonb;
BEGIN
  PERFORM public.auto_assert_automation_identity(
    p_staff_id, p_organization_id, p_auth_username, p_auth_password
  );

  SELECT CASE
    WHEN lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
      AND COALESCE(account.is_zalo_show_web, false) = false
      AND COALESCE(account.is_zalo_server, false) = true
    THEN 'server'
    ELSE 'desktop'
  END
  INTO v_runtime_target
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id
   AND account.staff_id = campaign.staff_id
  WHERE campaign.id = p_campaign_id
    AND campaign.staff_id = p_staff_id
    AND campaign.organization_id = p_organization_id
    AND COALESCE(campaign.is_delete, false) = false
    AND (account.organization_id IS NULL
      OR account.organization_id = p_organization_id)
    AND COALESCE(account.is_delete, false) = false;

  v_runtime_target := COALESCE(v_runtime_target, 'desktop');
  PERFORM set_config(
    'aka_agent.zalo_runtime_target', v_runtime_target, true
  );
  BEGIN
    v_result := public.aka_agent_stop_campaign_data_group_source(
      p_staff_id, p_organization_id, p_campaign_id, p_request_id, p_reason
    );
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config(
      'aka_agent.zalo_runtime_target', COALESCE(v_previous_target, ''), true
    );
    RAISE;
  END;
  PERFORM set_config(
    'aka_agent.zalo_runtime_target', COALESCE(v_previous_target, ''), true
  );
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_stop_campaign_data_group_source(p_staff_id bigint, p_organization_id bigint, p_campaign_id bigint, p_request_id text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_source public.auto_campaign_data_group_sources%ROWTYPE;
  v_locked_source public.auto_campaign_data_group_sources%ROWTYPE;
  v_batch public.auto_data_ingest_batches%ROWTYPE;
  v_hash text;
  v_runtime_target text := CASE
    WHEN NULLIF(btrim(COALESCE(
      current_setting('aka_agent.zalo_runtime_target', true), ''
    )), '') = 'desktop' THEN 'desktop'
    ELSE 'server'
  END;
BEGIN
  PERFORM public.aka_agent_internal_require_staff_tenant(
    p_staff_id, p_organization_id
  );
  IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
    OR length(btrim(p_request_id)) > 500
  THEN
    RAISE EXCEPTION 'invalid_data_group_source_request';
  END IF;

  -- Discover immutable lock keys without retaining a row lock.  All state is
  -- revalidated after acquiring the common group -> campaign -> source locks.
  SELECT source.*
  INTO v_source
  FROM public.auto_campaign_data_group_sources AS source
  WHERE source.campaign_id = p_campaign_id
    AND source.staff_id = p_staff_id
    AND source.organization_id = p_organization_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'campaign_data_group_source_not_found';
  END IF;

  PERFORM contact_group.id
  FROM public.auto_account_contact_groups AS contact_group
  WHERE contact_group.id = v_source.group_id
    AND contact_group.staff_id = p_staff_id
    AND contact_group.organization_id = p_organization_id
    AND contact_group.purpose = 'data_group'
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'data_group_not_found';
  END IF;

  PERFORM campaign.id
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account ON account.id = campaign.account_id
  WHERE campaign.id = p_campaign_id
    AND campaign.staff_id = p_staff_id
    AND campaign.organization_id = p_organization_id
    AND account.staff_id = p_staff_id
    AND (account.organization_id IS NULL OR account.organization_id = p_organization_id)
    AND COALESCE(account.is_delete, false) = false
      AND (
        COALESCE(account.flatform_type, '') <> 'zalo'
        OR (
          account.organization_id = p_organization_id
          AND (
            (
              v_runtime_target = 'desktop'
              AND COALESCE(account.is_zalo_server, false) = false
            )
            OR (
              v_runtime_target = 'server'
              AND COALESCE(account.is_zalo_show_web, false) = false
              AND COALESCE(account.is_zalo_server, false) = true
            )
          )
        )
      )
  FOR UPDATE OF campaign, account;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'data_group_campaign_not_found';
  END IF;

  SELECT source.*
  INTO v_locked_source
  FROM public.auto_campaign_data_group_sources AS source
  WHERE source.id = v_source.id
    AND source.campaign_id = p_campaign_id
    AND source.group_id = v_source.group_id
    AND source.staff_id = p_staff_id
    AND source.organization_id = p_organization_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'campaign_data_group_source_changed';
  END IF;
  v_source := v_locked_source;

  v_hash := md5(jsonb_build_object(
    'operation', 'stop_source',
    'campaignId', p_campaign_id,
    'reason', COALESCE(
      NULLIF(btrim(COALESCE(p_reason, '')), ''), 'manual_stop'
    )
  )::text);

  INSERT INTO public.auto_data_ingest_batches (
    request_id, operation, group_id, request_hash, status,
    staff_id, organization_id
  ) VALUES (
    btrim(p_request_id), 'stop_source', v_source.group_id, v_hash,
    'processing', p_staff_id, p_organization_id
  )
  ON CONFLICT (staff_id, organization_id, request_id) DO NOTHING
  RETURNING * INTO v_batch;

  IF NOT FOUND THEN
    SELECT batch.*
    INTO v_batch
    FROM public.auto_data_ingest_batches AS batch
    WHERE batch.staff_id = p_staff_id
      AND batch.organization_id = p_organization_id
      AND batch.request_id = btrim(p_request_id)
    FOR UPDATE;
    IF v_batch.operation <> 'stop_source'
      OR v_batch.request_hash <> v_hash
    THEN
      RAISE EXCEPTION 'data_group_request_id_conflict';
    END IF;
    IF v_batch.result IS NOT NULL THEN
      RETURN v_batch.result;
    END IF;
    RAISE EXCEPTION 'data_group_request_incomplete';
  END IF;

  UPDATE public.auto_campaign_data_group_sources
  SET status = 'stopped',
      stopped_at = COALESCE(stopped_at, now()),
      stop_reason = COALESCE(
        NULLIF(btrim(COALESCE(p_reason, '')), ''), 'manual_stop'
      ),
      updated_at = now()
  WHERE id = v_source.id
  RETURNING * INTO v_source;

  UPDATE public.auto_data_ingest_batches
  SET status = 'completed', result = to_jsonb(v_source), updated_at = now()
  WHERE id = v_batch.id;

  RETURN to_jsonb(v_source);
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_sync_contact_chat_tag_delta()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_conversation_id bigint; v_before bigint[];
  v_added bigint[]; v_removed bigint[]; v_previous text;
BEGIN
  IF current_setting('aka_agent.chat_tag_projection',true)='on'
    OR NEW.is_delete OR NEW.flatform_type IS DISTINCT FROM 'zalo' THEN RETURN NEW; END IF;
  v_before := CASE WHEN TG_OP='INSERT' THEN '{}'::bigint[] ELSE COALESCE(OLD.akabiz_tag_ids,'{}'::bigint[]) END;
  IF TG_OP='UPDATE' AND NEW.akabiz_tag_ids IS NOT DISTINCT FROM OLD.akabiz_tag_ids THEN RETURN NEW; END IF;
  SELECT conv.id INTO v_conversation_id
  FROM public.auto_account_contacts c
    JOIN public.chat_zalo_account_organization b ON b.auto_account_id=c.account_id
      AND b.organization_id=c.organization_id AND b.is_active AND c.flatform_type='zalo'
    JOIN public.chat_zalo_account_conversation ac ON ac.chat_zalo_account_id=b.chat_zalo_account_id
      AND ac.zalo_id=c.uid AND ac.conversation_type=CASE WHEN c.contact_type='person' THEN 'user' WHEN c.contact_type='group' THEN 'group' END
    JOIN public.chat_zalo_conversation conv ON conv.chat_zalo_account_organization_id=b.id
      AND conv.chat_zalo_account_conversation_id=ac.id AND conv.organization_id=c.organization_id
  WHERE c.id=NEW.id;
  IF v_conversation_id IS NULL THEN RETURN NEW; END IF;
  SELECT COALESCE(array_agg(DISTINCT k),'{}'::bigint[]) INTO v_added
    FROM unnest(COALESCE(NEW.akabiz_tag_ids,'{}'::bigint[])) k WHERE NOT k=ANY(v_before);
  SELECT COALESCE(array_agg(DISTINCT k),'{}'::bigint[]) INTO v_removed
    FROM unnest(v_before) k WHERE NOT k=ANY(COALESCE(NEW.akabiz_tag_ids,'{}'::bigint[]));
  IF EXISTS (SELECT 1 FROM unnest(v_added) k WHERE NOT EXISTS (
    SELECT 1 FROM public.auto_contact_tags t WHERE t.id=k AND t.staff_id=NEW.staff_id
      AND t.organization_id=NEW.organization_id AND NOT t.is_delete
      AND (t.auto_account_id IS NULL OR t.auto_account_id=NEW.account_id)
  )) THEN RAISE EXCEPTION 'contact_tag_scope_invalid'; END IF;
  v_previous := current_setting('aka_agent.chat_tag_writeback',true);
  PERFORM set_config('aka_agent.chat_tag_writeback','on',true);
  BEGIN
    DELETE FROM public.chat_zalo_conversation_system_tag link USING public.auto_contact_tags t
      WHERE link.chat_zalo_conversation_id=v_conversation_id AND link.organization_id=NEW.organization_id
        AND link.auto_contact_tag_id=t.id AND t.id=ANY(v_removed)
        AND t.staff_id=NEW.staff_id AND t.organization_id=NEW.organization_id;
    INSERT INTO public.chat_zalo_conversation_system_tag(organization_id,chat_zalo_conversation_id,auto_contact_tag_id,assigned_by_org_staff_id)
      SELECT NEW.organization_id,v_conversation_id,k,NEW.staff_id FROM unnest(v_added) k
      ON CONFLICT(chat_zalo_conversation_id,auto_contact_tag_id) DO NOTHING;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('aka_agent.chat_tag_writeback',COALESCE(v_previous,''),true);
    RAISE;
  END;
  PERFORM set_config('aka_agent.chat_tag_writeback',COALESCE(v_previous,''),true);
  PERFORM public.aka_agent_refresh_contact_chat_tags(NEW.id);
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_sync_dataset_auto_data_group_member()
