   IF h.data->'cursor' IS DISTINCT FROM coalesce(payload->'expected_cursor','null'::jsonb) THEN
     -- A lost response may be retried. Only the exact already-committed cursor is accepted.
     IF h.data->'cursor'=payload->'cursor' THEN RETURN jsonb_build_object('progress',h.data); END IF;
     RAISE EXCEPTION 'IMPORT_CURSOR_CONFLICT';
   END IF;
   FOR item IN SELECT value FROM jsonb_array_elements(payload->'inputs') LOOP
     mapped_status:=CASE (item->>'source_status')::integer WHEN 1 THEN 'chờ xử lý' WHEN 0 THEN 'tạm dừng'
       WHEN 2 THEN 'hoàn thành' WHEN 4 THEN 'hoàn thành' WHEN 5 THEN 'hoàn thành' WHEN 10 THEN 'hoàn thành' WHEN 13 THEN 'hoàn thành'
       WHEN 51 THEN 'hoàn thành' WHEN 52 THEN 'hoàn thành' WHEN 53 THEN 'hoàn thành' WHEN 54 THEN 'hoàn thành' END;
     IF mapped_status IS NULL OR mapped_status IS DISTINCT FROM item->>'status' OR item->>'source_id' IS NULL THEN RAISE EXCEPTION 'UNKNOWN_DETAIL_STATUS'; END IF;
     INSERT INTO public.auto_campaign_input_data(campaign_id,name,phone,uid,email,info1,info2,info3,info4,info5,status,is_delete)
       VALUES(c.id,item->>'name',item->>'phone',item->>'uid',item->>'email',item->>'info1',item->>'info2',item->>'info3',item->>'info4',item->>'info5',mapped_status,false)
       RETURNING id INTO target;
     n.id:=gen_random_uuid(); n.kind:='input'; n.source_id:=item->>'source_id'; n.parent_source_id:=source_key; n.target_id:=target;
     n.source_version:=item->>'source_hash'; n.source_status:=item->>'source_status'; n.state:='complete'; n.adjustments:='[]';
     n.data:=jsonb_build_object('imported_status',mapped_status); INSERT INTO public.akabiz_zalo_import_history SELECT n.*;
   END LOOP;
   UPDATE public.akabiz_zalo_import_history SET data=data||jsonb_build_object('cursor',payload->'cursor','imported_count',(data->>'imported_count')::bigint+jsonb_array_length(payload->'inputs')),error_code=NULL,state='pending',updated_at=clock_timestamp() WHERE id=h.id RETURNING * INTO h;
   IF (h.data->>'imported_count')::bigint>(h.data->>'expected_count')::bigint THEN RAISE EXCEPTION 'SOURCE_CHANGED'; END IF;
   RETURN jsonb_build_object('progress',h.data);
 END IF;
 IF (h.data->>'imported_count')::bigint IS DISTINCT FROM (h.data->>'expected_count')::bigint THEN RAISE EXCEPTION 'IMPORT_INCOMPLETE'; END IF;
 -- One count at completion catches missing/extra/deleted inputs. Content/status
 -- edits outside the importer are accepted; no full-row comparison is performed.
 SELECT count(*) INTO actual_count FROM public.auto_campaign_input_data i WHERE i.campaign_id=c.id AND NOT coalesce(i.is_delete,false);
 IF actual_count IS DISTINCT FROM (h.data->>'imported_count')::bigint THEN RAISE EXCEPTION 'TARGET_CONFLICT'; END IF;
 PERFORM 1 FROM public.auto_accounts account WHERE account.id=c.account_id AND account.staff_id=staff_id AND account.organization_id=org_id
   AND account.flatform_type='zalo' AND account.is_zalo_server=true AND NOT coalesce(account.is_zalo_show_web,false) AND NOT coalesce(account.is_delete,false) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'TARGET_CONFLICT'; END IF;
 SELECT x.data->>'uid' INTO desired FROM public.akabiz_zalo_import_history x WHERE x.kind='account' AND x.source_id=h.parent_source_id
   AND x.target_id=c.account_id AND x.source_system=r.source_system AND x.source_account_id=r.source_account_id AND x.source_staff_id=r.source_staff_id
   AND x.target_staff_id=staff_id AND x.target_organization_id=org_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'TARGET_CONFLICT'; END IF;
 IF desired IS NOT NULL AND (NOT EXISTS(SELECT 1 FROM public.auto_accounts account LEFT JOIN public.zalo_accounts z ON z.id=account.zalo_account_id
   WHERE account.id=c.account_id AND (z.zalo_uid=desired OR EXISTS(SELECT 1 FROM public.chat_zalo_account_organization b JOIN public.chat_zalo_account zc ON zc.id=b.chat_zalo_account_id
     WHERE b.auto_account_id=account.id AND b.organization_id=org_id AND b.is_active AND zc.zalo_id=desired)))
   OR EXISTS(SELECT 1 FROM public.auto_accounts account JOIN public.zalo_accounts z ON z.id=account.zalo_account_id
     WHERE account.id=c.account_id AND z.zalo_uid IS DISTINCT FROM desired)
   OR EXISTS(SELECT 1 FROM public.chat_zalo_account_organization b JOIN public.chat_zalo_account z ON z.id=b.chat_zalo_account_id
     WHERE b.auto_account_id=c.account_id AND b.organization_id=org_id AND b.is_active AND z.zalo_id IS DISTINCT FROM desired)) THEN RAISE EXCEPTION 'TARGET_CONFLICT'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(coalesce(c.extra_settings->'akaBizTagIds','[]')) LOOP
   PERFORM 1 FROM public.auto_contact_tags t WHERE t.id=(item#>>'{}')::bigint AND t.staff_id=staff_id AND t.organization_id=org_id AND NOT coalesce(t.is_delete,false) FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION 'TARGET_CONFLICT'; END IF;
   IF NOT EXISTS(SELECT 1 FROM public.auto_contact_tags t JOIN public.akabiz_zalo_import_history x ON x.target_id=t.id AND x.kind='tag'
     WHERE t.id=(item#>>'{}')::bigint AND x.source_system=r.source_system AND x.source_account_id=r.source_account_id AND x.source_staff_id=r.source_staff_id
       AND x.target_staff_id=staff_id AND x.target_organization_id=org_id AND md5(to_jsonb(t)::text)=x.data->>'target_hash') THEN RAISE EXCEPTION 'TARGET_CONFLICT'; END IF;
 END LOOP;
 IF coalesce((c.extra_settings->>'zaloFriendBlocklistEnabled')::boolean,false) THEN
   PERFORM 1 FROM public.auto_account_contact_groups g WHERE g.id=(c.extra_settings->>'zaloFriendBlocklistId')::bigint
     AND g.account_id=c.account_id AND g.staff_id=staff_id AND g.organization_id=org_id AND g.purpose='zalo_friend_blocklist' AND NOT coalesce(g.is_delete,false) FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION 'TARGET_CONFLICT'; END IF;
   SELECT x.* INTO block_history FROM public.akabiz_zalo_import_history x WHERE x.kind='blocklist' AND x.target_id=(c.extra_settings->>'zaloFriendBlocklistId')::bigint
     AND x.source_system=r.source_system AND x.source_account_id=r.source_account_id AND x.source_staff_id=r.source_staff_id
     AND x.target_staff_id=staff_id AND x.target_organization_id=org_id;
   IF block_history.id IS NULL OR block_history.state<>'complete' OR block_history.data->>'next_offset' IS DISTINCT FROM block_history.data->>'expected_count'
     OR (SELECT count(*) FROM public.akabiz_zalo_import_history x WHERE x.kind='blocklist_member' AND x.parent_source_id=block_history.source_id
       AND x.source_system=r.source_system AND x.source_account_id=r.source_account_id AND x.source_staff_id=r.source_staff_id
       AND x.target_staff_id=staff_id AND x.target_organization_id=org_id) IS DISTINCT FROM (block_history.data->>'expected_count')::bigint THEN RAISE EXCEPTION 'IMPORT_INCOMPLETE'; END IF;
   IF NOT EXISTS(SELECT 1 FROM public.auto_account_contact_groups g JOIN public.akabiz_zalo_import_history x ON x.target_id=g.id AND x.kind='blocklist'
     WHERE g.id=(c.extra_settings->>'zaloFriendBlocklistId')::bigint AND x.source_system=r.source_system AND x.source_account_id=r.source_account_id AND x.source_staff_id=r.source_staff_id
       AND x.target_staff_id=staff_id AND x.target_organization_id=org_id AND md5(to_jsonb(g)::text)=x.data->>'target_hash') THEN RAISE EXCEPTION 'TARGET_CONFLICT'; END IF;
   IF EXISTS(SELECT 1 FROM public.akabiz_zalo_import_history x LEFT JOIN public.auto_account_contact_group_members m ON m.id=x.target_id
     LEFT JOIN public.auto_account_contacts contact ON contact.id=m.contact_id
     WHERE x.kind='blocklist_member' AND x.source_system=r.source_system AND x.source_account_id=r.source_account_id AND x.source_staff_id=r.source_staff_id
       AND x.target_staff_id=staff_id AND x.target_organization_id=org_id
       AND x.parent_source_id=(SELECT b.source_id FROM public.akabiz_zalo_import_history b WHERE b.kind='blocklist'
         AND b.source_system=r.source_system AND b.source_account_id=r.source_account_id AND b.source_staff_id=r.source_staff_id
         AND b.target_staff_id=staff_id AND b.target_organization_id=org_id AND b.target_id=(c.extra_settings->>'zaloFriendBlocklistId')::bigint)
       AND (md5(to_jsonb(m)::text) IS DISTINCT FROM x.data->>'target_hash' OR coalesce(contact.is_delete,true) OR contact.account_id IS DISTINCT FROM c.account_id
         OR contact.uid IS DISTINCT FROM split_part(x.source_id,':',2))) THEN RAISE EXCEPTION 'TARGET_CONFLICT'; END IF;
   IF EXISTS(SELECT 1 FROM public.auto_account_contact_group_members m LEFT JOIN public.akabiz_zalo_import_history x
     ON x.target_id=m.id AND x.kind='blocklist_member' AND x.source_system=r.source_system AND x.source_account_id=r.source_account_id
       AND x.source_staff_id=r.source_staff_id AND x.target_staff_id=staff_id AND x.target_organization_id=org_id
     WHERE m.group_id=(c.extra_settings->>'zaloFriendBlocklistId')::bigint AND x.id IS NULL) THEN RAISE EXCEPTION 'TARGET_CONFLICT'; END IF;
 END IF;
 UPDATE public.auto_campaigns SET is_delete=false,status=h.data->>'desired_status',updated_at=clock_timestamp() WHERE id=c.id;
 UPDATE public.akabiz_zalo_import_history SET state='complete',error_code=NULL,updated_at=clock_timestamp() WHERE id=h.id;
 RETURN jsonb_build_object('campaign_id',c.id::text,'published',true,'progress',h.data);
END;
$function$

CREATE OR REPLACE FUNCTION public.akabiz_migrate_sql_account_v1(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_sql_id text := p->>'sql_account_id';
  a jsonb := p->'account';
  v_phone text;
  v_customer bigint;
  v_customer_ids bigint[];
  v_org bigint;
  v_org_ids bigint[];
  v_link text;
  v_creator bigint;
  v_owner bigint;
  v_staff bigint;
  v_group bigint;
  v_org_customer bigint;
  v_zalo bigint;
  v_admin bigint;
  v_ids bigint[];
  v_package_ids bigint[] := '{}';
  v_selected bigint;
  v_product_id bigint;
  v_product_row bigint;
  v_package public.org_product_package%rowtype;
  v_product_name text;
  v_kind text;
  v_days numeric;
  v_ranks bigint[];
  v_staff_map jsonb := '{}';
  v_group_map jsonb := '{}';
  v_products jsonb := '[]';
  v_helper jsonb;
  v_record jsonb;
  v_previous_ctx text;
  v_bad_customer_chain boolean := false;
  v_staff_created int := 0;
  v_staff_reused int := 0;
  v_groups_created int := 0;
  v_memberships_created int := 0;
  v_products_created int := 0;
  v_products_updated int := 0;
  v_zalo_created int := 0;
BEGIN
  IF v_sql_id IS NULL OR v_sql_id !~ '^[1-9][0-9]{0,9}$' THEN
    RAISE EXCEPTION 'MIG_PAYLOAD_INVALID';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('akabiz-sql-account:' || v_sql_id, 0));
  SELECT id, customer_id INTO v_org, v_customer FROM public.org_organization WHERE sql_account_id = v_sql_id;
  IF FOUND THEN
    RETURN jsonb_build_object('organization_id', v_org, 'customer_id', v_customer, 'already_migrated', true,
      'counts', jsonb_build_object('staff_created',0,'staff_reused',0,'groups_created',0,'memberships_created',0,
        'products_created',0,'products_updated',0,'zalo_accounts_created',0),
      'products','[]'::jsonb,'skipped_products','[]'::jsonb,'skipped_staff','[]'::jsonb,'skipped_shops','[]'::jsonb,'adjustments','[]'::jsonb);
  END IF;
  v_phone := public.normalize_phone(a->>'phone');
  IF v_phone IS NULL OR v_phone !~ '^0[1-9][0-9]{8}$'
    OR jsonb_typeof(p->'staff') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'staff') = 0
    OR jsonb_typeof(p->'groups') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'groups') = 0
    OR jsonb_typeof(p->'memberships') IS DISTINCT FROM 'array'
    OR jsonb_typeof(p->'shops') IS DISTINCT FROM 'array'
    OR jsonb_typeof(p->'product_ids') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'product_ids') = 0
    OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(p->'product_ids') x WHERE x::bigint NOT IN (3,16,18))
    OR NOT EXISTS (SELECT 1 FROM jsonb_array_elements(p->'staff') x
      WHERE x->>'id' = p->>'admin_sql_staff_id' AND (x->>'is_admin')::boolean)
    OR EXISTS (SELECT 1 FROM jsonb_array_elements(p->'staff') x WHERE public.normalize_phone(x->>'phone') IS DISTINCT FROM x->>'phone'
      OR coalesce(x->>'phone','') !~ '^0[1-9][0-9]{8}$')
    OR EXISTS (SELECT 1 FROM jsonb_array_elements(p->'staff') x GROUP BY x->>'phone' HAVING count(*) > 1)
    OR EXISTS (SELECT 1 FROM jsonb_array_elements(p->'staff') x GROUP BY x->>'id' HAVING count(*) > 1)
  THEN RAISE EXCEPTION 'MIG_PAYLOAD_INVALID'; END IF;

  -- Same phone lock as the portal helper; canonical customer row also serializes aliases.
  PERFORM pg_advisory_xact_lock(hashtextextended('zalo-referral-phone:' || v_phone, 0));
  WITH RECURSIVE matches AS (
    SELECT c.id, c.merged_into_customer_id, c.record_state, ARRAY[c.id] path, false cycle FROM public.aka_customer c
    WHERE public.normalize_phone(c.phone) = v_phone
    UNION ALL
    SELECT c.id, c.merged_into_customer_id, c.record_state, m.path || c.id, c.id = ANY(m.path)
    FROM matches m JOIN public.aka_customer c ON c.id = m.merged_into_customer_id
    WHERE NOT m.cycle AND cardinality(m.path) < 32
  ) SELECT array_agg(DISTINCT id) FILTER (WHERE merged_into_customer_id IS NULL),
      bool_or(cycle OR cardinality(path) >= 32 OR (record_state='merged' AND merged_into_customer_id IS NULL) OR (merged_into_customer_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM public.aka_customer c WHERE c.id = matches.merged_into_customer_id)))
    INTO v_customer_ids, v_bad_customer_chain FROM matches;
  IF coalesce(v_bad_customer_chain,false) OR cardinality(v_customer_ids) > 1 THEN RAISE EXCEPTION 'MIG_CUSTOMER_AMBIGUOUS'; END IF;
  v_customer := v_customer_ids[1];
  SELECT id INTO v_creator FROM public.org_staff WHERE sql_staff_id = (a->>'creator_sql_staff_id')::bigint;
  SELECT id INTO v_owner FROM public.org_staff WHERE sql_staff_id = (a->>'owner_sql_staff_id')::bigint;
  v_creator := coalesce(v_creator,15); v_owner := coalesce(v_owner,15);
  IF NOT EXISTS (SELECT 1 FROM public.org_staff WHERE id = v_creator)
    OR NOT EXISTS (SELECT 1 FROM public.org_staff WHERE id = v_owner) THEN RAISE EXCEPTION 'MIG_INTERNAL_STAFF_MISSING'; END IF;
  IF v_customer IS NULL THEN
    v_helper := public.fn_upsert_aka_customer_v1(jsonb_build_object('phone',v_phone,'name',a->>'customer_name',
      'email',a->>'email','org_staff_id',v_owner,'overwrite',false,'use_split_rules',false,'is_create_crm',false,
      'channel','akabiz_sql_migration','creation_path','akabiz_sql_migration'));
    IF NOT coalesce((v_helper->>'ok')::boolean,false) OR v_helper->>'customer_id' IS NULL THEN
      RAISE EXCEPTION 'MIG_CUSTOMER_CREATE_FAILED';
    END IF;
    v_customer := (v_helper->>'customer_id')::bigint;
    -- The helper assigns the same actor to create/owner. Only a newly inserted customer
    -- receives the independent SQL creator/owner attribution; existing CRM is untouched.
    IF coalesce((v_helper->>'is_new')::boolean,false) THEN
      UPDATE public.aka_customer SET org_staff_create_id=v_creator, org_staff_id_owner=v_owner,
        org_staff_update_id=v_creator WHERE id=v_customer;
    END IF;
  END IF;
  PERFORM 1 FROM public.aka_customer WHERE id=v_customer FOR UPDATE;

  -- Catalog is read for every migration. Rank all best candidates; never break a tie by id.
  v_kind := a->>'package_type';
  IF v_kind NOT IN ('demo','month','1_month','year','forever') OR v_kind IS NULL THEN RAISE EXCEPTION 'MIG_PACKAGE_UNKNOWN'; END IF;
  v_days := coalesce((a->>'duration_days')::numeric, CASE WHEN v_kind IN ('month','1_month') THEN 60 WHEN v_kind='year' THEN 365 END);
  IF v_kind IN ('month','1_month','year') AND (v_days IS NULL OR v_days <= 0) THEN RAISE EXCEPTION 'MIG_PACKAGE_UNKNOWN'; END IF;
  FOR v_product_id IN SELECT DISTINCT x::bigint FROM jsonb_array_elements_text(p->'product_ids') x ORDER BY 1 LOOP
    WITH candidates AS (
      SELECT pp.*, dense_rank() OVER (ORDER BY
        CASE WHEN v_kind='forever' THEN CASE WHEN lower(pp.package_type) IN ('forever','unlimited') THEN 0 ELSE 1 END ELSE 0 END,
        CASE WHEN v_kind='forever' AND lower(pp.package_type) NOT IN ('forever','unlimited') THEN -pp.duration_days::numeric
          WHEN v_kind NOT IN ('demo','forever') THEN abs(pp.duration_days::numeric-v_days) ELSE 0 END
      ) ranking
      FROM public.org_product_package pp JOIN public.org_product pr ON pr.id=pp.product_id
      WHERE pp.product_id=v_product_id AND pr.is_active IS TRUE
        AND CASE WHEN v_kind='demo' THEN lower(pp.package_type)='demo' ELSE lower(pp.package_type)<>'demo' END
        AND (v_product_id<>16 OR (pp.is_zalo_server IS TRUE AND coalesce(pp.is_zalo_show_web,false)=false))
        AND (v_product_id<>18 OR (pp.is_zalo_show_web IS TRUE AND coalesce(pp.is_zalo_server,false)=false))
    ) SELECT array_agg(id) INTO v_ranks FROM candidates WHERE ranking=1;
    IF coalesce(cardinality(v_ranks),0)=0 THEN RAISE EXCEPTION 'MIG_PACKAGE_MISSING'; END IF;
    IF cardinality(v_ranks)<>1 THEN RAISE EXCEPTION 'MIG_PACKAGE_AMBIGUOUS'; END IF;
    v_package_ids := array_append(v_package_ids,v_ranks[1]);
  END LOOP;
  -- Lock catalog rows until quota/package projection has been written.
  PERFORM 1 FROM public.org_product_package WHERE id=ANY(v_package_ids) ORDER BY id FOR SHARE;

  PERFORM pg_advisory_xact_lock(hashtextextended('aka-agent-zalo-runtime-entitlement-mutation',0));
  WITH RECURSIVE family AS (
    SELECT id FROM public.aka_customer WHERE id=v_customer
    UNION SELECT c.id FROM public.aka_customer c JOIN family f ON c.merged_into_customer_id=f.id
  ) SELECT array_agg(o.id ORDER BY o.id) INTO v_org_ids FROM public.org_organization o WHERE o.customer_id IN (SELECT id FROM family);
  IF cardinality(v_org_ids)>1 THEN RAISE EXCEPTION 'MIG_ORG_AMBIGUOUS'; END IF;
  v_org := v_org_ids[1];
  IF v_org IS NOT NULL THEN
    SELECT sql_account_id INTO v_link FROM public.org_organization WHERE id=v_org FOR UPDATE;
    IF nullif(v_link,'') IS NOT NULL THEN RAISE EXCEPTION 'MIG_SQL_LINK_CONFLICT'; END IF;
    PERFORM 1 FROM public.org_organization_product WHERE organization_id=v_org ORDER BY id FOR UPDATE;
    IF EXISTS (SELECT 1 FROM public.org_organization_product op WHERE op.organization_id=v_org
        AND NOT coalesce(op.is_deleted,false) AND op.product_id IN (SELECT x::bigint FROM jsonb_array_elements_text(p->'product_ids') x)
        AND lower(coalesce(op.package_type,'')) <> 'demo') THEN v_org := NULL;
    END IF;
  END IF;
  IF v_org IS NULL THEN
    INSERT INTO public.org_organization(customer_id,name,phone,email,staff_id_created,staff_id_owner,max_staff)
    VALUES(v_customer,a->>'name',v_phone,a->>'email',v_creator,v_owner,
      coalesce((a->>'max_staff')::int,(SELECT max(max_staff) FROM public.org_product_package WHERE id=ANY(v_package_ids))))
    RETURNING id INTO v_org;
  END IF;

  FOREACH v_selected IN ARRAY v_package_ids LOOP
    SELECT * INTO STRICT v_package FROM public.org_product_package WHERE id=v_selected;
    SELECT name INTO v_product_name FROM public.org_product WHERE id=v_package.product_id;
    SELECT array_agg(id) INTO v_ids FROM public.org_organization_product WHERE organization_id=v_org
      AND product_id=v_package.product_id AND NOT coalesce(is_deleted,false);
    IF cardinality(v_ids)>1 THEN RAISE EXCEPTION 'MIG_PRODUCT_AMBIGUOUS'; END IF;
    v_product_row := v_ids[1];
    IF v_product_row IS NULL THEN
      INSERT INTO public.org_organization_product(organization_id,product_package_id,product_id,
        organization_phone,organization_email,product_name,package_name,package_type,max_accounts,max_staff,
        duration_days,max_sends_per_day,expiration_date,is_paid,is_chat_sync,is_zalo_server,is_zalo_show_web,created_by,updated_by)
      VALUES(v_org,v_package.id,v_package.product_id,v_phone,a->>'email',v_product_name,v_package.name,v_package.package_type,
        coalesce((a->>'max_accounts')::int,v_package.max_account),coalesce((a->>'max_staff')::int,v_package.max_staff),
        v_package.duration_days,coalesce((a->>'max_sends_per_day')::int,v_package.max_sends_per_day),
        (a->>'expiration_date')::timestamptz,v_kind<>'demo',false,v_package.product_id=16,v_package.product_id=18,v_creator,v_owner);
      v_products_created := v_products_created+1;
    ELSE
      UPDATE public.org_organization_product SET product_package_id=v_package.id,
        product_name=v_product_name,package_name=v_package.name,package_type=v_package.package_type,
        max_accounts=coalesce((a->>'max_accounts')::int,v_package.max_account),max_staff=coalesce((a->>'max_staff')::int,v_package.max_staff),
        duration_days=v_package.duration_days,max_sends_per_day=coalesce((a->>'max_sends_per_day')::int,v_package.max_sends_per_day),
        expiration_date=(a->>'expiration_date')::timestamptz,is_paid=v_kind<>'demo',is_chat_sync=false,
        is_zalo_server=v_package.product_id=16,is_zalo_show_web=v_package.product_id=18,updated_by=v_owner,updated_at=now()
      WHERE id=v_product_row;
      v_products_updated := v_products_updated+1;
    END IF;
    v_products := v_products || jsonb_build_object('product_id',v_package.product_id,'package_id',v_package.id);
  END LOOP;

  -- Deterministic phone order avoids deadlocks when distinct customers share staff phones.
  FOR v_record IN SELECT x FROM jsonb_array_elements(p->'staff') x ORDER BY x->>'phone' LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended('akabiz-org-customer-phone:' || (v_record->>'phone'),0));
    SELECT array_agg(id) INTO v_ids FROM public.org_customer WHERE public.normalize_phone(phone)=v_record->>'phone';
    IF cardinality(v_ids)>1 THEN RAISE EXCEPTION 'MIG_ORG_CUSTOMER_AMBIGUOUS'; END IF;
    v_org_customer := v_ids[1];
    IF v_org_customer IS NULL THEN
      INSERT INTO public.org_customer(name,phone,email) VALUES(v_record->>'name',v_record->>'phone',v_record->>'email')
      ON CONFLICT (phone) DO NOTHING RETURNING id INTO v_org_customer;
      IF v_org_customer IS NULL THEN SELECT id INTO v_org_customer FROM public.org_customer WHERE phone=v_record->>'phone'; END IF;
    END IF;
    SELECT array_agg(id) INTO v_ids FROM public.org_staff WHERE organization_id=v_org AND public.normalize_phone(phone)=v_record->>'phone';
    IF cardinality(v_ids)>1 THEN RAISE EXCEPTION 'MIG_STAFF_AMBIGUOUS'; END IF;
    v_staff := v_ids[1];
    IF v_staff IS NULL THEN
      INSERT INTO public.org_staff(organization_id,customer_id,name,phone,email,username,password,is_admin,is_active)
      VALUES(v_org,v_org_customer,v_record->>'name',v_record->>'phone',v_record->>'email',
        v_org::text || '.' || (v_record->>'phone'),'123456',(v_record->>'is_admin')::boolean,(v_record->>'is_active')::boolean)
      RETURNING id INTO v_staff;
      v_staff_created := v_staff_created+1;
    ELSE
      IF EXISTS (SELECT 1 FROM public.org_staff WHERE id=v_staff AND (deleted_at IS NOT NULL OR sql_staff_id IS NOT NULL)) THEN
        RAISE EXCEPTION 'MIG_STAFF_CONFLICT';
      END IF;
      UPDATE public.org_staff SET customer_id=v_org_customer,is_admin=(v_record->>'is_admin')::boolean,
        is_active=(v_record->>'is_active')::boolean,updated_at=now() WHERE id=v_staff;
      v_staff_reused := v_staff_reused+1;
    END IF;
    v_staff_map := v_staff_map || jsonb_build_object(v_record->>'id',v_staff);
    IF v_record->>'id'=p->>'admin_sql_staff_id' THEN v_admin := v_staff; END IF;
  END LOOP;
  FOR v_record IN SELECT x FROM jsonb_array_elements(p->'groups') x LOOP
    IF v_record->>'parent_id' IS NOT NULL AND NOT v_group_map ? (v_record->>'parent_id') THEN RAISE EXCEPTION 'MIG_PAYLOAD_INVALID'; END IF;
    INSERT INTO public.org_group(organization_id,parent_id,name)
    VALUES(v_org,(v_group_map->>(v_record->>'parent_id'))::bigint,v_record->>'name') RETURNING id INTO v_group;
    v_group_map := v_group_map || jsonb_build_object(v_record->>'id',v_group);
    v_groups_created := v_groups_created+1;
  END LOOP;
  FOR v_record IN SELECT x FROM jsonb_array_elements(p->'memberships') x LOOP
    v_staff := (v_staff_map->>(v_record->>'staff_id'))::bigint; v_group := (v_group_map->>(v_record->>'group_id'))::bigint;
    IF v_staff IS NULL OR v_group IS NULL THEN RAISE EXCEPTION 'MIG_PAYLOAD_INVALID'; END IF;
    INSERT INTO public.org_group_staff(organization_id,staff_id,group_id,is_admin)
    VALUES(v_org,v_staff,v_group,(v_record->>'is_admin')::boolean);
    v_memberships_created := v_memberships_created+1;
  END LOOP;

  -- Only the backend migration can import dormant/expired/over-quota legacy accounts.
  -- Runtime still evaluates current entitlements and verifies each session normally.
  v_previous_ctx := current_setting('aka_agent.sql_migration_org',true);
  PERFORM set_config('aka_agent.sql_migration_org',v_org::text,true);
  FOR v_record IN SELECT x FROM jsonb_array_elements(p->'shops') x LOOP
    v_staff := (v_staff_map->>(v_record->>'staff_id'))::bigint;
    IF v_staff IS NULL OR NOT (p->'product_ids') @> '[16]'::jsonb THEN
      RAISE EXCEPTION 'MIG_PAYLOAD_INVALID';
    END IF;
    -- A Shop that has never logged in has no Zalo identity yet. Reset per Shop
    -- so it cannot inherit the previous Shop's identity; normal login links it later.
    v_zalo := NULL;
    IF nullif(btrim(v_record->>'zalo_uid'),'') IS NOT NULL THEN
      INSERT INTO public.zalo_accounts(zalo_uid,display_name,phone)
      VALUES(v_record->>'zalo_uid',v_record->>'name',v_record->>'phone') ON CONFLICT (zalo_uid) DO NOTHING
      RETURNING id INTO v_zalo;
      IF v_zalo IS NULL THEN SELECT id INTO v_zalo FROM public.zalo_accounts WHERE zalo_uid=v_record->>'zalo_uid'; END IF;
    END IF;
    INSERT INTO public.auto_accounts(name,flatform_type,staff_id,organization_id,zalo_account_id,
      is_active,is_delete,is_zalo_server,is_zalo_show_web,login_status,status,zalo_session,zalo_session_updated_at,zalo_session_last_error)
    VALUES(v_record->>'name','zalo',v_staff,v_org,v_zalo,(v_record->>'is_active')::boolean,false,true,false,
      'chưa đăng nhập','chờ xử lý',nullif(v_record->'session','null'::jsonb),
      CASE WHEN nullif(v_record->'session','null'::jsonb) IS NOT NULL THEN now() END,
      CASE WHEN nullif(v_record->'session','null'::jsonb) IS NULL THEN 'migration_login_required' END);
    v_zalo_created := v_zalo_created+1;
  END LOOP;
  PERFORM set_config('aka_agent.sql_migration_org',coalesce(v_previous_ctx,''),true);
  UPDATE public.org_organization SET staff_admin_id=v_admin,sql_account_id=v_sql_id,
    max_staff=coalesce((a->>'max_staff')::int,(SELECT max(max_staff) FROM public.org_organization_product
      WHERE organization_id=v_org AND NOT coalesce(is_deleted,false))),updated_at=now() WHERE id=v_org;
  RETURN jsonb_build_object('organization_id',v_org,'customer_id',v_customer,'already_migrated',false,
    'counts',jsonb_build_object('staff_created',v_staff_created,'staff_reused',v_staff_reused,
      'groups_created',v_groups_created,'memberships_created',v_memberships_created,
      'products_created',v_products_created,'products_updated',v_products_updated,'zalo_accounts_created',v_zalo_created),
    'products',v_products,'skipped_products',coalesce(p->'skipped_products','[]'::jsonb),'skipped_staff',coalesce(p->'skipped_staff','[]'::jsonb),
    'skipped_shops',coalesce(p->'skipped_shops','[]'::jsonb),'adjustments',coalesce(p->'adjustments','[]'::jsonb));
END;
$function$

CREATE OR REPLACE FUNCTION public.akabiz_portal_create_trial_account(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare
  v_role text := coalesce(nullif(current_setting('request.jwt.claim.role', true), ''), current_user);
  v_helper regprocedure := to_regprocedure('public.fn_upsert_aka_customer_v1(jsonb)');
  v_helper_checksum text;
  v_session_id uuid := nullif(p ->> 'session_id', '')::uuid;
  v_idempotency_hash text := nullif(btrim(p ->> 'idempotency_key_hash'), '');
  v_method text := nullif(btrim(p ->> 'method'), '');
  v_name text := left(nullif(regexp_replace(btrim(coalesce(p ->> 'name', '')), '[[:space:]]+', ' ', 'g'), ''), 200);
  v_email text := lower(nullif(btrim(p ->> 'normalized_email'), ''));
  v_phone text := public.normalize_phone(nullif(btrim(p ->> 'normalized_phone'), ''));
  v_industry_id bigint := nullif(p ->> 'industry_status_id', '')::bigint;
  v_creator_id bigint := coalesce(nullif(p ->> 'creator_staff_id', '')::bigint, 15);
  v_password text := coalesce(nullif(p ->> 'password', ''), '123456');
  v_download_url text := nullif(btrim(p ->> 'download_url'), '');
  v_support_email text := nullif(btrim(p ->> 'support_email'), '');
  v_support_phone text := nullif(btrim(p ->> 'support_phone'), '');
  v_package_ids bigint[];
  v_package_count integer;
  v_now timestamptz := now();
  v_key text;
  v_existing public.akabiz_portal_signups%rowtype;
  v_customer_phone_id bigint;
  v_customer_email_id bigint;
  v_customer_id bigint;
  v_customer_result jsonb;
  v_org_customer_id bigint;
  v_organization_id bigint;
  v_staff_id bigint;
  v_group_id bigint;
  v_signup_id uuid := gen_random_uuid();
  v_max_staff integer;
  v_products jsonb;
  v_result jsonb;
  r record;
begin
  if v_role not in ('service_role', 'postgres') then
    raise exception 'service_role_required' using errcode = '42501';
  end if;
  if v_helper is null then raise exception 'customer_helper_missing'; end if;
  select md5(pg_get_functiondef(v_helper)) into v_helper_checksum;
  if v_helper_checksum <> 'bbcba664f3b7ee5b0201bc326814f389' then
    raise exception 'customer_helper_drifted:%', v_helper_checksum;
  end if;

  if v_session_id is null or not exists (
    select 1 from public.akabiz_portal_signup_sessions s
    where s.id = v_session_id and s.status in ('active', 'completed') and s.expires_at > now()
  ) then return jsonb_build_object('ok', false, 'code', 'invalid_session'); end if;
  if v_idempotency_hash is null or v_idempotency_hash !~ '^[0-9a-f]{64}$' then
    return jsonb_build_object('ok', false, 'code', 'invalid_idempotency_key');
  end if;
  if v_method not in ('form', 'google') or v_name is null then
    return jsonb_build_object('ok', false, 'code', 'invalid_profile');
  end if;
  if v_email is null or v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then
    return jsonb_build_object('ok', false, 'code', 'invalid_email');
  end if;
  if v_phone is null or v_phone !~ '^0[1-9][0-9]{8}$' then
    return jsonb_build_object('ok', false, 'code', 'invalid_phone');
  end if;
  if not exists (select 1 from public.aka_crm_status where id = v_industry_id and type = 'industry' and is_active) then
    return jsonb_build_object('ok', false, 'code', 'invalid_industry');
  end if;
  if not exists (select 1 from public.org_staff where id = v_creator_id and is_active) then
    return jsonb_build_object('ok', false, 'code', 'invalid_creator');
  end if;

  select array_agg(distinct value::bigint order by value::bigint)
  into v_package_ids
  from jsonb_array_elements_text(coalesce(p -> 'package_ids', '[]'::jsonb)) value;
  v_package_count := coalesce(cardinality(v_package_ids), 0);
  if v_package_count = 0 or exists (
    select 1 from unnest(v_package_ids) id where id <> all(array[6,55,53,74,58,67]::bigint[])
  ) then return jsonb_build_object('ok', false, 'code', 'invalid_packages'); end if;
  if (select count(*) from public.org_product_package pp join public.org_product pr on pr.id = pp.product_id
      where pp.id = any(v_package_ids) and pp.package_type = 'demo' and pr.is_active) <> v_package_count then
    return jsonb_build_object('ok', false, 'code', 'inactive_packages');
  end if;

  for v_key in
    select key from unnest(array[
      'akabiz-portal-email:' || v_email,
      'akabiz-portal-idempotency:' || v_idempotency_hash,
      'akabiz-portal-phone:' || v_phone
    ]) key order by key
  loop
    perform pg_advisory_xact_lock(hashtextextended(v_key, 0));
  end loop;

  select * into v_existing from public.akabiz_portal_signups where idempotency_key_hash = v_idempotency_hash;
  if found then
    if v_existing.normalized_email <> v_email or v_existing.normalized_phone <> v_phone
       or v_existing.session_id <> v_session_id then
      return jsonb_build_object('ok', false, 'code', 'idempotency_conflict');
    end if;
    return jsonb_build_object('ok', true, 'result', v_existing.result_snapshot || jsonb_build_object('idempotentReplay', true));
  end if;

  if exists (
    select 1 from public.org_organization o
    where public.normalize_phone(o.phone) = v_phone or lower(btrim(o.email)) = v_email
    union all
    select 1 from public.org_staff s
    where public.normalize_phone(s.phone) = v_phone or lower(btrim(s.email)) = v_email
    union all
    select 1 from public.org_customer c join public.org_staff s on s.customer_id = c.id
    where public.normalize_phone(c.phone) = v_phone or lower(btrim(c.email)) = v_email
    union all
    select 1 from public.aka_customer c join public.org_organization o
      on o.customer_id = coalesce(c.merged_into_customer_id, c.id)
    where public.normalize_phone(c.phone) = v_phone or lower(btrim(c.email)) = v_email
  ) then return jsonb_build_object('ok', false, 'code', 'duplicate_identity'); end if;

  select coalesce(c.merged_into_customer_id, c.id) into v_customer_phone_id
  from public.aka_customer c
  where public.normalize_phone(c.phone) = v_phone
  order by case when coalesce(c.record_state, 'verified') = 'merged' then 1 else 0 end,
           c.created_at desc nulls last, c.id desc limit 1;
  select coalesce(c.merged_into_customer_id, c.id) into v_customer_email_id
  from public.aka_customer c
  where lower(btrim(c.email)) = v_email
  order by case when coalesce(c.record_state, 'verified') = 'merged' then 1 else 0 end,
           c.created_at desc nulls last, c.id desc limit 1;
  if v_customer_phone_id is not null and v_customer_email_id is not null and v_customer_phone_id <> v_customer_email_id then
    return jsonb_build_object('ok', false, 'code', 'ambiguous_customer');
  end if;
  v_customer_id := coalesce(v_customer_phone_id, v_customer_email_id);

  v_customer_result := public.fn_upsert_aka_customer_v1(jsonb_strip_nulls(jsonb_build_object(
    'customer_id', v_customer_id,
    'name', v_name,
    'phone', v_phone,
    'email', v_email,
    'industry_status_id', v_industry_id,
    'org_staff_id', v_creator_id,
    'channel', 'akabiz_portal',
    'form_title', 'Cổng đăng ký dùng thử akaBiz',
    'creation_path', 'akabiz_web_portal',
    'overwrite', true,
    'use_split_rules', false,
    'is_create_crm', false,
    'status', 'new'
  )));
  if coalesce((v_customer_result ->> 'ok')::boolean, false) is not true then
    raise exception 'customer_upsert_failed:%', coalesce(v_customer_result ->> 'error', 'unknown');
  end if;
  v_customer_id := (v_customer_result ->> 'customer_id')::bigint;
  update public.aka_customer
  set industry_status_id = v_industry_id, updated_at = v_now
  where id = v_customer_id;

  insert into public.org_customer(name, phone, email, industry, note)
  values (v_name, v_phone, v_email, null, null)
  returning id into v_org_customer_id;

  select max(pp.max_staff) into v_max_staff
  from public.org_product_package pp where pp.id = any(v_package_ids);
  insert into public.org_organization(
    customer_id, name, phone, email, max_staff,
    staff_id_created, staff_id_owner, demo_created_by, demo_created_at
  ) values (
    v_customer_id, v_name, v_phone, v_email, greatest(coalesce(v_max_staff, 1), 1),
    v_creator_id, v_creator_id, v_creator_id, v_now
  ) returning id into v_organization_id;

  insert into public.org_staff(
    organization_id, customer_id, name, phone, email, username, password,
    is_admin, is_created_demo, is_policy_accepted
  ) values (
    v_organization_id, v_org_customer_id, v_name, v_phone, v_email,
    v_organization_id::text || '.' || v_phone, v_password,
    true, null, false
  ) returning id into v_staff_id;
  update public.org_organization set staff_admin_id = v_staff_id, updated_at = v_now where id = v_organization_id;

  insert into public.org_group(organization_id, parent_id, name)
  values (v_organization_id, null, v_name) returning id into v_group_id;
  insert into public.org_group_staff(group_id, staff_id, organization_id, is_admin)
  values (v_group_id, v_staff_id, v_organization_id, true);

  for r in
    select pp.*, pr.name product_name
    from public.org_product_package pp join public.org_product pr on pr.id = pp.product_id
    where pp.id = any(v_package_ids) order by pp.id
  loop
    insert into public.org_organization_product(
      organization_id, product_package_id, organization_phone, organization_email,
      product_id, product_name, package_name, package_type, max_accounts, max_staff,
      duration_days, max_sends_per_day, is_zalo_server, is_zalo_show_web, is_chat_sync,
      purchase_date, trial_start_date, expiration_date,
      created_by, demo_created_by, demo_created_at, is_paid, is_deleted
    ) values (
      v_organization_id, r.id, v_phone, v_email,
      r.product_id, r.product_name, r.name, r.package_type, r.max_account, r.max_staff,
      r.duration_days::integer, r.max_sends_per_day,
      case when r.id = 74 then true else coalesce(r.is_zalo_server, false) end,
      coalesce(r.is_zalo_show_web, false), false,
      v_now, v_now, v_now + make_interval(days => r.duration_days::integer),
      v_creator_id, v_creator_id, v_now, false, false
    );
  end loop;

  select jsonb_agg(jsonb_build_object(
    'id', op.product_package_id,
    'name', case op.product_package_id
      when 6 then 'akaAgent Facebook & Fanpage'
      when 55 then 'akaAgent Email Marketing'
      when 53 then 'akaAgent Zalo Desktop QR'
      when 74 then 'akaAgent Zalo Server'
      when 58 then 'akaAgent SMS Mobile'
      when 67 then 'akaAgent Zalo Browser'
    end,
    'description', '', 'tag', null,
    'durationDays', op.duration_days,
    'maxAccounts', op.max_accounts,
    'maxStaff', op.max_staff,
    'maxSendsPerDay', op.max_sends_per_day,
    'productId', op.product_id,
    'isZaloServer', op.is_zalo_server,
    'isZaloShowWeb', op.is_zalo_show_web,
    'limitLabel', op.max_accounts::text || case when op.product_package_id = 58 then ' thiết bị' else ' tài khoản' end
      || case when op.max_sends_per_day is not null then ' · ' || op.max_sends_per_day::text || ' lượt/ngày' else '' end,
    'expirationDate', op.expiration_date
  ) order by array_position(array[6,55,53,74,58,67]::bigint[], op.product_package_id))
  into v_products
  from public.org_organization_product op where op.organization_id = v_organization_id;

  v_result := jsonb_build_object(
    'signupId', v_signup_id,
    'organizationId', v_organization_id,
    'staffId', v_staff_id,
    'username', v_organization_id::text || '.' || v_phone,
    'password', v_password,
    'name', v_name,
    'email', v_email,
    'phone', v_phone,
    'industryId', v_industry_id,
    'products', coalesce(v_products, '[]'::jsonb),
    'emailStatus', 'pending',
    'createdAt', v_now
  );

  insert into public.akabiz_portal_signups(
    id, session_id, idempotency_key_hash, method, normalized_email, normalized_phone,
    full_name, industry_status_id, package_ids, aka_customer_id, org_customer_id,
    organization_id, staff_id, result_snapshot
  ) values (
    v_signup_id, v_session_id, v_idempotency_hash, v_method, v_email, v_phone,
    v_name, v_industry_id, v_package_ids, v_customer_id, v_org_customer_id,
    v_organization_id, v_staff_id, v_result
  );

  insert into public.akabiz_portal_email_outbox(signup_id, to_email, subject, payload)
  values (
    v_signup_id,
    v_email,
    'Tài khoản akaAgent của bạn đã sẵn sàng',
    jsonb_build_object(
      'name', v_name, 'email', v_email,
      'username', v_organization_id::text || '.' || v_phone,
      'password', v_password, 'products', v_products,
      'downloadUrl', v_download_url,
      'supportEmail', v_support_email,
      'supportPhone', v_support_phone
    )
  );

  return jsonb_build_object('ok', true, 'result', v_result);
exception
  when unique_violation then
    return jsonb_build_object('ok', false, 'code', 'duplicate_identity');
end
$function$

CREATE OR REPLACE FUNCTION public.akamap_staff_client(p_username text, p_password text, p_action text, p_device jsonb, p_expected jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET lock_timeout TO '3s'
 SET statement_timeout TO '12s'
AS $function$
DECLARE
  s public.org_staff%ROWTYPE;
  subscription public.org_organization_product%ROWTYPE;
  package_kind text;
  stamp timestamptz;
  today_start timestamptz;
BEGIN
  IF p_action IS NULL OR p_action NOT IN ('login','reset_device')
    OR jsonb_typeof(p_device) IS DISTINCT FROM 'object'
    OR jsonb_typeof(p_expected) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'akamap_invalid_input';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_device) k WHERE NOT k=ANY(ARRAY['fingerprintHash','label','platform']))
    OR jsonb_typeof(p_device->'fingerprintHash') IS DISTINCT FROM 'string'
    OR p_device->>'fingerprintHash' !~ '^[a-f0-9]{64}$'
    OR jsonb_typeof(p_device->'label') IS DISTINCT FROM 'string'
    OR length(btrim(p_device->>'label')) NOT BETWEEN 1 AND 512
    OR jsonb_typeof(p_device->'platform') IS DISTINCT FROM 'string'
    OR p_device->>'platform' NOT IN ('mac','win') THEN
    RAISE EXCEPTION 'akamap_invalid_input';
  END IF;
  IF p_action='login' AND p_expected<>'{}'::jsonb THEN
    RAISE EXCEPTION 'akamap_invalid_input';
  ELSIF p_action='reset_device' THEN
    IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_expected) k WHERE NOT k=ANY(ARRAY['staffId','organizationId','boundAt']))
      OR jsonb_typeof(p_expected->'staffId') IS DISTINCT FROM 'number'
      OR p_expected->>'staffId' !~ '^[1-9][0-9]*$'
      OR jsonb_typeof(p_expected->'organizationId') IS DISTINCT FROM 'number'
      OR p_expected->>'organizationId' !~ '^[1-9][0-9]*$'
      OR NOT p_expected ? 'boundAt'
      OR jsonb_typeof(p_expected->'boundAt') NOT IN ('string','null') THEN
      RAISE EXCEPTION 'akamap_invalid_input';
    END IF;
  END IF;
  IF coalesce(btrim(p_username),'')='' OR coalesce(p_password,'')='' THEN
    RAISE EXCEPTION 'akamap_auth_invalid';
  END IF;

  -- Credentials, active state and the device mutation use the same locked row.
  -- Neither a staff ID nor the machine fingerprint can authenticate a caller.
  BEGIN
    SELECT * INTO STRICT s FROM public.org_staff
      WHERE username=btrim(p_username) AND password=p_password FOR UPDATE;
  EXCEPTION WHEN no_data_found OR too_many_rows THEN
    RAISE EXCEPTION 'akamap_auth_invalid';
  END;
  IF s.is_active IS DISTINCT FROM true OR s.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'akamap_staff_inactive';
  END IF;
  stamp := clock_timestamp();

  IF p_action='reset_device' THEN
    IF s.id::text IS DISTINCT FROM p_expected->>'staffId'
      OR s.organization_id::text IS DISTINCT FROM p_expected->>'organizationId'
      OR s.device_fingerprint_hash IS DISTINCT FROM p_device->>'fingerprintHash'
      OR (to_jsonb(s.device_bound_at)#>>'{}') IS DISTINCT FROM p_expected->>'boundAt' THEN
      RAISE EXCEPTION 'akamap_binding_conflict';
    END IF;
    -- Release only the akaMap/legacy columns. The newer akaAgent binding,
    -- recovery proof, device-change quota and login preferences are untouched.
    UPDATE public.org_staff SET device_fingerprint_hash=NULL,device_label=NULL,
      device_platform=NULL,device_bound_at=NULL,device_last_seen_at=NULL,updated_at=stamp
      WHERE id=s.id;
    RETURN jsonb_build_object('success',true);
  END IF;

  SELECT * INTO subscription FROM public.org_organization_product
    WHERE organization_id=s.organization_id AND product_id=4 AND is_deleted=false
    ORDER BY expiration_date DESC NULLS LAST,id DESC LIMIT 1;
  today_start := date_trunc('day',stamp AT TIME ZONE 'Asia/Ho_Chi_Minh') AT TIME ZONE 'Asia/Ho_Chi_Minh';
  IF NOT FOUND OR subscription.expiration_date IS NULL OR subscription.expiration_date<today_start THEN
    RAISE EXCEPTION 'akamap_product_expired';
  END IF;
  SELECT package_type INTO package_kind FROM public.org_product_package WHERE id=subscription.product_package_id;
  IF s.device_fingerprint_hash IS NOT NULL AND s.device_fingerprint_hash IS DISTINCT FROM p_device->>'fingerprintHash' THEN
    RAISE EXCEPTION 'akamap_device_locked';
  END IF;
  UPDATE public.org_staff SET device_fingerprint_hash=p_device->>'fingerprintHash',
    device_label=p_device->>'label',device_platform=p_device->>'platform',
    device_bound_at=CASE WHEN s.device_fingerprint_hash IS NULL THEN stamp ELSE s.device_bound_at END,
    device_last_seen_at=stamp,updated_at=stamp
    WHERE id=s.id RETURNING * INTO s;

  -- Explicit projection: never return password, arbitrary staff fields or tokens.
  RETURN jsonb_build_object(
    'staff',jsonb_build_object('id',s.id,'organization_id',s.organization_id,
      'name',s.name,'phone',s.phone,'username',s.username,'is_active',s.is_active,
      'device_label',s.device_label,'device_platform',s.device_platform,
      'device_bound_at',s.device_bound_at,'device_last_seen_at',s.device_last_seen_at),
    'subscription',jsonb_build_object('id',subscription.id,'product_id',subscription.product_id,
      'product_name',subscription.product_name,'purchase_date',subscription.purchase_date,
      'trial_start_date',subscription.trial_start_date,'expiration_date',subscription.expiration_date,
      'created_at',subscription.created_at,'package_type',coalesce(nullif(subscription.package_type,''),package_kind)),
    'serverTime',stamp);
END;
$function$

CREATE OR REPLACE FUNCTION public.append_auto_campaign_log(p_campaign_id bigint, p_staff_id bigint, p_log_line text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
 v_log text:=p_log_line;
 v_marker constant text:=' … [nội dung quá dài đã được rút gọn]';
BEGIN
 IF p_campaign_id IS NULL OR p_campaign_id<=0 THEN RAISE EXCEPTION 'Campaign ID must be a positive integer'; END IF;
 IF p_staff_id IS NULL OR p_staff_id<=0 THEN RAISE EXCEPTION 'Staff ID must be a positive integer'; END IF;
 IF nullif(btrim(coalesce(v_log,'')),'') IS NULL THEN RAISE EXCEPTION 'Campaign log line must not be empty'; END IF;
 IF char_length(v_log)>16000 THEN v_log:=left(v_log,16000-char_length(v_marker))||v_marker; END IF;
 -- All writers acquire this lock before identity allocation. A later cursor
 -- can therefore never jump over an earlier uncommitted append for this campaign.
 PERFORM pg_advisory_xact_lock(hashtextextended('auto_campaign_logs:'||p_campaign_id::text,0));
 IF NOT EXISTS (SELECT 1 FROM public.auto_campaigns c WHERE c.id=p_campaign_id AND c.staff_id=p_staff_id AND coalesce(c.is_delete,false)=false)
 THEN RAISE EXCEPTION 'Active campaign % was not found',p_campaign_id; END IF;
 INSERT INTO public.auto_campaign_logs(campaign_id,log) VALUES(p_campaign_id,v_log);
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.apply_renewal_crm_group(p_group jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_day date := (pg_catalog.statement_timestamp() at time zone 'Asia/Ho_Chi_Minh')::date;
  v_start timestamptz;
  v_customer_id bigint;
  v_owner_id bigint;
  v_type bigint;
  v_customer public.aka_customer%rowtype;
  v_crm public.aka_crm%rowtype;
  v_source_order public.aka_order%rowtype;
  v_org_product public.org_organization_product%rowtype;
  v_org public.org_organization%rowtype;
  v_primary jsonb;
  v_event jsonb;
  v_source jsonb;
  v_meta jsonb;
  v_renewal_meta jsonb;
  v_all_keys text[] := '{}';
  v_pending_keys text[] := '{}';
  v_pending_events jsonb := '[]';
  v_ledger jsonb;
  v_key text;
  v_alias text;
  v_alias_key text;
  v_kind text;
  v_prefix text;
  v_expiry date;
  v_offset integer;
  v_covered_offset integer;
  v_day_count integer;
  v_matched_id bigint;
  v_owner_count integer;
  v_current_order_owner bigint;
  v_sql_account bigint;
  v_org_product_id bigint;
  v_order_id bigint;
  v_processed boolean;
  v_event_pending boolean;
  v_created boolean := false;
  v_note text;
  v_reason text;
  v_schedule jsonb;
  v_paid_effective date;
  v_preserve_crm_through_id bigint;
begin
  if current_user not in ('postgres','supabase_admin','service_role') then
    raise exception 'renewal_crm_service_role_required' using errcode='42501';
  end if;
  if not exists(select 1 from public.aka_app_settings where key='renewal_crm' and value->>'enabled'='true') then
    return jsonb_build_object('status','disabled','reason','renewal_crm_disabled','applied_event_keys','[]'::jsonb);
  end if;
  v_schedule := public.renewal_crm_schedule();
  if coalesce(v_schedule->>'paid_effective_from','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
     or coalesce(v_schedule->>'preserve_crm_through_id','') !~ '^[0-9]+$' then
    return jsonb_build_object('status','review','reason','renewal_paid_schedule_not_activated','applied_event_keys','[]'::jsonb);
  end if;
  v_paid_effective := (v_schedule->>'paid_effective_from')::date;
  v_preserve_crm_through_id := (v_schedule->>'preserve_crm_through_id')::bigint;
  if p_group->>'paidEffectiveFrom' is distinct from v_paid_effective::text
     or p_group->>'preserveCrmThroughId' is distinct from v_preserve_crm_through_id::text then
    return jsonb_build_object('status','review','reason','renewal_paid_schedule_transition_mismatch','applied_event_keys','[]'::jsonb);
  end if;
  if jsonb_typeof(p_group) is distinct from 'object' or p_group->>'day' is distinct from v_day::text
     or coalesce(p_group->>'customerId','') !~ '^[1-9][0-9]{0,15}$'
     or coalesce(p_group->>'ownerId','') !~ '^[1-9][0-9]{0,15}$'
     or coalesce(p_group->>'crmTypeId','') not in ('3','4')
     or jsonb_typeof(p_group->'events') is distinct from 'array'
     or jsonb_typeof(p_group->'eventKeys') is distinct from 'array' then
    return jsonb_build_object('status','review','reason','invalid_group_or_noncurrent_day','applied_event_keys','[]'::jsonb);
  end if;
  if jsonb_array_length(p_group->'events') not between 1 and 100
     or jsonb_array_length(p_group->'eventKeys') not between 1 and 600 then
    return jsonb_build_object('status','review','reason','invalid_group_size','applied_event_keys','[]'::jsonb);
  end if;
  v_customer_id := (p_group->>'customerId')::bigint;
  v_owner_id := (p_group->>'ownerId')::bigint;
  v_type := (p_group->>'crmTypeId')::bigint;
  v_primary := p_group->'primary';
  if v_primary is distinct from p_group->'events'->0
     or v_primary->>'ownerId' is distinct from p_group->>'ownerId'
     or v_primary->>'crmTypeId' is distinct from p_group->>'crmTypeId' then
    return jsonb_build_object('status','review','reason','invalid_group_primary','applied_event_keys','[]'::jsonb);
  end if;
  v_start := v_day::timestamp at time zone 'Asia/Ho_Chi_Minh';
  -- Same lock is taken by every INSERT path, including manual writes.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('renewal-crm-customer:'||v_customer_id,0));
  select * into v_customer from public.aka_customer where id=v_customer_id for share;
  if not found or v_customer.record_state is distinct from 'verified' or v_customer.merged_into_customer_id is not null then
    return jsonb_build_object('status','review','reason','customer_unverified_or_merged','applied_event_keys','[]'::jsonb);
  end if;
  perform 1 from public.org_staff where id=v_owner_id and is_active and deleted_at is null for share;
  if not found then return jsonb_build_object('status','review','reason','owner_inactive','applied_event_keys','[]'::jsonb); end if;

  for v_event in select value from jsonb_array_elements(p_group->'events') loop
    v_source := v_event->'source';
    v_kind := case v_event->>'crmTypeId' when '4' then 'paid' when '3' then 'demo' end;
    if v_event->>'customerId' is distinct from p_group->>'customerId'
       or coalesce(v_event->>'entitlementKey','') !~ '^(sql|org|order):[1-9][0-9]{0,15}$'
       or coalesce(v_event->>'expirationDay','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
       or coalesce(v_event->>'dueDay','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
       or not (case when coalesce(v_event->>'offsetDays','') ~ '^-?[0-9]{1,3}$' then (v_event->>'offsetDays')::integer = any(public.renewal_crm_schedule_offsets(v_kind)) else false end)
       or v_kind is null
       or jsonb_typeof(v_event->'aliases') is distinct from 'array'
       or jsonb_typeof(v_event->'coveredEventKeys') is distinct from 'array'
       or jsonb_typeof(v_source) is distinct from 'object'
       or coalesce(v_source->>'kind','') not in ('sql_account','org_product','order')
       or coalesce(v_source->>'id','') !~ '^[1-9][0-9]{0,15}$'
       or v_source->>'customerId' is distinct from p_group->>'customerId'
       or v_source->>'expirationDay' is distinct from v_event->>'expirationDay'
       or v_source->>'ownerId' is distinct from v_event->>'ownerId'
       or v_source->>'ownerActive' is distinct from 'true'
       or v_source->>'paid' is distinct from (case when v_kind='paid' then 'true' else 'false' end) then
      return jsonb_build_object('status','review','reason','invalid_event','applied_event_keys','[]'::jsonb);
    end if;
    v_expiry := (v_event->>'expirationDay')::date;
    v_offset := (v_event->>'offsetDays')::integer;
    if v_expiry+v_offset <> (v_event->>'dueDay')::date
       or (v_event->>'dueDay')::date > v_day
       or not (v_event->'aliases' ? (v_event->>'entitlementKey'))
       or not (v_event->'aliases' ? ((case v_source->>'kind' when 'sql_account' then 'sql:' when 'org_product' then 'org:' else 'order:' end)||(v_source->>'id'))) then
      return jsonb_build_object('status','review','reason','invalid_event_date_or_identity','applied_event_keys','[]'::jsonb);
    end if;
    if v_kind='paid' and (v_event->>'dueDay')::date < v_paid_effective then
      return jsonb_build_object('status','review','reason','paid_milestone_before_effective_day','applied_event_keys','[]'::jsonb);
    end if;
    if (v_event->>'dueDay')::date < v_day-7 and not exists (
      select 1 from public.aka_app_settings p where p.key='renewal:pending:'||(v_event->>'entitlementKey')
        and p.value->>'status'='pending' and p.value->>'customer_id'=v_customer_id::text
        and p.value->>'expiration_day'=v_event->>'expirationDay'
        and p.value->>'event_key'=v_event->>'eventKey') and not exists (
      select 1 from public.aka_app_settings l where l.key='renewal:event:'||(v_event->>'eventKey')
        and l.value->>'applied'='true' and l.value->>'customer_id'=v_customer_id::text
        and exists(select 1 from public.aka_crm c where c.id=(l.value->>'crm_id')::bigint and c.customer_id=v_customer_id and c.crm_type_id in (3,4))) then
      return jsonb_build_object('status','review','reason','old_event_requires_durable_pending','applied_event_keys','[]'::jsonb);
    end if;
    v_prefix := 'renewal_crm_v1:'||(v_event->>'entitlementKey')||':'||v_expiry||':'||v_kind||':';
    if v_event->>'eventKey' is distinct from v_prefix||v_offset
       or v_event->>'cycleKey' is distinct from (v_event->>'entitlementKey')||':'||v_expiry||':'||v_kind
       or not (v_event->'coveredEventKeys' ? (v_event->>'eventKey')) then
      return jsonb_build_object('status','review','reason','invalid_event_key','applied_event_keys','[]'::jsonb);
    end if;
    perform 1 from public.org_staff where id=(v_event->>'ownerId')::bigint and is_active and deleted_at is null for share;
    if not found then return jsonb_build_object('status','review','reason','event_owner_inactive','applied_event_keys','[]'::jsonb); end if;
    v_sql_account := null; v_org_product_id := null; v_order_id := null;
    for v_alias in select value from jsonb_array_elements_text(v_event->'aliases') loop
      if v_alias !~ '^(sql|org|order):[1-9][0-9]{0,15}$' then
        return jsonb_build_object('status','review','reason','invalid_alias','applied_event_keys','[]'::jsonb);
      end if;
      if v_alias like 'sql:%' then v_sql_account := split_part(v_alias,':',2)::bigint; end if;
      if v_alias like 'org:%' then v_org_product_id := split_part(v_alias,':',2)::bigint; end if;
      if v_alias like 'order:%' then v_order_id := split_part(v_alias,':',2)::bigint; end if;
    end loop;
    -- Direct SQL state is rechecked by the server immediately before this RPC. Native
    -- organization/order state is locked and checked here in the CRM transaction.
    if v_source->>'kind'='org_product' then
      select * into v_org_product from public.org_organization_product where id=(v_source->>'id')::bigint for share;
      if not found or v_org_product.is_deleted or v_org_product.is_lock
         or (v_org_product.expiration_date at time zone 'Asia/Ho_Chi_Minh')::date is distinct from v_expiry
         or (case when v_org_product.is_paid then 'paid'
              when lower(btrim(coalesce(v_org_product.package_type,'')))='demo' then 'demo' when lower(btrim(coalesce(v_org_product.package_type,''))) ~ '^[0-9]*(month|year)$' then 'paid' end) is distinct from v_kind then
        return jsonb_build_object('status','review','reason','org_entitlement_changed','applied_event_keys','[]'::jsonb);
      end if;
      select * into v_org from public.org_organization where id=v_org_product.organization_id for share;
      if not found or v_org.customer_id<>v_customer_id or v_org.staff_id_owner<>(v_event->>'ownerId')::bigint then
        return jsonb_build_object('status','review','reason','org_identity_or_owner_changed','applied_event_keys','[]'::jsonb);
      end if;
      v_org_product_id := v_org_product.id;
    elsif v_source->>'kind'='order' then
      select * into v_source_order from public.aka_order where id=(v_source->>'id')::bigint for share;
      if not found or v_source_order.customer_id is distinct from v_customer_id or coalesce(v_source_order.is_deleted,false) or coalesce(v_source_order.is_lock,false)
         or (v_source_order.date_expiration at time zone (case when v_source_order.source_system='sql_account' then 'UTC' else 'Asia/Ho_Chi_Minh' end))::date is distinct from v_expiry
         or ((v_source_order.is_paid or (v_source_order.is_demo=false and lower(btrim(coalesce(v_source_order.package_type,v_source_order.package,''))) in ('month','year')))
             and (v_source_order.is_demo or lower(btrim(coalesce(v_source_order.package_type,v_source_order.package,'')))='demo'))
         or (case when v_source_order.is_paid or (v_source_order.is_demo=false and lower(btrim(coalesce(v_source_order.package_type,v_source_order.package,''))) in ('month','year')) then 'paid'
              when v_source_order.is_demo or lower(btrim(coalesce(v_source_order.package_type,v_source_order.package,'')))='demo' then 'demo' end) is distinct from v_kind then
        return jsonb_build_object('status','review','reason','order_entitlement_changed','applied_event_keys','[]'::jsonb);
      end if;
      perform 1 from public.org_staff s where s.sql_staff_id=v_source_order.staff_manage_id_old
        or s.id=v_source_order.org_staff_id or s.chat_staff_id=v_source_order.staff_id for share;
      v_current_order_owner := (private.aka_order_owner_state(v_source_order)->>'ownerId')::bigint;
      if v_current_order_owner is distinct from (v_event->>'ownerId')::bigint then
        return jsonb_build_object('status','review','reason','order_owner_changed_or_ambiguous','applied_event_keys','[]'::jsonb);
      end if;
      v_order_id := v_source_order.id;
    elsif v_source->>'kind' = 'sql_account' then
      -- The service checks fresh SQL entitlement facts. Fence a concurrent aka transfer in this transaction.
      for v_source_order in select * from public.aka_order where account_id_old=(v_source->>'id')::bigint
        or (source_system='sql_account' and source_record_id=(v_source->>'id')::bigint) for share loop
        if v_source_order.org_staff_id is not null and (private.aka_order_owner_state(v_source_order)->>'ownerId')::bigint is distinct from (v_event->>'ownerId')::bigint then
          return jsonb_build_object('status','review','reason','aka_owner_changed','applied_event_keys','[]'::jsonb);
        end if;
      end loop;
    else
      return jsonb_build_object('status','review','reason','invalid_source_kind','applied_event_keys','[]'::jsonb);
    end if;
    v_reason := private.crm_product_transition_reason(v_customer.custom_fields,v_order_id,v_sql_account,v_org_product_id,v_expiry);
    if v_reason is not null then return jsonb_build_object('status','review','reason',v_reason,'applied_event_keys','[]'::jsonb); end if;
    if v_kind='demo' and public.demo_care_should_skip_v1(v_customer_id,3,null,v_order_id) then
      return jsonb_build_object('status','review','reason','demo_care_managed_customer','applied_event_keys','[]'::jsonb);
    end if;
    v_event_pending := false;
    for v_key in select value from jsonb_array_elements_text(v_event->'coveredEventKeys') loop
      if v_key not like v_prefix||'%' or not (case when split_part(v_key,':',6) ~ '^-?[0-9]{1,3}$' then split_part(v_key,':',6)::integer = any(public.renewal_crm_schedule_offsets(v_kind)) else false end) then
        return jsonb_build_object('status','review','reason','invalid_covered_key','applied_event_keys','[]'::jsonb);
      end if;
      v_covered_offset := split_part(v_key,':',6)::integer;
      if v_kind='paid' and v_expiry+v_covered_offset < v_paid_effective then
        return jsonb_build_object('status','review','reason','paid_covered_milestone_before_effective_day','applied_event_keys','[]'::jsonb);
      end if;
      if v_key<>v_prefix||v_covered_offset or v_covered_offset>v_offset then
        return jsonb_build_object('status','review','reason','invalid_covered_milestone','applied_event_keys','[]'::jsonb);
      end if;
      v_all_keys := array_append(v_all_keys,v_key);
      v_processed := false;
      for v_alias in select value from jsonb_array_elements_text(v_event->'aliases') loop
        v_alias_key := 'renewal_crm_v1:'||v_alias||':'||v_expiry||':'||v_kind||':'||v_covered_offset;
        select value into v_ledger from public.aka_app_settings where key='renewal:event:'||v_alias_key;
        if found then
          if v_ledger->>'applied' is distinct from 'true' or v_ledger->>'customer_id' is distinct from v_customer_id::text
             or (v_ledger->>'crm_deleted_at' is null and not exists(select 1 from public.aka_crm where id=(v_ledger->>'crm_id')::bigint and customer_id=v_customer_id and crm_type_id in (3,4))) then
            return jsonb_build_object('status','review','reason','ledger_target_missing_or_changed','event_key',v_alias_key,'applied_event_keys','[]'::jsonb);
          end if;
          v_processed := true;
        end if;
      end loop;
      if not v_processed then v_pending_keys:=array_append(v_pending_keys,v_key); v_event_pending:=true; end if;
    end loop;
    if v_event_pending then v_pending_events:=v_pending_events||jsonb_build_array(v_event); end if;
  end loop;
  if (select array_agg(distinct k order by k) from unnest(v_all_keys) k)
       is distinct from (select array_agg(distinct k order by k) from jsonb_array_elements_text(p_group->'eventKeys') k) then
    return jsonb_build_object('status','review','reason','group_event_keys_mismatch','applied_event_keys','[]'::jsonb);
  end if;
  if cardinality(v_pending_keys)=0 then
    -- A slower overlapping runner may have saved pending again after the first apply.
    -- Repair only a matching cycle/milestone with a verified existing ledger target.
    for v_event in select value from jsonb_array_elements(p_group->'events') loop
      select (l.value->>'crm_id')::bigint into v_matched_id from public.aka_app_settings l
        where l.key='renewal:event:'||(v_event->>'eventKey') and l.value->>'applied'='true'
          and l.value->>'customer_id'=v_customer_id::text;
      if v_matched_id is not null then
        update public.aka_app_settings set value=value||jsonb_build_object('status','applied','applied',true,
            'crm_id',v_matched_id,'processed_at',pg_catalog.statement_timestamp()),updated_at=pg_catalog.statement_timestamp()
          where key='renewal:pending:'||(v_event->>'entitlementKey') and value->>'status'='pending'
            and value->>'customer_id'=v_customer_id::text and value->>'expiration_day'=v_event->>'expirationDay'
            and v_event->'coveredEventKeys' ? (value->>'event_key');
      end if;
    end loop;
    return jsonb_build_object('status','already_applied','crm_id',v_matched_id,'applied_event_keys','[]'::jsonb);
  end if;

  select count(*) into v_day_count from public.aka_crm c where c.customer_id=v_customer_id and c.crm_type_id in (3,4) and not public.renewal_crm_is_archived(c.gen_meta)
    and ((c.created_at>=v_start and c.created_at<v_start+interval '1 day')
      or (c.cskh_due_date>=v_start and c.cskh_due_date<v_start+interval '1 day')
      or c.gen_meta#>>'{renewal_v1,last_work_day}'=v_day::text);
  if v_day_count>1 then return jsonb_build_object('status','review','reason','existing_daily_duplicates','applied_event_keys','[]'::jsonb); end if;
  if v_day_count=1 then
    select * into v_crm from public.aka_crm c where c.customer_id=v_customer_id and c.crm_type_id in (3,4) and not public.renewal_crm_is_archived(c.gen_meta)
      and ((c.created_at>=v_start and c.created_at<v_start+interval '1 day')
        or (c.cskh_due_date>=v_start and c.cskh_due_date<v_start+interval '1 day')
        or c.gen_meta#>>'{renewal_v1,last_work_day}'=v_day::text) for update;
    if v_crm.id <= v_preserve_crm_through_id then
      return jsonb_build_object('status','deferred','reason','existing_crm_preserved_at_schedule_transition',
        'crm_id',v_crm.id,'applied_event_keys','[]'::jsonb);
    end if;
    if v_crm.org_staff_owner_id is distinct from v_owner_id then
      return jsonb_build_object('status','review','reason','existing_crm_owner_mismatch','crm_id',v_crm.id,'applied_event_keys','[]'::jsonb);
    end if;
    if v_crm.cskh_completed_date is not null or v_crm.contacted_channel_id is not null
       or cardinality(v_crm.contacted_channel_ids)>0 or v_crm.last_sent_at is not null or v_crm.last_sms_at is not null
       or v_crm.purchase_date is not null or v_crm.decline_date is not null or v_crm.error_date is not null
       or v_crm.unreachable_date is not null or v_crm.aka_call_id is not null
       or not (coalesce(v_crm.source_type,'') ~ '^(renewal_unified|expired|order_expir|org_product_expir)' or v_crm.sql_account_id is not null) then
      return jsonb_build_object('status','deferred','reason','today_crm_closed_contacted_or_manual','crm_id',v_crm.id,'applied_event_keys','[]'::jsonb);
    end if;
  else
    -- Reuse only an untouched open CRM for the same entitlement AND expiry cycle.
    select * into v_crm from public.aka_crm c where c.customer_id=v_customer_id and c.crm_type_id in (3,4) and not public.renewal_crm_is_archived(c.gen_meta)
      and c.id>v_preserve_crm_through_id
      and c.org_staff_owner_id=v_owner_id and c.cskh_completed_date is null
      and c.contacted_channel_id is null and coalesce(cardinality(c.contacted_channel_ids),0)=0
      and c.last_sent_at is null and c.last_sms_at is null and c.purchase_date is null
      and c.decline_date is null and c.error_date is null and c.unreachable_date is null and c.aka_call_id is null
      and c.source_expiration_date=(v_primary->>'expirationDay')::date
      and ((v_primary->'aliases' ? ('sql:'||c.sql_account_id))
        or (v_primary->'aliases' ? ('org:'||c.org_organization_product_id))
        or (v_primary->'aliases' ? ('order:'||c.source_order_id)))
      and (coalesce(c.source_type,'') ~ '^(renewal_unified|expired|order_expir|org_product_expir)' or c.sql_account_id is not null)
      order by c.created_at desc,c.id desc limit 1 for update;
  end if;
  v_meta := coalesce(v_crm.gen_meta,'{}'::jsonb);
  v_renewal_meta := coalesce(v_meta->'renewal_v1','{}'::jsonb);
  if jsonb_typeof(v_meta)<>'object' or jsonb_typeof(v_renewal_meta)<>'object'
      or (v_renewal_meta ? 'events' and jsonb_typeof(v_renewal_meta->'events')<>'array')
      or (v_renewal_meta ? 'event_keys' and jsonb_typeof(v_renewal_meta->'event_keys')<>'array') then
    return jsonb_build_object('status','review','reason','existing_renewal_metadata_invalid','applied_event_keys','[]'::jsonb);
  end if;
  v_renewal_meta := v_renewal_meta||jsonb_build_object('version','renewal_crm_v1','last_work_day',v_day,
    'owner_id',v_owner_id,'primary',v_primary,'updated_at',pg_catalog.statement_timestamp(),
    'events',coalesce(v_renewal_meta->'events','[]'::jsonb)||v_pending_events,
    'event_keys',(select jsonb_agg(distinct k order by k) from (
      select value as k from jsonb_array_elements_text(coalesce(v_renewal_meta->'event_keys','[]'::jsonb))
      union all select unnest(v_pending_keys)) keys));
  v_meta := v_meta||jsonb_build_object('renewal_v1',v_renewal_meta);
  select string_agg(format('- %s | %s | Hết hạn: %s | Mốc: %s ngày | Quản lý: %s',
      e->>'product',e->>'entitlementKey',e->>'expirationDay',e->>'offsetDays',e->>'ownerId'),E'\n') into v_note
      from jsonb_array_elements(v_pending_events) e;
  v_note := '[Chăm sóc gia hạn '||v_day||']'||E'\n'||v_note;
  if v_crm.id is null then
    v_sql_account:=null; v_org_product_id:=null;
    select split_part(value,':',2)::bigint into v_sql_account from jsonb_array_elements_text(v_primary->'aliases') where value like 'sql:%' limit 1;
    select split_part(value,':',2)::bigint into v_org_product_id from jsonb_array_elements_text(v_primary->'aliases') where value like 'org:%' limit 1;
    insert into public.aka_crm(customer_id,customer_name,customer_phone,crm_type_id,org_staff_owner_id,
      organization_id,source_type,source_order_id,sql_account_id,org_organization_product_id,
      source_expiration_date,source_expiration_source,cskh_due_date,is_read,priority,suggested_channel_id,note,gen_meta)
    values(v_customer_id,v_customer.name,v_customer.phone,v_type,v_owner_id,
      nullif(p_group->>'organizationId','')::bigint,'renewal_unified',null,v_sql_account,v_org_product_id,
      (v_primary->>'expirationDay')::date,'renewal_unified_snapshot',v_start+interval '17 hours',false,1,10,v_note,v_meta)
    returning * into v_crm;
    v_created:=true;
  else
    update public.aka_crm set cskh_due_date=v_start+interval '17 hours',is_read=false,
      note=concat_ws(E'\n\n',nullif(note,''),v_note),gen_meta=v_meta
    where id=v_crm.id returning * into v_crm;
  end if;
  -- Record each explicit source alias too: a later source sync cannot resurrect the event.
  for v_event in select value from jsonb_array_elements(v_pending_events) loop
    for v_key in select value from jsonb_array_elements_text(v_event->'coveredEventKeys') loop
      if not (v_key=any(v_pending_keys)) then continue; end if;
      for v_alias in select value from jsonb_array_elements_text(v_event->'aliases') loop
        v_alias_key := 'renewal_crm_v1:'||v_alias||':'||(v_event->>'expirationDay')||':'||case when v_event->>'crmTypeId'='4' then 'paid' else 'demo' end||':'||split_part(v_key,':',6);
        insert into public.aka_app_settings(key,value,updated_at) values('renewal:event:'||v_alias_key,
          jsonb_build_object('applied',true,'crm_id',v_crm.id,'customer_id',v_customer_id,'processed_at',pg_catalog.statement_timestamp(),
            'work_day',v_day,'event_key',v_alias_key,'canonical_event_key',v_key,'event',v_event),pg_catalog.statement_timestamp());
      end loop;
    end loop;
    update public.aka_app_settings set value=value||jsonb_build_object('status','applied','crm_id',v_crm.id,
        'applied',true,'processed_at',pg_catalog.statement_timestamp()),updated_at=pg_catalog.statement_timestamp()
      where key='renewal:pending:'||(v_event->>'entitlementKey')
        and value->>'status'='pending' and value->>'customer_id'=v_customer_id::text
        and value->>'expiration_day'=v_event->>'expirationDay'
        and v_event->'coveredEventKeys' ? (value->>'event_key');
  end loop;
  return jsonb_build_object('status',case when v_created then 'created' else 'updated' end,
    'crm_id',v_crm.id,'applied_event_keys',to_jsonb(v_pending_keys));
exception
  when others then
    -- The subtransaction rolls back CRM, metadata, ledger, and all DB trigger effects.
    return jsonb_build_object('status','review','reason','transaction_rolled_back','sqlstate',sqlstate,
      'error',left(sqlerrm,240),'applied_event_keys','[]'::jsonb);
end $function$

CREATE OR REPLACE FUNCTION public.archive_renewal_crm_duplicates_v1(p_manifest jsonb, p_apply boolean DEFAULT false, p_expected jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_batch constant text := 'renewal-crm-duplicates-20260909';
  v_pair record; v_c public.aka_crm%rowtype; v_d public.aka_crm%rowtype;
  v_expected jsonb := '{}'; v_time timestamptz := pg_catalog.statement_timestamp();
  v_total integer; v_archived integer := 0; v_pending integer := 0; v_key text; v_backup jsonb; v_c_meta jsonb; v_d_meta jsonb;
begin
  if current_user not in ('postgres','supabase_admin','service_role') then raise exception 'renewal_archive_service_role_required' using errcode='42501'; end if;
  if jsonb_typeof(p_manifest) is distinct from 'array' then raise exception 'renewal_archive_invalid_manifest'; end if;
  v_total := jsonb_array_length(p_manifest);
  if v_total not between 1 and 200 or exists(select 1 from public.renewal_crm_duplicate_manifest_v1(p_manifest) p
    where coalesce(p.canonical_id,0)<=0 or coalesce(p.duplicate_id,0)<=0 or coalesce(p.customer_id,0)<=0
      or coalesce(p.order_id,0)<=0 or coalesce(p.org_product_id,0)<=0 or p.expiry is null
      or not coalesce((p.type_id=3 and p.order_milestone='order_expired_demo')
        or (p.type_id=4 and p.order_milestone in ('order_expiring_7d','order_expiring_3d','order_expired_paid')),false))
    or (select count(distinct id) from (select canonical_id id from public.renewal_crm_duplicate_manifest_v1(p_manifest)
      union all select duplicate_id from public.renewal_crm_duplicate_manifest_v1(p_manifest)) x)<>v_total*2 then
    raise exception 'renewal_archive_invalid_manifest';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_batch,0));
  -- Same customer lock order as the renewal writer, then stable row lock order.
  for v_pair in select distinct customer_id from public.renewal_crm_duplicate_manifest_v1(p_manifest) order by customer_id loop
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('renewal-crm-customer:'||v_pair.customer_id,0));
  end loop;
  perform 1 from public.aka_crm where id in (select canonical_id from public.renewal_crm_duplicate_manifest_v1(p_manifest) union select duplicate_id from public.renewal_crm_duplicate_manifest_v1(p_manifest)) order by id for update;
  perform 1 from public.aka_order where id in (select order_id from public.renewal_crm_duplicate_manifest_v1(p_manifest)) order by id for share;
  perform 1 from public.org_organization_product where id in (select org_product_id from public.renewal_crm_duplicate_manifest_v1(p_manifest)) order by id for share;
  perform 1 from public.org_organization where id in (select p.organization_id from public.org_organization_product p join public.renewal_crm_duplicate_manifest_v1(p_manifest) m on p.id=m.org_product_id) order by id for share;
  perform 1 from public.org_staff where id in (select c.org_staff_owner_id from public.aka_crm c join public.renewal_crm_duplicate_manifest_v1(p_manifest) m on c.id=m.canonical_id) order by id for share;
  for v_pair in select * from public.renewal_crm_duplicate_manifest_v1(p_manifest) order by duplicate_id loop
    select * into v_c from public.aka_crm where id=v_pair.canonical_id;
    if not found then raise exception 'renewal_archive_canonical_missing:%',v_pair.canonical_id; end if;
    select * into v_d from public.aka_crm where id=v_pair.duplicate_id;
    if not found then raise exception 'renewal_archive_duplicate_missing:%',v_pair.duplicate_id; end if;
    if (v_d.cskh_completed_date is not null and v_c.cskh_completed_date is null)
      or (v_c.cskh_completed_date is null and not exists (
        select 1 from public.org_organization_product p join public.org_organization o on o.id=p.organization_id
          join public.org_staff s on s.id=o.staff_id_owner
        where p.id=v_pair.org_product_id and s.id=v_c.org_staff_owner_id and s.is_active and s.deleted_at is null)) then
      raise exception 'renewal_archive_survivor_care_or_owner_changed:%',v_pair.duplicate_id;
    end if;
    if (v_c.gen_meta is not null and jsonb_typeof(v_c.gen_meta)<>'object')
      or (v_d.gen_meta is not null and jsonb_typeof(v_d.gen_meta)<>'object') then
      raise exception 'renewal_archive_invalid_existing_metadata:%',v_pair.duplicate_id;
    end if;
    if v_c.customer_id is distinct from v_pair.customer_id or v_d.customer_id is distinct from v_pair.customer_id
      or v_c.crm_type_id is distinct from v_pair.type_id or v_d.crm_type_id is distinct from v_pair.type_id
      or v_c.org_organization_product_id is distinct from v_pair.org_product_id or v_d.source_order_id is distinct from v_pair.order_id
      or v_d.source_type is distinct from v_pair.order_milestone
      or v_c.source_type is distinct from replace(v_pair.order_milestone,'order_','org_product_')
      or v_c.source_expiration_date is distinct from v_pair.expiry or v_d.source_expiration_date is distinct from v_pair.expiry
      or not exists(select 1 from public.aka_order o where o.id=v_pair.order_id and o.customer_id=v_pair.customer_id
        and coalesce(o.org_organization_product_id,case when o.source_system='org_product' then o.source_record_id end)=v_pair.org_product_id)
      or not exists(select 1 from public.org_organization_product p join public.org_organization o on o.id=p.organization_id
        where p.id=v_pair.org_product_id and o.customer_id=v_pair.customer_id) then
      raise exception 'renewal_archive_identity_changed:%',v_pair.duplicate_id;
    end if;
    v_expected := v_expected || jsonb_build_object(v_c.id::text,md5((to_jsonb(v_c)-'updated_at')::text),v_d.id::text,md5((to_jsonb(v_d)-'updated_at')::text));
    if v_d.cskh_completed_date is null then v_pending:=v_pending+1; end if;
    v_key := 'renewal:duplicate:20260909:'||v_pair.duplicate_id;
    if public.renewal_crm_is_archived(v_d.gen_meta) then
      select value into v_backup from public.aka_app_settings where key=v_key;
      if v_d.gen_meta#>>'{renewal_duplicate_v1,batch_id}' is distinct from v_batch
        or v_d.gen_meta#>>'{renewal_duplicate_v1,canonical_crm_id}' is distinct from v_c.id::text
        or v_c.gen_meta#>>'{renewal_duplicate_v1,batch_id}' is distinct from v_batch
        or v_c.gen_meta#>>'{renewal_duplicate_v1,archived}' is distinct from 'false'
        or not coalesce(v_c.gen_meta#>'{renewal_duplicate_v1,duplicate_crm_ids}' @> jsonb_build_array(v_d.id),false)
        or v_backup->>'status' is distinct from 'archived' or v_backup->>'manifest_hash' is distinct from md5(p_manifest::text) then raise exception 'renewal_archive_partial_or_changed:%',v_d.id; end if;
      v_archived:=v_archived+1;
    elsif v_c.gen_meta ? 'renewal_duplicate_v1' or v_d.gen_meta ? 'renewal_duplicate_v1'
      or exists(select 1 from public.aka_app_settings where key=v_key) then
      raise exception 'renewal_archive_existing_metadata_or_backup:%',v_d.id;
    end if;
  end loop;
  if v_archived=v_total then return jsonb_build_object('status','already_archived','batch_id',v_batch,'archived',v_total,'preserved',v_total*2); end if;
  if v_archived<>0 then raise exception 'renewal_archive_partial_batch'; end if;
  if not coalesce(p_apply,false) then return jsonb_build_object('status','preview','batch_id',v_batch,'pairs',v_total,'rows',v_total*2,'manifest_hash',md5(p_manifest::text),'pending_duplicates',v_pending,'expected',v_expected); end if;
  if p_expected is distinct from v_expected then raise exception 'renewal_archive_preview_changed' using errcode='40001'; end if;
  perform pg_catalog.set_config('app.renewal_duplicate_archive_authorized','true',true);
  for v_pair in select * from public.renewal_crm_duplicate_manifest_v1(p_manifest) order by duplicate_id loop
    select * into v_c from public.aka_crm where id=v_pair.canonical_id;
    select * into v_d from public.aka_crm where id=v_pair.duplicate_id;
    v_c_meta := jsonb_build_object('archived',false,'duplicate_crm_ids',jsonb_build_array(v_d.id),'batch_id',v_batch,'archived_at',v_time);
    v_d_meta := jsonb_build_object('archived',true,'canonical_crm_id',v_c.id,'batch_id',v_batch,'archived_at',v_time,'reason','same_entitlement_cycle_milestone','original_source_type',v_d.source_type);
    insert into public.aka_app_settings(key,value) values('renewal:duplicate:20260909:'||v_d.id,
      jsonb_build_object('version',1,'batch_id',v_batch,'manifest_hash',md5(p_manifest::text),'status','archived','archived_at',v_time,'canonical_id',v_c.id,'duplicate_id',v_d.id,
        'canonical_original',to_jsonb(v_c),'duplicate_original',to_jsonb(v_d),'expected',jsonb_build_object(v_c.id::text,v_expected->v_c.id::text,v_d.id::text,v_expected->v_d.id::text)));
    update public.aka_crm set gen_meta=coalesce(gen_meta,'{}')||jsonb_build_object('renewal_duplicate_v1',v_c_meta) where id=v_c.id;
    update public.aka_crm set gen_meta=coalesce(gen_meta,'{}')||jsonb_build_object('renewal_duplicate_v1',v_d_meta) where id=v_d.id;
  end loop;
  perform pg_catalog.set_config('app.renewal_duplicate_archive_authorized','false',true);
  return jsonb_build_object('status','archived','batch_id',v_batch,'archived',v_total,'preserved',v_total*2,'pending_duplicates_removed',v_pending);
end $function$

CREATE OR REPLACE FUNCTION public.auto_assert_automation_identity(p_staff_id bigint, p_organization_id bigint, p_auth_username text, p_auth_password text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_claim_role text;
  v_claims jsonb;
BEGIN
  v_claim_role := NULLIF(current_setting('request.jwt.claim.role', true), '');

  IF v_claim_role IS NULL THEN
    BEGIN
      v_claims := NULLIF(
        current_setting('request.jwt.claims', true),
        ''
      )::jsonb;
      v_claim_role := NULLIF(v_claims ->> 'role', '');
    EXCEPTION
      WHEN OTHERS THEN
        v_claim_role := NULL;
    END;
  END IF;

  IF v_claim_role IS NULL THEN
    v_claim_role := NULLIF(auth.jwt() ->> 'role', '');
  END IF;

  IF v_claim_role = 'service_role' THEN
    RETURN;
  END IF;

  IF p_auth_username IS NULL OR p_auth_password IS NULL THEN
    RAISE EXCEPTION 'automation_auth_required';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.org_staff AS staff
    WHERE staff.id = p_staff_id
      AND staff.organization_id = p_organization_id
      AND staff.is_active = true
      AND staff.username = p_auth_username
      AND staff.password = p_auth_password
  ) THEN
    RAISE EXCEPTION 'automation_auth_invalid';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.auto_capture_message_opt_out_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_meta jsonb := NEW.data -> 'messageOptOutSource';
  v_id uuid;
  v_sent_at timestamptz;
  v_global_id text;
  v_scope record;
BEGIN
  IF NEW.status IS DISTINCT FROM 'thành công' OR COALESCE(NEW.is_delete, false)
    OR NEW.action_code IS NULL OR NEW.action_code NOT IN ('zalo_message_friend', 'zalo_message_stranger')
    OR jsonb_typeof(v_meta) IS DISTINCT FROM 'object' OR v_meta ->> 'version' IS DISTINCT FROM '1' THEN
    RETURN NEW;
  END IF;
  -- Invalid optional metadata must never turn a delivered message into a failed result write.
  BEGIN
    v_id := (v_meta ->> 'optOutId')::uuid;
    v_sent_at := (v_meta ->> 'sentAt')::timestamptz;
  EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow THEN
    RETURN NEW;
  END;
  v_global_id := NULLIF(btrim(v_meta ->> 'zaloGlobalId'), '');
  IF v_id IS NULL OR v_sent_at IS NULL OR NOT isfinite(v_sent_at) OR v_global_id IS NULL
    OR v_global_id IS DISTINCT FROM NULLIF(btrim(NEW.data #>> '{target,globalId}'), '')
    OR NULLIF(btrim(NEW.data #>> '{target,uid}'), '') IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT c.staff_id, c.organization_id, c.name, i.email INTO v_scope
  FROM public.auto_campaigns c
  JOIN public.auto_accounts a ON a.id = c.account_id AND a.id = NEW.account_id
    AND a.staff_id = c.staff_id AND a.organization_id = c.organization_id AND a.flatform_type = 'zalo'
  JOIN public.auto_campaign_input_data i ON i.id = NEW.input_data_id AND i.campaign_id = c.id
  WHERE c.id = NEW.campaign_id AND c.action_id IN (
    'zalo_message_phone', 'zalo_message_friend', 'zalo_message_birthday',
    'zalo_message_group_member', 'zalo_message_group_realtime',
    'zalo_message_remarketing_customer', 'zalo_message_friend_recommendation'
  );
  IF NOT FOUND THEN RETURN NEW; END IF;

  -- UPDATE locks the same row as confirm; PostgreSQL rechecks these predicates after waiting.
  -- A delayed result may fill the as-of-confirmation source, but never a later delivery.
  UPDATE public.auto_zalo_message_opt_outs o SET
    source_campaign_id = NEW.campaign_id,
    source_campaign_name = v_scope.name,
    source_detail_id = NEW.id,
    source_sent_at = v_sent_at,
    source_action_name = NEW.action_name,
    source_status = NEW.status,
    zalo_name = NULLIF(btrim(v_meta ->> 'zaloName'), ''),
    zalo_avatar = NULLIF(btrim(v_meta ->> 'zaloAvatar'), ''),
    email = COALESCE(NULLIF(btrim(v_scope.email), ''), o.email)
  WHERE o.id = v_id AND o.staff_id = v_scope.staff_id AND o.organization_id = v_scope.organization_id
    AND o.zalo_global_id = v_global_id
    AND v_sent_at >= o.created_at
    AND (o.confirmed_at IS NULL OR v_sent_at <= o.confirmed_at)
    AND (o.source_sent_at IS NULL OR (v_sent_at, NEW.id) > (o.source_sent_at, o.source_detail_id));
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.auto_guard_send_exclusion_definition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE used boolean:=false; changed boolean:=false;
BEGIN
 IF TG_TABLE_NAME='auto_filter_fields' THEN
  SELECT EXISTS(SELECT 1 FROM public.auto_campaign_send_exclusion_rules WHERE field_id=OLD.id) INTO used;
  changed := (NEW.code,NEW.data_type,NEW.source_key,NEW.source_config,NEW.options_source,NEW.options_config) IS DISTINCT FROM (OLD.code,OLD.data_type,OLD.source_key,OLD.source_config,OLD.options_source,OLD.options_config);
 ELSIF TG_TABLE_NAME='auto_filter_operators' THEN
  SELECT EXISTS(SELECT 1 FROM public.auto_campaign_send_exclusion_rules WHERE operator_id=OLD.id) INTO used;
  changed := (NEW.code,NEW.evaluator_key) IS DISTINCT FROM (OLD.code,OLD.evaluator_key);
 ELSIF TG_TABLE_NAME='auto_filter_field_operators' THEN
  SELECT EXISTS(SELECT 1 FROM public.auto_campaign_send_exclusion_rules WHERE field_id=OLD.field_id AND operator_id=OLD.operator_id) INTO used;
  changed := NEW IS DISTINCT FROM OLD;
 ELSE
  SELECT EXISTS(SELECT 1 FROM public.auto_campaign_send_exclusion_rules WHERE field_id=OLD.field_id) INTO used;
  changed := (NEW.field_id,NEW.code,NEW.value) IS DISTINCT FROM (OLD.field_id,OLD.code,OLD.value);
 END IF;
 IF used AND changed THEN RAISE EXCEPTION 'send_exclusion_definition_in_use: create a versioned definition and explicitly migrate rules'; END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.auto_retry_automation_enqueue_failure_internal(p_failure_id bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_failure public.auto_automation_enqueue_failures%ROWTYPE;
  v_status text;
BEGIN
  SELECT *
  INTO v_failure
  FROM public.auto_automation_enqueue_failures AS failure
  WHERE failure.id = p_failure_id
  FOR UPDATE;

  IF NOT FOUND OR v_failure.status = 'resolved' THEN
    RETURN true;
  END IF;

  PERFORM set_config('aka_agent.automation_reconcile', 'on', true);
  PERFORM set_config(
    'aka_agent.automation_event_at',
    v_failure.event_at::text,
    true
  );

  -- UPDATE OF status deliberately re-enters the same trigger implementation.
  -- The session-local reconcile flag bypasses its no-change fast path.
  UPDATE public.auto_campaign_details AS detail
  SET status = detail.status
  WHERE detail.id = v_failure.source_campaign_detail_id;

  PERFORM set_config('aka_agent.automation_reconcile', 'off', true);
  PERFORM set_config('aka_agent.automation_event_at', '', true);

  SELECT failure.status
  INTO v_status
  FROM public.auto_automation_enqueue_failures AS failure
  WHERE failure.id = p_failure_id;

  RETURN v_status IS NULL OR v_status = 'resolved';
EXCEPTION
  WHEN OTHERS THEN
    PERFORM set_config('aka_agent.automation_reconcile', 'off', true);
    PERFORM set_config('aka_agent.automation_event_at', '', true);
    RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.auto_validate_campaign_send_exclusion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND NEW.extra_settings->'zaloSendExclusionsByAccountId' IS NOT DISTINCT FROM OLD.extra_settings->'zaloSendExclusionsByAccountId'
 AND NEW.account_id IS NOT DISTINCT FROM OLD.account_id AND NEW.staff_id IS NOT DISTINCT FROM OLD.staff_id AND NEW.organization_id IS NOT DISTINCT FROM OLD.organization_id THEN RETURN NEW; END IF;
 PERFORM public.aka_agent_internal_validate_send_exclusion_selection(NEW.extra_settings->'zaloSendExclusionsByAccountId',NEW.staff_id,NEW.organization_id,NEW.account_id);
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.capture_aka_crm_pancake_override_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_event jsonb := new.last_pancake_override_event;
  v_event_id uuid;
  v_event_id_text text;
  v_actor_org_staff_id bigint;
  v_actor record;
  v_operation text;
  v_action text;
  v_failure_code text;
  v_failure_reason text;
  v_page_id text;
  v_conversation_id text;
  v_pancake_staff_id text;
  v_inserted_id bigint;
  v_existing public.aka_crm_pancake_override_audit%rowtype;
begin
  if v_event is null then
    return new;
  end if;

  if tg_op = 'UPDATE'
     and v_event is not distinct from old.last_pancake_override_event then
    return new;
  end if;

  if pg_catalog.jsonb_typeof(v_event) is distinct from 'object' then
    raise exception using
      errcode = '22023',
      message = 'pancake_override_event_must_be_object';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_object_keys(v_event) as event_key(key)
    where event_key.key not in (
      'event_id',
      'actor_org_staff_id',
      'operation',
      'action',
      'failure_code',
      'failure_reason',
      'page_id',
      'conversation_id',
      'pancake_staff_id'
    )
  ) then
    raise exception using
      errcode = '22023',
      message = 'pancake_override_event_contains_unknown_keys';
  end if;

  if not (v_event ? 'event_id')
     or pg_catalog.jsonb_typeof(v_event -> 'event_id') is distinct from 'string' then
    raise exception using
      errcode = '22023',
      message = 'pancake_override_event_id_invalid';
  end if;

  v_event_id_text := v_event ->> 'event_id';
  begin
    v_event_id := v_event_id_text::uuid;
  exception
    when invalid_text_representation then
      raise exception using
        errcode = '22023',
        message = 'pancake_override_event_id_invalid';
  end;

  if v_event_id::text is distinct from pg_catalog.lower(v_event_id_text) then
    raise exception using
      errcode = '22023',
      message = 'pancake_override_event_id_must_be_canonical';
  end if;

  if not (v_event ? 'actor_org_staff_id')
     or pg_catalog.jsonb_typeof(v_event -> 'actor_org_staff_id') is distinct from 'number'
     or (v_event ->> 'actor_org_staff_id') !~ '^[1-9][0-9]*$' then
    raise exception using
      errcode = '22023',
      message = 'pancake_override_actor_org_staff_id_invalid';
  end if;

  begin
    v_actor_org_staff_id := (v_event ->> 'actor_org_staff_id')::bigint;
  exception
    when numeric_value_out_of_range then
      raise exception using
        errcode = '22023',
        message = 'pancake_override_actor_org_staff_id_invalid';
  end;

  if pg_catalog.jsonb_typeof(v_event -> 'operation') is distinct from 'string'
     or (v_event ->> 'operation') not in ('complete', 'purchase_edit') then
    raise exception using
      errcode = '22023',
      message = 'pancake_override_operation_invalid';
  end if;
  v_operation := v_event ->> 'operation';

  if pg_catalog.jsonb_typeof(v_event -> 'action') is distinct from 'string'
     or (v_event ->> 'action') not in ('interest', 'demo', 'negotiation', 'purchase', 'follow_up', 'research', 'unreachable') then
    raise exception using
      errcode = '22023',
      message = 'pancake_override_action_invalid';
  end if;
  v_action := v_event ->> 'action';

  if v_operation = 'purchase_edit' and v_action <> 'purchase' then
    raise exception using
      errcode = '22023',
      message = 'pancake_override_operation_action_invalid';
  end if;

  if pg_catalog.jsonb_typeof(v_event -> 'failure_code') is distinct from 'string'
     or (v_event ->> 'failure_code') not in (
       'PANCAKE_MESSAGE_REQUIRED',
       'PANCAKE_TEXT_MESSAGE_REQUIRED',
       'PANCAKE_TEXT_MESSAGE_TOO_SHORT',
       'PANCAKE_STAFF_ID_MISSING',
       'PANCAKE_VERIFICATION_UNAVAILABLE'
     ) then
    raise exception using
      errcode = '22023',
      message = 'pancake_override_failure_code_invalid';
  end if;
  v_failure_code := v_event ->> 'failure_code';

  if pg_catalog.jsonb_typeof(v_event -> 'failure_reason') is distinct from 'string' then
    raise exception using
      errcode = '22023',
      message = 'pancake_override_failure_reason_invalid';
  end if;
  v_failure_reason := v_event ->> 'failure_reason';
  if nullif(pg_catalog.btrim(v_failure_reason), '') is null
     or v_failure_reason is distinct from pg_catalog.btrim(v_failure_reason)
     or pg_catalog.octet_length(v_failure_reason) > 1000
     or v_failure_reason ~* '(https?://|page_access_token|access[[:space:]_-]*token|bearer[[:space:]])' then
    raise exception using
      errcode = '22023',
      message = 'pancake_override_failure_reason_invalid';
  end if;

  if v_event ? 'page_id'
     and pg_catalog.jsonb_typeof(v_event -> 'page_id') not in ('string', 'null') then
    raise exception using
      errcode = '22023',
      message = 'pancake_override_page_id_invalid';
  end if;
  v_page_id := v_event ->> 'page_id';
  if v_page_id is not null and v_page_id !~ '^[A-Za-z0-9_-]{1,255}$' then
    raise exception using
      errcode = '22023',
      message = 'pancake_override_page_id_invalid';
  end if;

  if v_event ? 'conversation_id'
     and pg_catalog.jsonb_typeof(v_event -> 'conversation_id') not in ('string', 'null') then
    raise exception using
      errcode = '22023',
      message = 'pancake_override_conversation_id_invalid';
  end if;
  v_conversation_id := v_event ->> 'conversation_id';
  if v_conversation_id is not null
     and v_conversation_id !~ '^[A-Za-z0-9_-]{1,255}$' then
    raise exception using
      errcode = '22023',
      message = 'pancake_override_conversation_id_invalid';
  end if;

  if v_event ? 'pancake_staff_id'
     and pg_catalog.jsonb_typeof(v_event -> 'pancake_staff_id') not in ('string', 'null') then
    raise exception using
      errcode = '22023',
      message = 'pancake_override_staff_id_invalid';
  end if;
  v_pancake_staff_id := v_event ->> 'pancake_staff_id';
  if v_pancake_staff_id is not null
     and v_pancake_staff_id !~ '^[A-Za-z0-9_-]{1,255}$' then
    raise exception using
      errcode = '22023',
      message = 'pancake_override_staff_id_invalid';
  end if;

  -- Express luôn ghi org_staff_updated_id trong cùng CAS update. Ràng buộc
  -- actor event với updater của chính dòng CRM để không thể chỉ thay một ID
  -- super admin bất kỳ trong JSON.
  if new.org_staff_updated_id is distinct from v_actor_org_staff_id then
    raise exception using
      errcode = '42501',
      message = 'pancake_override_actor_must_match_crm_updater';
  end if;

  -- Retry một event đã append phải độc lập với trạng thái live có thể thay đổi
  -- của actor (đổi tên/tổ chức/quyền). Chỉ payload bất biến và CRM snapshot
  -- quyết định idempotency; cùng UUID nhưng khác CRM/payload luôn fail closed.
  select audit.*
  into v_existing
  from public.aka_crm_pancake_override_audit as audit
  where audit.event_id = v_event_id;

  if found then
    if v_existing.crm_id_snapshot is distinct from new.id
       or v_existing.actor_org_staff_id_snapshot is distinct from v_actor_org_staff_id
       or v_existing.operation is distinct from v_operation
       or v_existing.action is distinct from v_action
       or v_existing.failure_code is distinct from v_failure_code
       or v_existing.failure_reason is distinct from v_failure_reason
       or v_existing.page_id is distinct from v_page_id
       or v_existing.conversation_id is distinct from v_conversation_id
       or v_existing.pancake_staff_id is distinct from v_pancake_staff_id then
      raise exception using
        errcode = '23505',
        message = 'pancake_override_event_id_conflict';
    end if;

    return new;
  end if;

  select
    staff.id,
    staff.organization_id,
    nullif(pg_catalog.btrim(staff.name), '') as name,
    nullif(pg_catalog.btrim(staff.username), '') as username,
    staff.is_super_admin
  into v_actor
  from public.org_staff as staff
  where staff.id = v_actor_org_staff_id;

  if not found then
    raise exception using
      errcode = '23503',
      message = 'pancake_override_actor_org_staff_not_found';
  end if;

  -- Nhân viên thường chỉ được tạo audit cho ngoại lệ khóa Zalo với đúng
  -- failure code/reason do server phát sinh. Mọi override khác vẫn chỉ dành
  -- cho super admin. Actor vẫn bị ràng buộc với org_staff_updated_id ở trên.
  if v_actor.is_super_admin is distinct from true
     and not (
       v_failure_code in (
         'PANCAKE_MESSAGE_REQUIRED',
         'PANCAKE_TEXT_MESSAGE_REQUIRED',
         'PANCAKE_TEXT_MESSAGE_TOO_SHORT'
       )
       and v_failure_reason =
         'Nội dung đã CSKH chứa từ khóa “khóa zalo”; miễn yêu cầu có tin nhắn Pancake phù hợp trong ngày Việt Nam'
     ) then
    raise exception using
      errcode = '42501',
      message = 'pancake_override_actor_must_be_super_admin';
  end if;

  insert into public.aka_crm_pancake_override_audit (
    event_id,
    crm_id,
    crm_id_snapshot,
    actor_org_staff_id,
    actor_org_staff_id_snapshot,
    actor_organization_id_snapshot,
    actor_name_snapshot,
    actor_username_snapshot,
    operation,
    action,
    failure_code,
    failure_reason,
    page_id,
    conversation_id,
    pancake_staff_id
  )
  values (
    v_event_id,
    new.id,
    new.id,
    v_actor_org_staff_id,
    v_actor_org_staff_id,
    v_actor.organization_id,
    v_actor.name,
    v_actor.username,
    v_operation,
    v_action,
    v_failure_code,
    v_failure_reason,
    v_page_id,
    v_conversation_id,
    v_pancake_staff_id
  )
  on conflict (event_id) do nothing
  returning id into v_inserted_id;

  if v_inserted_id is null then
    select audit.*
    into strict v_existing
    from public.aka_crm_pancake_override_audit as audit
    where audit.event_id = v_event_id;

    if v_existing.crm_id_snapshot is distinct from new.id
       or v_existing.actor_org_staff_id_snapshot is distinct from v_actor_org_staff_id
       or v_existing.operation is distinct from v_operation
       or v_existing.action is distinct from v_action
       or v_existing.failure_code is distinct from v_failure_code
       or v_existing.failure_reason is distinct from v_failure_reason
       or v_existing.page_id is distinct from v_page_id
       or v_existing.conversation_id is distinct from v_conversation_id
       or v_existing.pancake_staff_id is distinct from v_pancake_staff_id then
      raise exception using
        errcode = '23505',
        message = 'pancake_override_event_id_conflict';
    end if;
  end if;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.chat_zalo_delete_data_group(p_staff_id bigint, p_organization_id bigint, p_group_id bigint, p_request_id text, p_detach_automations boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_result jsonb;
  v_detached_count integer := 0;
BEGIN
  PERFORM public.aka_agent_internal_require_staff_tenant(
    p_staff_id, p_organization_id
  );
  IF p_group_id IS NULL OR p_group_id <= 0
    OR NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
    OR length(btrim(p_request_id)) > 500
  THEN
    RAISE EXCEPTION 'invalid_data_group_delete_request';
  END IF;

  v_result := public.aka_agent_delete_data_group(
    p_staff_id,
    p_organization_id,
    p_group_id,
    btrim(p_request_id)
  );

  IF COALESCE(p_detach_automations, false) THEN
    UPDATE public.auto_automation AS automation
    SET target_data_group_id = NULL,
        updated_at = clock_timestamp()
    WHERE automation.staff_id = p_staff_id
      AND automation.organization_id = p_organization_id
      AND automation.target_data_group_id = p_group_id
      AND COALESCE(automation.is_delete, false) = false;
    GET DIAGNOSTICS v_detached_count = ROW_COUNT;
  END IF;

  RETURN COALESCE(v_result, '{}'::jsonb) || jsonb_build_object(
    'detach_automations', COALESCE(p_detach_automations, false),
    'detached_automation_count', v_detached_count
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.check_cskh_type23_guard(p_queue_id bigint, p_claim_token uuid)
 RETURNS TABLE(allowed boolean, skip_reason text, crm_id bigint, message_id uuid, message_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_queue private.cskh_type23_guard_queue%rowtype;
  v_candidate record;
  v_decision record;
begin
  select q.* into v_queue
  from private.cskh_type23_guard_queue q
  where q.id = p_queue_id
  for update;

  if not found
     or v_queue.status <> 'processing'
     or v_queue.claim_token is distinct from p_claim_token
     or v_queue.lease_expires_at <= pg_catalog.statement_timestamp() then
    raise exception using errcode = '55000', message = 'type23_guard_claim_invalid';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      pg_catalog.format('cskh_type23_guard:%s', v_queue.customer_id), 0
    )
  );

  select c.* into v_candidate
  from public.find_cskh_activity_crm_candidate(v_queue.event_id) c
  limit 1;

  if not found
     or v_candidate.customer_id is null
     or v_candidate.customer_id is distinct from v_queue.customer_id
     or v_candidate.event_reason not in ('monthly_expiring_15d', 'yearly_expiring_30d')
     or pg_catalog.abs(
          pg_catalog.date_part('epoch', v_candidate.event_at - v_queue.anchor_at)
        ) > 0.001
     or v_candidate.reason not in ('monthly_expiring_15d', 'yearly_expiring_30d') then
    update private.cskh_type23_guard_queue q
    set guard_checked_at = pg_catalog.statement_timestamp(),
        guard_decision = 'blocked',
        skip_reason = 'no_longer_type23_eligible',
        updated_at = pg_catalog.statement_timestamp()
    where q.id = v_queue.id;

    return query select false, 'no_longer_type23_eligible'::text,
                        null::bigint, null::uuid, null::timestamptz;
    return;
  end if;

  select d.* into v_decision
  from private.cskh_type23_guard_decision(
    v_queue.id, v_queue.customer_id, v_queue.anchor_at
  ) d;

  update private.cskh_type23_guard_queue q
  set guard_checked_at = pg_catalog.statement_timestamp(),
      guard_decision = case when v_decision.allowed then 'allowed' else 'blocked' end,
      skip_reason = v_decision.skip_reason,
      blocker_crm_id = v_decision.crm_id,
      blocker_message_id = v_decision.message_id,
      blocker_message_at = v_decision.message_at,
      updated_at = pg_catalog.statement_timestamp()
  where q.id = v_queue.id;

  return query select v_decision.allowed, v_decision.skip_reason,
                      v_decision.crm_id, v_decision.message_id,
                      v_decision.message_at;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_non_zalo_account_runtime_operation(p_account_id bigint, p_staff_id bigint, p_platform text, p_previous_status text, p_claim_token uuid, p_requires_login boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_account public.auto_accounts%ROWTYPE;
  v_organization_id bigint;
  v_platform text := lower(btrim(COALESCE(p_platform, '')));
  v_previous_status text := btrim(COALESCE(p_previous_status, ''));
BEGIN
  IF p_account_id IS NULL OR p_account_id <= 0 OR p_staff_id IS NULL OR p_staff_id <= 0 THEN
    RAISE EXCEPTION 'Account and staff IDs must be positive integers';
  END IF;
  IF v_platform NOT IN ('facebook', 'email') THEN
    RAISE EXCEPTION 'Non-Zalo runtime platform must be Facebook or Email';
  END IF;
  IF v_previous_status NOT IN ('chờ xử lý', 'tạm dừng') THEN
    RAISE EXCEPTION 'Previous account status must be pending or paused';
  END IF;
  IF p_claim_token IS NULL THEN
    RAISE EXCEPTION 'Runtime claim token is required';
  END IF;

  -- reset_desktop_running_statuses takes FOR UPDATE on this same row. The
  -- shared lock prevents a new account operation from entering recovery.
  SELECT staff.organization_id INTO v_organization_id
  FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share') AS staff
  WHERE staff.id = p_staff_id AND staff.is_active = true AND public.aka_agent_staff_time_allowed(staff.id)
  ;
  IF NOT FOUND OR v_organization_id IS NULL THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'staff_not_active'
    );
  END IF;

  SELECT account.* INTO v_account
  FROM public.auto_accounts AS account
  WHERE account.id = p_account_id
    AND account.staff_id = p_staff_id
    AND (account.organization_id IS NULL OR account.organization_id = v_organization_id)
  FOR UPDATE OF account;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'account_not_found'
    );
  END IF;

  IF COALESCE(v_account.is_delete, false)
    OR v_account.is_active IS NOT TRUE
    OR lower(btrim(COALESCE(v_account.flatform_type, ''))) <> v_platform
  THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'account_not_available'
    );
  END IF;

  -- Retrying the same client-generated token is idempotent after an ambiguous
  -- network response: the caller still owns this exact account-only claim.
  IF v_account.status = 'đang chạy'
    AND v_account.runtime_operation_claim_token = p_claim_token
  THEN
    RETURN jsonb_build_object(
      'claimed', true,
      'account_id', p_account_id,
      'previous_status', v_previous_status,
      'claim_token', p_claim_token,
      'platform', v_platform
    );
  END IF;

  IF (COALESCE(p_requires_login, true) AND v_account.login_status IS DISTINCT FROM 'đã đăng nhập')
    OR v_account.status IS DISTINCT FROM v_previous_status
  THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'account_not_available'
    );
  END IF;

  UPDATE public.auto_accounts AS account
  SET
    status = 'đang chạy',
    runtime_operation_claim_token = p_claim_token,
    updated_at = now()
  WHERE account.id = p_account_id;

  RETURN jsonb_build_object(
    'claimed', true,
    'account_id', p_account_id,
    'previous_status', v_previous_status,
    'claim_token', p_claim_token,
    'platform', v_platform
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_zalo_account_runtime_operation(p_account_id bigint, p_staff_id bigint, p_runtime_target text, p_requires_login boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_account public.auto_accounts%ROWTYPE;
  v_organization_id bigint;
  v_runtime_target text := lower(btrim(COALESCE(p_runtime_target, '')));
  v_capabilities record;
  v_is_web boolean;
  v_is_server boolean;
BEGIN
  IF p_account_id IS NULL OR p_account_id <= 0
    OR p_staff_id IS NULL OR p_staff_id <= 0
  THEN
    RAISE EXCEPTION 'Account and staff IDs must be positive integers';
  END IF;
  IF v_runtime_target NOT IN ('desktop', 'server') THEN
    RAISE EXCEPTION 'Runtime target must be desktop or server';
  END IF;

  SELECT staff.organization_id
  INTO v_organization_id
  FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share') AS staff
  WHERE staff.id = p_staff_id
    AND staff.is_active = true AND public.aka_agent_staff_time_allowed(staff.id)
  ;
  IF NOT FOUND OR v_organization_id IS NULL THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'reason', 'staff_not_active'
    );
  END IF;

  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('aka-agent-zalo-runtime-entitlement-mutation', 0)
  );
  SELECT *
  INTO v_capabilities
  FROM public.resolve_organization_zalo_account_capabilities(
    v_organization_id
  );

  SELECT account.*
  INTO v_account
  FROM public.auto_accounts AS account
  WHERE account.id = p_account_id
    AND account.staff_id = p_staff_id
  FOR UPDATE OF account;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'reason', 'account_not_found'
    );
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.auto_campaigns AS campaign
    WHERE campaign.account_id = p_account_id
      AND campaign.staff_id = p_staff_id
      AND campaign.runtime_unit_token IS NOT NULL
  ) OR EXISTS (
    SELECT 1
    FROM public.auto_campaigns AS campaign
    WHERE campaign.account_id = p_account_id
      AND campaign.staff_id = p_staff_id
      AND campaign.status = 'đang chạy'
  ) OR EXISTS (
    SELECT 1
    FROM public.auto_campaign_inputs AS campaign_input
    JOIN public.auto_campaigns AS campaign
      ON campaign.id = campaign_input.campaign_id
    WHERE campaign.account_id = p_account_id
      AND campaign.staff_id = p_staff_id
      AND campaign_input.status = 'đang chạy'
  ) OR EXISTS (
    SELECT 1
    FROM public.auto_campaign_input_data AS input_data
    JOIN public.auto_campaigns AS campaign
      ON campaign.id = input_data.campaign_id
    WHERE campaign.account_id = p_account_id
      AND campaign.staff_id = p_staff_id
      AND input_data.status = 'đang chạy'
  ) THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'reason', 'work_running'
    );
  END IF;

  IF COALESCE(v_account.is_delete, false)
    OR v_account.is_active IS NOT TRUE
    OR lower(btrim(COALESCE(v_account.flatform_type, ''))) <> 'zalo'
    OR (
      COALESCE(p_requires_login, true)
      AND v_account.login_status <> 'đã đăng nhập'
    )
    OR v_account.status NOT IN ('chờ xử lý', 'tạm dừng')
  THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'reason', 'account_not_available'
    );
  END IF;

  v_is_web := COALESCE(v_account.is_zalo_show_web, false);
  v_is_server := COALESCE(v_account.is_zalo_server, false);
  IF (
    v_runtime_target = 'server'
    AND (
      v_is_web
      OR NOT v_is_server
      OR NOT COALESCE(v_capabilities.qr_enabled, false)
      OR NOT COALESCE(v_capabilities.server_enabled, false)
    )
  ) OR (
    v_runtime_target = 'desktop'
    AND (
      v_is_server
      OR (
        v_is_web
        AND NOT COALESCE(v_capabilities.web_enabled, false)
      )
      OR (
        NOT v_is_web
        AND NOT v_is_server
        AND NOT COALESCE(v_capabilities.qr_enabled, false)
      )
    )
  ) THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'reason', 'runtime_not_owner'
    );
  END IF;

  UPDATE public.auto_accounts
  SET status = 'đang chạy', updated_at = now()
  WHERE id = p_account_id;

  RETURN jsonb_build_object(
    'claimed', true,
    'account_id', p_account_id,
    'previous_status', v_account.status,
    'runtime_target', v_runtime_target
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_zalo_account_runtime_operation(p_account_id bigint, p_staff_id bigint, p_runtime_target text, p_previous_status text, p_claim_token uuid, p_requires_login boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_account public.auto_accounts%ROWTYPE;
  v_organization_id bigint;
  v_runtime_target text := lower(btrim(COALESCE(p_runtime_target, '')));
  v_previous_status text := btrim(COALESCE(p_previous_status, ''));
  v_capabilities record;
  v_is_web boolean;
  v_is_server boolean;
BEGIN
  IF p_account_id IS NULL OR p_account_id <= 0
    OR p_staff_id IS NULL OR p_staff_id <= 0
  THEN
    RAISE EXCEPTION 'Account and staff IDs must be positive integers';
  END IF;
  IF v_runtime_target NOT IN ('desktop', 'server') THEN
    RAISE EXCEPTION 'Runtime target must be desktop or server';
  END IF;
  IF v_previous_status NOT IN ('chờ xử lý', 'tạm dừng') THEN
    RAISE EXCEPTION 'Previous account status must be pending or paused';
  END IF;
  IF p_claim_token IS NULL THEN
    RAISE EXCEPTION 'Runtime claim token is required';
  END IF;

  SELECT staff.organization_id
  INTO v_organization_id
  FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share') AS staff
  WHERE staff.id = p_staff_id
    AND staff.is_active = true AND public.aka_agent_staff_time_allowed(staff.id)
  ;
  IF NOT FOUND OR v_organization_id IS NULL THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'staff_not_active'
    );
  END IF;

  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('aka-agent-zalo-runtime-entitlement-mutation', 0)
  );
  SELECT *
  INTO v_capabilities
  FROM public.resolve_organization_zalo_account_capabilities(
    v_organization_id
  );

  SELECT account.*
  INTO v_account
  FROM public.auto_accounts AS account
  WHERE account.id = p_account_id
    AND account.staff_id = p_staff_id
    AND (
      account.organization_id IS NULL
      OR account.organization_id = v_organization_id
    )
  FOR UPDATE OF account;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'account_not_found'
    );
  END IF;

  IF COALESCE(v_account.is_delete, false)
    OR lower(btrim(COALESCE(v_account.flatform_type, ''))) <> 'zalo'
  THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'account_not_available'
    );
  END IF;

  v_is_web := COALESCE(v_account.is_zalo_show_web, false);
  v_is_server := COALESCE(v_account.is_zalo_server, false);
  IF (
    v_runtime_target = 'server'
    AND (
      v_is_web
      OR NOT v_is_server
      OR NOT COALESCE(v_capabilities.qr_enabled, false)
      OR NOT COALESCE(v_capabilities.server_enabled, false)
    )
  ) OR (
    v_runtime_target = 'desktop'
    AND (
      v_is_server
      OR (
        v_is_web
        AND NOT COALESCE(v_capabilities.web_enabled, false)
      )
      OR (
        NOT v_is_web
        AND NOT v_is_server
        AND NOT COALESCE(v_capabilities.qr_enabled, false)
      )
    )
  ) THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'runtime_not_owner'
    );
  END IF;

  -- Retry of the same account-operation token remains idempotent after an
  -- ambiguous response. A campaign cannot form a unit while this account row
  -- is already owned/running by that token.
  IF v_account.status = 'đang chạy'
    AND v_account.runtime_operation_claim_token = p_claim_token
  THEN
    RETURN jsonb_build_object(
      'claimed', true,
      'account_id', p_account_id,
      'previous_status', v_previous_status,
      'claim_token', p_claim_token,
      'runtime_target', v_runtime_target
    );
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.auto_campaigns AS campaign
    WHERE campaign.account_id = p_account_id
      AND campaign.staff_id = p_staff_id
      AND campaign.runtime_unit_token IS NOT NULL
  ) OR EXISTS (
    SELECT 1
    FROM public.auto_campaigns AS campaign
    WHERE campaign.account_id = p_account_id
      AND campaign.staff_id = p_staff_id
      AND campaign.status = 'đang chạy'
  ) OR EXISTS (
    SELECT 1
    FROM public.auto_campaign_inputs AS campaign_input
    JOIN public.auto_campaigns AS campaign
      ON campaign.id = campaign_input.campaign_id
    WHERE campaign.account_id = p_account_id
      AND campaign.staff_id = p_staff_id
      AND campaign_input.status = 'đang chạy'
  ) OR EXISTS (
    SELECT 1
    FROM public.auto_campaign_input_data AS input_data
    JOIN public.auto_campaigns AS campaign
      ON campaign.id = input_data.campaign_id
    WHERE campaign.account_id = p_account_id
      AND campaign.staff_id = p_staff_id
      AND input_data.status = 'đang chạy'
  ) THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'work_running'
    );
  END IF;

  IF v_account.status IS DISTINCT FROM v_previous_status
    OR (
      COALESCE(p_requires_login, true)
      AND (
        v_account.is_active IS NOT TRUE
        OR v_account.login_status IS DISTINCT FROM 'đã đăng nhập'
      )
    )
  THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'account_not_available'
    );
  END IF;

  UPDATE public.auto_accounts AS account
  SET status = 'đang chạy',
    runtime_operation_claim_token = p_claim_token,
    updated_at = now()
  WHERE account.id = p_account_id
    AND account.status = v_previous_status;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'account_not_available'
    );
  END IF;

  RETURN jsonb_build_object(
    'claimed', true,
    'account_id', p_account_id,
    'previous_status', v_previous_status,
    'claim_token', p_claim_token,
    'runtime_target', v_runtime_target
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_control_media(p_staff_id bigint, p_organization_id bigint, p_provider text, p_original_name text, p_cloud_url text, p_object_key text, p_mime_type text, p_size_bytes bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_media public.auto_media_files%ROWTYPE;
  v_active_count integer;
BEGIN
  IF p_staff_id IS NULL OR p_staff_id <= 0
    OR p_organization_id IS NULL OR p_organization_id <= 0
    OR NULLIF(btrim(COALESCE(p_original_name, '')), '') IS NULL
    OR NULLIF(btrim(COALESCE(p_cloud_url, '')), '') IS NULL
    OR NULLIF(btrim(COALESCE(p_object_key, '')), '') IS NULL
    OR p_size_bytes IS NULL OR p_size_bytes <= 0 THEN
    RAISE EXCEPTION 'invalid_control_media_payload';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.org_staff
    WHERE id = p_staff_id AND organization_id = p_organization_id AND is_active = true
  ) THEN
    RAISE EXCEPTION 'inactive_control_staff';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('control-media:' || p_staff_id::text, 0));

  SELECT * INTO v_media
  FROM public.auto_media_files
  WHERE staff_id = p_staff_id
    AND organization_id = p_organization_id
    AND object_key = p_object_key
    AND is_delete = false
  LIMIT 1;
  IF FOUND THEN
    RETURN to_jsonb(v_media);
  END IF;

  SELECT count(*)::integer INTO v_active_count
  FROM public.auto_media_files
  WHERE staff_id = p_staff_id
    AND organization_id = p_organization_id
    AND is_delete = false;
  IF v_active_count >= 5000 THEN
    RAISE EXCEPTION 'control_media_quota_exceeded';
  END IF;

  INSERT INTO public.auto_media_files (
    provider, original_name, local_path, cloud_url, object_key, mime_type,
    size_bytes, is_delete, staff_id, organization_id
  ) VALUES (
    COALESCE(NULLIF(btrim(p_provider), ''), 'r2'),
    btrim(p_original_name),
    NULL,
    btrim(p_cloud_url),
    btrim(p_object_key),
    NULLIF(btrim(COALESCE(p_mime_type, '')), ''),
    p_size_bytes,
    false,
    p_staff_id,
    p_organization_id
  ) RETURNING * INTO v_media;

  RETURN to_jsonb(v_media);
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_expired_care_task_v2(p_crm_id bigint, p_actor_org_staff_id bigint, p_expired_care_result_id bigint, p_contacted_channel_ids bigint[], p_task_note text, p_send_to_manager boolean DEFAULT false, p_reclaim_owner boolean DEFAULT false, p_aka_call_id bigint DEFAULT NULL::bigint)
 RETURNS TABLE(updated_crm_id bigint, manager_task_id bigint, ownership_transferred boolean)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_now timestamptz := pg_catalog.statement_timestamp();
  v_window_start timestamptz;
  v_window_end timestamptz;
  v_crm public.aka_crm%rowtype;
  v_call public.aka_call%rowtype;
  v_requires_call boolean := false;
  v_crm_phone_digits text;
  v_call_phone_digits text;
  v_crm_phone_normalized text;
  v_call_phone_normalized text;
begin
  -- Let v1 own the established customer-advisory-lock -> CRM-row-lock order.
  -- Any validation error below aborts this transaction and therefore rolls
  -- back every CRM/customer/manager-task change made by v1.
  select
    completed.updated_crm_id,
    completed.manager_task_id,
    completed.ownership_transferred
  into
    updated_crm_id,
    manager_task_id,
    ownership_transferred
  from public.complete_expired_care_task(
    p_crm_id,
    p_actor_org_staff_id,
    p_expired_care_result_id,
    p_contacted_channel_ids,
    p_task_note,
    p_send_to_manager,
    p_reclaim_owner
  ) as completed;

  -- v1 retains this row lock until the outer RPC transaction finishes.
  select crm.*
  into v_crm
  from public.aka_crm as crm
  where crm.id = p_crm_id
  for update of crm;

  if not found then
    raise exception using
      errcode = 'P0001',
      message = 'expired_care_crm_not_found';
  end if;

  select coalesce(
    (
      select crm_type.requires_call
      from public.aka_crm_type as crm_type
      where crm_type.id = v_crm.crm_type_id
    ),
    false
  )
  into v_requires_call;

  if v_requires_call and p_aka_call_id is null then
    raise exception using
      errcode = 'P0001',
      message = 'crm_call_required';
  end if;

  if not v_requires_call and p_aka_call_id is not null then
    raise exception using
      errcode = 'P0001',
      message = 'crm_call_not_allowed';
  end if;

  if p_aka_call_id is not null then
    select call_row.*
    into v_call
    from public.aka_call as call_row
    where call_row.id = p_aka_call_id
    for update;

    if not found then
      raise exception using
        errcode = 'P0001',
        message = 'crm_call_not_found';
    end if;

    -- Convert both boundaries from local calendar midnights to timestamptz.
    -- This remains correct if the configured time zone ever changes offset.
    v_window_start := (
      (
        pg_catalog.date_trunc(
          'day',
          v_now at time zone 'Asia/Ho_Chi_Minh'
        ) - interval '2 days'
      ) at time zone 'Asia/Ho_Chi_Minh'
    );
    v_window_end := (
      (
        pg_catalog.date_trunc(
          'day',
          v_now at time zone 'Asia/Ho_Chi_Minh'
        ) + interval '1 day'
      ) at time zone 'Asia/Ho_Chi_Minh'
    );

    if v_call.created_at < v_window_start
       or v_call.created_at >= v_window_end then
      raise exception using
        errcode = 'P0001',
        message = 'crm_call_not_today';
    end if;

    v_crm_phone_digits := pg_catalog.regexp_replace(
      coalesce(v_crm.customer_phone, ''),
      '[^0-9]',
      '',
      'g'
    );
    v_call_phone_digits := pg_catalog.regexp_replace(
      coalesce(v_call.phone, ''),
      '[^0-9]',
      '',
      'g'
    );

    v_crm_phone_normalized := case
      when v_crm_phone_digits ~ '^0[0-9]{9}$'
        then v_crm_phone_digits
      when v_crm_phone_digits ~ '^84[0-9]{9}$'
        then '0' || pg_catalog.substr(v_crm_phone_digits, 3)
      else null
    end;

    v_call_phone_normalized := case
      when v_call_phone_digits ~ '^0[0-9]{9}$'
        then v_call_phone_digits
      when v_call_phone_digits ~ '^84[0-9]{9}$'
        then '0' || pg_catalog.substr(v_call_phone_digits, 3)
      else null
    end;

    if v_crm_phone_normalized is null
       or v_call_phone_normalized is null
       or v_crm_phone_normalized is distinct from v_call_phone_normalized then
      raise exception using
        errcode = 'P0001',
        message = 'crm_call_phone_mismatch';
    end if;

    if (
      v_crm.aka_call_id is not null
      and v_crm.aka_call_id is distinct from p_aka_call_id
    ) or exists (
      select 1
      from public.aka_crm as linked_crm
      where linked_crm.aka_call_id = p_aka_call_id
        and linked_crm.id <> v_crm.id
    ) then
      raise exception using
        errcode = 'P0001',
        message = 'crm_call_already_used';
    end if;
  end if;

  if p_aka_call_id is not null then
    begin
      update public.aka_crm as crm
      set aka_call_id = p_aka_call_id
      where crm.id = updated_crm_id;
    exception
      when unique_violation then
        raise exception using
          errcode = 'P0001',
          message = 'crm_call_already_used';
    end;
  end if;

  return next;
end
$function$

CREATE OR REPLACE FUNCTION public.complete_type19_data_error_task(p_crm_id bigint, p_actor_org_staff_id bigint, p_error_date timestamp with time zone, p_error_reason_id bigint, p_image_urls text[], p_completed_at timestamp with time zone, p_updated_at timestamp with time zone, p_pipeline_auto text, p_pipeline_status_id bigint, p_aka_call_id bigint, p_call_requirement_audit jsonb)
 RETURNS TABLE(updated_crm jsonb, deleted_pending_count bigint)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_actor public.org_staff%rowtype;
  v_source public.aka_crm%rowtype;
  v_target public.aka_crm%rowtype;
  v_customer_id bigint;
  v_sibling_ids bigint[] := '{}'::bigint[];
begin
  updated_crm := null;
  deleted_pending_count := 0;

  select staff.*
  into v_actor
  from public.org_staff as staff
  where staff.id = p_actor_org_staff_id
  for share of staff;

  if not found then
    raise exception using
      errcode = 'P0001',
      message = 'type19_data_error_actor_not_found';
  end if;

  if v_actor.is_active is distinct from true then
    raise exception using
      errcode = 'P0001',
      message = 'type19_data_error_actor_inactive';
  end if;

  if p_error_date is null then
    raise exception using
      errcode = 'P0001',
      message = 'type19_data_error_error_date_required';
  end if;

  if coalesce(pg_catalog.cardinality(p_image_urls), 0) = 0
     or exists (
       select 1
       from pg_catalog.unnest(p_image_urls) as image_url(value)
       where pg_catalog.btrim(coalesce(image_url.value, '')) = ''
     ) then
    raise exception using
      errcode = 'P0001',
      message = 'type19_data_error_images_required';
  end if;

  if p_completed_at is null then
    raise exception using
      errcode = 'P0001',
      message = 'type19_data_error_completion_time_required';
  end if;

  if p_updated_at is null then
    raise exception using
      errcode = 'P0001',
      message = 'type19_data_error_updated_time_required';
  end if;

  if pg_catalog.btrim(coalesce(p_pipeline_auto, '')) <> 'data_error' then
    raise exception using
      errcode = 'P0001',
      message = 'type19_data_error_pipeline_invalid';
  end if;

  perform 1
  from public.aka_crm_status as status
  where status.id = p_pipeline_status_id
    and status.type = 'pipeline'
    and status.name = 'data_error'
    and status.is_active = true
  for share of status;

  if not found then
    raise exception using
      errcode = 'P0001',
      message = 'type19_data_error_pipeline_invalid';
  end if;

  perform 1
  from public.aka_crm_status as status
  where status.id = p_error_reason_id
    and status.type = 'error_reason'
    and status.is_active = true
  for share of status;

  if not found then
    raise exception using
      errcode = 'P0001',
      message = 'type19_data_error_reason_invalid';
  end if;

  -- Resolve the customer first, then serialize all Data lỗi completions for
  -- that customer before taking row locks. Callers of this RPC share the same
  -- lock namespace and therefore cannot deadlock by choosing different source
  -- tasks for one customer.
  select crm.customer_id
  into v_customer_id
  from public.aka_crm as crm
  where crm.id = p_crm_id;

  if not found then
    raise exception using
      errcode = 'P0001',
      message = 'type19_data_error_crm_not_found';
  end if;

  if v_customer_id is null then
    raise exception using
      errcode = 'P0001',
      message = 'type19_data_error_customer_missing';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      pg_catalog.format('aka_crm_type19_data_error_customer:%s', v_customer_id),
      0
    )
  );

  select crm.*
  into v_source
  from public.aka_crm as crm
  where crm.id = p_crm_id
  for update of crm;

  if not found then
    raise exception using
      errcode = 'P0001',
      message = 'type19_data_error_crm_not_found';
  end if;

  if v_source.customer_id is distinct from v_customer_id then
    raise exception using
      errcode = 'P0001',
      message = 'type19_data_error_customer_changed';
  end if;

  if v_source.crm_type_id is distinct from 19::bigint then
    raise exception using
      errcode = 'P0001',
      message = 'type19_data_error_wrong_type';
  end if;

  if v_source.cskh_completed_date is not null then
    raise exception using
      errcode = 'P0001',
      message = 'type19_data_error_already_completed';
  end if;

  if coalesce(v_actor.is_super_admin, false) is not true
     and v_source.org_staff_owner_id is distinct from v_actor.id
     and v_source.org_staff_support_id is distinct from v_actor.id then
    raise exception using
      errcode = 'P0001',
      message = 'type19_data_error_forbidden';
  end if;

  -- Retain a key-share lock on the customer while source/sibling state changes.
  perform 1
  from public.aka_customer as customer
  where customer.id = v_customer_id
  for key share of customer;

  if not found then
    raise exception using
      errcode = 'P0001',
      message = 'type19_data_error_customer_missing';
  end if;

  -- Capture exactly the sibling rows that were locked and authorized. A later
  -- DELETE by this explicit ID list cannot remove an unvalidated concurrent row.
  for v_target in
    select crm.*
    from public.aka_crm as crm
    where crm.customer_id = v_customer_id
      and crm.crm_type_id = 19
      and crm.cskh_completed_date is null
    order by crm.id
    for update of crm
  loop
    if v_target.id <> v_source.id then
      if coalesce(v_actor.is_super_admin, false) is not true
         and v_target.org_staff_owner_id is distinct from v_actor.id
         and v_target.org_staff_support_id is distinct from v_actor.id then
        raise exception using
          errcode = 'P0001',
          message = 'type19_data_error_sibling_forbidden';
      end if;

      v_sibling_ids := pg_catalog.array_append(v_sibling_ids, v_target.id);
    end if;
  end loop;

  update public.aka_crm as crm
  set
    error_date = p_error_date,
    error_reason_id = p_error_reason_id,
    image_urls = p_image_urls,
    aka_call_id = p_aka_call_id,
    call_requirement_audit = p_call_requirement_audit,
    cskh_completed_date = p_completed_at,
    updated_at = p_updated_at,
    org_staff_updated_id = v_actor.id,
    is_read = true,
    pipeline_auto = p_pipeline_auto,
    pipeline_status_id = p_pipeline_status_id
  where crm.id = v_source.id
    and crm.customer_id = v_customer_id
    and crm.crm_type_id = 19
    and crm.cskh_completed_date is null
  returning pg_catalog.to_jsonb(crm)
  into updated_crm;

  if updated_crm is null then
    raise exception using
      errcode = 'P0001',
      message = 'type19_data_error_completion_conflict';
  end if;

  if pg_catalog.cardinality(v_sibling_ids) > 0 then
    delete from public.aka_crm as crm
    where crm.id = any (v_sibling_ids)
      and crm.customer_id = v_customer_id
      and crm.crm_type_id = 19
      and crm.cskh_completed_date is null;

    get diagnostics deleted_pending_count = row_count;

    if deleted_pending_count is distinct from pg_catalog.cardinality(v_sibling_ids)::bigint then
      raise exception using
        errcode = 'P0001',
        message = 'type19_data_error_completion_conflict';
    end if;
  end if;

  return next;
end
$function$

CREATE OR REPLACE FUNCTION public.create_control_campaign_v2(p_staff_id bigint, p_organization_id bigint, p_idempotency_key text, p_campaign jsonb, p_inputs jsonb DEFAULT '[]'::jsonb, p_initial_status text DEFAULT 'chờ xử lý'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_result jsonb;
  v_campaign_id bigint;
BEGIN
  IF p_initial_status NOT IN ('chờ xử lý', 'tạm dừng') THEN
    RAISE EXCEPTION 'invalid_control_campaign_initial_status';
  END IF;

  v_result := public.create_control_campaign(
    p_staff_id,
    p_organization_id,
    p_idempotency_key,
    p_campaign,
    p_inputs
  );

  -- The inner insert and this update share a transaction, so a cloned campaign is
  -- never externally visible in the runnable state.
  IF p_initial_status = 'tạm dừng' AND COALESCE((v_result->>'created')::boolean, false) THEN
    v_campaign_id := NULLIF(v_result->>'campaign_id', '')::bigint;
    UPDATE public.auto_campaigns
    SET status = 'tạm dừng', updated_at = now()
    WHERE id = v_campaign_id
      AND staff_id = p_staff_id
      AND organization_id = p_organization_id
      AND COALESCE(is_delete, false) = false;
  END IF;

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.crm_trial_care_decision_v1(p_crm jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 s jsonb := p_crm#>'{gen_meta,trial_care_source}';
 owner_id bigint; org_id bigint; anchor timestamptz; anchor_day date;
 kind text; source_id bigint; source_row jsonb; candidates jsonb;
 products bigint[]; verified_products bigint[]; bought bigint[] := '{}'; product_keys bigint[];
 evidence jsonb := '[]'; proof record; source_count integer;
begin
 if not private.crm_trial_care_candidate_v1(p_crm) or nullif(p_crm->>'cskh_completed_date','') is not null then
  return jsonb_build_object('status','not_applicable','reason','not_open_automatic_trial_care','evidence','[]'::jsonb,'source',s);
 end if;
 owner_id := nullif(p_crm->>'customer_id','')::bigint;
 org_id := nullif(p_crm->>'organization_id','')::bigint;
 if owner_id is null or not exists(select 1 from public.aka_customer where id=owner_id) then
  return jsonb_build_object('status','needs_review','reason','trial_source_customer_missing','evidence',evidence,'source',s);
 end if;
 kind := case when coalesce(p_crm->>'note','') like 'Hỗ trợ kh quan tâm sau %' then 'interest'
  when coalesce(p_crm->>'note','') like 'Hỗ trợ kh hết hạn dùng thử%' then 'demo_expiry' else 'demo' end;
 if s is null or s='null'::jsonb then
  -- Legacy schedules do not carry product IDs. Infer only an exact, unique
  -- customer/organization/local-day event; never use the latest customer date.
  anchor := coalesce(nullif(p_crm->>case when kind='interest' then 'interest_date' else 'demo_date' end,'')::timestamptz,
    nullif(p_crm->>'created_at','')::timestamptz);
  anchor_day := (anchor at time zone 'Asia/Ho_Chi_Minh')::date;
  select jsonb_agg(jsonb_build_object('version',1,'kind',kind,'source_type','org_product','source_id',p.id,
    'org_product_id',p.id,'started_at',p.demo_created_at,'product_ids',jsonb_build_array(p.product_id)))
   into candidates from public.org_organization_product p join public.org_organization o on o.id=p.organization_id
   where o.customer_id=owner_id and (org_id is null or o.id=org_id) and not coalesce(p.is_deleted,false)
    and kind<>'interest' and (p.demo_created_at at time zone 'Asia/Ho_Chi_Minh')::date=anchor_day and p.product_id is not null;
  source_count := coalesce(jsonb_array_length(candidates),0);
  if source_count=0 then
   select jsonb_agg(jsonb_build_object('version',1,'kind',kind,'source_type','crm','source_id',c.id,
    'started_at',case when kind='interest' then c.interest_date else c.demo_date end,
    'product_ids',case when kind='interest' then to_jsonb(c.interest_product_ids) else to_jsonb(c.demo_product_ids) end,
    'sql_account_id',c.sql_account_id)) into candidates
   from public.aka_crm c where c.customer_id=owner_id and (org_id is null or c.organization_id=org_id)
    and c.id is distinct from nullif(p_crm->>'id','')::bigint
    and (not private.crm_trial_care_candidate_v1(to_jsonb(c)) or c.cskh_completed_date is not null)
    and (case when kind='interest' then c.interest_date else c.demo_date end at time zone 'Asia/Ho_Chi_Minh')::date=anchor_day
    and cardinality(case when kind='interest' then c.interest_product_ids else c.demo_product_ids end)>0;
   source_count := coalesce(jsonb_array_length(candidates),0);
  end if;
  if source_count<>1 then
   return jsonb_build_object('status','needs_review','reason','trial_source_ambiguous_or_missing','evidence',evidence,'source',null);
  end if;
  s := candidates->0;
 end if;
 if jsonb_typeof(s)<>'object' or s->>'version' is distinct from '1' or coalesce(s->>'kind','') not in ('interest','demo','demo_expiry')
  or coalesce(s->>'source_type','') not in ('org_product','crm') or coalesce(s->>'source_id','') !~ '^[1-9][0-9]*$'
  or jsonb_typeof(s->'product_ids') is distinct from 'array' or nullif(s->>'started_at','') is null then
  return jsonb_build_object('status','needs_review','reason','trial_source_invalid','evidence',evidence,'source',s);
 end if;
 kind := s->>'kind'; source_id := (s->>'source_id')::bigint; anchor := (s->>'started_at')::timestamptz;
 anchor_day := (anchor at time zone 'Asia/Ho_Chi_Minh')::date;
 select array_agg(distinct value::bigint order by value::bigint) into products from jsonb_array_elements_text(s->'product_ids');
 if cardinality(products) is null or exists(select 1 from unnest(products) p where p is null or p<=0) then
  return jsonb_build_object('status','needs_review','reason','trial_source_products_missing','evidence',evidence,'source',s);
 end if;
 if s->>'source_type'='org_product' then
  select to_jsonb(p) into source_row from public.org_organization_product p join public.org_organization o on o.id=p.organization_id
   where p.id=source_id and o.customer_id=owner_id and (org_id is null or o.id=org_id) and not coalesce(p.is_deleted,false);
  if source_row is null or kind='interest' or (s->>'org_product_id')::bigint is distinct from source_id then
   return jsonb_build_object('status','needs_review','reason','trial_source_owner_or_entitlement_changed','evidence',evidence,'source',s);
  end if;
  -- trial_start_date is rewritten by purchases. Only immutable demo attribution
  -- or the original unpaid audit snapshot can prove the source cycle.
  if (nullif(source_row->>'demo_created_at','')::timestamptz at time zone 'Asia/Ho_Chi_Minh')::date=anchor_day
     and (source_row->>'product_id')::bigint=any(products) and cardinality(products)=1
     and not exists (
      select 1 from public.org_organization_product_history original_demo
       where original_demo.org_organization_product_id=source_id
        and original_demo.organization_id=(source_row->>'organization_id')::bigint
        and original_demo.after_snapshot->>'is_paid'='false'
        and (coalesce(nullif(original_demo.after_snapshot->>'demo_created_at','')::timestamptz,
          original_demo.trial_start_date) at time zone 'Asia/Ho_Chi_Minh')::date=anchor_day
     ) then
   verified_products:=products;
  else
   select array_agg(distinct h.product_id order by h.product_id) into verified_products
   from public.org_organization_product_history h where h.org_organization_product_id=source_id
    and h.organization_id=(source_row->>'organization_id')::bigint
    and (coalesce(nullif(h.after_snapshot->>'demo_created_at','')::timestamptz,
      case when h.after_snapshot->>'is_paid'='false' then h.trial_start_date end) at time zone 'Asia/Ho_Chi_Minh')::date=anchor_day
    and h.after_snapshot->>'is_paid'='false';
  end if;
 else
  select to_jsonb(c) into source_row from public.aka_crm c where c.id=source_id and c.customer_id=owner_id
    and (org_id is null or c.organization_id=org_id)
    and (not private.crm_trial_care_candidate_v1(to_jsonb(c)) or c.cskh_completed_date is not null);
  if source_row is not null and (nullif(source_row->>case when kind='interest' then 'interest_date' else 'demo_date' end,'')::timestamptz
      at time zone 'Asia/Ho_Chi_Minh')::date=anchor_day then
   select array_agg(distinct value::bigint order by value::bigint) into verified_products
    from jsonb_array_elements_text(source_row->case when kind='interest' then 'interest_product_ids' else 'demo_product_ids' end);
   if s->>'sql_account_id' is not null and s->>'sql_account_id' is distinct from source_row->>'sql_account_id' then verified_products:=null; end if;
  end if;
 end if;
 -- One CRM event may start several product trials. New schedules split that
 -- event into product-specific rows; every requested product must still belong
 -- to the verified source event. A concrete org entitlement stays exact.
 if (s->>'source_type'='crm' and not coalesce(products <@ verified_products,false))
    or (s->>'source_type'='org_product' and verified_products is distinct from products) then
  return jsonb_build_object('status','needs_review','reason','trial_source_cycle_or_products_changed','evidence',evidence,'source',s);
 end if;
 product_keys := array(select distinct private.crm_trial_care_product_key_v1(x) from unnest(products) x order by 1);
 for proof in
  -- Paid orders use item allocation, never a shared header customer when any
  -- item has explicit allocation. Zero-value/admin grants are not payments.
  select distinct coalesce(p.product_id,a.product_id) as product_id,
   jsonb_build_object('type','sale_order','id',o.id,'item_id',i.id,'paid_at',o.paid_at) as detail
  from public.aka_sale_order o join public.aka_sale_order_item i on i.sale_order_id=o.id
   left join public.org_organization_product p on p.id=i.org_organization_product_id
   left join public.org_organization g on g.id=p.organization_id
   left join public.aka_order a on a.account_id_old=i.sql_account_id and a.customer_id=owner_id and a.source_system='sql_account'
  where o.status in ('paid','upgrading','completed','upgrade_failed') and o.paid_at is not null and o.amount>0
   and i.status in ('pending','completed','failed') and i.amount>0
   and (o.paid_at at time zone 'Asia/Ho_Chi_Minh')::date>=anchor_day
   and (i.customer_id=owner_id or (i.customer_id is null and o.customer_id=owner_id
    and not exists(select 1 from public.aka_sale_order_item x where x.sale_order_id=o.id
      and (x.customer_id is not null or x.sql_contact_id is not null or x.customer_name is not null or x.customer_phone is not null))))
   and ((i.target_type='org_product' and g.customer_id=owner_id and (org_id is null or g.id=org_id))
     or (i.target_type='sql_account' and a.customer_id=owner_id))
   and private.crm_trial_care_product_key_v1(coalesce(p.product_id,a.product_id))=any(product_keys)
  union all
  -- SQL account upgrades are mirrored to aka_order before staff completes CRM.
  -- Use only a verified customer/product and the exact CRM-bound account, or
  -- an active entitlement. Unmapped legacy product_list strings are not proof.
  select a.product_id,jsonb_build_object('type','paid_sql_entitlement','id',a.id,'sql_account_id',a.account_id_old,'purchase_date',a.purchase_date)
   from public.aka_order a where a.customer_id=owner_id and a.source_system='sql_account'
    and private.crm_trial_care_product_key_v1(a.product_id)=any(product_keys) and a.is_paid=true and not coalesce(a.is_demo,false)
    and not coalesce(a.is_deleted,false) and coalesce(lower(a.package_type),'') not in ('demo','trial','')
    and s->>'source_type'='crm'
    and ((s->>'sql_account_id')::bigint=a.account_id_old
      or (a.date_expiration>=clock_timestamp() and (org_id is null or a.organization_id=org_id)))
  union all
  select p.product_id,jsonb_build_object('type','paid_entitlement','id',p.id,'purchase_date',p.purchase_date)
   from public.org_organization_product p join public.org_organization o on o.id=p.organization_id
   where o.customer_id=owner_id and (org_id is null or o.id=org_id) and private.crm_trial_care_product_key_v1(p.product_id)=any(product_keys)
    and p.is_paid=true and not coalesce(p.is_deleted,false) and coalesce(lower(p.package_type),'') not in ('demo','trial','')
    and ((s->>'source_type'='org_product' and p.id=source_id)
      or (s->>'source_type'='crm' and p.expiration_date>=clock_timestamp()))
  union all
  select h.product_id,jsonb_build_object('type','paid_entitlement_history','id',h.id,'org_product_id',p.id,'changed_at',h.changed_at)
   from public.org_organization_product_history h join public.org_organization_product p on p.id=h.org_organization_product_id
   join public.org_organization o on o.id=p.organization_id
   where o.customer_id=owner_id and h.organization_id=o.id and (org_id is null or o.id=org_id)
    and private.crm_trial_care_product_key_v1(h.product_id)=any(product_keys) and h.after_snapshot->>'is_paid'='true'
    and coalesce(h.before_snapshot->>'is_paid','false')<>'true'
    and coalesce(lower(h.after_snapshot->>'package_type'),'') not in ('demo','trial','')
    and (h.changed_at at time zone 'Asia/Ho_Chi_Minh')::date>=anchor_day
    and (s->>'source_type'<>'org_product' or p.id=source_id)
  union all
  select product_id,jsonb_build_object('type','completed_purchase_crm','id',c.id,'purchase_date',c.purchase_date)
   from public.aka_crm c cross join lateral unnest(c.purchase_product_ids) as product_id
   where c.customer_id=owner_id and c.cskh_completed_date is not null and c.purchase_date is not null
    and (c.purchase_date at time zone 'Asia/Ho_Chi_Minh')::date>=anchor_day and private.crm_trial_care_product_key_v1(product_id)=any(product_keys)
    and (org_id is null or c.organization_id is null or c.organization_id=org_id)
 loop
  bought:=array_append(bought,private.crm_trial_care_product_key_v1(proof.product_id)); evidence:=evidence||jsonb_build_array(proof.detail);
 end loop;
 if product_keys <@ bought then
  return jsonb_build_object('status','purchased','reason','matching_product_purchased','evidence',evidence,'source',s);
 elsif cardinality(bought)>0 then
  return jsonb_build_object('status','needs_review','reason','partially_purchased_products','evidence',evidence,'source',s);
 end if;
 return jsonb_build_object('status','eligible','reason','verified_unpurchased_products','evidence',evidence,'source',s);
exception when invalid_text_representation or datetime_field_overflow or invalid_datetime_format or numeric_value_out_of_range or invalid_parameter_value then
 return jsonb_build_object('status','needs_review','reason','trial_source_invalid','evidence','[]'::jsonb,'source',s);
end $function$

CREATE OR REPLACE FUNCTION public.delete_control_zalo_account_group_atomic(p_staff_id bigint, p_organization_id bigint, p_group_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_group public.auto_account_groups%ROWTYPE;
BEGIN
  IF p_staff_id IS NULL OR p_staff_id <= 0
    OR p_organization_id IS NULL OR p_organization_id <= 0
    OR p_group_id IS NULL OR p_group_id <= 0
  THEN
    RAISE EXCEPTION 'invalid_control_zalo_account_group_delete';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'control-zalo-account-group:' || p_group_id::text, 0
  ));
  SELECT account_group.*
  INTO v_group
  FROM public.auto_account_groups AS account_group
  WHERE account_group.id = p_group_id
    AND account_group.staff_id = p_staff_id
    AND account_group.organization_id = p_organization_id
    AND account_group.flatform_type = 'zalo'
    AND COALESCE(account_group.is_delete, false) = false
  FOR UPDATE OF account_group;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('deleted', false, 'reason', 'not_found');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.auto_accounts AS account
    WHERE account.account_group_id = p_group_id
      AND COALESCE(account.is_delete, false) = false
  ) THEN
    RETURN jsonb_build_object(
      'deleted', false,
      'reason', 'account_group_in_use'
    );
  END IF;

  UPDATE public.auto_account_groups AS account_group
  SET is_delete = true, updated_at = now()
  WHERE account_group.id = p_group_id
    AND account_group.staff_id = p_staff_id
    AND account_group.organization_id = p_organization_id
    AND account_group.flatform_type = 'zalo'
    AND COALESCE(account_group.is_delete, false) = false;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('deleted', false, 'reason', 'not_found');
  END IF;
  RETURN jsonb_build_object('deleted', true, 'group_id', p_group_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_control_zalo_proxy_atomic(p_staff_id bigint, p_organization_id bigint, p_proxy_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_proxy public.auto_proxies%ROWTYPE;
BEGIN
  IF p_staff_id IS NULL OR p_staff_id <= 0
    OR p_organization_id IS NULL OR p_organization_id <= 0
    OR p_proxy_id IS NULL OR p_proxy_id <= 0
  THEN
    RAISE EXCEPTION 'invalid_control_zalo_proxy_delete';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'control-zalo-proxy:' || p_proxy_id::text, 0
  ));
  SELECT proxy.*
  INTO v_proxy
  FROM public.auto_proxies AS proxy
  WHERE proxy.id = p_proxy_id
    AND proxy.staff_id = p_staff_id
    AND proxy.organization_id = p_organization_id
    AND COALESCE(proxy.is_delete, false) = false
  FOR UPDATE OF proxy;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('deleted', false, 'reason', 'not_found');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.auto_accounts AS account
    WHERE account.proxy_id = p_proxy_id
      AND COALESCE(account.is_delete, false) = false
  ) THEN
    RETURN jsonb_build_object('deleted', false, 'reason', 'proxy_in_use');
  END IF;

  UPDATE public.auto_proxies AS proxy
  SET is_delete = true, updated_at = now()
  WHERE proxy.id = p_proxy_id
    AND proxy.staff_id = p_staff_id
    AND proxy.organization_id = p_organization_id
    AND COALESCE(proxy.is_delete, false) = false;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('deleted', false, 'reason', 'not_found');
  END IF;
  RETURN jsonb_build_object('deleted', true, 'proxy_id', p_proxy_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_zalo_account_capability_and_quota()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE
  v_new_platform text := lower(btrim(COALESCE(NEW.flatform_type, '')));
  v_old_platform text := CASE
    WHEN TG_OP = 'UPDATE' THEN lower(btrim(COALESCE(OLD.flatform_type, '')))
    ELSE ''
  END;
  v_staff_organization_id bigint;
  v_organization_id bigint;
  v_new_subtype text;
  v_pool record;
  v_pool_subtypes text[] := ARRAY[]::text[];
  v_account_count integer := 0;
  v_requires_capability_check boolean := false;
  v_requires_quota_check boolean := false;
  v_is_existing_subtype_change boolean := false;
  v_is_claimed_subtype_cas boolean := false;
BEGIN
  IF v_new_platform <> 'zalo' OR COALESCE(NEW.is_delete, false) THEN
    RETURN NEW;
  END IF;

  v_new_subtype := CASE
    WHEN COALESCE(NEW.is_zalo_show_web, false) THEN 'web'
    WHEN COALESCE(NEW.is_zalo_server, false) THEN 'server'
    ELSE 'qr'
  END;

  -- Backend-only SQL import: preserve expired entitlements, locked staff and existing
  -- legacy counts. This context is scoped/restored by akabiz_migrate_sql_account_v1.
  -- Tenant callers cannot opt in, even if they manage to set the custom GUC.
  IF TG_OP = 'INSERT'
    AND (current_setting('role', true) = 'service_role'
      OR (session_user = 'postgres' AND current_setting('role', true) IN ('none','postgres')))
    AND current_setting('aka_agent.sql_migration_org', true) = NEW.organization_id::text
    AND NEW.is_zalo_server = true AND NEW.is_zalo_show_web = false
    AND EXISTS (SELECT 1 FROM public.org_staff s WHERE s.id = NEW.staff_id
      AND s.organization_id = NEW.organization_id AND s.deleted_at IS NULL)
  THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    v_requires_capability_check := true;
    v_requires_quota_check := true;
  ELSE
    v_is_existing_subtype_change := v_old_platform = 'zalo'
      AND v_new_platform = 'zalo'
      AND OLD.id IS NOT DISTINCT FROM NEW.id
      AND OLD.flatform_type IS NOT DISTINCT FROM NEW.flatform_type
      AND COALESCE(OLD.is_delete, false) = false
      AND COALESCE(NEW.is_delete, false) = false
      AND OLD.staff_id IS NOT DISTINCT FROM NEW.staff_id
      AND OLD.organization_id IS NOT DISTINCT FROM NEW.organization_id
      AND (
        COALESCE(OLD.is_zalo_show_web, false)
          IS DISTINCT FROM COALESCE(NEW.is_zalo_show_web, false)
        OR COALESCE(OLD.is_zalo_server, false)
          IS DISTINCT FROM COALESCE(NEW.is_zalo_server, false)
      );
    v_is_claimed_subtype_cas := v_is_existing_subtype_change
      AND OLD.status = 'đang chạy'
      AND NEW.status = 'đang chạy'
      AND OLD.runtime_operation_claim_token IS NOT NULL
      AND OLD.runtime_operation_claim_token
        IS NOT DISTINCT FROM NEW.runtime_operation_claim_token;
    v_requires_capability_check := v_old_platform <> 'zalo'
      OR COALESCE(OLD.is_delete, false)
      OR OLD.staff_id IS DISTINCT FROM NEW.staff_id
      OR OLD.organization_id IS DISTINCT FROM NEW.organization_id
      OR COALESCE(OLD.is_zalo_show_web, false)
        IS DISTINCT FROM COALESCE(NEW.is_zalo_show_web, false)
      OR COALESCE(OLD.is_zalo_server, false)
        IS DISTINCT FROM COALESCE(NEW.is_zalo_server, false);
    v_requires_quota_check := v_requires_capability_check;
  END IF;

  IF NOT v_requires_capability_check AND NOT v_requires_quota_check THEN
    RETURN NEW;
  END IF;

  -- Subtype ownership is changed only by the tokenized claim/CAS/release
  -- protocol. Preserve the existing fail-closed and lock-order behavior.
  IF v_is_existing_subtype_change AND NOT v_is_claimed_subtype_cas THEN
    RAISE EXCEPTION 'zalo_account_subtype_change_claim_required';
  END IF;

  IF v_is_claimed_subtype_cas THEN
    SELECT staff.organization_id
    INTO v_staff_organization_id
    FROM public.org_staff AS staff
    WHERE staff.id = NEW.staff_id
      AND staff.is_active = true;
  ELSE
    SELECT staff.organization_id
    INTO v_staff_organization_id
    FROM public.org_staff AS staff
    WHERE staff.id = NEW.staff_id
      AND staff.is_active = true
    FOR SHARE OF staff;
  END IF;

  IF NOT FOUND OR v_staff_organization_id IS NULL THEN
    RAISE EXCEPTION 'zalo_account_staff_not_active';
  END IF;

  v_organization_id := COALESCE(NEW.organization_id, v_staff_organization_id);
  IF v_organization_id IS DISTINCT FROM v_staff_organization_id THEN
    RAISE EXCEPTION 'zalo_account_organization_mismatch';
  END IF;

  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('aka-agent-zalo-runtime-entitlement-mutation', 0)
  );

  SELECT *
  INTO v_pool
  FROM private.resolve_organization_zalo_entitlement_pools(v_organization_id)
  WHERE account_subtype = v_new_subtype;

  IF v_requires_capability_check AND v_pool.entitlement_id IS NULL THEN
    RAISE EXCEPTION 'zalo_account_capability_unavailable';
  END IF;

  IF v_requires_quota_check THEN
    SELECT COALESCE(
      array_agg(pool.account_subtype ORDER BY pool.account_subtype),
      ARRAY[]::text[]
    )
    INTO v_pool_subtypes
    FROM private.resolve_organization_zalo_entitlement_pools(
      v_organization_id
    ) AS pool
    WHERE pool.entitlement_id = v_pool.entitlement_id;

    -- This is the same transaction lock used by the atomic Control creator.
    -- Calls are re-entrant, so the RPC and trigger remain race-safe together.
    PERFORM pg_advisory_xact_lock(
      hashtextextended('control-zalo-account:' || NEW.staff_id::text, 0)
    );

    SELECT count(*)::integer
    INTO v_account_count
    FROM public.auto_accounts AS account
    WHERE account.staff_id = NEW.staff_id
      AND (
        account.organization_id IS NULL
        OR account.organization_id = v_organization_id
      )
      AND lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
      AND COALESCE(account.is_delete, false) = false
      AND (
        TG_OP <> 'UPDATE'
        OR account.id IS DISTINCT FROM NEW.id
      )
      AND (
        CASE
          WHEN COALESCE(account.is_zalo_show_web, false) THEN 'web'
          WHEN COALESCE(account.is_zalo_server, false) THEN 'server'
          ELSE 'qr'
        END
      ) = ANY(v_pool_subtypes);

    IF v_pool.max_accounts IS NOT NULL
      AND v_pool.max_accounts > 0
      AND v_account_count >= v_pool.max_accounts
    THEN
      RAISE EXCEPTION 'zalo_account_limit_reached';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enqueue_campaign_zalo_realtime_group_event(p_campaign_id bigint, p_account_id bigint, p_staff_id bigint, p_runtime_target text, p_group_id text, p_group_name text, p_trigger_type text, p_target_uid text, p_target_name text, p_event_time timestamp with time zone, p_schedule_at timestamp with time zone, p_raw_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(inserted boolean, event_id bigint, input_data_id bigint)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_event_id bigint;
  v_input_data_id bigint;
  v_organization_id bigint;
  v_capabilities record;
  v_runtime_target text := lower(btrim(COALESCE(p_runtime_target, '')));
  v_target_uid text := btrim(COALESCE(p_target_uid, ''));
  v_target_name text := NULLIF(btrim(COALESCE(p_target_name, '')), '');
  v_group_id text := btrim(COALESCE(p_group_id, ''));
  v_group_name text := NULLIF(btrim(COALESCE(p_group_name, '')), '');
  v_schedule_at timestamptz := COALESCE(p_schedule_at, now());
BEGIN
  IF p_campaign_id IS NULL OR p_campaign_id <= 0 THEN RAISE EXCEPTION 'campaign_id is required'; END IF;
  IF p_account_id IS NULL OR p_account_id <= 0 THEN RAISE EXCEPTION 'account_id is required'; END IF;
  IF p_staff_id IS NULL OR p_staff_id <= 0 THEN RAISE EXCEPTION 'staff_id is required'; END IF;
  IF v_runtime_target NOT IN ('desktop', 'server') THEN RAISE EXCEPTION 'runtime target must be desktop or server'; END IF;
  IF v_group_id = '' THEN RAISE EXCEPTION 'group_id is required'; END IF;
  IF v_target_uid = '' OR v_target_uid = '0' THEN RAISE EXCEPTION 'target_uid is required'; END IF;
  IF p_trigger_type NOT IN ('join', 'leave', 'interact') THEN RAISE EXCEPTION 'invalid trigger_type: %', p_trigger_type; END IF;

  SELECT staff.organization_id INTO v_organization_id
  FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share') AS staff
  WHERE staff.id = p_staff_id AND staff.is_active = true
  ;
  IF NOT FOUND OR v_organization_id IS NULL THEN RAISE EXCEPTION 'active staff % was not found', p_staff_id; END IF;

  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('aka-agent-zalo-runtime-entitlement-mutation', 0)
  );
  SELECT * INTO v_capabilities
  FROM public.resolve_organization_zalo_account_capabilities(v_organization_id);
  IF NOT COALESCE(v_capabilities.qr_enabled, false)
    OR (v_runtime_target = 'server'
      AND NOT COALESCE(v_capabilities.server_enabled, false))
  THEN RAISE EXCEPTION 'runtime_not_owner'; END IF;

  PERFORM 1
  FROM public.auto_campaigns AS campaign
  WHERE campaign.id = p_campaign_id
    AND campaign.account_id = p_account_id
    AND campaign.staff_id = p_staff_id
    AND campaign.action_id = 'zalo_message_group_realtime'
    AND campaign.status IN ('chờ xử lý', 'đang chạy')
    AND COALESCE(campaign.is_delete, false) = false
  FOR SHARE OF campaign;
  IF NOT FOUND THEN RAISE EXCEPTION 'runtime_control_paused'; END IF;

  PERFORM 1
  FROM public.auto_accounts AS account
  WHERE account.id = p_account_id
    AND account.staff_id = p_staff_id
    AND lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
    AND COALESCE(account.is_zalo_show_web, false) = false
    AND (
      (v_runtime_target = 'server' AND COALESCE(account.is_zalo_server, false) = true)
      OR (v_runtime_target = 'desktop' AND COALESCE(account.is_zalo_server, false) = false)
    )
    AND account.is_active = true
    AND account.status IN ('chờ xử lý', 'đang chạy')
    AND COALESCE(account.is_delete, false) = false
  FOR SHARE OF account;
  IF NOT FOUND THEN RAISE EXCEPTION 'runtime_control_paused'; END IF;

  INSERT INTO public.auto_campaign_zalo_realtime_group_events (
    campaign_id, account_id, group_id, group_name, trigger_type,
    target_uid, target_name, event_time, raw_payload
  ) VALUES (
    p_campaign_id, p_account_id, v_group_id, v_group_name, p_trigger_type,
    v_target_uid, v_target_name, COALESCE(p_event_time, now()), COALESCE(p_raw_payload, '{}'::jsonb)
  ) ON CONFLICT (campaign_id, target_uid) DO NOTHING
  RETURNING id INTO v_event_id;

  IF v_event_id IS NULL THEN
    SELECT event.id, event.input_data_id INTO v_event_id, v_input_data_id
    FROM public.auto_campaign_zalo_realtime_group_events AS event
    WHERE event.campaign_id = p_campaign_id AND event.target_uid = v_target_uid;
    RETURN QUERY SELECT false, v_event_id, v_input_data_id;
    RETURN;
  END IF;

  INSERT INTO public.auto_campaign_input_data (
    campaign_id, input_id, name, uid, status, note, schedule
  ) VALUES (
    p_campaign_id, NULL, v_target_name, v_target_uid, 'chờ xử lý', '', v_schedule_at
  ) RETURNING id INTO v_input_data_id;

  UPDATE public.auto_campaign_zalo_realtime_group_events
  SET input_data_id = v_input_data_id, updated_at = now()
  WHERE id = v_event_id;
  UPDATE public.auto_campaigns
  SET schedule = v_schedule_at, updated_at = now()
  WHERE id = p_campaign_id AND account_id = p_account_id
    AND status IN ('chờ xử lý', 'đang chạy')
    AND (schedule IS NULL OR schedule < now() OR schedule > v_schedule_at);

  RETURN QUERY SELECT true, v_event_id, v_input_data_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.enqueue_cskh_type23_guard_candidate(p_event_id uuid)
 RETURNS TABLE(queue_id bigint, event_id uuid, customer_id bigint, anchor_at timestamp with time zone, run_after timestamp with time zone, status text, inserted boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_candidate record;
  v_queue private.cskh_type23_guard_queue%rowtype;
  v_inserted boolean := false;
begin
  if p_event_id is null then
    return;
  end if;

  select c.* into v_candidate
  from public.find_cskh_activity_crm_candidate(p_event_id) c
  where c.event_reason in ('monthly_expiring_15d', 'yearly_expiring_30d')
    and c.reason in ('monthly_expiring_15d', 'yearly_expiring_30d')
  limit 1;

  if not found then
    return;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      pg_catalog.format('cskh_type23_guard_queue:%s', v_candidate.customer_id), 0
    )
  );

  select q.* into v_queue
  from private.cskh_type23_guard_queue q
  where q.event_id = p_event_id
  limit 1;

  if not found then
    select q.* into v_queue
    from private.cskh_type23_guard_queue q
    where q.customer_id = v_candidate.customer_id
      and q.status in ('pending', 'processing')
    order by q.anchor_at, q.id
    limit 1;
  end if;

  if not found then
    insert into private.cskh_type23_guard_queue (
      event_id, customer_id, anchor_at, run_after, candidate_reason,
      next_attempt_at, metadata
    ) values (
      v_candidate.event_id,
      v_candidate.customer_id,
      v_candidate.event_at,
      v_candidate.event_at + interval '72 hours',
      v_candidate.reason,
      v_candidate.event_at + interval '72 hours',
      pg_catalog.jsonb_build_object(
        'rules_version', 'cskh_type23_guard_v1_20260828',
        'event_reason', v_candidate.event_reason,
        'enqueue_reason', v_candidate.reason
      )
    )
    returning * into v_queue;
    v_inserted := true;
  end if;

  return query select v_queue.id, v_queue.event_id, v_queue.customer_id,
                      v_queue.anchor_at, v_queue.run_after, v_queue.status,
                      v_inserted;
end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_sms_auto_account_for_staff(p_staff_id bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_staff public.org_staff%ROWTYPE;
  v_phone text;
  v_primary_username text;
  v_fallback_username text;
  v_selected_username text;
  v_existing_account_id bigint;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('auto_accounts_sms_username', 0));

  SELECT * INTO v_staff
  FROM public.org_staff
  WHERE id = p_staff_id;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  v_phone := btrim(coalesce(v_staff.phone, ''));
  IF v_phone = '' THEN
    RETURN NULL;
  END IF;

  SELECT id INTO v_existing_account_id
  FROM public.auto_accounts
  WHERE staff_id = v_staff.id
    AND flatform_type = 'sms'
    AND coalesce(is_delete, false) = false
  ORDER BY id
  LIMIT 1;

  IF v_existing_account_id IS NOT NULL THEN
    RETURN v_existing_account_id;
  END IF;

  v_primary_username := v_phone;
  v_fallback_username := v_staff.organization_id::text || '.' || v_phone;

  IF NOT EXISTS (
    SELECT 1
    FROM public.auto_accounts
    WHERE flatform_type = 'sms'
      AND coalesce(is_delete, false) = false
      AND btrim(coalesce(username, '')) = v_primary_username
  ) THEN
    v_selected_username := v_primary_username;
  ELSIF NOT EXISTS (
    SELECT 1
    FROM public.auto_accounts
    WHERE flatform_type = 'sms'
      AND coalesce(is_delete, false) = false
      AND btrim(coalesce(username, '')) = v_fallback_username
  ) THEN
    v_selected_username := v_fallback_username;
  ELSE
    RAISE EXCEPTION 'Cannot create SMS account for staff %, username candidates already exist: %, %',
      v_staff.id, v_primary_username, v_fallback_username;
  END IF;

  INSERT INTO public.auto_accounts (
    name,
    flatform_type,
    login_status,
    status,
    is_active,
    is_delete,
    staff_id,
    organization_id,
    username,
    password,
    created_at,
    updated_at
  ) VALUES (
    v_phone,
    'sms',
    'chưa đăng nhập',
    'chờ xử lý',
    true,
    false,
    v_staff.id,
    v_staff.organization_id,
    v_selected_username,
    '123456',
    now(),
    now()
  )
  RETURNING id INTO v_existing_account_id;

  RETURN v_existing_account_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_alert_bug_stuck(p_hours numeric DEFAULT 2)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_link    text;
  rec       record;
  v_res     record;
  v_staff   text;
  v_shop    text;
  v_page    text;
  v_plink   text;
  v_payload jsonb;
  v_req     bigint;
  v_ins     uuid;
  v_sent    integer := 0;
  v_hour_vn integer := extract(hour from now() AT TIME ZONE 'Asia/Ho_Chi_Minh');
BEGIN
  IF (extract(hour from now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::int * 60 + extract(minute from now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::int) NOT BETWEEN 510 AND 1079 THEN RETURN 0; END IF; -- 8h30-18h VN
  SELECT link INTO v_link FROM aka_webhook_link WHERE id = 1;
  IF v_link IS NULL OR v_link = '' THEN RETURN 0; END IF;

  FOR rec IN
    SELECT m.id gom_id, m.conversation_id, m.contact_id, m.shop_id_2, m.contact_name,
           m.bot_intent, m.question_content, m.staff_id, m.created_at
    FROM message_gom m
    WHERE m.account_id = 1001
      AND m.bot_intent IN ('C3_REPORT_BUG','L1_TROUBLESHOOT')
      AND m.status = 'no_answer'
      AND m.created_at < now() - make_interval(hours => p_hours::int)
      AND m.created_at > now() - interval '6 hours'
      AND NOT EXISTS (SELECT 1 FROM aka_sales_alert_log l WHERE l.gom_id = m.id)
    ORDER BY m.created_at
    LIMIT 20
  LOOP
    SELECT * INTO v_res FROM fn_resolve_gom_staff(NULL, rec.staff_id, rec.contact_id, rec.shop_id_2);
    v_staff := NULL;
    IF v_res.o_org_staff_id IS NOT NULL THEN
      SELECT COALESCE(os.name_akabiz, os.name) INTO v_staff FROM org_staff os WHERE os.id = v_res.o_org_staff_id;
    END IF;
    IF v_staff IS NULL OR v_staff = '' THEN v_staff := 'Chưa gán NV'; END IF;

    SELECT s.name, s.pancake_page_id INTO v_shop, v_page FROM shops s WHERE s.id = rec.shop_id_2;
    v_plink := CASE WHEN v_page IS NOT NULL AND rec.conversation_id IS NOT NULL
               THEN 'https://pancake.vn/' || v_page || '?c_id=' || rec.conversation_id ELSE '' END;

    v_payload := jsonb_build_object(
      'alertReason',      'Khách đang KẸT LỖI, chưa ai theo sau ' || p_hours || ' giờ',
      'staffName',        v_staff,
      'assignedVia',      v_res.o_via,
      'customerName',     COALESCE(rec.contact_name,''),
      'intent',           rec.bot_intent,
      'customerQuestion', COALESCE(rec.question_content,''),
      'sentAt',           to_char(rec.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh','DD/MM HH24:MI'),
      'pancakeLink',      v_plink,
      'pancake_page',     COALESCE(v_shop,''),
      'note',             'Khách báo lỗi/đang xử lý lỗi mà không được phản hồi — rủi ro churn cao'
    );

    INSERT INTO aka_sales_alert_log(gom_id, intent_code, webhook_url, payload, alert_kind, conversation_id)
    VALUES (rec.gom_id, rec.bot_intent, v_link, v_payload, 'bug_stuck', rec.conversation_id)
    ON CONFLICT (gom_id) DO NOTHING
    RETURNING gom_id INTO v_ins;
    IF v_ins IS NULL THEN CONTINUE; END IF;

    SELECT net.http_post(url := v_link, body := v_payload,
      headers := '{"Content-Type":"application/json"}'::jsonb) INTO v_req;
    UPDATE aka_sales_alert_log SET net_request_id = v_req WHERE gom_id = v_ins;
    v_sent := v_sent + 1;
  END LOOP;
  RETURN v_sent;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_alert_stacked_unanswered(p_min integer DEFAULT 3, p_window_hours integer DEFAULT 4)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_link    text;
  rec       record;
  v_res     record;
  v_staff   text;
  v_shop    text;
  v_page    text;
  v_plink   text;
  v_payload jsonb;
  v_req     bigint;
  v_sent    integer := 0;
  v_ins     uuid;
  v_hour_vn integer := extract(hour from now() AT TIME ZONE 'Asia/Ho_Chi_Minh');
BEGIN
  IF (extract(hour from now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::int * 60 + extract(minute from now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::int) NOT BETWEEN 510 AND 1079 THEN RETURN 0; END IF; -- 8h30-18h VN

  SELECT link INTO v_link FROM aka_webhook_link WHERE id = 1;
  IF v_link IS NULL OR v_link = '' THEN RETURN 0; END IF;

  FOR rec IN
    SELECT m.conversation_id, m.contact_id, m.shop_id_2,
           max(m.contact_name) contact_name,
           count(*) cnt,
           (array_agg(m.id ORDER BY m.created_at DESC) FILTER (WHERE NOT EXISTS
             (SELECT 1 FROM aka_sales_alert_log l0 WHERE l0.gom_id = m.id)))[1] free_gom_id,
           max(m.staff_id::text)::uuid any_staff_id,
           string_agg(DISTINCT m.bot_intent, ', ') intents,
           jsonb_agg(left(coalesce(m.question_content,''),150) ORDER BY m.created_at) questions
    FROM message_gom m
    JOIN aka_ai_intent i ON i.intent_code = m.bot_intent AND i.is_active AND i.is_quan_trong
    WHERE m.account_id = 1001
      AND m.status = 'no_answer'
      AND m.conversation_id IS NOT NULL
      AND m.created_at > now() - make_interval(hours => p_window_hours)
    GROUP BY m.conversation_id, m.contact_id, m.shop_id_2
    HAVING count(*) >= p_min
    LIMIT 20
  LOOP
    IF rec.free_gom_id IS NULL THEN CONTINUE; END IF;

    IF EXISTS (SELECT 1 FROM aka_sales_alert_log l
               WHERE l.alert_kind = 'stacked' AND l.conversation_id = rec.conversation_id
                 AND (l.sent_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
                     = (now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date) THEN CONTINUE; END IF;

    SELECT * INTO v_res FROM fn_resolve_gom_staff(NULL, rec.any_staff_id, rec.contact_id, rec.shop_id_2);
    v_staff := NULL;
    IF v_res.o_org_staff_id IS NOT NULL THEN
      SELECT COALESCE(os.name_akabiz, os.name) INTO v_staff FROM org_staff os WHERE os.id = v_res.o_org_staff_id;
    END IF;
    IF v_staff IS NULL OR v_staff = '' THEN v_staff := 'Chưa gán NV'; END IF;

    SELECT s.name, s.pancake_page_id INTO v_shop, v_page FROM shops s WHERE s.id = rec.shop_id_2;
    v_plink := CASE WHEN v_page IS NOT NULL THEN 'https://pancake.vn/' || v_page || '?c_id=' || rec.conversation_id ELSE '' END;

    v_payload := jsonb_build_object(
      'alertReason',      'KHẨN: khách nhắn ' || rec.cnt || ' tin liên tiếp chưa ai trả lời (trong ' || p_window_hours || 'h)',
      'staffName',        v_staff,
      'assignedVia',      v_res.o_via,
      'customerName',     COALESCE(rec.contact_name,''),
      'messageCount',     rec.cnt,
      'intent',           rec.intents,
      'customerQuestion', (SELECT string_agg(q,' | ') FROM jsonb_array_elements_text(rec.questions) q),
      'pancakeLink',      v_plink,
      'pancake_page',     COALESCE(v_shop,''),
      'note',             'Khách đang chờ dồn nhiều tin — ưu tiên xử lý ngay'
    );

    INSERT INTO aka_sales_alert_log(gom_id, intent_code, webhook_url, payload, alert_kind, conversation_id)
    VALUES (rec.free_gom_id, 'STACKED', v_link, v_payload, 'stacked', rec.conversation_id)
    ON CONFLICT (gom_id) DO NOTHING
    RETURNING gom_id INTO v_ins;
    IF v_ins IS NULL THEN CONTINUE; END IF;

    SELECT net.http_post(url := v_link, body := v_payload,
      headers := '{"Content-Type":"application/json"}'::jsonb) INTO v_req;
    UPDATE aka_sales_alert_log SET net_request_id = v_req WHERE gom_id = v_ins;
    v_sent := v_sent + 1;
  END LOOP;
  RETURN v_sent;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_auto_link_customer_on_cskh_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_staff_uuid UUID;
  v_staff_id_old_text TEXT;
  v_staff_id_old_int INT;
  v_customer_id BIGINT;
  v_up JSONB;
BEGIN
  IF NEW.customer_phone IS NULL OR TRIM(NEW.customer_phone) = '' THEN
    RETURN NEW;
  END IF;
  IF NEW.customer_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- ① Lookup staff theo staff_name
  IF NEW.staff_name IS NOT NULL AND TRIM(NEW.staff_name) != '' THEN
    SELECT id, staff_id_old INTO v_staff_uuid, v_staff_id_old_text
    FROM staffs WHERE LOWER(TRIM(name)) = LOWER(TRIM(NEW.staff_name)) LIMIT 1;
    IF v_staff_uuid IS NOT NULL THEN
      BEGIN v_staff_id_old_int := v_staff_id_old_text::int; EXCEPTION WHEN OTHERS THEN v_staff_id_old_int := NULL; END;
      UPDATE aka_cskh SET staff_id = v_staff_uuid, staff_id_old = v_staff_id_old_int WHERE id = NEW.id;
    END IF;
  END IF;

  -- ② Tìm / tạo aka_customer qua HÀM CHUNG (khóa SĐT; chống trùng + race)
  v_up := public.fn_upsert_aka_customer_v1(jsonb_strip_nulls(jsonb_build_object(
    'phone', NEW.customer_phone,
    'name', NEW.customer_name,
    'chat_staff_id', v_staff_uuid,
    'channel', 'cskh',
    'creation_path', 'aka_cskh_auto_link',
    'custom_fields', jsonb_build_object('aka_cskh_id', NEW.id)
  )));
  IF coalesce((v_up ->> 'ok')::boolean, false) THEN
    v_customer_id := (v_up ->> 'customer_id')::bigint;
    IF coalesce((v_up ->> 'is_new')::boolean, false) THEN
      UPDATE aka_customer SET staff_id = COALESCE(staff_id, v_staff_uuid),
                              staff_id_old = COALESCE(staff_id_old, v_staff_id_old_text),
                              staff_name = COALESCE(staff_name, NEW.staff_name)
      WHERE id = v_customer_id;
    END IF;
  ELSE
    -- SĐT không hợp lệ theo chuẩn VN -> giữ hành vi cũ: thử khớp thô
    SELECT id INTO v_customer_id FROM aka_customer WHERE phone = NEW.customer_phone LIMIT 1;
  END IF;

  IF v_customer_id IS NOT NULL THEN
    UPDATE aka_cskh SET customer_id = v_customer_id WHERE id = NEW.id;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_birthday_care_process_job_v2(p_job_id bigint, p_dry_run boolean DEFAULT false, p_allow_past boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_job       aka_birthday_care_job%rowtype;
  v_cfg       aka_birthday_care_config%rowtype;
  v_gom       message_gom%rowtype;
  v_contact   contacts%rowtype;
  v_cust      aka_customer%rowtype;
  v_customer_id bigint;
  v_resolve_source text;
  v_phone     text;
  v_phone_from_name text;
  v_name      text;
  v_pancake_url text;
  v_lifecycle jsonb;
  v_owner_id  bigint; v_org_id bigint; v_owner_name text; v_owner_source text;
  v_existing_crm_id bigint; v_existing_type bigint;
  v_day_start timestamptz; v_day_end timestamptz;
  v_type_name text; v_priority integer;
  v_ctx jsonb; v_comp jsonb;
  v_source_type text;
  v_sel jsonb;
  v_crm_id bigint;
  v_last_msg text; v_last_msg_at timestamptz;
  v_result jsonb;
  v_now timestamptz := now();
begin
  select * into v_job from aka_birthday_care_job where id = p_job_id for update skip locked;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'job_not_found_or_locked', 'job_id', p_job_id);
  end if;
  if v_job.status <> 'queued' and not p_dry_run then
    return jsonb_build_object('ok', true, 'action', 'already_' || v_job.status, 'job_id', p_job_id, 'crm_id', v_job.crm_id);
  end if;

  select * into v_cfg from aka_birthday_care_config where singleton;
  select * into v_gom from message_gom where id = v_job.message_gom_id;
  if not found then
    return fn_birthday_care_finish_v2(p_job_id, p_dry_run, 'skipped', 'gom_not_found', null, null);
  end if;
  if not fn_birthday_care_is_birthday_v2(v_gom.intent, v_gom.ai_intent, v_gom.bot_intent, v_gom.question_content) then
    return fn_birthday_care_finish_v2(p_job_id, p_dry_run, 'skipped', 'not_birthday', null, null);
  end if;
  -- ưu đãi chỉ có hiệu lực đúng ngày sinh nhật: job của ngày cũ bỏ qua (trừ khi ép)
  if v_job.birthday_date_vn <> (v_now at time zone 'Asia/Ho_Chi_Minh')::date and not p_allow_past then
    return fn_birthday_care_finish_v2(p_job_id, p_dry_run, 'skipped', 'birthday_day_expired', null, null);
  end if;
  if not coalesce(v_cfg.enabled, false) then
    return fn_birthday_care_finish_v2(p_job_id, p_dry_run, 'skipped', 'flow_disabled', null, null);
  end if;

  if v_gom.contact_id is not null then
    select * into v_contact from contacts where id = v_gom.contact_id;
    if found and coalesce(v_contact.is_group, false) then
      return fn_birthday_care_finish_v2(p_job_id, p_dry_run, 'skipped', 'group_contact', null, null);
    end if;
  end if;

  -- ===== SĐT: contact → gom → trích từ tên hiển thị =====
  v_phone_from_name := (regexp_match(coalesce(v_contact.name, '') || ' ' || coalesce(v_gom.contact_name, ''), '(0[1-9][0-9]{8})'))[1];
  v_phone := normalize_phone(coalesce(nullif(btrim(v_contact.phone), ''), nullif(btrim(v_gom.phone), ''), nullif(btrim(v_gom.shared_phone), ''), v_phone_from_name));
  if v_phone !~ '^0[1-9][0-9]{8}$' then v_phone := null; end if;

  v_pancake_url := coalesce(fn_zalo_chat_referral_pancake_url_v1(v_gom.id),
    (select 'https://pancake.vn/' || s.pancake_page_id || '?c_id=' || v_gom.conversation_id
       from shops s where s.id::text = v_gom.shop_id and nullif(btrim(s.pancake_page_id), '') is not null limit 1));

  -- ===== resolve khách =====
  v_customer_id := v_gom.aka_customer_id; v_resolve_source := 'message_gom';
  if v_customer_id is null and v_contact.customer_id is not null then
    v_customer_id := v_contact.customer_id; v_resolve_source := 'contact';
  end if;
  if v_customer_id is not null then
    select * into v_cust from aka_customer where id = v_customer_id;
    if not found then
      v_customer_id := null;
    elsif coalesce(v_cust.record_state, 'active') = 'merged' and v_cust.merged_into_customer_id is not null then
      v_customer_id := v_cust.merged_into_customer_id; v_resolve_source := v_resolve_source || '+merged';
      select * into v_cust from aka_customer where id = v_customer_id;
    end if;
  end if;
  if v_customer_id is null and v_phone is not null then
    select * into v_cust from aka_customer c
    where normalize_phone(c.phone) = v_phone and coalesce(c.record_state, 'active') <> 'merged'
    order by case when c.account_id = v_gom.account_id then 0 else 1 end, c.created_at desc nulls last, c.id desc
    limit 1;
    if found then v_customer_id := v_cust.id; v_resolve_source := case when v_phone_from_name is not null and v_phone = normalize_phone(v_phone_from_name) then 'phone_in_name' else 'phone' end; end if;
  end if;

  v_name := coalesce(
    fn_birthday_care_clean_name_v2(v_cust.name),
    fn_birthday_care_clean_name_v2(v_contact.name),
    fn_birthday_care_clean_name_v2(v_gom.contact_name),
    nullif(btrim(v_cust.name_zalo), ''));
  v_phone := coalesce(nullif(normalize_phone(v_cust.phone), ''), v_phone);

  if v_customer_id is null then
    update aka_birthday_care_job set contact_name = coalesce(v_name, contact_name), phone = v_phone, pancake_url = v_pancake_url, updated_at = v_now where id = p_job_id;
    return fn_birthday_care_finish_v2(p_job_id, p_dry_run, 'skipped', 'customer_unresolved', null, null);
  end if;

  -- ===== phân loại gói =====
  v_lifecycle := fn_birthday_care_classify_v2(v_customer_id, v_job.birthday_date_vn);
  update aka_birthday_care_job
    set customer_id = v_customer_id, customer_name = v_name, phone = v_phone, pancake_url = v_pancake_url,
        resolve_source = v_resolve_source, lifecycle = v_lifecycle, updated_at = v_now
  where id = p_job_id;

  if not coalesce((v_lifecycle ->> 'eligible')::boolean, false) then
    return fn_birthday_care_finish_v2(p_job_id, p_dry_run, 'skipped', coalesce(v_lifecycle ->> 'skip_reason', 'not_eligible'), null, null);
  end if;
  v_sel := v_lifecycle -> 'selected';

  -- ===== chống trùng =====
  v_source_type := 'birthday_care:' || v_gom.id::text;
  select id into v_existing_crm_id from aka_crm where source_type = v_source_type limit 1;
  if v_existing_crm_id is not null then
    return fn_birthday_care_finish_v2(p_job_id, p_dry_run, 'duplicate', 'duplicate_source', v_existing_crm_id, v_existing_crm_id);
  end if;
  v_day_start := (v_job.birthday_date_vn::timestamp) at time zone 'Asia/Ho_Chi_Minh';
  v_day_end := v_day_start + interval '1 day';
  perform pg_advisory_xact_lock(hashtextextended('birthday_care:' || v_customer_id::text || ':' || v_job.birthday_date_vn::text, 0));
  select c.id, c.crm_type_id into v_existing_crm_id, v_existing_type
  from aka_crm c
  where c.customer_id = v_customer_id and c.created_at >= v_day_start and c.created_at < v_day_end
    and (c.crm_type_id = v_cfg.crm_type_id or coalesce(v_cfg.skip_if_other_crm_today, true))
  order by case when c.crm_type_id = v_cfg.crm_type_id then 0 else 1 end, c.created_at desc
  limit 1;
  if v_existing_crm_id is not null then
    return fn_birthday_care_finish_v2(p_job_id, p_dry_run, 'duplicate',
      case when v_existing_type = v_cfg.crm_type_id then 'duplicate_customer_birthday' else 'customer_has_crm_today_type_' || v_existing_type end,
      null, v_existing_crm_id);
  end if;

  -- ===== owner (cùng thang với phone-nudge / referral v3) =====
  select os.id, os.organization_id, os.name, 'chủ khách' into v_owner_id, v_org_id, v_owner_name, v_owner_source
  from org_staff os where os.id = v_cust.org_staff_id_owner and os.is_active = true;
  if v_owner_id is null and v_gom.conversation_id is not null then
    select os.id, os.organization_id, os.name, 'NV trả lời hội thoại' into v_owner_id, v_org_id, v_owner_name, v_owner_source
    from message_gom g2 join org_staff os on os.id = g2.answer_org_staff_id
    where g2.conversation_id = v_gom.conversation_id and g2.shop_id is not distinct from v_gom.shop_id
      and g2.answer_org_staff_id is not null and os.is_active = true
    order by coalesce(g2.answer_first_at, g2.created_at) desc limit 1;
  end if;
  if v_owner_id is null and v_contact.id is not null then
    select os.id, os.organization_id, os.name, 'NV phụ trách contact' into v_owner_id, v_org_id, v_owner_name, v_owner_source
    from unnest(coalesce(v_contact.staff_ids, array[]::text[])) sid(value)
    join org_staff os on os.chat_staff_id::text = sid.value
    where os.is_active = true order by os.id limit 1;
  end if;
  if v_owner_id is null then
    select os.id, os.organization_id, os.name, 'quản lý page' into v_owner_id, v_org_id, v_owner_name, v_owner_source
    from shops s join org_staff os on os.id = s.manager_org_staff_id
    where os.is_active = true and s.id = v_gom.shop_id_2 limit 1;
  end if;
  if v_owner_id is null then
    select os.id, os.organization_id, os.name, 'chia tự động' into v_owner_id, v_org_id, v_owner_name, v_owner_source
    from org_staff os
    where os.is_active = true and os.is_data_division = true
    order by (select count(*) from aka_crm x where x.org_staff_owner_id = os.id and x.created_at >= v_day_start), os.id
    limit 1;
  end if;
  if v_owner_id is null or v_org_id is null then
    return fn_birthday_care_finish_v2(p_job_id, p_dry_run, 'error', 'active_owner_not_resolved', null, null);
  end if;

  -- ===== tin gần nhất của khách (ngoài tin sinh nhật) =====
  select g2.question_content, coalesce(g2.question_first_at, g2.created_at) into v_last_msg, v_last_msg_at
  from message_gom g2
  where g2.conversation_id = v_gom.conversation_id and g2.id <> v_gom.id and g2.initiated_by = 'CUSTOMER'
    and nullif(btrim(g2.question_content), '') is not null
    and not fn_birthday_care_is_birthday_v2(g2.intent, g2.ai_intent, g2.bot_intent, g2.question_content)
  order by coalesce(g2.question_first_at, g2.created_at) desc limit 1;

  select t.name, t.stt into v_type_name, v_priority from aka_crm_type t where t.id = v_cfg.crm_type_id and t.is_active = true;
  if not found then
    return fn_birthday_care_finish_v2(p_job_id, p_dry_run, 'error', 'crm_type_inactive', null, null);
  end if;

  v_ctx := jsonb_build_object(
    'name', v_name, 'phone', v_phone, 'zalo', nullif(btrim(v_cust.zalo), ''), 'pancake_url', v_pancake_url,
    'birthday_date_vn', v_job.birthday_date_vn,
    'greeting_sent_at', v_gom.sent_at, 'greeting_status', v_gom.send_status, 'greeting_content', v_gom.reply_content,
    'lifecycle', v_lifecycle, 'owner_name', v_owner_name, 'owner_source', v_owner_source,
    'last_customer_message', v_last_msg, 'last_customer_message_at', v_last_msg_at,
    'cfg', to_jsonb(v_cfg));
  v_comp := fn_birthday_care_compose_v2(v_ctx);

  if p_dry_run then
    return jsonb_build_object('ok', true, 'dry_run', true, 'action', 'would_create', 'job_id', p_job_id,
      'customer_id', v_customer_id, 'customer_name', v_name, 'phone', v_phone, 'pancake_url', v_pancake_url,
      'resolve_source', v_resolve_source, 'rule', v_lifecycle ->> 'rule', 'segment', v_lifecycle ->> 'segment',
      'owner', v_owner_name, 'owner_source', v_owner_source, 'note', v_comp ->> 'note', 'message', v_comp ->> 'message');
  end if;

  insert into aka_crm (
    customer_id, customer_name, customer_phone, crm_type_id, priority, org_staff_owner_id, organization_id,
    created_by, note, suggested_content, proposed_content, proposed_channel, suggested_channel_id,
    cskh_due_date, is_read, source_type, source_order_id, org_organization_product_id,
    source_expiration_date, source_expiration_source, sql_account_id,
    gen_agent, gen_status, gen_at, gen_meta, pancake_url
  ) values (
    v_customer_id, v_name, v_phone, v_cfg.crm_type_id, v_priority, v_owner_id, v_org_id,
    v_owner_id, v_comp ->> 'note', v_comp ->> 'message', v_comp ->> 'message', 'zalo', 8,
    private.zalo_referral_due_date_v1(v_now), false, v_source_type,
    case when v_sel ->> 'source' = 'aka_order' then (v_sel ->> 'id')::bigint end,
    case when v_sel ->> 'source' = 'org_organization_product' then (v_sel ->> 'id')::bigint end,
    (v_sel ->> 'expires_on')::date,
    case when v_sel ->> 'expires_on' is not null then 'birthday_care_v2:' || (v_sel ->> 'source') end,
    v_gom.account_id,
    'birthday-care-v2', 'created', v_now,
    jsonb_strip_nulls(jsonb_build_object(
      'version', 'v2', 'job_id', p_job_id, 'message_gom_id', v_gom.id::text, 'conversation_id', v_gom.conversation_id,
      'contact_id', v_gom.contact_id::text, 'birthday_date_vn', v_job.birthday_date_vn, 'resolve_source', v_resolve_source,
      'rule', v_lifecycle ->> 'rule', 'segment', v_lifecycle ->> 'segment', 'selected', v_sel,
      'stats', v_lifecycle -> 'stats', 'offer', v_comp ->> 'offer', 'bonus_days', v_comp -> 'bonus_days',
      'discount_percent', v_comp -> 'discount_percent', 'owner_source', v_owner_source)),
    v_pancake_url
  ) returning id into v_crm_id;

  update message_gom set crm_id = coalesce(crm_id, v_crm_id), crm_ids = array_append(coalesce(crm_ids, '{}'::bigint[]), v_crm_id)
  where id = v_gom.id and not (v_crm_id = any (coalesce(crm_ids, '{}'::bigint[])));

  v_result := fn_birthday_care_finish_v2(p_job_id, false, 'created', v_lifecycle ->> 'rule', v_crm_id, null);
  return v_result || jsonb_build_object('customer_id', v_customer_id, 'customer_name', v_name, 'owner', v_owner_name, 'segment', v_lifecycle ->> 'segment');
exception
  when others then
    update aka_birthday_care_job
      set attempt_count = attempt_count + 1, last_error = left(sqlstate || ' ' || sqlerrm, 500), updated_at = now(),
          status = case when attempt_count + 1 >= coalesce(v_cfg.max_attempts, 3) then 'error' else 'queued' end,
          reason = case when attempt_count + 1 >= coalesce(v_cfg.max_attempts, 3) then 'max_attempts' else reason end,
          process_after = now() + interval '5 minutes'
    where id = p_job_id;
    return jsonb_build_object('ok', false, 'error', sqlstate || ' ' || sqlerrm, 'job_id', p_job_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_birthday_care_run_v2(p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id bigint; v_r jsonb; v_out jsonb := '[]'::jsonb; v_n integer := 0;
begin
  for v_id in
    select id from aka_birthday_care_job
    where status = 'queued' and process_after <= now()
    order by process_after, id limit greatest(p_limit, 1)
  loop
    v_r := fn_birthday_care_process_job_v2(v_id, false);
    v_n := v_n + 1;
    v_out := v_out || jsonb_build_array(v_r - 'note' - 'message');
  end loop;
  return jsonb_build_object('processed', v_n, 'results', v_out);
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_birthday_offer_authorize_send_v1(p_job_id uuid, p_claim_token uuid, p_promotion_id bigint, p_promotion_match_key text, p_ai_log_id bigint, p_message_sha256 text, p_expected_content text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_job private.birthday_offer_jobs%rowtype;
  v_context jsonb;
  v_promotion jsonb;
  v_workflow jsonb;
  v_using_id bigint;
  v_auto_send_enabled boolean := false;
  v_require_active_promotion boolean := true;
  v_daily_cap integer := 10;
  v_min_confidence numeric := 0.70;
  v_ai public.ai_log%rowtype;
  v_ai_decision text;
  v_ai_confidence numeric;
  v_ai_product_id bigint;
  v_ai_product_code text;
  v_hash text;
  v_day_start timestamptz;
  v_day_end timestamptz;
  v_send_deadline timestamptz;
  v_authorized_count integer;
begin
  select j.* into v_job
  from private.birthday_offer_jobs j
  where j.id = p_job_id
    and j.status = 'processing'
    and j.claim_token = p_claim_token
    and j.lease_expires_at > pg_catalog.now()
  for update;

  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'authorized', false, 'status', 'invalid_claim',
      'reason', 'claim_missing_or_expired'
    );
  end if;

  if v_job.stage = 'reconcile' or v_job.authorized_at is not null then
    if v_job.authorized_at is not null
       and v_job.authorized_claim_token = p_claim_token
       and v_job.stage = 'send'
       and v_job.expected_message_sha256 = pg_catalog.lower(coalesce(p_message_sha256, ''))
       and (v_job.authorized_promotion ->> 'id')::bigint = p_promotion_id then
      return pg_catalog.jsonb_build_object(
        'ok', true,
        'authorized', true,
        'status', 'authorized',
        'job_id', v_job.id,
        'customer_id', v_job.customer_id,
        'lifecycle_status', v_job.classifier_snapshot ->> 'status',
        'promotion', v_job.authorized_promotion,
        'delivery', v_job.delivery_snapshot,
        'authorization', pg_catalog.jsonb_build_object(
          'authorized_at', v_job.authorized_at,
          'send_deadline', least(
            ((v_job.birthday_date_vn + 1)::timestamp at time zone 'Asia/Ho_Chi_Minh'),
            coalesce(
              (v_job.authorized_promotion ->> 'ends_at')::timestamptz,
              ((v_job.birthday_date_vn + 1)::timestamp at time zone 'Asia/Ho_Chi_Minh')
            )
          ),
          'message_sha256', v_job.expected_message_sha256,
          'ai_log_id', v_job.authorized_ai_log_id
        )
      );
    end if;

    return pg_catalog.jsonb_build_object(
      'ok', false, 'authorized', false, 'status', 'reconcile_required',
      'reason', 'job_already_authorized_do_not_resend'
    );
  end if;

  if v_job.dry_run then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'authorized', false, 'status', 'dry_run_only',
      'reason', 'dry_run_job_cannot_authorize_external_send'
    );
  end if;

  if nullif(pg_catalog.btrim(p_expected_content), '') is null
     or pg_catalog.length(p_expected_content) > 500 then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'authorized', false, 'status', 'invalid_message',
      'reason', 'expected_content_required_and_max_500_chars'
    );
  end if;

  v_hash := pg_catalog.encode(
    extensions.digest(p_expected_content, 'sha256'),
    'hex'
  );

  if pg_catalog.lower(coalesce(p_message_sha256, '')) <> v_hash then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'authorized', false, 'status', 'invalid_message',
      'reason', 'message_sha256_mismatch'
    );
  end if;

  select u.id, u.request_options -> 'workflow' into v_using_id, v_workflow
  from public.ai_using u
  where u.code = 'birthday_offer_analyze_v1'
    and u.is_active
  order by u.updated_at desc nulls last, u.id desc
  limit 1;

  if v_workflow is null then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'authorized', false, 'status', 'workflow_disabled',
      'reason', 'birthday_offer_analyze_v1_workflow_missing_or_inactive'
    );
  end if;

  begin
    v_auto_send_enabled := coalesce((v_workflow ->> 'auto_send_enabled')::boolean, false);
    v_require_active_promotion := coalesce(
      (v_workflow ->> 'require_active_promotion')::boolean,
      false
    );
    v_daily_cap := least(
      greatest(coalesce((v_workflow ->> 'daily_send_cap')::integer, 10), 0),
      100
    );
    v_min_confidence := least(
      greatest(coalesce((v_workflow ->> 'min_confidence')::numeric, 0.70), 0),
      1
    );
  exception
    when others then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'authorized', false, 'status', 'workflow_disabled',
        'reason', 'workflow_config_invalid'
      );
  end;

  if not v_auto_send_enabled then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'authorized', false, 'status', 'workflow_disabled',
      'reason', 'auto_send_enabled_is_false'
    );
  end if;

  if not v_require_active_promotion then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'authorized', false, 'status', 'workflow_disabled',
      'reason', 'require_active_promotion_must_be_true'
    );
  end if;

  v_context := private.birthday_offer_context_v1(v_job.birthday_gom_id);

  if v_context ->> 'action' <> 'send_offer'
     or v_context ->> 'status' not in ('expired_used', 'never_purchased') then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'authorized', false, 'status', 'candidate_changed',
      'reason', 'customer_no_longer_send_offer_candidate'
    );
  end if;

  if v_context -> 'delivery' is distinct from v_job.delivery_snapshot then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'authorized', false, 'status', 'delivery_changed',
      'reason', 'delivery_snapshot_changed'
    );
  end if;

  select item into v_promotion
  from pg_catalog.jsonb_array_elements(coalesce(v_context -> 'allowed_promotions', '[]'::jsonb)) item
  where (item ->> 'id')::bigint = p_promotion_id
    and item ->> 'match_key' = p_promotion_match_key
  limit 1;

  if v_promotion is null then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'authorized', false, 'status', 'no_active_promotion',
      'reason', 'promotion_missing_expired_or_not_matched'
    );
  end if;

  select l.* into v_ai
  from public.ai_log l
  where l.id = p_ai_log_id
    and l.using_id = v_using_id
    and l.using_code = 'birthday_offer_analyze_v1'
    and l.block_name = 'birthday-offer-analyze-v1'
    and l.node_id = 'birthday-offer:' || p_job_id::text
    and l.status = 'success'
    and l.provider = 'deepseek'
    and l.sanitized_request ->> 'schema_version' = 'birthday_offer_analyze_v1'
    and l.sanitized_request ->> 'job_id' = p_job_id::text
    and l.sanitized_request ->> 'birthday_gom_id' = v_job.birthday_gom_id::text
    and l.sanitized_request ->> 'customer_id' = v_job.customer_id::text
    and l.sanitized_request ->> 'promotion_id' = p_promotion_id::text
    and l.sanitized_response ->> 'schema_version' = 'birthday_offer_analyze_v1'
  order by l.created_at desc, l.id desc
  limit 1;

  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'authorized', false, 'status', 'ai_not_approved',
      'reason', 'successful_ai_log_not_found'
    );
  end if;

  v_ai_decision := pg_catalog.upper(coalesce(
    v_ai.sanitized_response ->> 'decision',
    v_ai.sanitized_response #>> '{verdict,decision}',
    case when pg_catalog.lower(coalesce(v_ai.sanitized_response ->> 'should_send', 'false')) = 'true'
      then 'SEND' else 'SKIP' end
  ));

  begin
    v_ai_confidence := coalesce(
      nullif(v_ai.sanitized_response ->> 'confidence', '')::numeric,
      nullif(v_ai.sanitized_response #>> '{verdict,confidence}', '')::numeric
    );
  exception
    when others then
      v_ai_confidence := null;
  end;

  begin
    v_ai_product_id := coalesce(
      nullif(v_ai.sanitized_response ->> 'product_id', '')::bigint,
      nullif(v_ai.sanitized_response #>> '{verdict,product_id}', '')::bigint
    );
  exception
    when others then
      v_ai_product_id := null;
  end;
  v_ai_product_code := pg_catalog.lower(pg_catalog.btrim(coalesce(
    v_ai.sanitized_response ->> 'product_code',
    v_ai.sanitized_response #>> '{verdict,product_code}',
    ''
  )));

  if v_ai_decision <> 'SEND'
     or v_ai_confidence is null
     or v_ai_confidence < v_min_confidence then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'authorized', false, 'status', 'ai_not_approved',
      'reason', 'decision_or_confidence_rejected'
    );
  end if;

  if pg_catalog.lower(coalesce(v_ai.sanitized_response ->> 'do_not_contact', 'true')) <> 'false'
     or pg_catalog.lower(coalesce(
       v_ai.sanitized_response ->> 'support_or_complaint_only',
       'true'
     )) <> 'false'
     or (
       v_context ->> 'status' = 'never_purchased'
       and pg_catalog.upper(coalesce(v_ai.sanitized_response ->> 'product_source', '')) <> 'CHAT'
     )
     or (
       v_context ->> 'status' = 'expired_used'
       and pg_catalog.upper(coalesce(v_ai.sanitized_response ->> 'product_source', ''))
           not in ('CHAT', 'DB_HISTORY')
     )
     or (
       pg_catalog.upper(coalesce(v_ai.sanitized_response ->> 'product_source', '')) = 'CHAT'
       and case
         when pg_catalog.jsonb_typeof(v_ai.sanitized_response -> 'evidence_seqs') = 'array'
         then pg_catalog.jsonb_array_length(v_ai.sanitized_response -> 'evidence_seqs') = 0
         else true
       end
     ) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'authorized', false, 'status', 'ai_not_approved',
      'reason', 'ai_safety_flags_or_evidence_rejected'
    );
  end if;

  if (v_ai_product_id is null and v_ai_product_code = '')
     or (
       v_ai_product_id is not null
       and v_ai_product_id is distinct from (v_promotion ->> 'product_id')::bigint
     )
     or (
       v_ai_product_id is null
       and v_ai_product_code is distinct from
         pg_catalog.lower(coalesce(v_promotion ->> 'product_code', ''))
     ) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'authorized', false, 'status', 'promotion_mismatch',
      'reason', 'ai_product_not_allowed_by_promotion'
    );
  end if;

  v_day_start := (v_job.birthday_date_vn::timestamp at time zone 'Asia/Ho_Chi_Minh');
  v_day_end := ((v_job.birthday_date_vn + 1)::timestamp at time zone 'Asia/Ho_Chi_Minh');
  v_send_deadline := least(
    v_day_end,
    coalesce((v_promotion ->> 'ends_at')::timestamptz, v_day_end)
  );

  if pg_catalog.now() >= v_send_deadline then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'authorized', false, 'status', 'candidate_changed',
      'reason', 'birthday_offer_day_expired'
    );
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      pg_catalog.format('birthday_offer_daily_cap:%s', v_job.birthday_date_vn),
      0
    )
  );

  select count(*)::integer into v_authorized_count
  from private.birthday_offer_jobs j
  where j.dry_run = false
    and j.authorized_at >= v_day_start
    and j.authorized_at < v_day_end;

  if v_authorized_count >= v_daily_cap then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'authorized', false, 'status', 'daily_send_cap_reached',
      'reason', 'daily_send_cap_reached',
      'daily_send_cap', v_daily_cap
    );
  end if;

  update private.birthday_offer_jobs j
  set authorized_at = pg_catalog.now(),
      authorized_claim_token = p_claim_token,
      reconcile_deadline_at = least(
        pg_catalog.now() + interval '30 minutes',
        v_send_deadline
      ),
      authorized_ai_log_id = p_ai_log_id,
      authorized_promotion = v_promotion,
      expected_message_sha256 = v_hash,
      expected_message_content = p_expected_content,
      stage = 'send',
      classifier_snapshot = v_context
  where j.id = v_job.id;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'authorized', true,
    'status', 'authorized',
    'job_id', v_job.id,
    'customer_id', v_job.customer_id,
    'lifecycle_status', v_context ->> 'status',
    'promotion', v_promotion,
    'delivery', v_context -> 'delivery',
    'authorization', pg_catalog.jsonb_build_object(
      'authorized_at', pg_catalog.now(),
      'send_deadline', v_send_deadline,
      'message_sha256', v_hash,
      'ai_log_id', p_ai_log_id
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_chat_followup_post_ai_filter_v1(p_day date, p_customer_id bigint, p_contact_id uuid, p_conversation_id text, p_gom_id uuid, p_apply boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  cfg             public.aka_chat_followup_filter_config%rowtype;
  v_final         bigint := p_customer_id;
  v_phone         text;
  v_phone_src     text;
  v_pancake       text;
  v_conv          text;
  v_page          text;
  v_owner         bigint;
  v_owner_src     text;
  v_group         text;
  v_days_left     integer;
  v_reason        text := 'ok';
  v_pass          boolean := true;
  v_target        bigint;
  v_merged        boolean := false;
  v_merge_err     text;
  v_cust          public.aka_customer%rowtype;
  v_dup_crm       bigint;
  v_dau           timestamptz;
  v_cuoi          timestamptz;
  v_now           timestamptz := now();
  v_paid_far      boolean;
  v_paid_near     boolean;
  v_paid_near_exp timestamptz;
  v_had_paid      boolean;
  v_demo_active   boolean;
  v_had_demo      boolean;
  v_details       jsonb := '{}'::jsonb;
begin
  select * into cfg from public.aka_chat_followup_filter_config where id = 1;
  if cfg.id is null or not cfg.enabled then
    return jsonb_build_object('passed', true, 'reason', 'filter_disabled',
                              'final_customer_id', p_customer_id);
  end if;

  v_dau  := ((p_day - cfg.crm_dup_window_days)::timestamp at time zone 'Asia/Ho_Chi_Minh');
  v_cuoi := ((p_day + cfg.crm_dup_window_days + 1)::timestamp at time zone 'Asia/Ho_Chi_Minh');

  -- ---------- A. SDT ----------
  select e.phone, e.source into v_phone, v_phone_src
    from public.fn_chat_followup_extract_phone_v1(p_customer_id, p_contact_id, p_conversation_id, p_gom_id) e
   limit 1;

  -- ---------- B. Link pancake dung chuan ----------
  if p_contact_id is not null then
    select ct.conversion_id, sh.pancake_page_id
      into v_conv, v_page
      from public.contacts ct
      left join public.shops sh on sh.id::text = ct.shop_id
     where ct.id = p_contact_id;
    if v_conv is not null and v_page is not null then
      v_pancake := format('https://pancake.vn/%s?c_id=%s', v_page, v_conv);
      if v_pancake !~ '^https://pancake\.vn/[A-Za-z0-9_\-]+\?c_id=[A-Za-z0-9_\-]+$' then
        v_pancake := null;
      end if;
    end if;
  end if;

  -- ---------- C. Gop trung theo SDT ----------
  if v_phone is not null then
    select c.id into v_target
      from public.aka_customer c
     where public.normalize_phone(c.phone) = v_phone
       and coalesce(c.record_state, '') <> 'merged'
     order by (c.id = p_customer_id) desc, c.id desc
     limit 1;
    if v_target is not null and v_target <> p_customer_id then
      v_final := v_target;
      v_details := v_details || jsonb_build_object('phone_matched_customer_id', v_target);
    end if;
  end if;

  select * into v_cust from public.aka_customer where id = v_final;
  if v_cust.id is null then
    return jsonb_build_object('passed', false, 'reason', 'khach_khong_ton_tai', 'final_customer_id', v_final);
  end if;
  if coalesce(v_cust.record_state,'') = 'merged' and v_cust.merged_into_customer_id is not null then
    v_final := v_cust.merged_into_customer_id;
    select * into v_cust from public.aka_customer where id = v_final;
  end if;

  -- ---------- D. Nhom khach (tinh tren khach cuoi cung) ----------
  select
    bool_or(exp_at > v_now + make_interval(days => cfg.renewal_window_days)),
    bool_or(exp_at >= v_now and exp_at <= v_now + make_interval(days => cfg.renewal_window_days)),
    max(exp_at) filter (where exp_at >= v_now and exp_at <= v_now + make_interval(days => cfg.renewal_window_days)),
    count(*) > 0
  into v_paid_far, v_paid_near, v_paid_near_exp, v_had_paid
  from (
    select ao.date_expiration as exp_at
      from public.aka_order ao
     where ao.customer_id = v_final
       and coalesce(ao.is_active, true) = true
       and coalesce(ao.is_demo, false) = false
       and lower(coalesce(ao.package, '')) <> 'demo'
       and nullif(btrim(coalesce(ao.product_list, '')), '') is not null
       and btrim(coalesce(ao.product_list, '')) <> '[]'
    union all
    select op.expiration_date
      from public.org_organization_product op
      join public.org_organization org on org.id = op.organization_id
     where org.customer_id = v_final
       and coalesce(op.is_deleted, false) = false
       and op.is_paid
       and coalesce(op.is_lock, false) = false
  ) paid;

  select bool_or(exp_at >= v_now), count(*) > 0
    into v_demo_active, v_had_demo
  from (
    select ao.date_expiration as exp_at
      from public.aka_order ao
     where ao.customer_id = v_final
       and (coalesce(ao.is_demo, false) or lower(coalesce(ao.package, '')) = 'demo')
    union all
    select op.expiration_date
      from public.org_organization_product op
      join public.org_organization org on org.id = op.organization_id
     where org.customer_id = v_final
       and coalesce(op.is_deleted, false) = false
       and not coalesce(op.is_paid, false)
  ) demo;

  v_paid_far := coalesce(v_paid_far, false);
  v_paid_near := coalesce(v_paid_near, false);
  v_had_paid := coalesce(v_had_paid, false);
  v_demo_active := coalesce(v_demo_active, false);
  v_had_demo := coalesce(v_had_demo, false);

  if v_paid_far then
    v_group := 'con_han_dai'; v_pass := false; v_reason := 'con_han_dai';
  elsif v_paid_near then
    v_group := 'con_han_sap_het';
    v_days_left := greatest(0, floor(extract(epoch from (v_paid_near_exp - v_now)) / 86400))::int;
  elsif v_had_paid then
    v_group := 'het_han_su_dung';
  elsif v_demo_active and not cfg.allow_active_demo then
    v_group := 'dang_demo'; v_pass := false; v_reason := 'dang_demo';
  elsif v_had_demo then
    v_group := case when v_demo_active then 'dang_demo' else 'het_han_demo' end;
  else
    v_group := 'chua_mua';
  end if;

  -- ---------- E. Phai co SDT hoac link pancake ----------
  if v_pass and cfg.require_contact and v_phone is null and v_pancake is null then
    v_pass := false; v_reason := 'khong_co_lien_he';
  end if;

  -- ---------- F. Chong trung CRM ±N ngay, moi type ----------
  if v_pass then
    select cr.id into v_dup_crm
      from public.aka_crm cr
     where cr.customer_id = v_final
       and coalesce(cr.source_type, '') not like 'chat_followup:' || to_char(p_day, 'YYYYMMDD') || ':%'
       and (
         (cr.created_at >= v_dau and cr.created_at < v_cuoi)
         or (cr.cskh_due_date >= v_dau and cr.cskh_due_date < v_cuoi)
       )
     order by cr.created_at desc
     limit 1;
    if v_dup_crm is not null then
      v_pass := false; v_reason := 'trung_crm_7_ngay';
      v_details := v_details || jsonb_build_object('dup_crm_id', v_dup_crm);
    end if;
  end if;

  -- ---------- G. Owner = NV nhan tin gan nhat ----------
  select g.answer_org_staff_id into v_owner
    from public.message_gom g
   where ((p_conversation_id is not null and g.conversation_id = p_conversation_id) or g.id = p_gom_id)
     and g.answer_org_staff_id is not null
   order by coalesce(g.answer_last_at, g.created_at) desc
   limit 1;
  v_owner_src := 'conversation';
  if v_owner is null and p_contact_id is not null then
    select g.answer_org_staff_id into v_owner
      from public.message_gom g
     where g.contact_id = p_contact_id and g.answer_org_staff_id is not null
     order by coalesce(g.answer_last_at, g.created_at) desc
     limit 1;
    v_owner_src := 'contact';
  end if;
  if v_owner is null then
    v_owner := v_cust.org_staff_id_owner; v_owner_src := 'customer_owner';
  end if;
  if v_owner is null then
    select s.id into v_owner
      from public.org_staff s
     where s.is_active and s.is_data_division
     order by (select count(*) from public.aka_crm r2
                where r2.org_staff_owner_id = s.id and r2.cskh_completed_date is null), s.id
     limit 1;
    v_owner_src := 'data_division_least_loaded';
  end if;

  -- ---------- H. Ap dung ----------
  if p_apply and v_pass and cfg.update_customer then
    update public.aka_customer c
       set phone = case when public.fn_normalize_phone_vn(c.phone) ~ '^0[35789][0-9]{8}$' then c.phone else coalesce(v_phone, c.phone) end,
           custom_fields = coalesce(c.custom_fields, '{}'::jsonb)
             || case when v_pancake is not null then jsonb_build_object(
                  'pancake_url', v_pancake,
                  'contact_id', p_contact_id::text,
                  'conversion_id', v_conv,
                  'pancake_page_id', v_page) else '{}'::jsonb end
             || jsonb_build_object('chat_followup_filter_at', v_now, 'chat_followup_group', v_group),
           org_staff_id_owner = case when cfg.set_customer_owner_if_null then coalesce(c.org_staff_id_owner, v_owner) else c.org_staff_id_owner end,
           updated_at = v_now
     where c.id = v_final;

    if p_contact_id is not null then
      update public.contacts ct set customer_id = v_final
       where ct.id = p_contact_id and ct.customer_id is distinct from v_final;
    end if;

    if v_final <> p_customer_id and cfg.merge_shell_customer then
      if exists (
        select 1 from public.aka_customer s
         where s.id = p_customer_id
           and coalesce(s.record_state,'') <> 'merged'
           and coalesce(s.custom_fields->>'nguon','') like 'chat-followup%'
           and nullif(btrim(coalesce(s.phone,'')), '') is null
           and not exists (select 1 from public.aka_order o where o.customer_id = s.id)
           and not exists (select 1 from public.org_organization og where og.customer_id = s.id)
      ) then
        begin
          perform public.fn_merge_verified_customer_identity_v1(
            p_customer_id, v_final, null, null, 'chat-followup-v2: trung SDT ' || v_phone);
          v_merged := true;
        exception when others then
          v_merge_err := sqlerrm;
        end;
      end if;
    end if;
  end if;

  v_details := v_details || jsonb_build_object(
    'paid_far', v_paid_far, 'paid_near', v_paid_near, 'had_paid', v_had_paid,
    'demo_active', v_demo_active, 'had_demo', v_had_demo,
    'owner_source', v_owner_src, 'merged_shell', v_merged, 'merge_error', v_merge_err);

  insert into public.aka_chat_followup_filter_log
    (day, mode, customer_id, final_customer_id, gom_id, contact_id, passed, reason,
     customer_group, days_left, phone, phone_source, pancake_url, owner_id, details)
  values
    (p_day, case when p_apply then 'apply' else 'dry' end, p_customer_id, v_final, p_gom_id, p_contact_id,
     v_pass, v_reason, v_group, v_days_left, v_phone, v_phone_src, v_pancake, v_owner, v_details);

  return jsonb_build_object(
    'passed', v_pass,
    'reason', v_reason,
    'final_customer_id', v_final,
    'customer_group', v_group,
    'group_label', case v_group
                     when 'chua_mua' then 'Chua mua'
                     when 'het_han_demo' then 'Het han demo'
                     when 'het_han_su_dung' then 'Het han su dung'
                     when 'con_han_sap_het' then format('Con han - con %s ngay', v_days_left)
                     when 'dang_demo' then 'Dang demo'
                     else v_group end,
    'days_left', v_days_left,
    'phone', v_phone,
    'phone_source', v_phone_src,
    'pancake_url', v_pancake,
    'owner_id', v_owner,
    'owner_source', v_owner_src,
    'customer_name', v_cust.name,
    'details', v_details
  );
end
$function$

CREATE OR REPLACE FUNCTION public.fn_contact_match_aka_customer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_account_id   integer;
  v_staff_id     text;
  v_org_staff_id bigint;
  v_page_id      text;
  v_up           jsonb;
  v_kcd_matches bigint[];
  v_kcd_url text;
BEGIN
  -- Personal Zalo akaBiz: match a unique full page+conversation identity, never create from phone hints.
  SELECT account_id,pancake_page_id INTO v_account_id,v_page_id
    FROM public.shops WHERE id::text=NEW.shop_id OR pancake_page_id=NEW.shop_id LIMIT 1;
  IF v_account_id=1001 AND v_page_id ~ '^pzl_[0-9]+$' AND NOT coalesce(NEW.is_group,false) THEN
    IF NEW.customer_id IS NULL AND NEW.conversion_id ~ '^pzl_u_[0-9]+_[0-9]+$' THEN
      v_kcd_url:='https://pancake.vn/'||v_page_id||'?c_id='||NEW.conversion_id;
      SELECT array_agg(DISTINCT coalesce(a.merged_into_customer_id,a.id)) INTO v_kcd_matches
      FROM public.aka_customer a WHERE a.account_id=1001 AND
        (a.pancake_url=v_kcd_url OR a.custom_fields->'pancake_urls' ? v_kcd_url);
      IF cardinality(v_kcd_matches)=1 THEN NEW.customer_id:=v_kcd_matches[1]; END IF;
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.phone IS NULL OR NEW.phone = '' THEN RETURN NEW; END IF;
  IF NEW.customer_id IS NOT NULL THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND OLD.phone IS NOT DISTINCT FROM NEW.phone THEN RETURN NEW; END IF;

  SELECT account_id, pancake_page_id INTO v_account_id, v_page_id
  FROM public.shops WHERE pancake_page_id = NEW.shop_id OR id::text = NEW.shop_id LIMIT 1;
  IF v_account_id IS NULL OR v_account_id != 1001 THEN RETURN NEW; END IF;

  v_staff_id := CASE WHEN NEW.staff_ids IS NOT NULL AND array_length(NEW.staff_ids, 1) >= 1 THEN NEW.staff_ids[1]::text ELSE NULL END;
  IF v_staff_id IS NOT NULL THEN
    SELECT id INTO v_org_staff_id FROM public.org_staff WHERE chat_staff_id::text = v_staff_id AND is_active IS TRUE ORDER BY id LIMIT 1;
  END IF;

  -- (HÀM CHUNG) v2: gọi trực tiếp fn_upsert_aka_customer_v1 thay cho pg_net -> edge insert_aka_customer (đồng bộ, hết race, gắn ngay customer_id)
  BEGIN
    v_up := public.fn_upsert_aka_customer_v1(jsonb_strip_nulls(jsonb_build_object(
      'phone', NEW.phone,
      'zalo_uid', NEW.uid,
      'pancake_url', CASE WHEN nullif(btrim(v_page_id), '') IS NOT NULL AND nullif(btrim(NEW.conversion_id), '') IS NOT NULL
                          AND coalesce(NEW.is_group, false) = false
                          THEN 'https://pancake.vn/' || v_page_id || '?c_id=' || NEW.conversion_id END,
      'name', COALESCE(NEW.name, NEW.zalo_name), 'name_zalo', NEW.zalo_name,
      'account_id', v_account_id, 'channel', 'trigger_from_contact', 'is_split_exempt', true,
      'org_staff_id', v_org_staff_id, 'chat_staff_id', v_staff_id,
      'creation_path', 'trigger_from_contact',
      'custom_fields', jsonb_build_object('contact_id', NEW.id::text, 'shop_id', NEW.shop_id)
    )));
    IF coalesce((v_up ->> 'ok')::boolean, false) THEN
      NEW.customer_id := (v_up ->> 'customer_id')::bigint;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'fn_contact_match_aka_customer upsert failed for contact %: %', NEW.id, SQLERRM;
  END;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_context_lay_dau_vao(p_id bigint, p_lease uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  j public.context_lan_thu_thap%rowtype;
  s public.context_cai_dat_to_chuc%rowtype;
  k public.context_khach_hang%rowtype;
  v_kh bigint; v_ht jsonb; v_moi jsonb; v_hash text; v_prev text; v_noise text[];
  v_stage jsonb; v_now_local timestamp; v_payload jsonb; v_code text; v_org_name text;
  v_truong jsonb; v_dm jsonb; v_gt jsonb; v_giai_doan jsonb; v_max_luc timestamptz; v_ban_do jsonb; v_ai_ht jsonb; v_viec jsonb; v_sig jsonb;
  v_bo_qua text;
begin
  select * into j from public.context_lan_thu_thap where id = p_id and lease_token = p_lease and status = 'processing' for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'lease_khong_hop_le'); end if;
  select * into s from public.context_cai_dat_to_chuc where organization_id = j.organization_id;
  v_kh := public.fn_context_ho_so_chinh(j.khach_hang_id);
  select * into k from public.context_khach_hang where id = v_kh;
  select o.name into v_org_name from public.org_organization o where o.id = j.organization_id;
  v_now_local := now() at time zone s.mui_gio;
  v_stage := public.fn_context_giai_doan_khach(v_kh);
  v_code := case when j.ly_do_chay = 'tong_hop_dem' then s.ai_using_code_tong_hop else s.ai_using_code end;

  if k.la_noi_bo then v_bo_qua := 'khach_noi_bo';
  elsif v_code is null then v_bo_qua := 'thieu_cau_hinh_ai';
  end if;
  if v_bo_qua is not null then
    update public.context_lan_thu_thap set status = 'skipped', ly_do_bo_qua = v_bo_qua, completed_at = now(), lease_token = null, lease_expires_at = null, khach_hang_id = v_kh where id = p_id;
    return jsonb_build_object('ok', true, 'bo_qua', v_bo_qua);
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('stt', f.stt, 'code', f.code, 'name', f.name)
            || case when j.ly_do_chay = 'tong_hop_dem'
                    then jsonb_strip_nulls(jsonb_build_object('muc_tieu_ho_tro', f.muc_tieu_ho_tro, 'cta_giai_doan', f.cta_giai_doan))
                    else '{}'::jsonb end
          order by f.stt), '[]'::jsonb)
    into v_giai_doan from public.aka_funnel_stage f where f.is_active;

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id', v -> 'id', 'loai', v -> 'loai', 'noi_dung', v -> 'noi_dung', 'han', v -> 'han')) order by o), '[]'::jsonb)
    into v_viec from jsonb_array_elements(coalesce(k.viec_dang_treo, '[]'::jsonb)) with ordinality t(v, o);

  -- ===== Tổng hợp cuối ngày =====
  if j.ly_do_chay = 'tong_hop_dem' then
    if not coalesce(k.can_tong_hop_lai, false) then
      update public.context_lan_thu_thap set status = 'skipped', ly_do_bo_qua = 'khong_can_tong_hop', completed_at = now(), lease_token = null, lease_expires_at = null, khach_hang_id = v_kh where id = p_id;
      return jsonb_build_object('ok', true, 'bo_qua', 'khong_can_tong_hop');
    end if;
    v_ht := public.fn_context_hoi_thoai(v_kh, date_trunc('day', v_now_local) at time zone s.mui_gio, 20, 8000);
    if s.che_do_chay_thu then
      -- Chạy thử: dùng các giá trị "lẽ ra được áp dụng" trong nhật ký
      select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('truong', x.name, 'code', x.code, 'gia_tri', x.gia_tri_hien_thi, 'do_tin_cay', x.do_tin_cay,
               'luc', to_char(x.cau_noi_luc at time zone s.mui_gio, 'DD/MM/YYYY')))), '[]'::jsonb)
        into v_gt
        from (select distinct on (n.truong_thong_tin_id, n.gia_tri_ma) t.name, t.code, t.sort_order, n.gia_tri_hien_thi, n.do_tin_cay, n.cau_noi_luc, n.hanh_dong
                from public.context_nhat_ky_gia_tri n join public.context_truong_thong_tin t on t.id = n.truong_thong_tin_id
               where n.khach_hang_id = v_kh and (n.duoc_ap_dung or n.ly_do_khong_ap_dung = 'chay_thu')
                 and (t.so_ngay_hieu_luc is null or n.cau_noi_luc + make_interval(days => t.so_ngay_hieu_luc) > now())
               order by n.truong_thong_tin_id, n.gia_tri_ma, n.cau_noi_luc desc nulls last, n.id desc) x
       where x.hanh_dong <> 'xoa';
    else
      select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('truong', t.name, 'code', t.code, 'gia_tri', g.gia_tri_hien_thi, 'do_tin_cay', g.do_tin_cay,
               'so_lan_xac_nhan', g.so_lan_xac_nhan, 'luc', to_char(g.cau_noi_cuoi_luc at time zone s.mui_gio, 'DD/MM/YYYY'))) order by t.sort_order), '[]'::jsonb)
        into v_gt
        from public.context_gia_tri_hien_tai g join public.context_truong_thong_tin t on t.id = g.truong_thong_tin_id
       where g.khach_hang_id = v_kh and t.is_active and not t.is_delete and (g.het_han_luc is null or g.het_han_luc > now());
    end if;
    if jsonb_array_length(v_ht) = 0 and jsonb_array_length(v_gt) = 0 then
      update public.context_lan_thu_thap set status = 'skipped', ly_do_bo_qua = 'khong_co_du_lieu', completed_at = now(), lease_token = null, lease_expires_at = null, khach_hang_id = v_kh where id = p_id;
      update public.context_khach_hang set can_tong_hop_lai = false where id = v_kh;
      return jsonb_build_object('ok', true, 'bo_qua', 'khong_co_du_lieu');
    end if;
    select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('target', f.code, 'dau_hieu', p.dau_hieu, 'la_nhay_buoc', p.la_nhay_buoc,
             'luc', to_char(p.cau_noi_luc at time zone s.mui_gio, 'DD/MM/YYYY'))) order by p.cau_noi_luc desc), '[]'::jsonb)
      into v_sig
      from (select * from public.context_tin_hieu_pheu x where x.khach_hang_id = v_kh order by x.cau_noi_luc desc nulls last limit 5) p
      join public.aka_funnel_stage f on f.id = p.target_funnel_stage_id;
    select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('nguoi_noi', e -> 'nguoi_noi', 'luc', e -> 'luc_hien_thi', 'hom_nay', e -> 'moi', 'noi_dung', e -> 'noi_dung')) order by o), '[]'::jsonb)
      into v_ai_ht from jsonb_array_elements(v_ht) with ordinality t(e, o);
    v_payload := jsonb_build_object(
      'ngay_hien_tai', to_char(v_now_local, 'YYYY-MM-DD'),
      'ben_ban_hang', v_org_name,
      'khach', jsonb_strip_nulls(jsonb_build_object('ten', k.name, 'muc_do_nong', k.muc_do_nong, 'tom_tat_cu', k.tom_tat_cho_agent)),
      'giai_doan_chinh_thuc', case when v_stage is null then null else jsonb_build_object('code', v_stage ->> 'code', 'name', v_stage ->> 'name') end,
      'danh_sach_giai_doan', v_giai_doan,
      'thong_tin_da_thu', v_gt,
      'viec_dang_treo', v_viec,
      'tin_hieu_pheu_gan_day', v_sig,
      'hoi_thoai', v_ai_ht);
    update public.context_lan_thu_thap set khach_hang_id = v_kh, ai_using_code = v_code, input_hash = md5(v_payload::text), cac_ban_ghi_da_doc = null where id = p_id;
    return jsonb_build_object('ok', true, 'ly_do_chay', j.ly_do_chay, 'ai_using_code', v_code, 'payload', v_payload, 'so_tin', jsonb_array_length(v_ht));
  end if;

  -- ===== Trích thông tin từ tin mới =====
  -- Lần đầu hoặc đọc lại toàn bộ: chỉ trích từ tin trong 90 ngày, tin cũ hơn chỉ làm ngữ cảnh
  v_ht := public.fn_context_hoi_thoai(v_kh,
            case when j.ly_do_chay in ('doi_cau_hinh', 'nhan_vien_yeu_cau') or k.da_doc_den_luc is null
                 then now() - interval '90 days' else k.da_doc_den_luc end,
            s.so_luot_ngu_canh);
  select coalesce(jsonb_agg(e order by o), '[]'::jsonb) into v_moi
    from jsonb_array_elements(v_ht) with ordinality t(e, o) where (e ->> 'moi')::boolean;
  select max((e ->> 'luc')::timestamptz) into v_max_luc from jsonb_array_elements(v_ht) e;

  if jsonb_array_length(v_moi) = 0 then
    update public.context_lan_thu_thap set status = 'skipped', ly_do_bo_qua = 'khong_co_tin_moi', completed_at = now(), lease_token = null, lease_expires_at = null, khach_hang_id = v_kh where id = p_id;
    return jsonb_build_object('ok', true, 'bo_qua', 'khong_co_tin_moi');
  end if;

  select array_agg(distinct x) into v_noise
    from public.context_nguon_thu_thap n cross join lateral jsonb_array_elements_text(coalesce(n.dieu_kien_loc_tin -> 'bo_qua_intent', '[]'::jsonb)) x
   where n.organization_id = j.organization_id and n.is_active;
  if j.ly_do_chay in ('tin_moi', 'quet_bu') and not exists (
       select 1 from jsonb_array_elements(v_moi) e
        where (e ->> 'nguoi_noi' = 'khach' and not (coalesce(e ->> 'intent', '') = any(coalesce(v_noise, '{}'::text[])) or public.fn_context_la_tin_xa_giao(e ->> 'noi_dung')))
           or (e ->> 'nguoi_noi' = 'nhan_vien' and char_length(coalesce(e ->> 'noi_dung', '')) >= 40)) then
    -- Không lùi mốc đã đọc: câu nhân viên ngắn trong đoạn này vẫn được đọc ở lần sau
    update public.context_lan_thu_thap set status = 'skipped', ly_do_bo_qua = 'chi_tin_xa_giao', completed_at = now(), lease_token = null, lease_expires_at = null, khach_hang_id = v_kh where id = p_id;
    return jsonb_build_object('ok', true, 'bo_qua', 'chi_tin_xa_giao');
  end if;

  v_hash := md5(coalesce((select string_agg(coalesce(e ->> 'nguon', '') || ':' || coalesce(e ->> 'ban_ghi', '') || ':' || coalesce(e ->> 'phan', '') || ':' || coalesce(e ->> 'noi_dung', ''), '|' order by o)
                            from jsonb_array_elements(v_moi) with ordinality t(e, o)), '')
                || '#' || s.phien_ban_cau_hinh || '#' || case when j.ly_do_chay in ('tin_moi', 'quet_bu') then 'trich' else j.ly_do_chay end);
  select l.input_hash into v_prev from public.context_lan_thu_thap l
   where l.khach_hang_id = v_kh and l.status = 'completed' and l.ly_do_chay <> 'tong_hop_dem' and l.id <> p_id
   order by l.completed_at desc nulls last limit 1;
  if v_prev = v_hash then
    update public.context_khach_hang set da_doc_den_luc = greatest(coalesce(da_doc_den_luc, v_max_luc), v_max_luc) where id = v_kh;
    update public.context_lan_thu_thap set status = 'skipped', ly_do_bo_qua = 'trung_dau_vao', input_hash = v_hash, completed_at = now(), lease_token = null, lease_expires_at = null, khach_hang_id = v_kh where id = p_id;
    return jsonb_build_object('ok', true, 'bo_qua', 'trung_dau_vao');
  end if;

  -- Trường đang bật + danh mục lựa chọn (danh mục trùng nhau chỉ gửi một lần)
  with f as (
    select t.id, t.code, t.name, t.kieu_gia_tri, t.mo_ta_cho_ai, t.lay_ca_cau_nhan_vien, t.sort_order
      from public.context_truong_thong_tin t
     where t.organization_id = j.organization_id and t.is_active and not t.is_delete and t.cach_ghi_nhan = 'ai'
  ), o as (
    select l.truong_thong_tin_id, l.vai_tro,
           jsonb_agg(left(l.code || ' = ' || l.name
                     || case when cardinality(l.tu_khoa) > 0 then ' (' || array_to_string(l.tu_khoa, ', ') || ')' else '' end
                     || coalesce(' — ' || l.mo_ta_cho_ai, ''), 220) order by l.sort_order, l.code) as ds
      from public.context_lua_chon l join f on f.id = l.truong_thong_tin_id
     where l.is_active
     group by l.truong_thong_tin_id, l.vai_tro
  ), dm as (
    select x.ds, 'dm' || dense_rank() over (order by md5(x.ds::text)) as k from (select distinct o.ds from o) x
  )
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
           'code', f.code, 'name', f.name, 'kieu_gia_tri', f.kieu_gia_tri, 'mo_ta_cho_ai', f.mo_ta_cho_ai,
           'lay_ca_cau_nhan_vien', f.lay_ca_cau_nhan_vien,
           'lua_chon_chinh', (select dm.k from o join dm on dm.ds = o.ds where o.truong_thong_tin_id = f.id and o.vai_tro = 'chinh'),
           'lua_chon_phu', (select dm.k from o join dm on dm.ds = o.ds where o.truong_thong_tin_id = f.id and o.vai_tro = 'phu')))
         order by f.sort_order), '[]'::jsonb),
         coalesce((select jsonb_object_agg(dm.k, dm.ds) from dm), '{}'::jsonb)
    into v_truong, v_dm
    from f;

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('code', t.code, 'gia_tri_ma', g.gia_tri_ma, 'gia_tri_phu_ma', g.gia_tri_phu_ma,
           'gia_tri_hien_thi', g.gia_tri_hien_thi, 'lan_cuoi', to_char(g.cau_noi_cuoi_luc at time zone s.mui_gio, 'DD/MM/YYYY'))) order by t.sort_order), '[]'::jsonb)
    into v_gt
    from public.context_gia_tri_hien_tai g join public.context_truong_thong_tin t on t.id = g.truong_thong_tin_id
   where g.khach_hang_id = v_kh and t.is_active and not t.is_delete and (g.het_han_luc is null or g.het_han_luc > now());

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('ma_tin', e -> 'ma_tin', 'nguoi_noi', e -> 'nguoi_noi', 'luc', e -> 'luc_hien_thi',
           'moi', e -> 'moi', 'intent', e -> 'intent', 'noi_dung', e -> 'noi_dung')) order by o), '[]'::jsonb),
         jsonb_agg(jsonb_build_object('ma_tin', e -> 'ma_tin', 'nguon', e -> 'nguon', 'ban_ghi', e -> 'ban_ghi', 'phan', e -> 'phan',
           'luc', e -> 'luc', 'nguoi_noi', e -> 'nguoi_noi') order by o)
    into v_ai_ht, v_ban_do
    from jsonb_array_elements(v_ht) with ordinality t(e, o);

  v_payload := jsonb_build_object(
    'ngay_hien_tai', to_char(v_now_local, 'YYYY-MM-DD'),
    'ben_ban_hang', v_org_name,
    'khach', jsonb_strip_nulls(jsonb_build_object('ten', k.name)),
    'giai_doan_chinh_thuc', case when v_stage is null then null else jsonb_build_object('code', v_stage ->> 'code', 'name', v_stage ->> 'name') end,
    'danh_sach_giai_doan', v_giai_doan,
    'truong_thong_tin', v_truong,
    'danh_muc', v_dm,
    'gia_tri_hien_tai', v_gt,
    'viec_dang_treo', v_viec,
    'hoi_thoai', v_ai_ht);

  update public.context_lan_thu_thap
     set khach_hang_id = v_kh, ai_using_code = v_code, input_hash = v_hash, cac_ban_ghi_da_doc = v_ban_do, tin_cuoi_da_doc_luc = v_max_luc
   where id = p_id;
  return jsonb_build_object('ok', true, 'ly_do_chay', j.ly_do_chay, 'ai_using_code', v_code, 'payload', v_payload,
                            'so_tin', jsonb_array_length(v_ht), 'so_tin_moi', jsonb_array_length(v_moi));
end $function$

CREATE OR REPLACE FUNCTION public.fn_context_nhan_dien_khach_zalo(p_org bigint, p_conversation_id bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_kh bigint; v_contact bigint; v_name text; v_phone text; v_aka bigint; v_accs integer[];
begin
  if p_conversation_id is null then return null; end if;

  select m.khach_hang_id into v_kh from public.context_khach_hang_ma m
   where m.organization_id = p_org and m.loai_ma = 'chat_zalo_conversation' and m.gia_tri = p_conversation_id::text;
  if v_kh is not null and exists (select 1 from public.context_khach_hang_ma m2
       where m2.khach_hang_id = public.fn_context_ho_so_chinh(v_kh) and m2.loai_ma = 'aka_customer') then
    return public.fn_context_ho_so_chinh(v_kh);
  end if;

  select c.chat_zalo_contact_id,
         coalesce(nullif(btrim(ct.display_name_override), ''), nullif(btrim(u.alias_name), ''), nullif(btrim(u.display_name), ''), nullif(btrim(u.zalo_name), '')),
         public.normalize_phone(coalesce(nullif(btrim(ct.phone_number_override), ''), nullif(btrim(u.phone_number), '')))
    into v_contact, v_name, v_phone
  from public.chat_zalo_conversation c
  left join public.chat_zalo_contact ct on ct.id = c.chat_zalo_contact_id
  left join public.chat_zalo_account_conversation ac on ac.id = c.chat_zalo_account_conversation_id
  left join public.chat_zalo_account_user u on u.id = coalesce(ct.chat_zalo_account_user_id, ac.chat_zalo_account_user_id)
  where c.id = p_conversation_id and c.organization_id = p_org;
  if not found then return null; end if;

  select s.aka_customer_account_ids into v_accs from public.context_cai_dat_to_chuc s where s.organization_id = p_org;
  if cardinality(coalesce(v_accs, '{}'::integer[])) > 0 and coalesce(v_phone, '') ~ '^0[1-9][0-9]{8}$' then
    select coalesce(a.merged_into_customer_id, a.id) into v_aka from public.aka_customer a
     where public.normalize_phone(a.phone) = v_phone and a.account_id = any(v_accs)
     order by a.updated_at desc nulls last, a.id limit 1;
  end if;

  perform pg_advisory_xact_lock(hashtextextended('context_khach:' || p_org || ':' || coalesce('aka:' || v_aka, 'zconv:' || p_conversation_id), 0));
  select m.khach_hang_id into v_kh from public.context_khach_hang_ma m
   where m.organization_id = p_org and m.loai_ma = 'chat_zalo_conversation' and m.gia_tri = p_conversation_id::text;
  if v_kh is null and v_contact is not null then
    select m.khach_hang_id into v_kh from public.context_khach_hang_ma m
     where m.organization_id = p_org and m.loai_ma = 'chat_zalo_contact' and m.gia_tri = v_contact::text;
  end if;
  if v_kh is null and v_aka is not null then
    select m.khach_hang_id into v_kh from public.context_khach_hang_ma m
     where m.organization_id = p_org and m.loai_ma = 'aka_customer' and m.gia_tri = v_aka::text;
  end if;
  if v_kh is null then
    insert into public.context_khach_hang (organization_id, name) values (p_org, v_name) returning id into v_kh;
  end if;
  v_kh := public.fn_context_ho_so_chinh(v_kh);
  insert into public.context_khach_hang_ma (organization_id, khach_hang_id, loai_ma, gia_tri, cach_lien_ket)
  values (p_org, v_kh, 'chat_zalo_conversation', p_conversation_id::text, 'tu_tin_nhan')
  on conflict (organization_id, loai_ma, gia_tri) do nothing;
  if v_contact is not null then
    insert into public.context_khach_hang_ma (organization_id, khach_hang_id, loai_ma, gia_tri, cach_lien_ket)
    values (p_org, v_kh, 'chat_zalo_contact', v_contact::text, 'tu_tin_nhan')
    on conflict (organization_id, loai_ma, gia_tri) do nothing;
  end if;
  select m.khach_hang_id into v_kh from public.context_khach_hang_ma m
   where m.organization_id = p_org and m.loai_ma = 'chat_zalo_conversation' and m.gia_tri = p_conversation_id::text;
  return public.fn_context_lien_ket_aka(p_org, v_kh, v_aka, 'sdt_zalo');
end $function$

CREATE OR REPLACE FUNCTION public.fn_context_trg_message_gom()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'UPDATE' and new.question_content is not distinct from old.question_content
     and new.contact_id is not distinct from old.contact_id then
    return null;
  end if;
  begin
    if tg_op = 'UPDATE' and old.contact_id is not null and new.contact_id is distinct from old.contact_id then
      perform public.fn_context_doi_contact(old.contact_id, new.contact_id);
    end if;
    perform public.fn_context_xep_hang('message_gom', new.id::text);
  exception when others then
    raise warning 'fn_context_trg_message_gom %: % (%)', new.id, sqlerrm, sqlstate;
  end;
  return null;
end $function$

CREATE OR REPLACE FUNCTION public.fn_context_xep_hang(p_bang text, p_ban_ghi_id text, p_ly_do text DEFAULT 'tin_moi'::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_src public.context_nguon_thu_thap%rowtype;
  v_cfg public.context_cai_dat_to_chuc%rowtype;
  v_kh bigint; v_job bigint; v_luc timestamptz;
  g record; z record;
begin
  if p_bang = 'message_gom' then
    select m.id, m.account_id, m.contact_id, m.conversation_id, m.question_content, m.image_content,
           coalesce(m.question_last_at, m.question_first_at, m.created_at, now()) as luc
      into g from public.message_gom m where m.id = p_ban_ghi_id::uuid;
    if not found or g.contact_id is null then return null; end if;
    if public.fn_context_noi_dung_gom_hoi(g.question_content, g.image_content) is null then return null; end if;
    select s.* into v_src from public.context_nguon_thu_thap s
     where s.bang_nguon = 'public.message_gom' and s.account_id = g.account_id and s.is_active;
    if not found then return null; end if;
    if coalesce((v_src.dieu_kien_loc_tin ->> 'bo_qua_hoi_thoai_nhom')::boolean, true) and coalesce(g.conversation_id, '') like 'pzl_g_%' then return null; end if;
    select c.* into v_cfg from public.context_cai_dat_to_chuc c where c.organization_id = v_src.organization_id and c.is_active;
    if not found then return null; end if;
    v_kh := public.fn_context_nhan_dien_khach_gom(v_src.organization_id, g.contact_id);
    v_luc := g.luc;

  elsif p_bang = 'chat_zalo_message' then
    select m.id, m.organization_id, m.chat_zalo_account_organization_id as ao_id, m.chat_zalo_conversation_id as conv_id,
           m.direction, m.content_text, m.content_kind, m.is_recalled, m.deleted_at, m.deletion_scope,
           coalesce(m.zalo_sent_at, m.received_at) as luc, ac.conversation_type
      into z
      from public.chat_zalo_message m
      join public.chat_zalo_conversation c on c.id = m.chat_zalo_conversation_id
      join public.chat_zalo_account_conversation ac on ac.id = c.chat_zalo_account_conversation_id
     where m.id = p_ban_ghi_id::bigint;
    if not found or z.direction <> 'incoming' or coalesce(btrim(z.content_text), '') = ''
       or z.is_recalled or z.deleted_at is not null or z.deletion_scope is not null then return null; end if;
    select s.* into v_src from public.context_nguon_thu_thap s
     where s.bang_nguon = 'public.chat_zalo_message' and s.organization_id = z.organization_id and s.account_id is null and s.is_active;
    if not found then return null; end if;
    if coalesce((v_src.dieu_kien_loc_tin ->> 'chi_hoi_thoai_ca_nhan')::boolean, true) and z.conversation_type <> 'user' then return null; end if;
    if coalesce(v_src.dieu_kien_loc_tin -> 'bo_qua_tai_khoan_zalo_ids', '[]'::jsonb) @> to_jsonb(z.ao_id) then return null; end if;
    if jsonb_typeof(v_src.dieu_kien_loc_tin -> 'loai_noi_dung') = 'array'
       and not ((v_src.dieu_kien_loc_tin -> 'loai_noi_dung') ? z.content_kind) then return null; end if;
    select c.* into v_cfg from public.context_cai_dat_to_chuc c where c.organization_id = v_src.organization_id and c.is_active;
    if not found then return null; end if;
    v_kh := public.fn_context_nhan_dien_khach_zalo(z.organization_id, z.conv_id);
    v_luc := z.luc;
  else
    return null;
  end if;

  if v_kh is null then return null; end if;
  if exists (select 1 from public.context_khach_hang k where k.id = v_kh and k.la_noi_bo) then return null; end if;

  update public.context_khach_hang set khach_nhan_cuoi_luc = greatest(coalesce(khach_nhan_cuoi_luc, v_luc), v_luc)
   where id = v_kh and (khach_nhan_cuoi_luc is null or khach_nhan_cuoi_luc < v_luc);

  insert into public.context_lan_thu_thap (organization_id, khach_hang_id, nguon_thu_thap_id, ban_ghi_nguon_id, ly_do_chay, status, due_at)
  values (v_src.organization_id, v_kh, v_src.id, p_ban_ghi_id, coalesce(p_ly_do, 'tin_moi'), 'pending',
          now() + make_interval(mins => v_cfg.so_phut_cho_gom))
  on conflict (khach_hang_id, ly_do_chay) where status = 'pending'
  do update set
    due_at = least(excluded.due_at, public.context_lan_thu_thap.created_at + make_interval(mins => v_cfg.so_phut_cho_toi_da)),
    ban_ghi_nguon_id = excluded.ban_ghi_nguon_id,
    nguon_thu_thap_id = excluded.nguon_thu_thap_id
  returning id into v_job;
  return v_job;
end $function$

CREATE OR REPLACE FUNCTION public.fn_create_aka_crm_v1(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_customer_id   bigint := nullif(p ->> 'customer_id', '')::bigint;
  v_phone         text;
  v_cust          aka_customer%rowtype;
  v_type          aka_crm_type%rowtype;
  v_crm_type_id   bigint := nullif(p ->> 'crm_type_id', '')::bigint;
  v_owner_id      bigint;
  v_owner_name    text;
  v_org_id        bigint := nullif(p ->> 'organization_id', '')::bigint;
  v_owner_source  text := 'none';
  v_explicit_owner boolean := false;
  v_chat_staff    uuid;
  v_allow_same_day boolean := coalesce((p ->> 'allow_same_day')::boolean, false);
  v_notify_lark   boolean := coalesce((p ->> 'notify_lark')::boolean, true);
  v_source_type   text := nullif(btrim(coalesce(p ->> 'source_type', '')), '');
  v_source_order  bigint := nullif(p ->> 'source_order_id', '')::bigint;
  v_note          text := nullif(btrim(coalesce(p ->> 'note', '')), '');
  v_pancake_url   text := nullif(btrim(coalesce(p ->> 'pancake_url', '')), '');
  v_due           timestamptz;
  v_priority      integer;
  v_channel_id    bigint;
  v_day_start     timestamptz := date_trunc('day', now() at time zone 'Asia/Ho_Chi_Minh') at time zone 'Asia/Ho_Chi_Minh';
  v_dup           aka_crm%rowtype;
  v_crm_id        bigint;
  v_customer_name text;
  v_customer_phone text;
  v_lark_url      constant text := 'https://akagroup.sg.larksuite.com/base/workflow/webhook/event/UN6EaP7lQwc3JbhD4n7lGG55gBc';
  v_lark_req      bigint;
begin
  -- ---------- khách ----------
  if v_customer_id is null then
    v_phone := normalize_phone(nullif(btrim(coalesce(p ->> 'customer_phone', '')), ''));
    if v_phone ~ '^0[1-9][0-9]{8}$' then
      select id into v_customer_id from aka_customer
      where normalize_phone(phone) = v_phone and coalesce(record_state, 'active') <> 'merged'
      order by created_at desc nulls last, id desc limit 1;
    end if;
  end if;
  if v_customer_id is null then
    return jsonb_build_object('ok', false, 'error', 'missing_identifier', 'message', 'Cần customer_id hoặc customer_phone hợp lệ');
  end if;
  select * into v_cust from aka_customer where id = v_customer_id;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'customer_not_found', 'customer_id', v_customer_id);
  end if;
  if v_cust.merged_into_customer_id is not null then
    v_customer_id := v_cust.merged_into_customer_id;
    select * into v_cust from aka_customer where id = v_customer_id;
  end if;


  if public.demo_care_should_skip_v1(v_customer_id, v_crm_type_id, null, v_source_order) then
    return jsonb_build_object('ok', true, 'created', false, 'skipped', true,
      'skip_reason', 'demo_care_managed_customer', 'crm_id', null, 'customer_id', v_customer_id);
  end if;
  -- ---------- loại CRM ----------
  if v_crm_type_id is null then
    return jsonb_build_object('ok', false, 'error', 'crm_type_required');
  end if;
  select * into v_type from aka_crm_type where id = v_crm_type_id;
  if not found or v_type.is_active is not true then
    return jsonb_build_object('ok', false, 'error', 'crm_type_inactive', 'crm_type_id', v_crm_type_id);
  end if;

  -- ---------- chủ sổ (thứ tự như edge create-aka-crm) ----------
  if nullif(p ->> 'org_staff_owner_id', '') is not null then
    v_explicit_owner := true;
    select id, name into v_owner_id, v_owner_name from org_staff
    where id = (p ->> 'org_staff_owner_id')::bigint and is_active = true;
    if v_owner_id is null then
      return jsonb_build_object('ok', false, 'error', 'owner_unavailable', 'org_staff_owner_id', p ->> 'org_staff_owner_id');
    end if;
    v_owner_source := 'explicit';
  end if;
  if v_owner_id is null then
    begin v_chat_staff := nullif(p ->> 'chat_staff_id', '')::uuid; exception when others then v_chat_staff := null; end;
    if v_chat_staff is not null then
      select id, name into v_owner_id, v_owner_name from org_staff where chat_staff_id = v_chat_staff and is_active = true order by id limit 1;
      if v_owner_id is not null then v_owner_source := 'chat_staff'; end if;
    end if;
  end if;
  if v_owner_id is null and v_cust.org_staff_id_owner is not null then
    select id, name into v_owner_id, v_owner_name from org_staff where id = v_cust.org_staff_id_owner and is_active = true;
    if v_owner_id is not null then v_owner_source := 'customer_owner'; end if;
  end if;
  if v_owner_id is null then
    select os.id, os.name into v_owner_id, v_owner_name
    from org_staff os where os.is_active = true and os.is_data_division = true
    order by (select count(*) from aka_crm c where c.org_staff_owner_id = os.id and c.created_at >= v_day_start), os.id
    limit 1;
    if v_owner_id is not null then v_owner_source := 'data_division_pool'; end if;
  end if;
  if v_owner_id is null then
    return jsonb_build_object('ok', false, 'error', 'no_assignable_staff');
  end if;
  if v_org_id is null then
    select organization_id into v_org_id from org_staff where id = v_owner_id;
  end if;

  -- ---------- chống trùng ----------
  if v_source_type is not null and v_source_order is not null then
    select * into v_dup from aka_crm where source_order_id = v_source_order and source_type = v_source_type order by id desc limit 1;
    if found then
      return jsonb_build_object('ok', true, 'created', false, 'skipped', true, 'skip_reason', 'duplicate_source_order',
        'crm_id', v_dup.id, 'customer_id', v_customer_id, 'crm_type_id', v_dup.crm_type_id,
        'org_staff_owner_id', v_dup.org_staff_owner_id, 'organization_id', v_dup.organization_id, 'cskh_due_date', v_dup.cskh_due_date);
    end if;
  end if;
  if not v_allow_same_day then
    select * into v_dup from aka_crm where customer_id = v_customer_id and created_at >= v_day_start order by created_at desc limit 1;
    if found then
      return jsonb_build_object('ok', true, 'created', false, 'skipped', true, 'skip_reason', 'duplicate_today',
        'crm_id', v_dup.id, 'customer_id', v_customer_id, 'crm_type_id', v_dup.crm_type_id,
        'org_staff_owner_id', v_dup.org_staff_owner_id, 'organization_id', v_dup.organization_id, 'cskh_due_date', v_dup.cskh_due_date);
    end if;
  end if;

  -- ---------- giá trị mặc định ----------
  v_priority := coalesce(nullif(p ->> 'priority', '')::integer, v_type.stt, 100);
  v_channel_id := coalesce(nullif(p ->> 'suggested_channel_id', '')::bigint, v_type.contact_channel_id);
  v_due := coalesce(nullif(p ->> 'cskh_due_date', '')::timestamptz, private.zalo_referral_due_date_v1(now()));
  v_customer_name := case when coalesce((p->>'preserve_unknown_name')::boolean,false) then coalesce(nullif(btrim(p->>'customer_name'),''),nullif(btrim(v_cust.name),'')) else coalesce(nullif(btrim(coalesce(p ->> 'customer_name', '')), ''), nullif(btrim(v_cust.name), ''), v_cust.phone, '') end;
  v_customer_phone := coalesce(nullif(btrim(v_cust.phone), ''), '');
  if v_pancake_url is null then v_pancake_url := nullif(btrim(v_cust.pancake_url), ''); end if;
  if v_pancake_url is not null and v_pancake_url !~* '^https://([a-z0-9.-]+\.)?pancake\.vn/.*c_id=' then v_pancake_url := null; end if;

  -- ---------- insert ----------
  begin
    insert into aka_crm (
      customer_id, customer_name, customer_phone, crm_type_id, organization_id, org_staff_owner_id,
      suggested_channel_id, suggested_content, note, priority, created_by, cskh_due_date, is_read,
      source_type, source_order_id, gen_agent, gen_status, gen_at, gen_meta, pancake_url, lead_id, sql_account_id
    ) values (
      v_customer_id, v_customer_name, v_customer_phone, v_crm_type_id, v_org_id, v_owner_id,
      v_channel_id, nullif(btrim(coalesce(p ->> 'suggested_content', '')), ''), v_note, v_priority,
      coalesce(nullif(p ->> 'created_by', '')::bigint, v_owner_id), v_due, false,
      v_source_type, v_source_order,
      nullif(btrim(coalesce(p ->> 'gen_agent', '')), ''),
      nullif(btrim(coalesce(p ->> 'gen_status', '')), ''),
      case when nullif(btrim(coalesce(p ->> 'gen_agent', '')), '') is not null then now() end,
      case when p ? 'gen_meta' and jsonb_typeof(p -> 'gen_meta') = 'object' then p -> 'gen_meta' end,
      v_pancake_url,
      nullif(p ->> 'lead_id', '')::bigint,
      v_cust.account_id
    ) returning id into v_crm_id;
  exception
    when unique_violation then
      select * into v_dup from aka_crm where source_order_id = v_source_order and source_type = v_source_type order by id desc limit 1;
      return jsonb_build_object('ok', true, 'created', false, 'skipped', true, 'skip_reason', 'duplicate_source_order',
        'crm_id', v_dup.id, 'customer_id', v_customer_id, 'crm_type_id', v_dup.crm_type_id, 'detail', left(sqlerrm, 200));
    when others then

      if sqlerrm = 'demo_care_managed_customer' then
        return jsonb_build_object('ok', true, 'created', false, 'skipped', true,
          'skip_reason', 'demo_care_managed_customer', 'crm_id', null, 'customer_id', v_customer_id);
      end if;
      if sqlerrm like '%crm_duplicate_customer_today%' then
        select * into v_dup from aka_crm where customer_id = v_customer_id and created_at >= v_day_start order by created_at desc limit 1;
        return jsonb_build_object('ok', true, 'created', false, 'skipped', true, 'skip_reason', 'duplicate_today',
          'crm_id', v_dup.id, 'customer_id', v_customer_id, 'crm_type_id', v_dup.crm_type_id);
      end if;
      return jsonb_build_object('ok', false, 'error', 'db_insert_failed', 'sqlstate', sqlstate, 'detail', left(sqlerrm, 300));
  end;

  -- ---------- Lark (không chặn) ----------
  if v_notify_lark then
    begin
      select net.http_post(
        url := v_lark_url,
        headers := '{"Content-Type":"application/json"}'::jsonb,
        body := jsonb_build_object(
          'staffname', coalesce(v_owner_name, ''),
          'note', v_customer_name || ' - ' || v_customer_phone || ' - ' || coalesce(v_type.name, ''),
          'date', to_char(v_due at time zone 'Asia/Ho_Chi_Minh', 'YYYY/MM/DD HH24:MI')),
        timeout_milliseconds := 8000) into v_lark_req;
    exception when others then
      v_lark_req := null;
    end;
  end if;

  return jsonb_build_object('ok', true, 'created', true, 'skipped', false, 'crm_id', v_crm_id,
    'customer_id', v_customer_id, 'crm_type_id', v_crm_type_id, 'crm_type_name', v_type.name,
    'org_staff_owner_id', v_owner_id, 'organization_id', v_org_id, 'owner_source', v_owner_source, 'staff_name', v_owner_name,
    'priority', v_priority, 'suggested_channel_id', v_channel_id, 'cskh_due_date', v_due,
    'pancake_url', v_pancake_url, 'lark_request_id', v_lark_req);
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_kcd_admin_decide_v3(p_contact_id uuid, p_decision text, p_staff_id bigint, p_note text, p_expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare ctx jsonb; r jsonb; k text; saved_at timestamptz; target jsonb; event_message text;
begin
 if p_decision not in('customer','not_customer') or p_decision is null then return jsonb_build_object('ok',false,'reason','invalid_decision'); end if;
 if p_staff_id is null or not exists(select 1 from org_staff where id=p_staff_id and is_active is true and is_super_admin is true) then
  return jsonb_build_object('ok',false,'reason','invalid_actor'); end if;
 ctx:=fn_kcd_context_v3(p_contact_id);
 perform pg_advisory_xact_lock(hashtextextended('kcd-conversation:'||coalesce(ctx->>'canonical_id','kcd:'||p_contact_id),0));
 ctx:=fn_kcd_context_v3(p_contact_id); k:=coalesce(ctx->>'key','kcd:'||p_contact_id);
 select value,updated_at into r,saved_at from aka_app_settings where key=k for update;
 if r is null then return jsonb_build_object('ok',false,'reason','record_missing'); end if;
 if p_expected_updated_at is null or saved_at is distinct from p_expected_updated_at then
  return jsonb_build_object('ok',false,'reason','stale_record','record',r,'key',k); end if;
 if p_decision='customer' and r->>'applied' is distinct from 'true' then
  target:=fn_kcd_target_v3((r->>'contact_id')::uuid,r);
  if target->>'ok' is distinct from 'true' then return target||jsonb_build_object('record',r,'key',k); end if;
 end if;
 event_message:=case when p_decision='customer' then 'Admin xác nhận khách hàng thật và yêu cầu tạo hoặc dùng lại CRM.'
  when r->>'applied'='true' then 'Admin đánh dấu không phải khách hàng; giữ nguyên hồ sơ và CRM đã tạo để đối soát.'
  else 'Admin xác nhận không phải khách hàng; dừng tự động xử lý hồ sơ này.' end;
 r:=r||jsonb_build_object('workflow_version','kcd-v3','admin_decision',jsonb_build_object('decision',p_decision,
  'staff_id',p_staff_id,'at',clock_timestamp(),'note',left(coalesce(p_note,''),2000)),
  'status',case when p_decision='not_customer' then 'rejected' else 'approved' end,
  'decision_reason',case when p_decision='not_customer' then 'admin_not_customer' else 'admin_customer' end,
  'due_at',clock_timestamp(),'lease_until',null,'lease_token',null,'updated_at',clock_timestamp(),
  'progress_log',coalesce(r->'progress_log','[]')||jsonb_build_array(fn_kcd_log_v3('admin_decision','success',event_message,'admin',p_staff_id,
    jsonb_build_object('decision',p_decision,'note',left(coalesce(p_note,''),2000)))));
 update aka_app_settings set value=r,updated_at=(r->>'updated_at')::timestamptz where key=k;
 return jsonb_build_object('ok',true,'record',r,'key',k);
end $function$

CREATE OR REPLACE FUNCTION public.fn_kcd_apply_v2(p_contact_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET lock_timeout TO '2s'
AS $function$
declare
  r jsonb; cfg jsonb; proof jsonb; snap jsonb; ident jsonb; c jsonb; s jsonb;
  up jsonb; crm jsonb; outcome jsonb; cid bigint; crmid bigint; expected bigint; v_url text;
begin
  -- Fixed lock order, held through creation and final evidence persistence.
  select value into cfg from aka_app_settings where key='khach_chu_dong' for share;
  select value into r from aka_app_settings where key='kcd:'||p_contact_id for update;
  if r is null then return jsonb_build_object('ok',false,'reason','record_missing'); end if;
  if coalesce((r->>'applied')::boolean,false) then
    return jsonb_build_object('ok',true,'already_applied',true,'result',r->'apply_result'); end if;
  proof:=r->'verification'; ident:=proof->'identity';
  if cfg->>'enabled' is distinct from 'true' or cfg->>'dry_run' is distinct from 'false'
    or cfg->>'ai_enabled' is distinct from 'true' or cfg->>'v2_live_validated' is distinct from 'true'
    or cfg->>'circuit_open'='true' then outcome:=jsonb_build_object('ok',false,'reason','configuration_blocks_apply');
  elsif r->>'dry_run' is distinct from 'false' or coalesce((r->>'backfill')::boolean,false)
    or r->>'trigger_source' in ('backfill','audit') or r->>'status' is distinct from 'verified'
    or r->>'policy_version' is distinct from 'kcd-v2' or proof->>'version' is distinct from 'kcd-v2'
    or r->>'application_eligible' is distinct from 'true' then
    outcome:=jsonb_build_object('ok',false,'reason','provenance_blocks_apply');
  elsif proof->>'decision' is distinct from 'verified'
    or proof->>'contact_id' is distinct from p_contact_id::text
    or exists(select 1 from unnest(array['binding','dates','identity','history','initiator','ai']) k
      where proof->'checks'->k->>'status' is distinct from 'pass')
    or nullif(ident->>'global_id','') is null or proof->>'evidence_contract' is distinct from 'zalo-global-v1'
    or proof->>'business_day' is distinct from r->>'business_day'
    or not coalesce(cfg->'apply_kinds' ? (proof->>'kind'),false)
    or coalesce(cfg->'skip_intents' ? (proof->'evidence'->'ai'->'verdict'->>'intent'),false)
    or proof->'evidence'->'ai'->>'status' is distinct from 'ok'
    or proof->'evidence'->'ai'->'verdict'->>'contract_valid' is distinct from 'true'
    or coalesce((proof->'evidence'->'ai'->'verdict'->>'confidence')::numeric,-1)<
      (case when proof->>'kind'='A_KHACH_GUI_KET_BAN' then coalesce((cfg->>'ai_conf_min_a')::numeric,80) else coalesce((cfg->>'ai_conf_min_d')::numeric,85) end)
    or proof->'evidence'->'ai'->'verdict'->>'initiator' is distinct from 'customer' then
    outcome:=jsonb_build_object('ok',false,'reason','mandatory_checks_missing');
  elsif nullif(proof->>'verified_at','') is null or (proof->>'verified_at')::timestamptz<clock_timestamp()-interval '5 minutes'
    or (proof->>'verified_at')::timestamptz>clock_timestamp()+interval '5 seconds'
    or proof->>'evidence_hash' is distinct from md5((proof-'evidence_hash')::text) then
    outcome:=jsonb_build_object('ok',false,'reason','evidence_stale_or_invalid');
  else
    perform pg_advisory_xact_lock(hashtextextended('kcd-global:'||(ident->>'global_id'),0));
    -- A short table SHARE lock prevents inserts/updates from changing the source set between recheck and commit.
    lock table contacts,messages,shops in share mode;
    lock table aka_customer in share row exclusive mode;
    snap:=fn_kcd_snapshot_v2(p_contact_id,ident);
    if snap->>'fingerprint' is distinct from proof->>'snapshot_hash' or snap->'data'->>'complete' is distinct from 'true' then
      outcome:=jsonb_build_object('ok',false,'reason','source_changed');
    else
      c:=snap->'data'->'contact'; s:=snap->'data'->'shop';
      expected:=nullif(ident->>'existing_customer_id','')::bigint;
      v_url:='https://pancake.vn/'||(s->>'pancake_page_id')||'?c_id='||(c->>'conversion_id');
      -- Any error below rolls back this entire subtransaction, including common-RPC writes and pg_net notifications.
      begin
        up:=fn_upsert_aka_customer_v1(jsonb_build_object('customer_id',expected,'phone',ident->>'phone',
          'name',coalesce(c->>'name',c->>'zalo_name'),'pancake_url',v_url,'account_id',1001,
          'contact_id',p_contact_id,'conversation_id',c->>'conversion_id','shop_id',c->>'shop_id',
          'shop_id_2',s->>'id','chat_staff_id',c->'staff_ids'->>0,
          'channel','zalo_khach_chu_dong','creation_path','khach_chu_dong_v2',
          'source_status_id',case when proof->>'kind'='A_KHACH_GUI_KET_BAN' then 52 else 104 end,
          'custom_fields',jsonb_build_object('zalo_global_id',ident->>'global_id','pancake_customer_id',ident->>'customer_id','kcd_evidence_hash',proof->>'evidence_hash'),
          'is_create_crm',false,'is_split_exempt',true,'use_split_rules',false,'overwrite',false,'touch_return',false));
        cid:=nullif(up->>'customer_id','')::bigint;
        if up->>'ok' is distinct from 'true' or cid is null or jsonb_array_length(coalesce(up->'conflicts','[]'))>0
          or (expected is not null and expected<>cid) or (expected is null and up->>'is_new' is distinct from 'true') then
          raise exception 'kcd_customer_conflict'; end if;
        crm:=fn_create_aka_crm_v1(jsonb_build_object('customer_id',cid,'crm_type_id',32,'suggested_channel_id',8,
          'pancake_url',v_url,'source_type','khach_chu_dong','source','khach-chu-dong-worker','gen_agent','kcd-v2',
          'chat_staff_id',c->'staff_ids'->>0,'org_staff_owner_id',up->'org_staff_owner_id',
          'note','Khách chủ động đã xác minh kcd-v2. Ngày phát sinh: '||(r->>'business_day'),
          'gen_meta',jsonb_build_object('version','kcd-v2','contact_id',p_contact_id,'evidence_hash',proof->>'evidence_hash')));
        crmid:=nullif(crm->>'crm_id','')::bigint;
        if crm->>'ok' is distinct from 'true' or crmid is null then raise exception 'kcd_crm_failed: %',crm->>'error'; end if;
        if not exists(select 1 from aka_customer where id=cid and account_id=1001) or
          not exists(select 1 from aka_crm where id=crmid and customer_id=cid) then raise exception 'kcd_result_not_found'; end if;
        update contacts set customer_id=cid where id=p_contact_id and (customer_id is null or customer_id=cid);
        if not found then raise exception 'kcd_contact_link_conflict'; end if;
        outcome:=jsonb_build_object('ok',true,'customer_id',cid,'customer_is_new',up->'is_new','crm_id',crmid,
          'crm_created',crm->'created','crm_reused',crm->'skipped','crm_type_id',crm->'crm_type_id','crm_reason',crm->>'skip_reason');
        r:=r||jsonb_build_object('applied',true,'aka_customer_id',cid,'aka_crm_id',crmid,'customer_is_new',up->'is_new','applied_at',now());
      exception when others then
        outcome:=jsonb_build_object('ok',false,'reason','transaction_rolled_back','detail',left(sqlerrm,200));
      end;
    end if;
  end if;
  if outcome->>'ok'='false' and outcome->>'reason' in ('source_changed','evidence_stale_or_invalid','transaction_rolled_back') then
    r:=r||jsonb_build_object('status',case when coalesce((r->>'attempt_count')::int,0)<3 then 'pending' else 'review' end,
      'due_at',now()+interval '10 minutes','decision_reason',outcome->>'reason');
  end if;
  update aka_app_settings set value=r||jsonb_build_object('apply_result',outcome,'updated_at',now()),updated_at=now()
    where key='kcd:'||p_contact_id;
  return outcome;
end $function$

CREATE OR REPLACE FUNCTION public.fn_kcd_apply_v3(p_contact_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET lock_timeout TO '2s'
AS $function$
declare ctx jsonb; target jsonb; r jsonb; cfg jsonb; proof jsonb; snap jsonb; ident jsonb; c jsonb; s jsonb;
 k text; manual boolean; outcome jsonb; up jsonb; crm jsonb; cid bigint; crmid bigint; expected bigint; stamp timestamptz; scope_ids uuid[];
begin
 ctx:=fn_kcd_context_v3(p_contact_id);
 perform pg_advisory_xact_lock(hashtextextended('kcd-conversation:'||coalesce(ctx->>'canonical_id','kcd:'||p_contact_id),0));
 ctx:=fn_kcd_context_v3(p_contact_id); k:=coalesce(ctx->>'key','kcd:'||p_contact_id);
 select value into cfg from aka_app_settings where key='khach_chu_dong' for share;
 select value into r from aka_app_settings where key=k for update;
 if r is null then return jsonb_build_object('ok',false,'reason','record_missing'); end if;
 if r->>'applied'='true' then
  return coalesce(r->'apply_result','{}')||jsonb_build_object('ok',true,'already_applied',true,'result',r->'apply_result'); end if;
 proof:=case when jsonb_typeof(r->'verification')='object' then r->'verification' else '{}'::jsonb end; ident:=coalesce(proof->'identity','{}');
 manual:=r->'admin_decision'->>'decision'='customer' and r->>'status'='approved';
 if r->'admin_decision'->>'decision'='not_customer' then
  outcome:=jsonb_build_object('ok',false,'reason','admin_rejected');
 elsif not coalesce(manual,false) and (cfg->>'workflow_version' is distinct from 'kcd-v3'
  or cfg->>'enabled' is distinct from 'true' or cfg->>'dry_run' is distinct from 'false'
  or cfg->>'ai_enabled' is distinct from 'true' or cfg->>'circuit_open'='true') then
  outcome:=jsonb_build_object('ok',false,'reason','configuration_blocks_apply');
 elsif not coalesce(manual,false) and (r->>'dry_run' is distinct from 'false'
  or r->>'application_eligible' is distinct from 'true' or r->>'backfill'='true'
  or r->>'trigger_source' in('backfill','audit') or r->>'status' is distinct from 'verified'
  or r->>'workflow_version' is distinct from 'kcd-v3' or r->>'automation_decision' is distinct from 'auto_ready') then
  outcome:=jsonb_build_object('ok',false,'reason','provenance_blocks_apply');
 elsif not coalesce(manual,false) and (proof->>'version' is distinct from 'kcd-v2'
  or proof->>'workflow_version' is distinct from 'kcd-v3' or proof->>'automation_decision' is distinct from 'auto_ready'
  or coalesce(proof->>'newness','existing') not in('new','unknown')
  or proof->>'contact_id' is distinct from r->>'contact_id' or proof->>'business_day' is distinct from r->>'business_day'
  or proof->>'evidence_contract' is distinct from 'zalo-global-v1' or nullif(ident->>'global_id','') is null
  or exists(select 1 from unnest(array['binding','dates','identity','initiator','ai']) check_name
    where proof->'checks'->check_name->>'status' is distinct from 'pass')
  or coalesce(proof->'checks'->'history'->>'status','fail') not in('pass','unknown')
  or not coalesce(cfg->'apply_kinds' ? (proof->>'kind'),false)
  or coalesce(cfg->'skip_intents' ? (proof->'evidence'->'ai'->'verdict'->>'intent'),false)
  or proof->'evidence'->'ai'->>'status' is distinct from 'ok'
  or proof->'evidence'->'ai'->'verdict'->>'contract_valid' is distinct from 'true'
  or proof->'evidence'->'ai'->'verdict'->>'initiator' is distinct from 'customer'
  or coalesce((proof->'evidence'->'ai'->'verdict'->>'intent_confidence')::numeric,-1)<coalesce((cfg->>'intent_conf_min')::numeric,80)
  or coalesce((proof->'evidence'->'ai'->'verdict'->>'confidence')::numeric,-1)<
   (case when proof->>'kind'='A_KHACH_GUI_KET_BAN' then coalesce((cfg->>'ai_conf_min_a')::numeric,80)
     else coalesce((cfg->>'ai_conf_min_d')::numeric,85) end)) then
  outcome:=jsonb_build_object('ok',false,'reason','mandatory_checks_missing');
 elsif not coalesce(manual,false) and (nullif(proof->>'verified_at','') is null
  or (proof->>'verified_at')::timestamptz<clock_timestamp()-interval '5 minutes'
  or (proof->>'verified_at')::timestamptz>clock_timestamp()+interval '5 seconds'
  or proof->>'evidence_hash' is distinct from md5((proof-'evidence_hash')::text)) then
  outcome:=jsonb_build_object('ok',false,'reason','evidence_stale_or_invalid');
 else
  -- Short serialization covers source phantoms and common upsert/CRM side effects.
  -- SHARE ROW EXCLUSIVE avoids the SHARE->ROW EXCLUSIVE lock-upgrade deadlock of v2.
  lock table contacts,messages,shops in share row exclusive mode;
  lock table aka_customer in share row exclusive mode;
  target:=fn_kcd_target_v3((r->>'contact_id')::uuid,r);
  if target->>'ok' is distinct from 'true' then outcome:=target;
  else
   snap:=fn_kcd_snapshot_v2((r->>'contact_id')::uuid,ident);
   if not coalesce(manual,false) and (snap->>'source_fingerprint' is distinct from proof->>'snapshot_hash'
      or snap->'data'->>'complete' is distinct from 'true') then
    outcome:=jsonb_build_object('ok',false,'reason','source_changed');
   else
    c:=target->'contact'; s:=target->'shop'; expected:=(target->>'expected_customer_id')::bigint;
    scope_ids:=array(select x::uuid from jsonb_array_elements_text(target->'scope_contact_ids') x);
    begin
     up:=fn_upsert_aka_customer_v1(jsonb_build_object('customer_id',expected,
      'phone',case when not coalesce(manual,false) then ident->>'phone' else null end,
      'name',coalesce(c->>'name',c->>'zalo_name'),'pancake_url',target->>'pancake_url','account_id',1001,
      'contact_id',r->>'contact_id','conversation_id',c->>'conversion_id','shop_id',c->>'shop_id','shop_id_2',s->>'id',
      'chat_staff_id',c->'staff_ids'->>0,'channel','zalo_khach_chu_dong','creation_path','khach_chu_dong_v3',
      'source_status_id',case when proof->>'kind'='A_KHACH_GUI_KET_BAN' then 52 else 104 end,
      'custom_fields',jsonb_strip_nulls(jsonb_build_object('zalo_global_id',target->>'trusted_global_id',
        'pancake_customer_id',case when not coalesce(manual,false) then ident->>'customer_id' end,
        'kcd_evidence_hash',proof->>'evidence_hash','kcd_workflow_version','kcd-v3')),
      'is_create_crm',false,'is_split_exempt',true,'use_split_rules',false,'overwrite',false,'touch_return',false));
     cid:=nullif(up->>'customer_id','')::bigint;
     if up->>'ok' is distinct from 'true' or cid is null or jsonb_array_length(coalesce(up->'conflicts','[]'))>0
       or (expected is not null and expected<>cid) or (expected is null and up->>'is_new' is distinct from 'true') then
       raise exception 'kcd_customer_conflict'; end if;
     crm:=fn_create_aka_crm_v1(jsonb_build_object('customer_id',cid,'crm_type_id',32,'suggested_channel_id',8,
      'pancake_url',target->>'pancake_url','source_type','khach_chu_dong','source','zalo-kh-moi','gen_agent','kcd-v3',
      'chat_staff_id',c->'staff_ids'->>0,'org_staff_owner_id',
      (select os.id from org_staff os where os.id=(up->>'org_staff_owner_id')::bigint and os.is_active is true),
      'note',case when manual then 'Admin xác nhận khách hàng thật từ Zalo.' else 'Khách chủ động đã được tự động xác minh.' end,
      'gen_meta',jsonb_build_object('version','kcd-v3','contact_id',r->>'contact_id','evidence_hash',proof->>'evidence_hash',
        'newness',coalesce(r->>'newness','unknown'),'admin_decision',r->'admin_decision')));
     crmid:=nullif(crm->>'crm_id','')::bigint;
     if crm->>'ok' is distinct from 'true' or crmid is null then raise exception 'kcd_crm_failed: %',crm->>'error'; end if;
     if not exists(select 1 from aka_customer where id=cid and account_id=1001)
       or not exists(select 1 from aka_crm where id=crmid and customer_id=cid) then raise exception 'kcd_result_not_found'; end if;
     if exists(select 1 from contacts ct where ct.id=any(scope_ids) and customer_id is not null and customer_id<>cid) then
       raise exception 'kcd_contact_link_conflict'; end if;
     update contacts set customer_id=cid where id=any(scope_ids) and customer_id is distinct from cid;
     outcome:=jsonb_build_object('ok',true,'customer_id',cid,'customer_is_new',up->'is_new','crm_id',crmid,
      'crm_created',crm->'created','crm_reused',crm->'skipped','crm_type_id',crm->'crm_type_id','crm_reason',crm->>'skip_reason');
     r:=r||jsonb_build_object('applied',true,'aka_customer_id',cid,'aka_crm_id',crmid,'customer_is_new',up->'is_new',
      'applied_at',clock_timestamp(),'lease_until',null,'lease_token',null,'last_error',null,
      'decision_reason',case when manual then 'admin_customer' else 'auto_ready' end);
    exception when others then
     outcome:=jsonb_build_object('ok',false,'reason','transaction_rolled_back','detail',left(sqlerrm,200));
    end;
   end if;
  end if;
 end if;
 if outcome->>'ok' is distinct from 'true' then
  r:=r||jsonb_build_object('status',case when r->'admin_decision'->>'decision'='not_customer' then 'rejected' when manual then 'approved' when coalesce((r->>'attempt_count')::int,0)<3
    and outcome->>'reason' in('source_changed','evidence_stale_or_invalid','transaction_rolled_back') then 'pending' else 'review' end,
   'due_at',clock_timestamp()+case when coalesce((r->>'attempt_count')::int,0)<3 then interval '10 minutes' else interval '6 hours' end,
   'decision_reason',outcome->>'reason','last_error',outcome->>'reason');
 end if;
 stamp:=clock_timestamp();
 r:=r||jsonb_build_object('apply_result',outcome,'updated_at',stamp,
  'progress_log',coalesce(r->'progress_log','[]')||jsonb_build_array(fn_kcd_log_v3('apply',
   case when outcome->>'ok'='true' then 'success' else 'error' end,
   case when outcome->>'ok'='true' then 'Đã tạo hoặc dùng lại khách hàng và CRM.' else 'Chưa tạo được CRM: '||coalesce(outcome->>'reason','unknown') end,
   case when manual then 'admin' else 'worker' end,(r->'admin_decision'->>'staff_id')::bigint,outcome)));
 update aka_app_settings set value=r,updated_at=stamp where key=k;
 return outcome;
end $function$

CREATE OR REPLACE FUNCTION public.fn_kcd_rerun_v3(p_contact_id uuid, p_staff_id bigint, p_expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare ctx jsonb; r jsonb; k text; saved_at timestamptz;
begin
 if p_staff_id is null or not exists(select 1 from org_staff where id=p_staff_id and is_active is true and is_super_admin is true) then
  return jsonb_build_object('ok',false,'reason','invalid_actor'); end if;
 ctx:=fn_kcd_context_v3(p_contact_id);
 perform pg_advisory_xact_lock(hashtextextended('kcd-conversation:'||coalesce(ctx->>'canonical_id','kcd:'||p_contact_id),0));
 ctx:=fn_kcd_context_v3(p_contact_id); k:=coalesce(ctx->>'key','kcd:'||p_contact_id);
 select value,updated_at into r,saved_at from aka_app_settings where key=k for update;
 if r is null then return jsonb_build_object('ok',false,'reason','record_missing'); end if;
 if p_expected_updated_at is null or saved_at is distinct from p_expected_updated_at then return jsonb_build_object('ok',false,'reason','stale_record'); end if;
 if r->>'applied'='true' then return jsonb_build_object('ok',false,'reason','already_applied','record',r,'key',k); end if;
 -- Deliberate admin rerun may reopen a rejection; the previous decision remains in the append-only log.
 r:=(r-'admin_decision')||jsonb_build_object('workflow_version','kcd-v3','status','pending','automation_decision','needs_review',
  'attempt_count',0,'decision_reason','admin_rerun','due_at',clock_timestamp(),'lease_until',null,'lease_token',null,'updated_at',clock_timestamp(),
  'progress_log',coalesce(r->'progress_log','[]')||jsonb_build_array(fn_kcd_log_v3('retry','info','Admin yêu cầu xác minh lại.','admin',p_staff_id)));
 update aka_app_settings set value=r,updated_at=(r->>'updated_at')::timestamptz where key=k;
 return jsonb_build_object('ok',true,'record',r,'key',k);
end $function$

CREATE OR REPLACE FUNCTION public.fn_kgt_apply_v2(p_gom_id uuid, p_lease_token uuid, p_evidence_hash text, p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cfg jsonb; v_input jsonb; v_record jsonb; c jsonb; a jsonb; v_match jsonb; v_target jsonb; v_up jsonb; v_ref_up jsonb;
  v_crm jsonb; v_crm_payload jsonb; v_event jsonb; v_events jsonb; v_results jsonb:='[]'; v_event_key text;
  v_customer bigint; v_referrer bigint; v_known_sender bigint; v_ids bigint[]; v_contacts jsonb; v_oldest timestamptz;
  v_type integer; v_route text; v_day date:=(now() at time zone 'Asia/Ho_Chi_Minh')::date;
  v_start timestamptz; v_source_day timestamptz; v_cutover timestamptz; v_existing public.aka_crm%rowtype; v_before public.aka_customer%rowtype;
  v_id uuid; v_identity text; v_dates jsonb; v_old boolean; v_lock text; v_reuse_reason text; v_new_note text;
  v_has_prior_referrer boolean; v_target_account integer;
begin
  p_result:=p_result||jsonb_build_object('triage',public.fn_kgt_triage_v1(p_result));
  select value into v_cfg from public.aka_app_settings where key='khach_gioi_thieu';
  if coalesce((v_cfg->>'enabled')::boolean,false) is not true or coalesce((v_cfg->>'dry_run')::boolean,true) is true or coalesce((v_cfg->>'processing_paused')::boolean,false) then raise exception 'kgt_live_disabled'; end if;
  if p_result->>'version' is distinct from 'kgt-v2' or coalesce(p_result->>'policy_version','') not in ('kgt-v3','kgt-v4','kgt-v5') or p_result->>'status' is distinct from 'verified' or p_result#>>'{ai,status}' is distinct from 'ok'
     or p_result->>'evidence_hash' is distinct from p_evidence_hash then raise exception 'kgt_invalid_verification'; end if;
  -- Source rows first, then queue, matching the order in source update triggers.
  perform 1 from public.message_gom where id=p_gom_id for share;
  v_input:=public.fn_kgt_input_v2(p_gom_id);
  for v_id in select (m->>'id')::uuid from jsonb_array_elements(coalesce(v_input->'current_messages','[]')||coalesce(v_input->'context_messages','[]')) m order by m->>'id'
  loop perform 1 from public.messages where id=v_id for share; end loop;
  v_input:=public.fn_kgt_input_v2(p_gom_id);
  select value into v_record from public.aka_app_settings where key='kgt:'||p_gom_id::text for update;
  if v_record->>'status' is distinct from 'processing' or nullif(v_record->>'lease_until','') is null or v_record->>'lease_token' is distinct from p_lease_token::text or v_record->>'evidence_hash' is distinct from p_evidence_hash
    or v_input->>'evidence_hash' is distinct from p_evidence_hash or (v_record->>'lease_until')::timestamptz<now() then raise exception 'kgt_stale_evidence_or_lease'; end if;
  if v_input#>>'{gom,initiated_by}' <> 'CUSTOMER' or v_input#>>'{gom,source}' <> 'pancake' or coalesce((v_input#>>'{gom,account_id}')::integer,0)<>1001 then raise exception 'kgt_invalid_scope'; end if;

  if coalesce((v_input#>>'{contact,is_group}')::boolean,false) or coalesce((v_input->>'source_truncated')::boolean,false) then raise exception 'kgt_unsafe_source'; end if;
  if coalesce((v_record->>'dry_run')::boolean,false) or coalesce((v_record->>'review_only')::boolean,false) then raise exception 'kgt_shadow_record_never_applies'; end if;
  if p_result->>'policy_version'='kgt-v5' then
    if v_cfg->>'policy_version' is distinct from 'kgt-v5' or coalesce((v_cfg->>'processing_paused')::boolean,false) then raise exception 'kgt_policy_not_active'; end if;
    select (value->>'activated_at')::timestamptz into v_cutover from public.aka_app_settings where key='kgt_intake_cutover_v1';
    if v_cutover is null or coalesce((v_input#>>'{gom,question_first_at}')::timestamptz,(v_input#>>'{gom,created_at}')::timestamptz,'-infinity'::timestamptz)<greatest(v_cutover,clock_timestamp()-interval '48 hours') then raise exception 'kgt_before_live_cutover'; end if;
  elsif v_cfg->>'policy_version'='kgt-v5' then raise exception 'kgt_policy_not_active';
  end if;
  if v_input#>>'{source_binding,valid}' is distinct from 'true'
    or not exists(select 1 from jsonb_array_elements(v_input->'current_messages') m
      where m->>'sender_type'='CUSTOMER' and not coalesce((m->>'is_hidden')::boolean,false)
        and not coalesce((m->>'is_undo')::boolean,false)) then raise exception 'kgt_source_unresolved'; end if;
  v_known_sender:=public.fn_kgt_canonical_customer_v2((v_input#>>'{sender_customer,id}')::bigint);
  v_source_day:=date_trunc('day',coalesce((v_input#>>'{gom,question_first_at}')::timestamptz,(v_input#>>'{gom,created_at}')::timestamptz) at time zone 'Asia/Ho_Chi_Minh') at time zone 'Asia/Ho_Chi_Minh';
  v_start:=v_day::timestamp at time zone 'Asia/Ho_Chi_Minh';
  -- All identifiers in deterministic order; same locks as the shared customer upsert.
  for v_lock in select distinct k from (
    select 'zalo-referral-phone:'||public.normalize_phone(x#>>'{apply,upsert_payload,phone}') k from jsonb_array_elements(p_result->'candidates') x
    union all select 'zalo-referral-uid:1001:'||public.fn_zalo_referral_canonical_uid_v1(x#>>'{apply,upsert_payload,zalo_uid}') from jsonb_array_elements(p_result->'candidates') x
    union all select 'zalo-referral-phone:'||public.normalize_phone(x#>>'{apply,referrer_upsert_payload,phone}') from jsonb_array_elements(p_result->'candidates') x
    union all select 'zalo-referral-uid:1001:'||public.fn_zalo_referral_canonical_uid_v1(x#>>'{apply,referrer_upsert_payload,zalo_uid}') from jsonb_array_elements(p_result->'candidates') x
  ) q where k is not null order by k loop perform pg_advisory_xact_lock(hashtextextended(v_lock,0)); end loop;

  for c in select value from jsonb_array_elements(p_result->'candidates') where value->'apply' <> 'null'::jsonb order by value#>>'{apply,upsert_payload,zalo_uid}',value#>>'{apply,upsert_payload,phone}'
  loop
    a:=c->'apply'; v_route:=a->>'route'; v_target:=a->'upsert_payload'; v_crm_payload:=a->'crm_payload'; v_type:=(v_crm_payload->>'crm_type_id')::integer;
    -- kgt-v4: route self_referred (khách tự nhắn, nói được X giới thiệu) → CRM 31 như referral nhưng hồ sơ là của chính người chat.
    if coalesce(v_type,0) not in (19,31,32) or (v_route in ('referral','self_referred')) is distinct from (v_type=31) or coalesce(v_route,'') not in ('referral','self','self_referred')
      or coalesce((c#>>'{l1,evidence_verified}')::boolean,false) is not true or coalesce((c#>>'{l1,confidence}')::numeric,0)<90
      or ((p_result->>'policy_version'<>'kgt-v5' or v_route='self') and coalesce(c#>>'{l1,intent}','') not in ('gioi_thieu','tu_van','dung_thu','mua_hang')) then raise exception 'kgt_invalid_candidate'; end if;

    if (v_route='referral' and c#>>'{l1,kind}' is distinct from 'REFERRAL_OTHER')
      or (v_route in ('self','self_referred') and (c#>>'{l1,kind}' is distinct from 'SELF' or (c#>>'{l1,intent}'='gioi_thieu' and (v_route='self' or p_result->>'policy_version'<>'kgt-v5')))) then raise exception 'kgt_verdict_route_mismatch'; end if;
    if c#>>'{l1,evidence_checks,verified}' is distinct from 'true'
      or c#>>'{l1,evidence_checks,contact_owner}' is distinct from (case when v_route='referral' then 'other' else 'sender' end)
      or (c#>'{l1,independent_review}' is not null and c#>'{l1,independent_review}'<>'null'::jsonb
        and c#>>'{l1,independent_review,outcome}' is distinct from 'accepted') then raise exception 'kgt_invalid_candidate_evidence'; end if;
    -- v5 referral proof is independent of purchase intent. SELF keeps its original need gate.
    if p_result->>'policy_version'='kgt-v5' and v_route in ('referral','self_referred') then
      if c#>>'{l1,referral_state}' is distinct from 'confirmed'
        or c#>>'{l1,evidence_checks,referral_verified}' is distinct from 'true'
        or jsonb_typeof(c#>'{l1,evidence_checks,referral_message_ids}') is distinct from 'array'
        or coalesce(jsonb_array_length(c#>'{l1,evidence_checks,referral_message_ids}'),0)=0
        or (v_route='self_referred' and (c#>>'{l1,independent_review,outcome}' is distinct from 'accepted' or nullif(p_result#>>'{referred_by,name}','') is null or nullif(p_result#>>'{referred_by,quote}','') is null))
        then raise exception 'kgt_referral_unverified'; end if;
    elsif c#>>'{l1,evidence_checks,need_state}' is distinct from 'new_request'
      or jsonb_typeof(c#>'{l1,evidence_checks,customer_need_message_ids}') is distinct from 'array'
      or coalesce(jsonb_array_length(c#>'{l1,evidence_checks,customer_need_message_ids}'),0)=0
      then raise exception 'kgt_invalid_candidate_evidence'; end if;
    v_identity:=case when nullif(v_target->>'zalo_uid','') is not null then 'uid:'||public.fn_zalo_referral_canonical_uid_v1(v_target->>'zalo_uid') else 'phone:'||public.normalize_phone(v_target->>'phone') end;
    if v_identity is null then raise exception 'kgt_missing_identifier'; end if;
    v_event_key:=encode(extensions.digest(p_gom_id::text||':'||v_identity,'sha256'),'hex');
    select * into v_existing from public.aka_crm where gen_meta->'kgt_events' ? v_event_key order by id limit 1;
    if found then
      v_results:=v_results||jsonb_build_array(jsonb_build_object('ref',c->>'ref','evidence_hash',p_evidence_hash,'customer_id',v_existing.customer_id,'crm_id',v_existing.id,'crm_type_id',v_existing.crm_type_id,'reused',true,'event_key',v_event_key));
      continue;
    end if;
    v_match:=public.fn_kgt_lookup_v2(v_target->>'phone',v_target->>'zalo_uid');

    if v_match->>'identity_conflict' is not null or coalesce((v_match->>'ok')::boolean,false) is not true then raise exception 'kgt_identity_unresolved'; end if;
    select coalesce(array_agg((x->>'id')::bigint),'{}'::bigint[]) into v_ids from jsonb_array_elements(v_match->'customers') x;
    -- kgt-v4: account_id 1632 (kho lịch sử akaBiz) và NULL cùng tổ chức với 1001; chỉ tài khoản khác mới là xung đột.
    if exists(select 1 from jsonb_array_elements(v_match->'customers') x
        where nullif(x->>'account_id','') is not null and (x->>'account_id')::integer not in (1001,1632)) then raise exception 'kgt_identity_conflict'; end if;
    -- K9 (25/10/2026): route self — hồ sơ của chính hội thoại (v_known_sender, fn_kgt_input_v2 đã ràng buộc uid) nằm trong các hồ sơ
    -- khớp thì chọn hồ sơ đó; hồ sơ trùng / contact khác uid cùng SĐT chỉ dùng để tính tuổi khách (v_dates bên dưới).
    if v_route in ('self','self_referred') and v_known_sender is not null and v_known_sender=any(v_ids) then
      v_ids:=array[v_known_sender];
    else
      if cardinality(v_ids)>1 then raise exception 'kgt_identity_conflict'; end if;
      if exists(select 1 from jsonb_array_elements(v_match->'contacts') x where (x->>'customer_id') is null and nullif(v_target->>'zalo_uid','') is not null
        and public.fn_zalo_referral_canonical_uid_v1(x->>'uid') <> public.fn_zalo_referral_canonical_uid_v1(v_target->>'zalo_uid'))
        or (select count(distinct public.fn_zalo_referral_canonical_uid_v1(x->>'uid')) from jsonb_array_elements(v_match->'contacts') x where x->>'customer_id' is null)>1
        then raise exception 'kgt_contact_identity_conflict'; end if;
    end if;
    v_customer:=v_ids[1];
    if nullif(v_target->>'customer_id','') is not null and public.fn_kgt_canonical_customer_v2((v_target->>'customer_id')::bigint) is distinct from v_customer then raise exception 'kgt_target_changed'; end if;
    v_dates:=coalesce(v_match->'customers','[]')||coalesce(v_match->'contacts','[]');
    if (p_result->>'policy_version'<>'kgt-v5' or v_route='self') and exists(select 1 from jsonb_array_elements(v_dates) x where nullif(x->>'created_at','') is null or (x->>'created_at')::timestamptz>=v_source_day+interval '1 day') then raise exception 'kgt_creation_date_unknown'; end if;
    v_old:=exists(select 1 from jsonb_array_elements(v_dates) x where (x->>'created_at')::timestamptz<v_source_day);
    if v_route in ('self','self_referred') then
      if v_input#>>'{source_binding,sender_profile_resolution}'='conflict' then raise exception 'kgt_self_sender_profile_conflict'; end if;
      if v_known_sender is not null and v_customer is not null and v_customer<>v_known_sender then raise exception 'kgt_self_identity_conflict'; end if;
      if (p_result->>'policy_version'<>'kgt-v5' or v_route='self') and v_input->'contact' <> 'null'::jsonb and nullif(v_input#>>'{contact,created_at}','') is null then raise exception 'kgt_sender_age_unknown'; end if;
      if (p_result->>'policy_version'<>'kgt-v5' or v_route='self') and v_known_sender is not null and nullif(v_input#>>'{sender_customer,created_at}','') is null then raise exception 'kgt_sender_age_unknown'; end if;
      v_old:=v_old or coalesce((v_input#>>'{contact,created_at}')::timestamptz<v_source_day,false) or coalesce((v_input#>>'{sender_customer,created_at}')::timestamptz<v_source_day,false);
      if v_type<>(case when v_route='self_referred' then 31 when v_old then 19 else 32 end) then raise exception 'kgt_self_type_changed'; end if;
      v_target:=v_target||jsonb_build_object('customer_id',coalesce(v_known_sender,v_customer));
      if v_route='self_referred' then
        -- Người giới thiệu X do API tra (SĐT / tên Zalo khớp chính xác). Chỉ nhận referrer_id tồn tại và không phải chính khách;
        -- không tạo hồ sơ X. Hồ sơ B đã có người giới thiệu từ trước thì giữ nguyên (A remains the original referrer).
        v_referrer:=nullif(v_target->>'referrer_id','')::bigint;
        if v_referrer is not null and (v_referrer=coalesce(v_known_sender,v_customer) or not exists(select 1 from public.aka_customer where id=v_referrer)) then v_referrer:=null; end if;
        if v_referrer is null then v_target:=v_target-'referrer_id'; else v_target:=v_target||jsonb_build_object('referrer_id',v_referrer); end if;
        v_has_prior_referrer:=false;
        v_target_account:=coalesce(nullif(v_target->>'account_id','')::integer,1001);
        if coalesce(v_known_sender,v_customer) is not null then
          select * into v_before from public.aka_customer where id=coalesce(v_known_sender,v_customer) for update;
          if found then
            v_target_account:=coalesce(v_before.account_id,v_target_account);
            if v_before.referrer_id is not null or nullif(btrim(v_before.referrer_phone),'') is not null then
              v_has_prior_referrer:=true;
              v_target:=v_target-'referrer_id'-'referrer_phone'-'referrer_pancake_url';
            end if;
          end if;
        end if;
        v_target:=v_target||jsonb_build_object('custom_fields',coalesce(v_target->'custom_fields','{}')||
          jsonb_build_object('khach_gioi_thieu_self',coalesce(v_target#>'{custom_fields,khach_gioi_thieu_self}','{}')||
            jsonb_build_object('gom_id',p_gom_id,'source_evidence_hash',p_evidence_hash,
              'referrer_resolution',case when v_referrer is null then 'unresolved' else 'linked' end)));
        -- 25/10/2026: X chưa tra được và B chưa có người giới thiệu → ràng buộc aka_customer_referred_requires_info chỉ nhận
        -- dấu vết "unresolved" ở custom_fields.khach_gioi_thieu (account 1001). Ngoài 1001 thì không bật is_referred;
        -- người giới thiệu vẫn được lưu ở gen_meta.referral của CRM 31.
        if v_referrer is null and not v_has_prior_referrer and nullif(btrim(coalesce(v_target->>'referrer_phone','')),'') is null then
          if v_target_account=1001 then
            v_target:=v_target||jsonb_build_object('custom_fields',coalesce(v_target->'custom_fields','{}')||
              jsonb_build_object('khach_gioi_thieu',coalesce(v_target#>'{custom_fields,khach_gioi_thieu}','{}')||
                jsonb_build_object('gom_id',p_gom_id,'source_evidence_hash',p_evidence_hash,'referrer_resolution','unresolved','route','self_referred')));
          else
            v_target:=v_target-'is_referred'-'referrer_pancake_url';
          end if;
        end if;
      end if;
    else
      v_referrer:=v_known_sender;
      -- Do not create a referrer profile just to make this event applicable.
      if v_referrer is null then
        v_target:=v_target-'referrer_id'-'referrer_phone'-'referrer_pancake_url';
      end if;
      v_target:=v_target||jsonb_build_object('custom_fields',coalesce(v_target->'custom_fields','{}')||
        jsonb_build_object('khach_gioi_thieu',coalesce(v_target#>'{custom_fields,khach_gioi_thieu}','{}')||
          jsonb_build_object('gom_id',p_gom_id,'source_evidence_hash',p_evidence_hash,
            'referrer_resolution',case when v_referrer is null then 'unresolved' else 'linked' end)));
      if v_customer=v_referrer then raise exception 'kgt_referrer_is_target'; end if;
      select * into v_before from public.aka_customer where id=v_customer for update;
      -- A remains the original referrer. B belongs to this event, never mixed into A's profile fields.
      if v_before.referrer_id is not null or nullif(btrim(v_before.referrer_phone),'') is not null then
        v_target:=v_target-'referrer_id'-'referrer_phone'-'referrer_pancake_url'-'is_referred';
      else v_target:=v_target||jsonb_build_object('referrer_id',v_referrer); end if;
      v_target:=v_target||jsonb_build_object('customer_id',v_customer);
    end if;
    v_up:=public.fn_upsert_aka_customer_v1(jsonb_strip_nulls(v_target||jsonb_build_object('is_create_crm',false,'preserve_unknown_name',true)));
    if coalesce((v_up->>'ok')::boolean,false) is not true or jsonb_array_length(coalesce(v_up->'conflicts','[]'))>0 then raise exception 'kgt_customer_upsert_failed'; end if;
    v_customer:=(v_up->>'customer_id')::bigint;
    if v_route='referral' and v_customer=v_referrer then raise exception 'kgt_referrer_is_target'; end if;
    perform pg_advisory_xact_lock(hashtextextended('kgt-crm-customer:'||v_customer,0));
    -- kgt-v4 (user 19/09/2026): không tạo CRM mới khi khách còn CRM chưa hoàn thành (mọi loại) hoặc đã có CRM pipeline
    -- trong 7 ngày → dùng lại CRM đó: đánh dấu chưa đọc, nối ghi chú lượt mới, ghi gen_meta.kgt_reuse. Trước đó chỉ chặn
    -- cùng loại + cùng ngày VN → 37/200 CRM lặp, 28/200 bị nhân viên đánh dấu "TRÙNG".
    select * into v_existing from public.aka_crm
      where customer_id=v_customer and coalesce(gen_meta->'renewal_duplicate_v1'->>'archived','false')<>'true'
        and (cskh_completed_date is null or (gen_agent='khach-gioi-thieu-v1' and created_at>=now()-interval '7 days'))
      order by (cskh_completed_date is null) desc, (crm_type_id=v_type) desc, created_at desc limit 1 for update;
    if found then
      v_reuse_reason:=case when v_existing.cskh_completed_date is null then 'open_crm' else 'recent_pipeline_crm' end;
      v_new_note:=nullif(btrim(coalesce(v_crm_payload->>'note','')),'');
      update public.aka_crm set is_read=false, updated_at=now(),
        note=case when v_new_note is null or position(left(v_new_note,60) in coalesce(note,''))>0 then note
                  else left(coalesce(note,'')||E'\n['||to_char(now() at time zone 'Asia/Ho_Chi_Minh','DD/MM HH24:MI')||' lượt mới] '||v_new_note,4000) end,
        gen_meta=coalesce(gen_meta,'{}')
          ||jsonb_build_object('kgt_reuse',coalesce(gen_meta->'kgt_reuse','[]')||jsonb_build_array(jsonb_build_object('gom_id',p_gom_id,'at',now(),'reason',v_reuse_reason,'route',v_route,'crm_type_id',v_type)))
          ||case when v_type=31 and v_crm_payload#>'{gen_meta,referral}' is not null and (gen_meta->'referral') is null
              then jsonb_build_object('referral',v_crm_payload#>'{gen_meta,referral}') else '{}'::jsonb end
        where id=v_existing.id;
      v_crm:=jsonb_build_object('ok',true,'crm_id',v_existing.id,'crm_type_id',v_existing.crm_type_id,'created',false,'reused',v_reuse_reason);
    else
      v_crm:=public.fn_create_aka_crm_v1(v_crm_payload||jsonb_build_object('customer_id',v_customer,'allow_same_day',true,'notify_lark',false,'preserve_unknown_name',true));
    end if;
    if coalesce((v_crm->>'ok')::boolean,false) is not true or nullif(v_crm->>'crm_id','') is null
      or (coalesce((v_crm->>'created')::boolean,true) and (v_crm->>'crm_type_id')::integer<>v_type) then raise exception 'kgt_crm_failed: %',v_crm->>'error'; end if;
    v_event:=jsonb_build_object('gom_id',p_gom_id,'evidence_hash',p_evidence_hash,'identity',v_identity,'route',v_route,'at',now(),
      'referrer_customer_id',case when v_route in ('referral','self_referred') then v_referrer end,'referrer_resolution',case when v_route in ('referral','self_referred') then case when v_referrer is null then 'unresolved' else 'linked' end end,
      'source_binding',v_input->'source_binding','referrer',p_result->'referrer','referred_by',p_result->'referred_by','verification',c-'apply','version','kgt-v2','policy_version',p_result->>'policy_version');
    update public.aka_crm set gen_meta=coalesce(gen_meta,'{}')||jsonb_build_object('kgt_events',coalesce(gen_meta->'kgt_events','{}')||jsonb_build_object(v_event_key,v_event)) where id=(v_crm->>'crm_id')::bigint;
    v_results:=v_results||jsonb_build_array(jsonb_build_object('ref',c->>'ref','evidence_hash',p_evidence_hash,'customer_id',v_customer,'crm_id',(v_crm->>'crm_id')::bigint,'crm_type_id',(v_crm->>'crm_type_id')::integer,'event_key',v_event_key,'created',v_crm->'created','reused',v_crm->'reused'));
  end loop;
  if jsonb_array_length(v_results)=0 then raise exception 'kgt_no_applied_candidates'; end if;
  update public.aka_app_settings set value=value||public.fn_kgt_result_meta_v2(p_result)||jsonb_build_object('status',case when p_result#>>'{triage,needs_review}'='true' then 'review' else 'verified' end,
    'owner_org_staff_id',v_input#>'{shop,manager_org_staff_id}','owner_unassigned',v_input#>>'{shop,manager_org_staff_id}' is null,
    'review_due_at',case when p_result#>>'{triage,needs_review}'='true' then coalesce(nullif(v_record->'review_due_at','null'::jsonb),to_jsonb(now()+interval '24 hours')) else 'null'::jsonb end,
    'applied',true,'lease_token',null,'lease_until',null,
    'result',p_result,'apply_result',v_results,'prior_apply_result',coalesce(v_record->'prior_apply_result','[]')||coalesce(v_record->'apply_result','[]'),'decision_reason',p_result->>'reason','last_error',null,'updated_at',now()),updated_at=now() where key='kgt:'||p_gom_id::text;
  return jsonb_build_object('status',case when p_result#>>'{triage,needs_review}'='true' then 'review' else 'verified' end,
    'needs_review',p_result#>>'{triage,needs_review}'='true','applied',true,'gom_id',p_gom_id,'results',v_results);
end $function$

CREATE OR REPLACE FUNCTION public.fn_kgt_lookup_v2(p_phone text DEFAULT NULL::text, p_uid text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_phone text := public.normalize_phone(p_phone);
  v_uid text := public.fn_zalo_referral_canonical_uid_v1(p_uid);
  v_unresolved boolean; v_contacts jsonb; v_customers jsonb; v_zalo jsonb; v_ids bigint[];
begin
  if v_phone !~ '^0[1-9][0-9]{8}$' then v_phone := null; end if;
  if v_uid !~ '^[0-9]{15,20}$' then v_uid := null; end if;
  select coalesce(jsonb_agg(to_jsonb(c) || jsonb_build_object('original_customer_id',c.customer_id,'customer_id',public.fn_kgt_canonical_customer_v2(c.customer_id))), '[]'::jsonb)
    into v_contacts
  from (select id,shop_id,name,zalo_name,phone,phone_list,uid,bio,customer_id,created_at,conversion_id from public.contacts
    where (v_phone is not null and (public.normalize_phone(phone)=v_phone or public.fn_kgt_phones_v2(phone_list) @> array[v_phone]))
       or (v_uid is not null and public.fn_zalo_referral_canonical_uid_v1(uid)=v_uid)) c;
  -- Resolve merges only AFTER the indexed identifier filters. The former unresolved-link
  -- scan invoked the canonical resolver for unrelated customers, causing multi-second lookups.
  with matched as materialized (
    select id from public.aka_customer where v_phone is not null and public.normalize_phone(phone)=v_phone
    union select id from public.aka_customer where v_uid is not null and public.fn_zalo_referral_canonical_uid_v1(zalo_referral_id)=v_uid
    union select id from public.aka_customer where v_uid is not null and zalo ~ '^(pzl_u_[0-9]+_[0-9]+|[0-9]{15,20})$'
      and public.fn_zalo_referral_canonical_uid_v1(zalo)=v_uid
  ), canonical as materialized (
    select public.fn_kgt_canonical_customer_v2(id) as id from matched
    union all select (c->>'customer_id')::bigint from jsonb_array_elements(v_contacts) c where c->>'original_customer_id' is not null
  )
  select coalesce(array_agg(distinct id) filter (where id is not null),'{}'::bigint[]),coalesce(bool_or(id is null),false)
    into v_ids,v_unresolved from canonical;
  select coalesce(jsonb_agg(to_jsonb(c)), '[]'::jsonb) into v_customers from
    (select id,name,phone,zalo,zalo_referral_id,created_at,custom_fields,channel,org_staff_id_owner,is_referred,referrer_id,record_state,account_id
     from public.aka_customer where id=any(v_ids)) c;
  if v_uid is not null then
    select to_jsonb(z) into v_zalo from
      (select zalo_uid,user_id,display_name,zalo_name,username,phone_number from public.zalo_users where zalo_uid=v_uid or user_id=v_uid order by zalo_uid limit 1) z;
  end if;
  return jsonb_build_object('ok',true,'identity_conflict',case when v_unresolved then 'unresolved_customer_link' end,'customers',v_customers,'contacts',v_contacts,'zalo_user',v_zalo);
end $function$

CREATE OR REPLACE FUNCTION public.fn_kgt_review_action_v1(p_gom_id uuid, p_action text, p_staff_id bigint, p_note text, p_expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r jsonb; v_saved_at timestamptz; v_now timestamptz:=clock_timestamp(); v_input jsonb; v_super boolean; v_cutover timestamptz;
begin
  if p_action is null or p_action not in ('retry','dismiss','handled') then return jsonb_build_object('ok',false,'reason','invalid_action'); end if;
  select is_super_admin into v_super from public.org_staff where id=p_staff_id and is_active is true;
  if not found then
    return jsonb_build_object('ok',false,'reason','invalid_actor'); end if;
  if p_action in ('dismiss','handled') and nullif(btrim(p_note),'') is null then return jsonb_build_object('ok',false,'reason','note_required'); end if;
  if p_action='handled' and p_note !~* '(https?://[^[:space:]]+|\m(CRM|KH)\M[^0-9]*[0-9]+)' then
    return jsonb_build_object('ok',false,'reason','reference_required'); end if;
  select value,updated_at into r,v_saved_at from public.aka_app_settings where key='kgt:'||p_gom_id::text for update;
  if r is null then return jsonb_build_object('ok',false,'reason','record_missing'); end if;
  if coalesce(v_super,false) is false and (r->>'owner_org_staff_id')::bigint is distinct from p_staff_id then
    return jsonb_build_object('ok',false,'reason','not_assigned_owner'); end if;
  if p_expected_updated_at is null or v_saved_at is distinct from p_expected_updated_at then return jsonb_build_object('ok',false,'reason','stale_record'); end if;
  if r->>'status'='processing' and (r->>'lease_until')::timestamptz>v_now then return jsonb_build_object('ok',false,'reason','record_processing'); end if;
  if p_action='retry' then
    if coalesce((r->>'review_only')::boolean,false) then return jsonb_build_object('ok',false,'reason','historical_review_only'); end if;
    if r->>'applied'='true' and r->>'needs_review' is distinct from 'true' then return jsonb_build_object('ok',false,'reason','already_applied'); end if;
    v_input:=public.fn_kgt_input_v2(p_gom_id);
    if v_input is null then return jsonb_build_object('ok',false,'reason','source_missing'); end if;
    select (value->>'activated_at')::timestamptz into v_cutover from public.aka_app_settings where key='kgt_intake_cutover_v1';
    if coalesce((v_input#>>'{gom,question_first_at}')::timestamptz,(v_input#>>'{gom,created_at}')::timestamptz,'-infinity'::timestamptz)<greatest(coalesce(v_cutover,'infinity'::timestamptz),v_now-interval '48 hours') then
      return jsonb_build_object('ok',false,'reason','historical_review_only'); end if;
    r:=r||jsonb_build_object('status','pending','attempt_count',0,'due_at',v_now,'evidence_hash',v_input->>'evidence_hash',
      'needs_review',true,'decision_reason','admin_retry');
  else
    r:=r||jsonb_build_object('status',case when p_action='dismiss' then 'dismissed' else 'handled' end,
      'needs_review',false,'review_resolved_at',v_now,'review_resolved_by',p_staff_id,
      'decision_reason',case when p_action='dismiss' then 'admin_dismissed' else 'admin_handled' end);
  end if;
  r:=r||jsonb_build_object('lease_token',null,'lease_until',null,'updated_at',v_now,
    'review_history',coalesce(r->'review_history','[]'::jsonb)||jsonb_build_array(jsonb_build_object('action',p_action,'staff_id',p_staff_id,
      'note',left(btrim(coalesce(p_note,'')),2000),'at',v_now,'evidence_hash',r->>'evidence_hash')));
  update public.aka_app_settings set value=r,updated_at=v_now where key='kgt:'||p_gom_id::text;
  return jsonb_build_object('ok',true,'record',r,'updated_at',v_now);
end $function$

CREATE OR REPLACE FUNCTION public.fn_kt_context_lay_dau_vao(p_id bigint, p_lease uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  j context_kiem_thu.context_lan_thu_thap%rowtype;
  s context_kiem_thu.context_cai_dat_to_chuc%rowtype;
  k context_kiem_thu.context_khach_hang%rowtype;
  v_kh bigint; v_ht jsonb; v_moi jsonb; v_hash text; v_prev text; v_noise text[];
  v_stage jsonb; v_now_local timestamp; v_payload jsonb; v_code text; v_org_name text;
  v_truong jsonb; v_dm jsonb; v_gt jsonb; v_giai_doan jsonb; v_max_luc timestamptz; v_ban_do jsonb; v_ai_ht jsonb; v_viec jsonb; v_sig jsonb;
  v_bo_qua text;
begin
  select * into j from context_kiem_thu.context_lan_thu_thap where id = p_id and lease_token = p_lease and status = 'processing' for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'lease_khong_hop_le'); end if;
  select * into s from context_kiem_thu.context_cai_dat_to_chuc where organization_id = j.organization_id;
  v_kh := public.fn_kt_context_ho_so_chinh(j.khach_hang_id);
  select * into k from context_kiem_thu.context_khach_hang where id = v_kh;
  select o.name into v_org_name from public.org_organization o where o.id = j.organization_id;
  v_now_local := now() at time zone s.mui_gio;
  v_stage := public.fn_kt_context_giai_doan_khach(v_kh);
  v_code := case when j.ly_do_chay = 'tong_hop_dem' then s.ai_using_code_tong_hop else s.ai_using_code end;

  if k.la_noi_bo then v_bo_qua := 'khach_noi_bo';
  elsif v_code is null then v_bo_qua := 'thieu_cau_hinh_ai';
  end if;
  if v_bo_qua is not null then
    update context_kiem_thu.context_lan_thu_thap set status = 'skipped', ly_do_bo_qua = v_bo_qua, completed_at = now(), lease_token = null, lease_expires_at = null, khach_hang_id = v_kh where id = p_id;
    return jsonb_build_object('ok', true, 'bo_qua', v_bo_qua);
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('stt', f.stt, 'code', f.code, 'name', f.name)
            || case when j.ly_do_chay = 'tong_hop_dem'
                    then jsonb_strip_nulls(jsonb_build_object('muc_tieu_ho_tro', f.muc_tieu_ho_tro, 'cta_giai_doan', f.cta_giai_doan))
                    else '{}'::jsonb end
          order by f.stt), '[]'::jsonb)
    into v_giai_doan from public.aka_funnel_stage f where f.is_active;

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id', v -> 'id', 'loai', v -> 'loai', 'noi_dung', v -> 'noi_dung', 'han', v -> 'han')) order by o), '[]'::jsonb)
    into v_viec from jsonb_array_elements(coalesce(k.viec_dang_treo, '[]'::jsonb)) with ordinality t(v, o);

  -- ===== Tổng hợp cuối ngày =====
  if j.ly_do_chay = 'tong_hop_dem' then
    if not coalesce(k.can_tong_hop_lai, false) then
      update context_kiem_thu.context_lan_thu_thap set status = 'skipped', ly_do_bo_qua = 'khong_can_tong_hop', completed_at = now(), lease_token = null, lease_expires_at = null, khach_hang_id = v_kh where id = p_id;
      return jsonb_build_object('ok', true, 'bo_qua', 'khong_can_tong_hop');
    end if;
    v_ht := public.fn_kt_context_hoi_thoai(v_kh, date_trunc('day', v_now_local) at time zone s.mui_gio, 20, 8000);
    if s.che_do_chay_thu then
      -- Chạy thử: dùng các giá trị "lẽ ra được áp dụng" trong nhật ký
      select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('truong', x.name, 'code', x.code, 'gia_tri', x.gia_tri_hien_thi, 'do_tin_cay', x.do_tin_cay,
               'luc', to_char(x.cau_noi_luc at time zone s.mui_gio, 'DD/MM/YYYY')))), '[]'::jsonb)
        into v_gt
        from (select distinct on (n.truong_thong_tin_id, n.gia_tri_ma) t.name, t.code, t.sort_order, n.gia_tri_hien_thi, n.do_tin_cay, n.cau_noi_luc, n.hanh_dong
                from context_kiem_thu.context_nhat_ky_gia_tri n join context_kiem_thu.context_truong_thong_tin t on t.id = n.truong_thong_tin_id
               where n.khach_hang_id = v_kh and (n.duoc_ap_dung or n.ly_do_khong_ap_dung = 'chay_thu')
                 and (t.so_ngay_hieu_luc is null or n.cau_noi_luc + make_interval(days => t.so_ngay_hieu_luc) > now())
               order by n.truong_thong_tin_id, n.gia_tri_ma, n.cau_noi_luc desc nulls last, n.id desc) x
       where x.hanh_dong <> 'xoa';
    else
      select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('truong', t.name, 'code', t.code, 'gia_tri', g.gia_tri_hien_thi, 'do_tin_cay', g.do_tin_cay,
               'so_lan_xac_nhan', g.so_lan_xac_nhan, 'luc', to_char(g.cau_noi_cuoi_luc at time zone s.mui_gio, 'DD/MM/YYYY'))) order by t.sort_order), '[]'::jsonb)
        into v_gt
        from context_kiem_thu.context_gia_tri_hien_tai g join context_kiem_thu.context_truong_thong_tin t on t.id = g.truong_thong_tin_id
       where g.khach_hang_id = v_kh and t.is_active and not t.is_delete and (g.het_han_luc is null or g.het_han_luc > now());
    end if;
    if jsonb_array_length(v_ht) = 0 and jsonb_array_length(v_gt) = 0 then
      update context_kiem_thu.context_lan_thu_thap set status = 'skipped', ly_do_bo_qua = 'khong_co_du_lieu', completed_at = now(), lease_token = null, lease_expires_at = null, khach_hang_id = v_kh where id = p_id;
      update context_kiem_thu.context_khach_hang set can_tong_hop_lai = false where id = v_kh;
      return jsonb_build_object('ok', true, 'bo_qua', 'khong_co_du_lieu');
    end if;
    select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('target', f.code, 'dau_hieu', p.dau_hieu, 'la_nhay_buoc', p.la_nhay_buoc,
             'luc', to_char(p.cau_noi_luc at time zone s.mui_gio, 'DD/MM/YYYY'))) order by p.cau_noi_luc desc), '[]'::jsonb)
      into v_sig
      from (select * from context_kiem_thu.context_tin_hieu_pheu x where x.khach_hang_id = v_kh order by x.cau_noi_luc desc nulls last limit 5) p
      join public.aka_funnel_stage f on f.id = p.target_funnel_stage_id;
    select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('nguoi_noi', e -> 'nguoi_noi', 'luc', e -> 'luc_hien_thi', 'hom_nay', e -> 'moi', 'noi_dung', e -> 'noi_dung')) order by o), '[]'::jsonb)
      into v_ai_ht from jsonb_array_elements(v_ht) with ordinality t(e, o);
    v_payload := jsonb_build_object(
      'ngay_hien_tai', to_char(v_now_local, 'YYYY-MM-DD'),
      'ben_ban_hang', v_org_name,
      'khach', jsonb_strip_nulls(jsonb_build_object('ten', k.name, 'muc_do_nong', k.muc_do_nong, 'tom_tat_cu', k.tom_tat_cho_agent)),
      'giai_doan_chinh_thuc', case when v_stage is null then null else jsonb_build_object('code', v_stage ->> 'code', 'name', v_stage ->> 'name') end,
      'danh_sach_giai_doan', v_giai_doan,
      'thong_tin_da_thu', v_gt,
      'viec_dang_treo', v_viec,
      'tin_hieu_pheu_gan_day', v_sig,
      'hoi_thoai', v_ai_ht);
    update context_kiem_thu.context_lan_thu_thap set khach_hang_id = v_kh, ai_using_code = v_code, input_hash = md5(v_payload::text), cac_ban_ghi_da_doc = null, dau_vao = v_payload where id = p_id;
    return jsonb_build_object('ok', true, 'ly_do_chay', j.ly_do_chay, 'ai_using_code', v_code, 'payload', v_payload, 'so_tin', jsonb_array_length(v_ht));
  end if;

  -- ===== Trích thông tin từ tin mới =====
  -- Lần đầu hoặc đọc lại toàn bộ: chỉ trích từ tin trong 90 ngày, tin cũ hơn chỉ làm ngữ cảnh
  v_ht := public.fn_kt_context_hoi_thoai(v_kh,
            case when j.ly_do_chay in ('doi_cau_hinh', 'nhan_vien_yeu_cau') or k.da_doc_den_luc is null
                 then now() - interval '90 days' else k.da_doc_den_luc end,
            s.so_luot_ngu_canh, 14000, j.den_luc);
  select coalesce(jsonb_agg(e order by o), '[]'::jsonb) into v_moi
    from jsonb_array_elements(v_ht) with ordinality t(e, o) where (e ->> 'moi')::boolean;
  select max((e ->> 'luc')::timestamptz) into v_max_luc from jsonb_array_elements(v_ht) e;

  if jsonb_array_length(v_moi) = 0 then
    update context_kiem_thu.context_lan_thu_thap set status = 'skipped', ly_do_bo_qua = 'khong_co_tin_moi', completed_at = now(), lease_token = null, lease_expires_at = null, khach_hang_id = v_kh where id = p_id;
    return jsonb_build_object('ok', true, 'bo_qua', 'khong_co_tin_moi');
  end if;

  select array_agg(distinct x) into v_noise
    from context_kiem_thu.context_nguon_thu_thap n cross join lateral jsonb_array_elements_text(coalesce(n.dieu_kien_loc_tin -> 'bo_qua_intent', '[]'::jsonb)) x
   where n.organization_id = j.organization_id and n.is_active;
  if j.ly_do_chay in ('tin_moi', 'quet_bu') and not exists (
       select 1 from jsonb_array_elements(v_moi) e
        where (e ->> 'nguoi_noi' = 'khach' and not (coalesce(e ->> 'intent', '') = any(coalesce(v_noise, '{}'::text[])) or public.fn_kt_context_la_tin_xa_giao(e ->> 'noi_dung')))
           or (e ->> 'nguoi_noi' = 'nhan_vien' and char_length(coalesce(e ->> 'noi_dung', '')) >= 40)) then
    -- Không lùi mốc đã đọc: câu nhân viên ngắn trong đoạn này vẫn được đọc ở lần sau
    update context_kiem_thu.context_lan_thu_thap set status = 'skipped', ly_do_bo_qua = 'chi_tin_xa_giao', completed_at = now(), lease_token = null, lease_expires_at = null, khach_hang_id = v_kh where id = p_id;
    return jsonb_build_object('ok', true, 'bo_qua', 'chi_tin_xa_giao');
  end if;

  v_hash := md5(coalesce((select string_agg(coalesce(e ->> 'nguon', '') || ':' || coalesce(e ->> 'ban_ghi', '') || ':' || coalesce(e ->> 'phan', '') || ':' || coalesce(e ->> 'noi_dung', ''), '|' order by o)
                            from jsonb_array_elements(v_moi) with ordinality t(e, o)), '')
                || '#' || s.phien_ban_cau_hinh || '#' || case when j.ly_do_chay in ('tin_moi', 'quet_bu') then 'trich' else j.ly_do_chay end);
  select l.input_hash into v_prev from context_kiem_thu.context_lan_thu_thap l
   where l.khach_hang_id = v_kh and l.status = 'completed' and l.ly_do_chay <> 'tong_hop_dem' and l.id <> p_id
   order by l.completed_at desc nulls last limit 1;
  if v_prev = v_hash then
    update context_kiem_thu.context_khach_hang set da_doc_den_luc = greatest(coalesce(da_doc_den_luc, v_max_luc), v_max_luc) where id = v_kh;
    update context_kiem_thu.context_lan_thu_thap set status = 'skipped', ly_do_bo_qua = 'trung_dau_vao', input_hash = v_hash, completed_at = now(), lease_token = null, lease_expires_at = null, khach_hang_id = v_kh where id = p_id;
    return jsonb_build_object('ok', true, 'bo_qua', 'trung_dau_vao');
  end if;

  -- Trường đang bật + danh mục lựa chọn (danh mục trùng nhau chỉ gửi một lần)
  with f as (
    select t.id, t.code, t.name, t.kieu_gia_tri, t.mo_ta_cho_ai, t.lay_ca_cau_nhan_vien, t.sort_order
      from context_kiem_thu.context_truong_thong_tin t
     where t.organization_id = j.organization_id and t.is_active and not t.is_delete and t.cach_ghi_nhan = 'ai'
  ), o as (
    select l.truong_thong_tin_id, l.vai_tro,
           jsonb_agg(left(l.code || ' = ' || l.name
                     || case when cardinality(l.tu_khoa) > 0 then ' (' || array_to_string(l.tu_khoa, ', ') || ')' else '' end
                     || coalesce(' — ' || l.mo_ta_cho_ai, ''), 220) order by l.sort_order, l.code) as ds
      from context_kiem_thu.context_lua_chon l join f on f.id = l.truong_thong_tin_id
     where l.is_active
     group by l.truong_thong_tin_id, l.vai_tro
  ), dm as (
    select x.ds, 'dm' || dense_rank() over (order by md5(x.ds::text)) as k from (select distinct o.ds from o) x
  )
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
           'code', f.code, 'name', f.name, 'kieu_gia_tri', f.kieu_gia_tri, 'mo_ta_cho_ai', f.mo_ta_cho_ai,
           'lay_ca_cau_nhan_vien', f.lay_ca_cau_nhan_vien,
           'lua_chon_chinh', (select dm.k from o join dm on dm.ds = o.ds where o.truong_thong_tin_id = f.id and o.vai_tro = 'chinh'),
           'lua_chon_phu', (select dm.k from o join dm on dm.ds = o.ds where o.truong_thong_tin_id = f.id and o.vai_tro = 'phu')))
         order by f.sort_order), '[]'::jsonb),
         coalesce((select jsonb_object_agg(dm.k, dm.ds) from dm), '{}'::jsonb)
    into v_truong, v_dm
    from f;

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('code', t.code, 'gia_tri_ma', g.gia_tri_ma, 'gia_tri_phu_ma', g.gia_tri_phu_ma,
           'gia_tri_hien_thi', g.gia_tri_hien_thi, 'lan_cuoi', to_char(g.cau_noi_cuoi_luc at time zone s.mui_gio, 'DD/MM/YYYY'))) order by t.sort_order), '[]'::jsonb)
    into v_gt
    from context_kiem_thu.context_gia_tri_hien_tai g join context_kiem_thu.context_truong_thong_tin t on t.id = g.truong_thong_tin_id
   where g.khach_hang_id = v_kh and t.is_active and not t.is_delete and (g.het_han_luc is null or g.het_han_luc > now());

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('ma_tin', e -> 'ma_tin', 'nguoi_noi', e -> 'nguoi_noi', 'luc', e -> 'luc_hien_thi',
           'moi', e -> 'moi', 'intent', e -> 'intent', 'noi_dung', e -> 'noi_dung')) order by o), '[]'::jsonb),
         jsonb_agg(jsonb_build_object('ma_tin', e -> 'ma_tin', 'nguon', e -> 'nguon', 'ban_ghi', e -> 'ban_ghi', 'phan', e -> 'phan',
           'luc', e -> 'luc', 'nguoi_noi', e -> 'nguoi_noi') order by o)
    into v_ai_ht, v_ban_do
    from jsonb_array_elements(v_ht) with ordinality t(e, o);

  v_payload := jsonb_build_object(
    'ngay_hien_tai', to_char(v_now_local, 'YYYY-MM-DD'),
    'ben_ban_hang', v_org_name,
    'khach', jsonb_strip_nulls(jsonb_build_object('ten', k.name)),
    'giai_doan_chinh_thuc', case when v_stage is null then null else jsonb_build_object('code', v_stage ->> 'code', 'name', v_stage ->> 'name') end,
    'danh_sach_giai_doan', v_giai_doan,
    'truong_thong_tin', v_truong,
    'danh_muc', v_dm,
    'gia_tri_hien_tai', v_gt,
    'viec_dang_treo', v_viec,
    'hoi_thoai', v_ai_ht);

  update context_kiem_thu.context_lan_thu_thap
     set khach_hang_id = v_kh, ai_using_code = v_code, input_hash = v_hash, cac_ban_ghi_da_doc = v_ban_do, tin_cuoi_da_doc_luc = v_max_luc, dau_vao = v_payload
   where id = p_id;
  return jsonb_build_object('ok', true, 'ly_do_chay', j.ly_do_chay, 'ai_using_code', v_code, 'payload', v_payload,
                            'so_tin', jsonb_array_length(v_ht), 'so_tin_moi', jsonb_array_length(v_moi));
end $function$

CREATE OR REPLACE FUNCTION public.fn_kt_context_nhan_dien_khach_zalo(p_org bigint, p_conversation_id bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_kh bigint; v_contact bigint; v_name text; v_phone text; v_aka bigint; v_accs integer[];
begin
  if p_conversation_id is null then return null; end if;

  select m.khach_hang_id into v_kh from context_kiem_thu.context_khach_hang_ma m
   where m.organization_id = p_org and m.loai_ma = 'chat_zalo_conversation' and m.gia_tri = p_conversation_id::text;
  if v_kh is not null and exists (select 1 from context_kiem_thu.context_khach_hang_ma m2
       where m2.khach_hang_id = public.fn_kt_context_ho_so_chinh(v_kh) and m2.loai_ma = 'aka_customer') then
    return public.fn_kt_context_ho_so_chinh(v_kh);
  end if;

  select c.chat_zalo_contact_id,
         coalesce(nullif(btrim(ct.display_name_override), ''), nullif(btrim(u.alias_name), ''), nullif(btrim(u.display_name), ''), nullif(btrim(u.zalo_name), '')),
         public.normalize_phone(coalesce(nullif(btrim(ct.phone_number_override), ''), nullif(btrim(u.phone_number), '')))
    into v_contact, v_name, v_phone
  from public.chat_zalo_conversation c
  left join public.chat_zalo_contact ct on ct.id = c.chat_zalo_contact_id
  left join public.chat_zalo_account_conversation ac on ac.id = c.chat_zalo_account_conversation_id
  left join public.chat_zalo_account_user u on u.id = coalesce(ct.chat_zalo_account_user_id, ac.chat_zalo_account_user_id)
  where c.id = p_conversation_id and c.organization_id = p_org;
  if not found then return null; end if;

  select s.aka_customer_account_ids into v_accs from context_kiem_thu.context_cai_dat_to_chuc s where s.organization_id = p_org;
  if cardinality(coalesce(v_accs, '{}'::integer[])) > 0 and coalesce(v_phone, '') ~ '^0[1-9][0-9]{8}$' then
    select coalesce(a.merged_into_customer_id, a.id) into v_aka from public.aka_customer a
     where public.normalize_phone(a.phone) = v_phone and a.account_id = any(v_accs)
     order by a.updated_at desc nulls last, a.id limit 1;
  end if;

  perform pg_advisory_xact_lock(hashtextextended('context_khach:' || p_org || ':' || coalesce('aka:' || v_aka, 'zconv:' || p_conversation_id), 0));
  select m.khach_hang_id into v_kh from context_kiem_thu.context_khach_hang_ma m
   where m.organization_id = p_org and m.loai_ma = 'chat_zalo_conversation' and m.gia_tri = p_conversation_id::text;
  if v_kh is null and v_contact is not null then
    select m.khach_hang_id into v_kh from context_kiem_thu.context_khach_hang_ma m
     where m.organization_id = p_org and m.loai_ma = 'chat_zalo_contact' and m.gia_tri = v_contact::text;
  end if;
  if v_kh is null and v_aka is not null then
    select m.khach_hang_id into v_kh from context_kiem_thu.context_khach_hang_ma m
     where m.organization_id = p_org and m.loai_ma = 'aka_customer' and m.gia_tri = v_aka::text;
  end if;
  if v_kh is null then
    insert into context_kiem_thu.context_khach_hang (organization_id, name) values (p_org, v_name) returning id into v_kh;
  end if;
  v_kh := public.fn_kt_context_ho_so_chinh(v_kh);
  insert into context_kiem_thu.context_khach_hang_ma (organization_id, khach_hang_id, loai_ma, gia_tri, cach_lien_ket)
  values (p_org, v_kh, 'chat_zalo_conversation', p_conversation_id::text, 'tu_tin_nhan')
  on conflict (organization_id, loai_ma, gia_tri) do nothing;
  if v_contact is not null then
    insert into context_kiem_thu.context_khach_hang_ma (organization_id, khach_hang_id, loai_ma, gia_tri, cach_lien_ket)
    values (p_org, v_kh, 'chat_zalo_contact', v_contact::text, 'tu_tin_nhan')
    on conflict (organization_id, loai_ma, gia_tri) do nothing;
  end if;
  select m.khach_hang_id into v_kh from context_kiem_thu.context_khach_hang_ma m
   where m.organization_id = p_org and m.loai_ma = 'chat_zalo_conversation' and m.gia_tri = p_conversation_id::text;
  return public.fn_kt_context_lien_ket_aka(p_org, v_kh, v_aka, 'sdt_zalo');
end $function$

CREATE OR REPLACE FUNCTION public.fn_kt_context_tao_dot(p_ten text, p_ten_mau text, p_moc timestamp with time zone, p_den_luc timestamp with time zone DEFAULT NULL::timestamp with time zone, p_lam_moi boolean DEFAULT true, p_mo_ta text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_dot bigint; r record; v_job bigint; v_n int := 0; v_khong int := 0; v_cfg jsonb;
begin
  if p_lam_moi then
    truncate context_kiem_thu.context_tin_hieu_pheu, context_kiem_thu.context_gia_tri_hien_tai, context_kiem_thu.context_nhat_ky_gia_tri,
             context_kiem_thu.context_lan_thu_thap, context_kiem_thu.context_khach_hang_ma, context_kiem_thu.context_khach_hang;
  end if;
  select jsonb_build_object(
           'prompt_trich', (select jsonb_build_object('code', p.code, 'updated_at', p.updated_at, 'md5', md5(p.prompt_system))
                              from public.ai_using u join public.ai_prompt p on p.id = u.prompt_id where u.code = s.ai_using_code),
           'request_options', (select u.request_options from public.ai_using u where u.code = s.ai_using_code),
           'model', (select m.model from public.ai_using u join public.ai_model m on m.id = u.model_id where u.code = s.ai_using_code),
           'phien_ban_cau_hinh', s.phien_ban_cau_hinh, 'moc', p_moc, 'den_luc', p_den_luc, 'lam_moi', p_lam_moi)
    into v_cfg from context_kiem_thu.context_cai_dat_to_chuc s where s.organization_id = 1;
  insert into context_kiem_thu.dot_kiem_thu (ten, mo_ta, cau_hinh) values (p_ten, p_mo_ta, v_cfg) returning id into v_dot;

  for r in select * from context_kiem_thu.mau_khach where ten_mau = p_ten_mau order by id loop
    v_job := public.fn_kt_context_xep_hang(r.bang_nguon, r.ban_ghi_id, 'tin_moi');
    if v_job is null then v_khong := v_khong + 1; continue; end if;
    v_n := v_n + 1;
  end loop;
  -- Việc vừa xếp: gắn đợt, đến hạn ngay, giới hạn thời điểm đọc
  update context_kiem_thu.context_lan_thu_thap
     set dot_id = v_dot, due_at = now(), den_luc = p_den_luc
   where status = 'pending' and dot_id is null;
  -- Lần đọc đầu của khách: chỉ trích tin sau p_moc
  if p_moc is not null then
    update context_kiem_thu.context_khach_hang set da_doc_den_luc = p_moc where da_doc_den_luc is null;
  end if;
  return jsonb_build_object('dot_id', v_dot, 'xep_hang', v_n, 'khong_xep_duoc', v_khong,
                            'viec_cho', (select count(*) from context_kiem_thu.context_lan_thu_thap where dot_id = v_dot and status = 'pending'));
end $function$

CREATE OR REPLACE FUNCTION public.fn_kt_context_trg_message_gom()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'UPDATE' and new.question_content is not distinct from old.question_content
     and new.contact_id is not distinct from old.contact_id then
    return null;
  end if;
  begin
    if tg_op = 'UPDATE' and old.contact_id is not null and new.contact_id is distinct from old.contact_id then
      perform public.fn_kt_context_doi_contact(old.contact_id, new.contact_id);
    end if;
    perform public.fn_kt_context_xep_hang('message_gom', new.id::text);
  exception when others then
    raise warning 'fn_context_trg_message_gom %: % (%)', new.id, sqlerrm, sqlstate;
  end;
  return null;
end $function$

CREATE OR REPLACE FUNCTION public.fn_kt_context_xep_hang(p_bang text, p_ban_ghi_id text, p_ly_do text DEFAULT 'tin_moi'::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_src context_kiem_thu.context_nguon_thu_thap%rowtype;
  v_cfg context_kiem_thu.context_cai_dat_to_chuc%rowtype;
  v_kh bigint; v_job bigint; v_luc timestamptz;
  g record; z record;
begin
  if p_bang = 'message_gom' then
    select m.id, m.account_id, m.contact_id, m.conversation_id, m.question_content, m.image_content,
           coalesce(m.question_last_at, m.question_first_at, m.created_at, now()) as luc
      into g from public.message_gom m where m.id = p_ban_ghi_id::uuid;
    if not found or g.contact_id is null then return null; end if;
    if public.fn_kt_context_noi_dung_gom_hoi(g.question_content, g.image_content) is null then return null; end if;
    select s.* into v_src from context_kiem_thu.context_nguon_thu_thap s
     where s.bang_nguon = 'public.message_gom' and s.account_id = g.account_id and s.is_active;
    if not found then return null; end if;
    if coalesce((v_src.dieu_kien_loc_tin ->> 'bo_qua_hoi_thoai_nhom')::boolean, true) and coalesce(g.conversation_id, '') like 'pzl_g_%' then return null; end if;
    select c.* into v_cfg from context_kiem_thu.context_cai_dat_to_chuc c where c.organization_id = v_src.organization_id and c.is_active;
    if not found then return null; end if;
    v_kh := public.fn_kt_context_nhan_dien_khach_gom(v_src.organization_id, g.contact_id);
    v_luc := g.luc;

  elsif p_bang = 'chat_zalo_message' then
    select m.id, m.organization_id, m.chat_zalo_account_organization_id as ao_id, m.chat_zalo_conversation_id as conv_id,
           m.direction, m.content_text, m.content_kind, m.is_recalled, m.deleted_at, m.deletion_scope,
           coalesce(m.zalo_sent_at, m.received_at) as luc, ac.conversation_type
      into z
      from public.chat_zalo_message m
      join public.chat_zalo_conversation c on c.id = m.chat_zalo_conversation_id
      join public.chat_zalo_account_conversation ac on ac.id = c.chat_zalo_account_conversation_id
     where m.id = p_ban_ghi_id::bigint;
    if not found or z.direction <> 'incoming' or coalesce(btrim(z.content_text), '') = ''
       or z.is_recalled or z.deleted_at is not null or z.deletion_scope is not null then return null; end if;
    select s.* into v_src from context_kiem_thu.context_nguon_thu_thap s
     where s.bang_nguon = 'public.chat_zalo_message' and s.organization_id = z.organization_id and s.account_id is null and s.is_active;
    if not found then return null; end if;
    if coalesce((v_src.dieu_kien_loc_tin ->> 'chi_hoi_thoai_ca_nhan')::boolean, true) and z.conversation_type <> 'user' then return null; end if;
    if coalesce(v_src.dieu_kien_loc_tin -> 'bo_qua_tai_khoan_zalo_ids', '[]'::jsonb) @> to_jsonb(z.ao_id) then return null; end if;
    if jsonb_typeof(v_src.dieu_kien_loc_tin -> 'loai_noi_dung') = 'array'
       and not ((v_src.dieu_kien_loc_tin -> 'loai_noi_dung') ? z.content_kind) then return null; end if;
    select c.* into v_cfg from context_kiem_thu.context_cai_dat_to_chuc c where c.organization_id = v_src.organization_id and c.is_active;
    if not found then return null; end if;
    v_kh := public.fn_kt_context_nhan_dien_khach_zalo(z.organization_id, z.conv_id);
    v_luc := z.luc;
  else
    return null;
  end if;

  if v_kh is null then return null; end if;
  if exists (select 1 from context_kiem_thu.context_khach_hang k where k.id = v_kh and k.la_noi_bo) then return null; end if;

  update context_kiem_thu.context_khach_hang set khach_nhan_cuoi_luc = greatest(coalesce(khach_nhan_cuoi_luc, v_luc), v_luc)
   where id = v_kh and (khach_nhan_cuoi_luc is null or khach_nhan_cuoi_luc < v_luc);

  insert into context_kiem_thu.context_lan_thu_thap (organization_id, khach_hang_id, nguon_thu_thap_id, ban_ghi_nguon_id, ly_do_chay, status, due_at)
  values (v_src.organization_id, v_kh, v_src.id, p_ban_ghi_id, coalesce(p_ly_do, 'tin_moi'), 'pending',
          now() + make_interval(mins => v_cfg.so_phut_cho_gom))
  on conflict (khach_hang_id, ly_do_chay) where status = 'pending'
  do update set
    due_at = least(excluded.due_at, context_kiem_thu.context_lan_thu_thap.created_at + make_interval(mins => v_cfg.so_phut_cho_toi_da)),
    ban_ghi_nguon_id = excluded.ban_ghi_nguon_id,
    nguon_thu_thap_id = excluded.nguon_thu_thap_id
  returning id into v_job;
  return v_job;
end $function$

CREATE OR REPLACE FUNCTION public.fn_notify_answer_quality()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_intent   public.aka_ai_intent%ROWTYPE;
  v_breaches jsonb := '[]'::jsonb;
  v_val      numeric;
  r          record;
  v_state    record;
  v_wid      bigint;
  v_link     text;
  v_is_live  boolean;
  v_cap      integer;
  v_cnt      integer;
  v_shop     text;
  v_page     text;
  v_pancake  text;
  v_staff    text;
  v_res      record;
  v_staff_id bigint;
  v_sub      jsonb;
  v_summary  text;
  v_payload  jsonb;
  v_req      bigint;
  v_win_start time;
  v_win_end   time;
  v_win_dow   smallint[];
  v_local     timestamp;
  v_cta_name  text;
BEGIN
  SELECT * INTO v_intent FROM public.aka_ai_intent
   WHERE intent_code = NEW.bot_intent AND is_active LIMIT 1;
  IF NOT FOUND OR COALESCE(v_intent.is_notify_quality, false) = false THEN RETURN NULL; END IF;

  FOR r IN SELECT criterion_code, criterion_name, poor_threshold, alert_webhook_id, apply_intent_codes
           FROM public.aka_chat_quality_criteria
           WHERE is_send_alert AND alert_webhook_id IS NOT NULL AND poor_threshold IS NOT NULL
  LOOP
    IF r.apply_intent_codes IS NOT NULL AND NOT (NEW.bot_intent = ANY(r.apply_intent_codes)) THEN
      CONTINUE;
    END IF;
    -- Nhánh CTA: có phân loại AI thì dùng phân loại, KHÔNG so ngưỡng điểm nữa
    IF r.criterion_code = 'cta_conversion' AND NEW.cta_review IS NOT NULL THEN
      IF COALESCE((NEW.cta_review->>'can_thiet')::boolean, false)
         AND NEW.cta_review->>'loi' IN ('thieu','yeu','sai_giai_doan','lech_chu_de') THEN
        v_breaches := v_breaches || jsonb_build_object(
          'type','cta','code','cta_conversion',
          'name', CASE NEW.cta_review->>'loi'
                    WHEN 'thieu' THEN 'Thiếu CTA'
                    WHEN 'yeu' THEN 'CTA yếu'
                    WHEN 'sai_giai_doan' THEN 'CTA sai giai đoạn'
                    ELSE 'CTA lệch chủ đề' END,
          'loi', NEW.cta_review->>'loi',
          'value', NULLIF(NEW.relevance_breakdown->>'cta_conversion','')::numeric,
          'threshold', r.poor_threshold,
          'webhook_id', r.alert_webhook_id);
      END IF;
      CONTINUE;
    END IF;
    IF r.criterion_code = 'overall' THEN v_val := NEW.relevance_score;
    ELSE v_val := NULLIF(NEW.relevance_breakdown->>r.criterion_code, '')::numeric; END IF;
    IF v_val IS NOT NULL AND v_val < r.poor_threshold THEN
      v_breaches := v_breaches || jsonb_build_object('type','quality','code',r.criterion_code,
        'name',r.criterion_name,'value',v_val,'threshold',r.poor_threshold,'webhook_id',r.alert_webhook_id);
    END IF;
  END LOOP;

  SELECT s.state_code, s.state_name, s.alert_webhook_id, s.min_confidence INTO v_state
  FROM public.aka_staff_attitude_state s
  WHERE s.state_code = NEW.attitude_state_code AND s.is_send_alert AND s.alert_webhook_id IS NOT NULL;
  IF FOUND AND COALESCE(NEW.attitude_confidence,1) >= COALESCE(v_state.min_confidence,0.6) THEN
    v_breaches := v_breaches || jsonb_build_object('type','attitude','code',v_state.state_code,
      'name',v_state.state_name,'confidence',NEW.attitude_confidence,'webhook_id',v_state.alert_webhook_id);
  END IF;

  IF jsonb_array_length(v_breaches) = 0 THEN RETURN NULL; END IF;

  SELECT * INTO v_res FROM public.fn_resolve_gom_staff(NEW.answer_org_staff_id, NEW.staff_id, NEW.contact_id, NEW.shop_id_2);
  v_staff_id := v_res.o_org_staff_id;

  SELECT name, pancake_page_id INTO v_shop, v_page FROM public.shops WHERE id = NEW.shop_id_2;
  v_pancake := CASE WHEN v_page IS NOT NULL AND NEW.conversation_id IS NOT NULL
                    THEN 'https://pancake.vn/' || v_page || '?c_id=' || NEW.conversation_id ELSE '' END;

  IF v_staff_id IS NOT NULL THEN
    SELECT COALESCE(os.name_akabiz, os.name) INTO v_staff
    FROM public.org_staff os WHERE os.id = v_staff_id LIMIT 1;
  END IF;
  IF v_staff IS NULL OR v_staff = '' THEN v_staff := NULLIF(NEW.answer_staff_name, ''); END IF;
  IF v_staff IS NULL OR v_staff = '' THEN v_staff := 'Chưa gán NV'; END IF;

  FOR v_wid IN SELECT DISTINCT (b->>'webhook_id')::bigint FROM jsonb_array_elements(v_breaches) b
  LOOP
    IF EXISTS (SELECT 1 FROM public.aka_answer_quality_alert a
               WHERE a.gom_id = NEW.id AND a.alert_webhook_id = v_wid) THEN CONTINUE; END IF;

    SELECT link, is_live, max_per_staff_per_day, send_window_start, send_window_end, send_window_dow
      INTO v_link, v_is_live, v_cap, v_win_start, v_win_end, v_win_dow
    FROM public.aka_webhook_link WHERE id = v_wid;
    IF v_link IS NULL OR v_link = '' THEN CONTINUE; END IF;

    v_sub := (SELECT jsonb_agg(b) FROM jsonb_array_elements(v_breaches) b
              WHERE (b->>'webhook_id')::bigint = v_wid);

    -- KHUNG GIỜ GỬI (giờ VN): ngoài khung → bỏ qua, chỉ log skipped_window (không gửi bù)
    IF v_win_start IS NOT NULL AND v_win_end IS NOT NULL THEN
      v_local := now() AT TIME ZONE 'Asia/Ho_Chi_Minh';
      IF (v_win_dow IS NOT NULL AND NOT (EXTRACT(isodow FROM v_local)::smallint = ANY(v_win_dow)))
         OR v_local::time < v_win_start OR v_local::time > v_win_end THEN
        INSERT INTO public.aka_answer_quality_alert(gom_id,account_id,intent_code,answer_org_staff_id,answer_staff_name,
          reasons,relevance_score,attitude_state_code,alert_webhook_id,webhook_url,payload,net_request_id,status)
        VALUES (NEW.id,NEW.account_id,NEW.bot_intent,v_staff_id,v_staff,
          v_sub,NEW.relevance_score,NEW.attitude_state_code,v_wid,v_link,NULL,NULL,'skipped_window')
        ON CONFLICT (gom_id, alert_webhook_id) DO NOTHING;
        CONTINUE;
      END IF;
    END IF;

    IF v_cap IS NOT NULL AND v_staff_id IS NOT NULL THEN
      SELECT count(*) INTO v_cnt FROM public.aka_answer_quality_alert a
       WHERE a.answer_org_staff_id = v_staff_id
         AND a.alert_webhook_id = v_wid
         AND a.status IN ('sent','dry_run')
         AND (a.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
             = (now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date;
      IF v_cnt >= v_cap THEN CONTINUE; END IF;
    END IF;

    v_summary := (SELECT string_agg(
        CASE WHEN b->>'type' = 'quality'
             THEN (b->>'name') || ' ' || (b->>'value') || '/' || (b->>'threshold')
             WHEN b->>'type' = 'cta'
             THEN 'CTA lỗi: ' || (b->>'name') || ' (điểm ' || COALESCE(b->>'value','?') || '/20'
                  || CASE WHEN COALESCE(NEW.cta_review->>'giai_doan','') <> ''
                          THEN ', giai đoạn ' || (NEW.cta_review->>'giai_doan') ELSE '' END || ')'
             ELSE 'Thái độ: ' || (b->>'name') || ' (' || (b->>'confidence') || ')' END, '; ')
      FROM jsonb_array_elements(v_sub) b);

    SELECT b->>'name' INTO v_cta_name FROM jsonb_array_elements(v_sub) b WHERE b->>'type'='cta' LIMIT 1;

    v_payload := jsonb_build_object(
      'alertReason',      CASE WHEN v_cta_name IS NOT NULL THEN 'CTA lỗi: ' || v_cta_name
                               ELSE 'Chất lượng/thái độ dưới ngưỡng' END,
      'staffName',        v_staff,
      'assignedVia',      v_res.o_via,
      'intent',           NEW.bot_intent || COALESCE(' - ' || v_intent.intent_name, ''),
      'customerName',     COALESCE(NEW.contact_name, ''),
      'customerQuestion', COALESCE(NEW.question_content, ''),
      'answerContent',    COALESCE(NEW.answer_content, ''),
      'relevanceScore',   NEW.relevance_score,
      'attitudeState',    COALESCE(NEW.attitude_state_code, ''),
      'attitudeEvidence', COALESCE(NEW.attitude_evidence, ''),
      'analysis',         COALESCE(NEW.relevance_analysis, ''),
      'suggestedReply',   COALESCE(NEW.relevance_suggested_reply, ''),
      'ctaRequired',      COALESCE(NEW.cta_review->>'can_thiet', ''),
      'ctaIssueCode',     COALESCE(NEW.cta_review->>'loi', ''),
      'ctaIssueLabel',    CASE NEW.cta_review->>'loi'
                            WHEN 'thieu' THEN 'Thiếu CTA'
                            WHEN 'yeu' THEN 'CTA yếu'
                            WHEN 'sai_giai_doan' THEN 'CTA sai giai đoạn'
                            WHEN 'lech_chu_de' THEN 'CTA lệch chủ đề'
                            WHEN 'ok' THEN 'CTA đạt'
                            WHEN 'khong_can' THEN 'Không cần CTA'
                            ELSE '' END,
      'ctaFound',         COALESCE(NEW.cta_review->>'hien_co', ''),
      'ctaNote',          COALESCE(NEW.cta_review->>'nhan_xet', ''),
      'ctaSuggested',     COALESCE(NEW.cta_review->>'de_xuat', ''),
      'ctaScore',         COALESCE(NEW.relevance_breakdown->>'cta_conversion', ''),
      'funnelStage',      COALESCE(NEW.cta_review->>'giai_doan', ''),
      'breachSummary',    COALESCE(v_summary, ''),
      'breaches',         v_sub,
      'pancakeLink',      v_pancake,
      'pancake_page',     COALESCE(v_shop, ''),
      'note',             CASE v_res.o_via
                            WHEN 'unassigned' THEN 'Contact chưa được gán NV quản lý'
                            WHEN 'page_manager' THEN 'Gửi tới NV quản lý page'
                            ELSE '' END
    );

    IF v_is_live THEN
      SELECT net.http_post(url := v_link, body := v_payload,
        headers := '{"Content-Type":"application/json"}'::jsonb) INTO v_req;
      INSERT INTO public.aka_answer_quality_alert(gom_id,account_id,intent_code,answer_org_staff_id,answer_staff_name,
        reasons,relevance_score,attitude_state_code,alert_webhook_id,webhook_url,payload,net_request_id,status)
      VALUES (NEW.id,NEW.account_id,NEW.bot_intent,v_staff_id,v_staff,
        v_sub,NEW.relevance_score,NEW.attitude_state_code,v_wid,v_link,v_payload,v_req,'sent')
      ON CONFLICT (gom_id, alert_webhook_id) DO NOTHING;
    ELSE
      INSERT INTO public.aka_answer_quality_alert(gom_id,account_id,intent_code,answer_org_staff_id,answer_staff_name,
        reasons,relevance_score,attitude_state_code,alert_webhook_id,webhook_url,payload,net_request_id,status)
      VALUES (NEW.id,NEW.account_id,NEW.bot_intent,v_staff_id,v_staff,
        v_sub,NEW.relevance_score,NEW.attitude_state_code,v_wid,v_link,v_payload,NULL,'dry_run')
      ON CONFLICT (gom_id, alert_webhook_id) DO NOTHING;
    END IF;
  END LOOP;

  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'fn_notify_answer_quality error gom=% : %', NEW.id, SQLERRM;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_notify_sales_unanswered()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_intent   public.aka_ai_intent%ROWTYPE;
  v_webhook  text;
  v_shop     text;
  v_page_id  text;
  v_link     text;
  v_staff    text;
  v_res      record;
  v_payload  jsonb;
  v_req_id   bigint;
BEGIN
  SELECT * INTO v_intent FROM public.aka_ai_intent
  WHERE intent_code = NEW.bot_intent AND is_active LIMIT 1;

  IF NOT FOUND OR COALESCE(v_intent.notify_staff, false) = false
     OR v_intent.notify_webhook_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT link INTO v_webhook FROM public.aka_webhook_link
  WHERE id = v_intent.notify_webhook_id;
  IF v_webhook IS NULL OR v_webhook = '' THEN RETURN NULL; END IF;

  IF EXISTS (SELECT 1 FROM public.aka_sales_alert_log WHERE gom_id = NEW.id) THEN
    RETURN NULL;
  END IF;

  SELECT name, pancake_page_id INTO v_shop, v_page_id
  FROM public.shops WHERE id = NEW.shop_id_2;

  v_link := CASE
    WHEN v_page_id IS NOT NULL AND NEW.conversation_id IS NOT NULL
    THEN 'https://pancake.vn/' || v_page_id || '?c_id=' || NEW.conversation_id
    ELSE '' END;

  SELECT * INTO v_res FROM public.fn_resolve_gom_staff(NEW.answer_org_staff_id, NEW.staff_id, NEW.contact_id, NEW.shop_id_2);

  IF v_res.o_org_staff_id IS NOT NULL THEN
    SELECT COALESCE(os.name_akabiz, os.name) INTO v_staff
    FROM public.org_staff os WHERE os.id = v_res.o_org_staff_id LIMIT 1;
  END IF;
  IF v_staff IS NULL OR v_staff = '' THEN v_staff := NULLIF(NEW.staff_name, ''); END IF;
  IF v_staff IS NULL OR v_staff = '' THEN v_staff := 'Chưa gán NV'; END IF;

  v_payload := jsonb_build_object(
    'staffName',        v_staff,
    'assignedVia',      v_res.o_via,
    'customerQuestion', COALESCE(NEW.question_content, ''),
    'questionMeaning',  v_intent.intent_name,
    'intent',           NEW.bot_intent || COALESCE(' - ' || v_intent.intent_name, ''),
    'customerName',     COALESCE(NEW.contact_name, ''),
    'pancakeLink',      v_link,
    'pancake_page',     COALESCE(v_shop, ''),
    'note',             CASE v_res.o_via
                          WHEN 'unassigned' THEN 'Contact chưa được gán NV quản lý'
                          WHEN 'page_manager' THEN 'Gửi tới NV quản lý page'
                          ELSE '' END
  );

  SELECT net.http_post(url := v_webhook, body := v_payload,
    headers := '{"Content-Type":"application/json"}'::jsonb) INTO v_req_id;

  INSERT INTO public.aka_sales_alert_log(gom_id, intent_code, webhook_url, payload, net_request_id)
  VALUES (NEW.id, NEW.bot_intent, v_webhook, v_payload, v_req_id)
  ON CONFLICT (gom_id) DO NOTHING;

  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'fn_notify_sales_unanswered error gom=% : %', NEW.id, SQLERRM;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_opp_cond(p_cond text, p_opp aka_salesopportunity, p_ctx jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare v_today date := (p_ctx->>'today')::date; v_h date := (p_ctx->>'h_date')::date; r boolean; v_last date;
begin
  case p_cond
    when 'has_trial' then return (p_ctx->>'trial_start') is not null;
    when 'has_phone' then return coalesce((p_ctx->>'has_phone')::boolean,false);
    when 'has_email' then return coalesce((p_ctx->>'has_email')::boolean,false);
    when 'replied_before' then
      return exists (select 1 from public.message_gom m where m.aka_customer_id=p_opp.customer_id and nullif(m.question_content,'') is not null and m.question_first_at >= p_opp.created_at);
    when 'silent_48h' then
      return not exists (select 1 from public.message_gom m where m.aka_customer_id=p_opp.customer_id and nullif(m.question_content,'') is not null and m.question_first_at >= now()-interval '48 hours');
    when 'silent_today' then
      return not exists (select 1 from public.message_gom m where m.aka_customer_id=p_opp.customer_id and nullif(m.question_content,'') is not null and (m.question_first_at at time zone 'Asia/Ho_Chi_Minh')::date = v_today);
    when 'silent_30d' then
      return not exists (select 1 from public.message_gom m where m.aka_customer_id=p_opp.customer_id and nullif(m.question_content,'') is not null and m.question_first_at >= now()-interval '30 days');
    when 'silent_since_H-3' then
      return v_h is null or not exists (select 1 from public.message_gom m where m.aka_customer_id=p_opp.customer_id and nullif(m.question_content,'') is not null and m.question_first_at >= (v_h-3)::timestamp);
    when 'not_reached_t0' then
      return exists (select 1 from public.aka_crm c where c.id = p_opp.source_crm_id and (c.error_reason_id is not null or c.unreachable_date is not null))
          or not exists (select 1 from public.aka_call k join public.aka_customer cu on cu.id=p_opp.customer_id where k.phone = cu.phone and k.created_at >= p_opp.created_at and coalesce(k.call_seconds,0) >= 30);
    when 'busy_deferred' then
      return exists (select 1 from public.aka_crm c where c.customer_id=p_opp.customer_id and c.decline_reason_id = 32 and c.updated_at >= p_opp.created_at)
          or exists (select 1 from public.message_gom m where m.aka_customer_id=p_opp.customer_id and m.bot_intent='D3_FOLLOW_UP' and m.question_first_at >= p_opp.created_at);
    when 'declined' then
      return exists (select 1 from public.aka_crm c where c.customer_id=p_opp.customer_id and c.decline_reason_id in (21,30,31) and c.updated_at >= p_opp.created_at);
    when 'purchased' then return public.fn_trang_thai_mua(p_opp.customer_id) = 'dang_dung';
    when 'usage_good' then
      v_last := (p_ctx->'renewal'->>'last_act')::date;
      return v_last is not null and v_today - v_last <= 7 and coalesce((p_ctx->'renewal'->>'login14')::int,0) >= 3;
    when 'usage_broken' then
      v_last := (p_ctx->'renewal'->>'last_act')::date;
      return v_last is null or v_today - v_last >= 8;
    when 'signal_positive' then
      v_last := (p_ctx->'renewal'->>'last_act')::date;
      return public.fn_opp_cond('replied_before', p_opp, p_ctx) or public.fn_opp_cond('busy_deferred', p_opp, p_ctx)
          or (v_h is not null and v_last is not null and v_last >= v_h);
    when 'renewal_score_hot' then return p_ctx->>'segment' = 'hot';
    when 'renewal_score_warm' then return p_ctx->>'segment' = 'warm';
    when 'renewal_score_cool' then return p_ctx->>'segment' = 'cool';
    when 'renewal_score_cold' then return p_ctx->>'segment' = 'cold';
    when 'product_zalo' then return p_ctx->>'product_group' = 'zalo';
    when 'product_facebook' then return p_ctx->>'product_group' = 'facebook';
    when 'product_sms' then return p_ctx->>'product_group' = 'sms';
    when 'package_year' then return p_ctx->>'package' = 'year';
    when 'package_2month' then return p_ctx->>'package' = '2month';
    else return true;
  end case;
end $function$

CREATE OR REPLACE FUNCTION public.fn_opp_conds_all(p_conds jsonb, p_opp aka_salesopportunity, p_ctx jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare c text;
begin
  if p_conds is null or jsonb_typeof(p_conds) <> 'array' then return true; end if;
  for c in select value #>> '{}' from jsonb_array_elements(p_conds) loop
    if not public.fn_opp_cond(c, p_opp, p_ctx) then return false; end if;
  end loop;
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.fn_opp_conds_any(p_conds jsonb, p_opp aka_salesopportunity, p_ctx jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare c text;
begin
  if p_conds is null or jsonb_typeof(p_conds) <> 'array' then return false; end if;
  for c in select value #>> '{}' from jsonb_array_elements(p_conds) loop
    if public.fn_opp_cond(c, p_opp, p_ctx) then return true; end if;
  end loop;
  return false;
end $function$

CREATE OR REPLACE FUNCTION public.fn_opp_ctx(p_opp aka_salesopportunity)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare t record; cu record; st record; v_ctx jsonb; v_pc jsonb; v_seg text; v_state text; v_ren jsonb; v_trial date; v_ref text; v_ok bigint := 0; v_camp bigint := 0; cfg jsonb;
begin
  select * into t from public.aka_salesopportunity_type where id = p_opp.type_id;
  select name, phone, email, referrer_id, inbox_url, linh_vuc into cu from public.aka_customer where id = p_opp.customer_id;
  select name, phone into st from public.org_staff where id = p_opp.owner_org_staff_id;
  cfg := public.fn_opp_config();
  v_pc := public.fn_opp_product_context(p_opp.customer_id);
  v_trial := coalesce(p_opp.trial_start_date, public.fn_opp_trial_start(p_opp.customer_id));
  v_state := public.fn_opp_trial_state(p_opp.customer_id);
  if cu.referrer_id is not null then select name into v_ref from public.aka_customer where id = cu.referrer_id; end if;
  if t.anchor_kind = 'expiration' then
    v_ren := public.fn_opp_renewal_score(p_opp.customer_id, p_opp.anchor_date);
    v_seg := v_ren->>'group';
  elsif t.code = 'new_crm_data' then v_seg := public.fn_opp_lead_grade(p_opp.customer_id);
  elsif t.code = 'new_zalo' then
    select coalesce(c.gen_meta->>'ai_tier', c.gen_meta->>'tier') into v_seg from public.aka_crm c where c.id = p_opp.source_crm_id;
    v_seg := coalesce(v_seg, 'TRIAL');
  end if;
  -- số liệu bản thử / chiến dịch (hệ mới + cũ)
  select coalesce(sum(cnt),0), coalesce(sum(camps),0) into v_ok, v_camp from (
    select count(*) filter (where (d.report_group='success' OR (d.report_group IS NULL AND d.status in ('thành công','đã xem','đã tham gia')))) cnt, count(distinct c.id) camps
      from public.auto_campaigns c join public.org_organization g on g.id=c.organization_id
      left join public.auto_campaign_details d on d.campaign_id=c.id
     where g.customer_id=p_opp.customer_id and coalesce(c.is_delete,false)=false
    union all
    select coalesce(sum(tr.status_thanh_cong),0), count(distinct tr.campaign_id)
      from public.aka_order o join public.aka_tracking_app tr on tr.account_id=o.account_id_old
     where o.customer_id=p_opp.customer_id and tr.event_timestamp >= now()-interval '60 days') x;
  v_ctx := jsonb_build_object(
    'today', public.fn_opp_today_vn(), 'trial_start', v_trial, 'state', v_state, 'segment', v_seg,
    'product_group', v_pc->>'product_group', 'package', v_pc->>'package', 'renewal', v_ren,
    'h_date', case when t.anchor_kind='expiration' then p_opp.anchor_date end,
    'has_phone', nullif(cu.phone,'') is not null, 'has_email', nullif(cu.email,'') is not null,
    'ten', coalesce(cu.name,'anh/chị'), 'san_pham', coalesce(nullif(v_pc->>'product_raw',''),'akaBiz'),
    'goi', v_pc->>'package', 'ngay_het_han', case when t.anchor_kind='expiration' then to_char(p_opp.anchor_date,'DD/MM/YYYY') end,
    'so_ngay_con', case when t.anchor_kind='expiration' then (p_opp.anchor_date - public.fn_opp_today_vn())::text end,
    'nv_ten', coalesce(st.name,''), 'nv_sdt', coalesce(st.phone,''), 'nguoi_gioi_thieu', coalesce(v_ref,''),
    'so_tin_thanh_cong', v_ok::text, 'so_chien_dich', v_camp::text, 'nganh', coalesce(cu.linh_vuc,'{nganh}'), 'inbox_url', cu.inbox_url)
    || coalesce(cfg->'placeholders', '{}'::jsonb);
  return v_ctx;
end $function$

CREATE OR REPLACE FUNCTION public.fn_opp_morning(p_ngay date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare cfg jsonb; v_ngay date; r record; n_exp int; n_task int := 0; n_opp int := 0; n_err int := 0; v_err text[] := '{}'; k int;
begin
  cfg := public.fn_opp_config();
  if not coalesce((cfg->>'morning_enabled')::boolean, true) then return jsonb_build_object('skipped', 'morning_disabled'); end if;
  v_ngay := coalesce(p_ngay, public.fn_opp_today_vn());
  n_exp := public.fn_opp_dong_het_vong_doi();
  for r in select id from public.aka_salesopportunity where status = 'open' order by id loop
    begin
      k := public.fn_opp_sinh_buoc(r.id, v_ngay); n_task := n_task + k; n_opp := n_opp + 1;
    exception when others then
      n_err := n_err + 1; v_err := v_err || format('#%s: %s', r.id, left(sqlerrm, 160));
    end;
  end loop;
  perform public.fn_opp_log(case when n_err > 0 then 'partial' else 'success' end,
    format('Sáng %s: %s cơ hội mở, %s task sinh, %s hết vòng đời, %s lỗi', v_ngay, n_opp, n_task, n_exp, n_err),
    jsonb_build_object('ngay', v_ngay, 'opps', n_opp, 'tasks', n_task, 'expired', n_exp, 'errors', to_jsonb(v_err)), n_task, 0, n_err);
  return jsonb_build_object('ngay', v_ngay, 'opps', n_opp, 'tasks', n_task, 'expired', n_exp, 'errors', n_err);
end $function$

CREATE OR REPLACE FUNCTION public.fn_opp_renewal_score(p_customer_id bigint, p_h date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare v_score int := 0; v_last_act date; v_login14 int := 0; v_camp14 int := 0; v_camp60 int := 0;
        v_last_msg date; v_buy_intent int := 0; v_bug int := 0; v_first_buy date; v_ref boolean; v_pg text; v_ref_day date;
begin
  v_ref_day := least(p_h, public.fn_opp_today_vn());
  -- hệ cũ: tracking theo account_id_old
  select max((t.event_timestamp at time zone 'Asia/Ho_Chi_Minh')::date),
         count(distinct (t.event_timestamp at time zone 'Asia/Ho_Chi_Minh')::date) filter (where t.event_type in ('login','login_app_akabiz','open_app_akabiz') and t.event_timestamp >= (v_ref_day-14)::timestamp),
         count(distinct t.campaign_id) filter (where t.event_type='add' and t.campaign_id is not null and t.event_timestamp >= (v_ref_day-14)::timestamp),
         count(distinct t.campaign_id) filter (where t.event_type='update' and t.campaign_id is not null and t.event_timestamp >= (v_ref_day-60)::timestamp)
    into v_last_act, v_login14, v_camp14, v_camp60
    from public.aka_order o join public.aka_tracking_app t on t.account_id=o.account_id_old
   where o.customer_id=p_customer_id and t.event_timestamp >= (v_ref_day-60)::timestamp and t.event_timestamp < (v_ref_day+1)::timestamp;
  -- hệ mới: auto_campaigns
  select greatest(v_last_act, max((coalesce(c.last_run_at,c.updated_at) at time zone 'Asia/Ho_Chi_Minh')::date)),
         v_camp14 + count(*) filter (where c.created_at >= (v_ref_day-14)::timestamp),
         v_camp60 + count(*) filter (where c.last_run_at >= (v_ref_day-60)::timestamp)
    into v_last_act, v_camp14, v_camp60
    from public.auto_campaigns c join public.org_organization g on g.id=c.organization_id
   where g.customer_id=p_customer_id and coalesce(c.is_delete,false)=false and coalesce(c.last_run_at,c.updated_at) < (v_ref_day+1)::timestamp;
  -- tin nhắn
  select max((m.question_first_at at time zone 'Asia/Ho_Chi_Minh')::date),
         count(*) filter (where m.bot_intent in ('A1_ASK_PRICE','C2_PURCHASE_UPGRADE','C4_RENEWAL','C5_ASK_DISCOUNT')),
         count(*) filter (where m.bot_intent in ('C3_REPORT_BUG','L1_TROUBLESHOOT','L3_FIX_FAILED'))
    into v_last_msg, v_buy_intent, v_bug
    from public.message_gom m where m.aka_customer_id=p_customer_id and m.question_content is not null and m.question_content<>''
     and m.question_first_at >= (v_ref_day-60)::timestamp and m.question_first_at < (v_ref_day+1)::timestamp;
  select min(d)::date into v_first_buy from (
    select o.date_create d from public.aka_order o where o.customer_id=p_customer_id and coalesce(o.is_demo,false)=false and lower(coalesce(o.package,''))<>'demo'
    union all select q.purchase_date from public.org_organization_product q join public.org_organization g on g.id=q.organization_id where g.customer_id=p_customer_id and q.is_paid) x;
  select coalesce(is_referred,false) or referrer_id is not null into v_ref from public.aka_customer where id=p_customer_id;
  v_pg := public.fn_opp_product_context(p_customer_id)->>'product_group';

  v_score := v_score + case when v_last_act is null then 0
                            when v_ref_day - v_last_act <= 1 then 40 when v_ref_day - v_last_act <= 3 then 25
                            when v_ref_day - v_last_act <= 7 then 20 when v_ref_day - v_last_act <= 14 then 10
                            when v_ref_day - v_last_act <= 30 then 0 else -10 end;
  v_score := v_score + case when v_login14 = 0 then 0 when v_login14 = 1 then 8 when v_login14 <= 3 then 12 when v_login14 <= 6 then 15 else 20 end;
  v_score := v_score + case when v_camp14 = 0 then 0 when v_camp14 <= 3 then 8 when v_camp14 <= 10 then 15 else 20 end;
  v_score := v_score + case when v_camp60 <= 5 then 0 when v_camp60 <= 10 then 8 else 15 end;
  v_score := v_score + case when v_last_msg is null then 0 when v_ref_day - v_last_msg <= 3 then 15 when v_ref_day - v_last_msg <= 14 then 8 when v_ref_day - v_last_msg <= 30 then 3 else 0 end;
  v_score := v_score + case when v_buy_intent = 0 then 0 when v_buy_intent <= 3 then 3 else 8 end;
  v_score := v_score + case when v_bug >= 3 then 5 else 0 end;
  v_score := v_score + case when v_first_buy is not null and v_ref_day - v_first_buy > 75 then 5 else 0 end;
  v_score := v_score + case when v_ref then 5 else 0 end;
  v_score := v_score + case when v_pg in ('facebook','sms') then -5 else 0 end;

  return jsonb_build_object('score', v_score,
    'group', case when v_score >= 60 then 'hot' when v_score >= 35 then 'warm' when v_score >= 15 then 'cool' else 'cold' end,
    'last_act', v_last_act, 'login14', v_login14, 'camp14', v_camp14, 'camp60', v_camp60, 'last_msg', v_last_msg);
end $function$

CREATE OR REPLACE FUNCTION public.fn_opp_sinh_buoc(p_opp_id bigint, p_ngay date DEFAULT NULL::date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.aka_salesopportunity; t record; cfg jsonb; ctx jsonb; steps jsonb; s jsonb; v_ngay date; v_off_anchor int; v_off_trial int;
        v_from text; v_code text; v_actor text; v_actions jsonb; v_created int := 0; v_progress jsonb; v_trial date;
        v_replied48 boolean; v_due timestamptz; v_due_date date; v_due_time text; v_chan bigint; v_content text; v_note text; v_crm_id bigint;
        v_staff_ok boolean; v_auto_ok boolean; v_manual boolean; v_prio int; cu record; a text; v_next jsonb; v_min_off int := null; v_auto_send boolean;
        v_gen_status text; v_dow int; v_has_call boolean; v_has_zalo boolean;
begin
  select * into o from public.aka_salesopportunity where id = p_opp_id for update;
  if not found or o.status <> 'open' then return 0; end if;
  select * into t from public.aka_salesopportunity_type where id = o.type_id;
  cfg := public.fn_opp_config();
  v_auto_send := coalesce((cfg->>'auto_send_enabled')::boolean, false);
  v_ngay := coalesce(p_ngay, public.fn_opp_today_vn());
  -- luật dừng: CSDL thấy khách đang trả phí với cơ hội bán mới → won
  if t.opportunity_type = 'new_sale' and t.auto_close_on_purchase and public.fn_trang_thai_mua(o.customer_id) = 'dang_dung' then
    perform public.fn_dong_co_hoi_ban_hang(o.id, 'won', 'purchased_detected');
    return 0;
  end if;
  ctx := public.fn_opp_ctx(o);
  if not coalesce((cfg->>'step_generation_enabled')::boolean, true) then
    -- tạm dừng sinh task: vẫn cập nhật ngày thử để vòng đời đúng, không insert aka_crm
    if (ctx->>'trial_start') is not null and o.trial_start_date is distinct from (ctx->>'trial_start')::date then
      update public.aka_salesopportunity set trial_start_date = (ctx->>'trial_start')::date where id = o.id;
    end if;
    return 0;
  end if;
  v_trial := (ctx->>'trial_start')::date;
  if v_trial is not null and o.trial_start_date is distinct from v_trial then
    update public.aka_salesopportunity set trial_start_date = v_trial where id = o.id;  -- trigger BEFORE UPDATE kéo dài lifecycle
  end if;
  select * into cu from public.aka_customer where id = o.customer_id;
  v_progress := coalesce(o.care_progress, '{}'::jsonb);
  v_off_anchor := v_ngay - o.anchor_date;
  v_off_trial := case when v_trial is not null then v_ngay - v_trial end;
  v_replied48 := not public.fn_opp_cond('silent_48h', o, ctx);
  v_dow := extract(dow from v_ngay)::int;  -- 0 = CN, 6 = T7
  steps := public.fn_opp_steps(o.type_id);

  for s in select * from jsonb_array_elements(steps) loop
    v_code := s->>'code'; v_from := coalesce(s->>'from','anchor');
    if v_progress ? v_code then continue; end if;
    if v_from = 'trial_start' then
      if v_off_trial is null then continue; end if;
      if (s->>'offset')::int <> v_off_trial then
        if (s->>'offset')::int > v_off_trial then v_min_off := least(coalesce(v_min_off, 9999), (s->>'offset')::int - v_off_trial); end if;
        continue;
      end if;
    else
      if (s->>'offset')::int <> v_off_anchor then
        if (s->>'offset')::int > v_off_anchor then v_min_off := least(coalesce(v_min_off, 9999), (s->>'offset')::int - v_off_anchor); end if;
        continue;
      end if;
    end if;

    s := public.fn_opp_apply_variants(s, ctx);
    if coalesce((s->>'skip')::boolean,false) then v_progress := v_progress || jsonb_build_object(v_code, 'skipped:'||coalesce(s->>'skip_reason','variant')); continue; end if;
    if public.fn_opp_conds_any(s->'skip_if', o, ctx) then v_progress := v_progress || jsonb_build_object(v_code, 'skipped:skip_if'); continue; end if;
    if s ? 'only_if' and jsonb_array_length(coalesce(s->'only_if','[]'::jsonb)) > 0 and not public.fn_opp_conds_all(s->'only_if', o, ctx) then
      v_progress := v_progress || jsonb_build_object(v_code, 'skipped:only_if'); continue; end if;

    v_actor := coalesce(s->>'actor','staff'); v_actions := coalesce(s->'actions','["zalo"]'::jsonb);
    v_manual := false;
    if v_actor = 'auto' and v_replied48 then v_actor := 'staff'; v_manual := true; end if;      -- T-reply: khách vừa nhắn → NV gửi tay
    if v_actor = 'auto' and not v_auto_send then v_actor := 'staff'; v_manual := true; end if;  -- worker gửi chưa bật → NV gửi tay
    v_staff_ok := v_actor in ('staff','both') and (v_actor <> 'both' or public.fn_opp_conds_all(s->'only_if_staff', o, ctx));
    v_auto_ok  := v_actor in ('auto','both') and (v_actor <> 'both' or public.fn_opp_conds_all(s->'only_if_auto', o, ctx));
    if v_actor = 'both' and v_auto_ok and (v_replied48 or not v_auto_send) then v_auto_ok := false; if not v_staff_ok then v_staff_ok := true; v_manual := true; end if; end if;
    if not v_staff_ok and not v_auto_ok then v_progress := v_progress || jsonb_build_object(v_code, 'skipped:only_if_staff'); continue; end if;

    -- giờ hẹn (CN → T2; T7 chỉ NV)
    v_due_time := coalesce(s->>'due_time_vn', cfg->'global_rules'->>'due_time_default_vn', '08:30');
    v_due_date := v_ngay;
    if v_dow = 0 then v_due_date := v_ngay + 1; elsif v_dow = 6 and v_actor = 'auto' then v_due_date := v_ngay + 2; end if;
    if v_due_time = 'immediate' then v_due := now();
    else v_due := (v_due_date::text || ' ' || v_due_time)::timestamp at time zone 'Asia/Ho_Chi_Minh'; end if;
    v_prio := coalesce((s->>'priority')::int, 20) + coalesce((t.care_process->>'priority_boost')::int, 0);

    v_has_call := v_actions ? 'call'; v_has_zalo := v_actions ? 'zalo';
    -- task NV: gộp call+zalo
    if v_staff_ok and (v_has_call or v_has_zalo or v_actor = 'staff') then
      v_chan := case when v_has_call then 10 else 8 end;
      v_content := public.fn_opp_render(coalesce(s->'content'->>'zalo', s->'content'->>'call', s->'content'->>'sms'), ctx);
      v_note := format('[Cơ hội #%s · %s · %s%s] %s', o.id, t.name, v_code, case when v_manual then ' · AUTO→NV gửi tay' else '' end, coalesce(s->>'goal',''));
      v_gen_status := 'scheduled';
      insert into public.aka_crm (customer_id, customer_name, customer_phone, crm_type_id, priority, org_staff_owner_id, organization_id, created_by,
              cskh_due_date, note, task_note, pancake_url, suggested_channel_id, suggested_content, is_read, source_type, gen_status, gen_agent, gen_at, gen_meta,
              sales_opportunity_id, interest_product_ids, source_expiration_date)
      values (o.customer_id, cu.name, cu.phone, t.crm_type_id, v_prio, o.owner_org_staff_id, o.organization_id, o.owner_org_staff_id,
              v_due, left(v_note, 500), left(public.fn_opp_render(coalesce(s->'content'->>'call',''), ctx), 1000), cu.inbox_url, v_chan, v_content, false, 'sales_opp', v_gen_status, 'sales_opp_v2', now(),
              jsonb_build_object('opp_id', o.id, 'type_code', t.code, 'step_code', v_code, 'from', v_from, 'offset', s->>'offset', 'actor', 'staff', 'manual_send', v_manual,
                                 'actions', v_actions, 'segment', ctx->>'segment', 'state', ctx->>'state', 'variant_applied', s->'variant_applied', 'why', s->>'why'),
              o.id, case when o.product_id is not null then array[o.product_id] end, case when t.anchor_kind='expiration' then o.anchor_date end)
      on conflict do nothing
      returning id into v_crm_id;
      if v_crm_id is not null then v_created := v_created + 1; v_progress := v_progress || jsonb_build_object(v_code, v_crm_id); end if;
    end if;
    -- task auto: từng kênh
    if v_auto_ok then
      for a in select value #>> '{}' from jsonb_array_elements(v_actions) loop
        if a not in ('zalo','email','sms') then continue; end if;
        if a = 'zalo' and v_staff_ok then continue; end if;   -- NV đã nhận phần Zalo
        if a = 'email' and not coalesce((ctx->>'has_email')::boolean,false) then continue; end if;
        v_chan := case a when 'zalo' then 8 when 'email' then 121 else 9 end;
        v_content := public.fn_opp_render(case a when 'email' then coalesce(s->'content'->'email'->>'subject','')||E'\n'||coalesce(s->'content'->'email'->>'body','') else s->'content'->>a end, ctx);
        if v_content is null or v_content = '' then continue; end if;
        insert into public.aka_crm (customer_id, customer_name, customer_phone, crm_type_id, priority, org_staff_owner_id, organization_id, created_by,
                cskh_due_date, note, pancake_url, suggested_channel_id, suggested_content, is_read, source_type, gen_status, gen_agent, gen_at, gen_meta,
                sales_opportunity_id, interest_product_ids, source_expiration_date)
        values (o.customer_id, cu.name, cu.phone, t.crm_type_id, v_prio + 10, o.owner_org_staff_id, o.organization_id, o.owner_org_staff_id,
                v_due, left(format('[Cơ hội #%s · %s · %s · AUTO %s] %s', o.id, t.name, v_code, a, coalesce(s->>'goal','')), 500), cu.inbox_url, v_chan, v_content, false, 'sales_opp', 'pending_send', 'sales_opp_v2', now(),
                jsonb_build_object('opp_id', o.id, 'type_code', t.code, 'step_code', v_code, 'from', v_from, 'offset', s->>'offset', 'actor', 'auto', 'channel', a,
                                   'segment', ctx->>'segment', 'state', ctx->>'state', 'variant_applied', s->'variant_applied'),
                o.id, case when o.product_id is not null then array[o.product_id] end, case when t.anchor_kind='expiration' then o.anchor_date end)
        on conflict do nothing
        returning id into v_crm_id;
        if v_crm_id is not null then v_created := v_created + 1; v_progress := v_progress || jsonb_build_object(v_code || ':' || a, v_crm_id); if not (v_progress ? v_code) then v_progress := v_progress || jsonb_build_object(v_code, v_crm_id); end if; end if;
      end loop;
    end if;
  end loop;

  update public.aka_salesopportunity
     set care_progress = v_progress,
         next_action_at = case when v_min_off is not null then ((v_ngay + v_min_off)::text || ' 08:30')::timestamp at time zone 'Asia/Ho_Chi_Minh' else next_action_at end,
         next_action_type = coalesce(next_action_type, 'follow_up'),
         version = version + 1
   where id = o.id;
  return v_created;
end $function$

CREATE OR REPLACE FUNCTION public.fn_opp_suy_loai(p_customer_id bigint, p_crm_id bigint DEFAULT NULL::bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare v_tt text; v_h date; c record; v_crm_type bigint; v_code text;
begin
  v_tt := public.fn_trang_thai_mua(p_customer_id);
  select is_referred, referrer_id, source_status_id, channel into c from public.aka_customer where id=p_customer_id;
  if p_crm_id is not null then select crm_type_id into v_crm_type from public.aka_crm where id=p_crm_id; end if;
  if v_tt = 'dang_dung' then
    v_h := public.fn_opp_ngay_het_han(p_customer_id);
    if v_h is not null and v_h - public.fn_opp_today_vn() <= 15 then v_code := 'renewal'; else v_code := 'cross_sell'; end if;
  elsif v_tt = 'het_han' then
    v_code := 'renewal';
  else
    if coalesce(c.is_referred,false) or c.referrer_id is not null or c.source_status_id = 50 then v_code := 'new_referral';
    elsif c.channel = 'trigger_from_contact' or c.source_status_id in (52,104) or v_crm_type = 19 then v_code := 'new_zalo';
    else v_code := 'new_crm_data'; end if;
  end if;
  return (select id from public.aka_salesopportunity_type where code = v_code and is_active);
end $function$

CREATE OR REPLACE FUNCTION public.fn_opp_trial_state(p_customer_id bigint)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare v_start date; v_login boolean := false; v_camp boolean := false; v_ok boolean := false;
begin
  v_start := public.fn_opp_trial_start(p_customer_id);
  if v_start is null then return null; end if;
  -- hệ mới
  select exists (select 1 from public.auto_accounts a join public.org_organization g on g.id=a.organization_id
                  where g.customer_id=p_customer_id and coalesce(a.is_delete,false)=false) into v_login;
  select exists (select 1 from public.auto_campaigns c join public.org_organization g on g.id=c.organization_id
                  where g.customer_id=p_customer_id and coalesce(c.is_delete,false)=false) into v_camp;
  if v_camp then
    select exists (select 1 from public.auto_campaign_details d join public.auto_campaigns c on c.id=d.campaign_id
                    join public.org_organization g on g.id=c.organization_id
                   where g.customer_id=p_customer_id and (d.report_group='success' OR (d.report_group IS NULL AND d.status in ('thành công','đã xem','đã tham gia')))) into v_ok;
  end if;
  -- hệ cũ
  if not v_ok then
    perform 1;
    select bool_or(t.event_type in ('login','login_app_akabiz','open_app_akabiz')) or v_login,
           bool_or(t.event_type='add' and t.campaign_id is not null) or v_camp,
           bool_or(coalesce(t.status_thanh_cong,0) > 0 or coalesce(t.status_da_xem,0) > 0) or v_ok
      into v_login, v_camp, v_ok
      from public.aka_order o join public.aka_tracking_app t on t.account_id = o.account_id_old
     where o.customer_id = p_customer_id and (coalesce(o.is_demo,false) or lower(coalesce(o.package,''))='demo')
       and t.event_timestamp >= v_start::timestamp;
  end if;
  if v_ok then return 'S3'; elsif v_camp then return 'S2'; elsif v_login then return 'S1'; else return 'S0'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.fn_phone_nudge_create_crm_v1(p_job_id bigint, p_force boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_job          aka_phone_nudge_job%rowtype;
  v_gom          message_gom%rowtype;
  v_contact      contacts%rowtype;
  v_crm_type_id  constant bigint := 32;   -- CSKH mới - về từ Zalo
  v_priority     integer;
  v_crm_type_name text;
  v_uid          text;
  v_name         text;
  v_phone        text;
  v_customer_id  bigint;
  v_customer_is_new boolean := false;
  v_owner_id     bigint;
  v_org_id       bigint;
  v_owner_name   text;
  v_pancake_url  text;
  v_note         text;
  v_source_type  text;
  v_lead_id      bigint;
  v_crm_id       bigint;
  v_existing_crm_id bigint;
  v_existing_type bigint;
  v_day_start    timestamptz;
  v_interest     text;
  v_qual_reason  text;
  v_result       jsonb;
  v_upsert       jsonb;
  v_crm          jsonb;
begin
  select * into v_job from aka_phone_nudge_job where id = p_job_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'job_not_found', 'job_id', p_job_id);
  end if;

  -- idempotent
  if v_job.aka_crm_id is not null then
    return jsonb_build_object('ok', true, 'created', false, 'action', 'already_created',
      'crm_id', v_job.aka_crm_id, 'customer_id', v_job.aka_customer_id, 'job_id', p_job_id);
  end if;

  -- điều kiện: Pancake OK (hoặc chưa bật check) + AI xác nhận khách quan tâm
  if not p_force then
    if v_job.pancake_check is not null and coalesce(v_job.pancake_check ->> 'verdict', '') <> 'OK' then
      return jsonb_build_object('ok', false, 'skipped', 'pancake_not_ok',
        'verdict', v_job.pancake_check ->> 'verdict', 'job_id', p_job_id);
    end if;
    if coalesce((v_job.qualify_result ->> 'is_prospect')::boolean, false) is not true then
      return jsonb_build_object('ok', false, 'skipped', 'not_prospect', 'job_id', p_job_id);
    end if;
  end if;

  select * into v_gom from message_gom where id = v_job.message_gom_id;
  if v_job.contact_id is not null then
    select * into v_contact from contacts where id = v_job.contact_id;
  end if;

  v_uid := fn_zalo_referral_canonical_uid_v1(coalesce(v_contact.uid, v_gom.zalo_id));
  if v_uid is not null and v_uid !~ '^[[:alnum:]_.@-]{3,100}$' then v_uid := null; end if;

  v_phone := normalize_phone(coalesce(nullif(btrim(v_contact.phone), ''), nullif(btrim(v_gom.shared_phone), ''), nullif(btrim(v_gom.phone), '')));
  if v_phone !~ '^0[1-9][0-9]{8}$' then v_phone := null; end if;

  v_name := left(regexp_replace(coalesce(
      nullif(btrim(v_job.contact_name), ''), nullif(btrim(v_gom.contact_name), ''), nullif(btrim(v_contact.name), ''),
      case when v_uid is not null then 'Liên hệ Zalo ' || right(v_uid, 6) end, 'Khách Zalo mới'), '[[:space:]]+', ' ', 'g'), 200);

  v_pancake_url := coalesce(fn_zalo_chat_referral_pancake_url_v1(v_job.message_gom_id),
    (select 'https://pancake.vn/' || s.pancake_page_id || '?c_id=' || v_job.conversation_id
       from shops s where s.id = v_job.shop_id_2 and nullif(btrim(s.pancake_page_id), '') is not null));

  -- ---------- tạo / cập nhật aka_customer qua HÀM CHUNG (v2) ----------
  v_upsert := fn_upsert_aka_customer_v1(jsonb_strip_nulls(jsonb_build_object(
    'customer_id', coalesce(v_gom.aka_customer_id, v_contact.customer_id),
    'phone', v_phone,
    'zalo_uid', coalesce(v_contact.uid, v_gom.zalo_id),
    'pancake_url', v_pancake_url,
    'name', v_name, 'name_zalo', v_name,
    'channel', 'trigger_from_contact', 'account_id', v_job.account_id, 'source_status_id', 104,
    'is_split_exempt', true, 'creation_path', 'phone_nudge_v1',
    'custom_fields', jsonb_strip_nulls(jsonb_build_object(
        'phone_nudge_job_id', p_job_id, 'phone_nudge_trigger_type', v_job.trigger_type,
        'message_gom_id', v_job.message_gom_id::text, 'conversation_id', v_job.conversation_id,
        'contact_id', v_job.contact_id::text,
        'pancake_customer_inserted_at', v_job.pancake_check ->> 'customer_inserted_at')),
    'conversation_id', v_job.conversation_id, 'shop_id', v_job.shop_id, 'shop_id_2', v_job.shop_id_2,
    'chat_staff_id', v_job.staff_id, 'contact_id', v_job.contact_id
  )));
  if coalesce((v_upsert ->> 'ok')::boolean, false) is not true then
    update aka_phone_nudge_job set crm_result = v_upsert, updated_at = now() where id = p_job_id;
    return v_upsert || jsonb_build_object('job_id', p_job_id, 'stage', 'upsert_customer');
  end if;
  v_customer_id := (v_upsert ->> 'customer_id')::bigint;
  v_customer_is_new := coalesce((v_upsert ->> 'is_new')::boolean, false);
  v_owner_id := (v_upsert ->> 'org_staff_owner_id')::bigint;
  select os.organization_id, os.name into v_org_id, v_owner_name from org_staff os where os.id = v_owner_id;
  if v_owner_id is null or v_org_id is null then
    return jsonb_build_object('ok', false, 'error', 'active_owner_not_resolved', 'job_id', p_job_id, 'upsert', v_upsert);
  end if;

  -- ---------- chống trùng CRM ----------
  v_day_start := date_trunc('day', now() at time zone 'Asia/Ho_Chi_Minh') at time zone 'Asia/Ho_Chi_Minh';
  select c.id, c.crm_type_id into v_existing_crm_id, v_existing_type from aka_crm c
  where c.customer_id = v_customer_id
    and (c.created_at >= v_day_start
         or (c.crm_type_id in (1, 2, 5, 31, 32) and c.created_at > now() - interval '14 days'))
  order by c.created_at desc limit 1;
  if v_existing_crm_id is not null then
    v_result := jsonb_build_object('ok', true, 'created', false, 'action', 'duplicate',
      'crm_id', v_existing_crm_id, 'existing_crm_type_id', v_existing_type,
      'customer_id', v_customer_id, 'customer_is_new', v_customer_is_new, 'job_id', p_job_id);
    update aka_phone_nudge_job set aka_customer_id = v_customer_id, crm_result = v_result, updated_at = now() where id = p_job_id;
    return v_result;
  end if;

  select t.stt, t.name into v_priority, v_crm_type_name from aka_crm_type t where t.id = v_crm_type_id and t.is_active = true;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'required_crm_type_inactive', 'job_id', p_job_id);
  end if;

  v_interest := nullif(btrim(v_job.qualify_result ->> 'interest_level'), '');
  v_qual_reason := left(nullif(btrim(coalesce(v_job.qualify_result ->> 'reason', v_job.qualify_result ->> 'note', '')), ''), 300);
  v_note := 'Khách mới về từ Zalo - ' ||
    case v_job.trigger_type when 'FRIEND_REQUEST' then 'khách gửi lời mời kết bạn' when 'FIRST_MESSAGE' then 'khách nhắn tin đầu tiên' else lower(v_job.trigger_type) end ||
    case when v_phone is null then ' (chưa có SĐT). ' else ' (SĐT: ' || v_phone || '). ' end || 'Người chat: ' || v_name ||
    case when v_job.staff_name is not null then ' - NV tiếp nhận: ' || v_job.staff_name else '' end ||
    E'\nĐã xác minh: Pancake tạo trong ngày' ||
    case when v_job.pancake_check ->> 'customer_inserted_at' is not null then ' (' || (v_job.pancake_check ->> 'customer_inserted_at') || ' UTC)' else '' end ||
    '; AI xác nhận khách quan tâm' || case when v_interest is not null then ' - mức ' || v_interest else '' end ||
    case when v_qual_reason is not null then E'\nAI: ' || v_qual_reason else '' end ||
    case when v_job.status = 'SENT' then E'\nĐã tự động nhắn xin SĐT lúc ' || to_char(v_job.sent_at at time zone 'Asia/Ho_Chi_Minh', 'HH24:MI DD/MM') else '' end ||
    E'\nViệc cần làm: nhắn Zalo tư vấn + xin SĐT/nhu cầu.' ||
    case when v_pancake_url is not null then E'\nLink Pancake: ' || v_pancake_url else '' end;

  v_source_type := 'phone_nudge:' || p_job_id::text;

  insert into aka_lead (
    name, phone, phone_norm, type_source, source, akacustomer_id, organization_id, status, note,
    pancake_url, raw_payload, source_occurred_at
  ) values (
    v_name, v_phone, v_phone, 'phone_nudge', v_job.source, v_customer_id, v_org_id, 'new', v_note, v_pancake_url,
    jsonb_strip_nulls(jsonb_build_object(
      'source_type', v_source_type, 'job_id', p_job_id, 'trigger_type', v_job.trigger_type,
      'message_gom_id', v_job.message_gom_id::text, 'conversation_id', v_job.conversation_id,
      'target_zalo_uid', v_uid, 'pancake_check', v_job.pancake_check, 'qualify_result', v_job.qualify_result)),
    v_job.trigger_at
  ) returning id into v_lead_id;

  -- ---------- tạo CRM qua HÀM CHUNG fn_create_aka_crm_v1 (v3) ----------
  v_crm := fn_create_aka_crm_v1(jsonb_strip_nulls(jsonb_build_object(
    'customer_id', v_customer_id, 'crm_type_id', v_crm_type_id,
    'org_staff_owner_id', v_owner_id, 'organization_id', v_org_id,
    'customer_name', v_name, 'note', v_note, 'suggested_channel_id', 8,
    'source_type', v_source_type, 'source_order_id', v_customer_id,
    'gen_agent', 'phone-nudge-v1', 'gen_status', 'created',
    'gen_meta', jsonb_strip_nulls(jsonb_build_object(
      'version', 'v3', 'phone_nudge_job_id', p_job_id, 'trigger_type', v_job.trigger_type,
      'message_gom_id', v_job.message_gom_id::text, 'conversation_id', v_job.conversation_id,
      'contact_id', v_job.contact_id::text, 'target_zalo_uid', v_uid,
      'pancake_verdict', v_job.pancake_check ->> 'verdict',
      'pancake_customer_inserted_at', v_job.pancake_check ->> 'customer_inserted_at',
      'ai_is_prospect', v_job.qualify_result -> 'is_prospect', 'ai_interest_level', v_interest,
      'nudge_status', v_job.status, 'customer_is_new', v_customer_is_new, 'lead_id', v_lead_id)),
    'pancake_url', v_pancake_url, 'lead_id', v_lead_id,
    'allow_same_day', false, 'notify_lark', true
  )));
  v_crm_id := nullif(v_crm ->> 'crm_id', '')::bigint;

  if coalesce((v_crm ->> 'created')::boolean, false) is not true then
    v_result := jsonb_build_object('ok', coalesce((v_crm ->> 'ok')::boolean, false), 'created', false,
      'action', coalesce(v_crm ->> 'skip_reason', v_crm ->> 'error', 'duplicate'), 'crm_id', v_crm_id,
      'customer_id', v_customer_id, 'customer_is_new', v_customer_is_new, 'job_id', p_job_id, 'crm', v_crm);
  else
    v_result := jsonb_build_object('ok', true, 'created', true, 'action', 'created', 'crm_id', v_crm_id,
      'customer_id', v_customer_id, 'customer_is_new', v_customer_is_new, 'customer_name', v_name,
      'crm_type_id', v_crm_type_id, 'crm_type_name', v_crm_type_name, 'org_staff_owner_id', v_owner_id,
      'staff_name', v_owner_name, 'lead_id', v_lead_id, 'pancake_url', v_pancake_url, 'job_id', p_job_id,
      'upsert', v_upsert - 'name' - 'phone' - 'pancake_url', 'crm', v_crm - 'gen_meta');
  end if;

  update aka_phone_nudge_job
  set aka_customer_id = v_customer_id, aka_crm_id = v_crm_id, crm_created_at = now(), crm_result = v_result, updated_at = now()
  where id = p_job_id;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_resolve_gom_staff(p_answer_org_staff_id bigint, p_staff_id uuid, p_contact_id uuid, p_shop_id uuid, OUT o_org_staff_id bigint, OUT o_via text)
 RETURNS record
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_answer_org_staff_id IS NOT NULL THEN
    o_org_staff_id := p_answer_org_staff_id; o_via := 'direct'; RETURN;
  END IF;

  IF p_staff_id IS NOT NULL THEN
    SELECT os.id INTO o_org_staff_id FROM org_staff os
    WHERE os.chat_staff_id = p_staff_id LIMIT 1;
    IF o_org_staff_id IS NOT NULL THEN o_via := 'mapped'; RETURN; END IF;
  END IF;

  IF p_contact_id IS NOT NULL THEN
    BEGIN
      SELECT os.id INTO o_org_staff_id
      FROM contacts c
      JOIN org_staff os ON os.chat_staff_id = NULLIF((c.staff_ids)[1],'')::uuid AND os.is_active
      WHERE c.id = p_contact_id LIMIT 1;
    EXCEPTION WHEN OTHERS THEN o_org_staff_id := NULL;
    END;
    IF o_org_staff_id IS NOT NULL THEN o_via := 'contact_owner'; RETURN; END IF;

    SELECT ac.org_staff_id_owner INTO o_org_staff_id
    FROM contacts c JOIN aka_customer ac ON ac.id = c.customer_id
    WHERE c.id = p_contact_id AND ac.org_staff_id_owner IS NOT NULL LIMIT 1;
    IF o_org_staff_id IS NOT NULL THEN o_via := 'customer_owner'; RETURN; END IF;
  END IF;

  -- Tầng 5: NV quản lý chính của page Pancake
  IF p_shop_id IS NOT NULL THEN
    SELECT s.manager_org_staff_id INTO o_org_staff_id
    FROM shops s WHERE s.id = p_shop_id AND s.manager_org_staff_id IS NOT NULL;
    IF o_org_staff_id IS NOT NULL THEN o_via := 'page_manager'; RETURN; END IF;
  END IF;

  o_via := 'unassigned';
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_set_chat_zalo_cskh_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_source_id bigint;
begin
  if new.channel = 'trigger_from_contact' and new.account_id = 1001 then
    select s.id
    into v_source_id
    from public.aka_crm_status s
    where s.type = 'source'
      and s.name = 'Chat Zalo CSKH'
      and s.is_active = true
    order by s.id
    limit 1;

    if v_source_id is null then
      raise exception 'active source Chat Zalo CSKH is missing';
    end if;

    -- This source is authoritative for this exact creation path.
    new.source_status_id := v_source_id;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_sync_contacted_channel_name()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.contacted_channel_id IS NOT NULL THEN
    SELECT s.name INTO NEW.contacted_channel_name
    FROM public.aka_crm_status s
    WHERE s.id = NEW.contacted_channel_id;
  ELSE
    NEW.contacted_channel_name := NULL;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_sync_content_group_crm_type_ids()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    UPDATE public.auto_content_groups
       SET crm_type_ids = array_remove(crm_type_ids, OLD.id)
     WHERE OLD.id = ANY(crm_type_ids);
    RETURN OLD;
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.content_group_id IS NOT DISTINCT FROM OLD.content_group_id THEN
    RETURN NEW;
  END IF;

  -- gỡ khỏi mọi nhóm CRM-managed khác
  UPDATE public.auto_content_groups
     SET crm_type_ids = array_remove(crm_type_ids, NEW.id)
   WHERE NEW.id = ANY(crm_type_ids)
     AND (NEW.content_group_id IS NULL OR id <> NEW.content_group_id);

  -- thêm vào nhóm mới
  IF NEW.content_group_id IS NOT NULL THEN
    UPDATE public.auto_content_groups
       SET crm_type_ids = array_append(COALESCE(crm_type_ids, '{}'), NEW.id)
     WHERE id = NEW.content_group_id
       AND NOT (NEW.id = ANY(COALESCE(crm_type_ids, '{}')));
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_tao_co_hoi_ban_hang(p_customer_id bigint, p_type_id bigint DEFAULT NULL::bigint, p_source_kind text DEFAULT 'crm'::text, p_source_crm_id bigint DEFAULT NULL::bigint, p_owner_staff_id bigint DEFAULT NULL::bigint, p_anchor_date date DEFAULT NULL::date, p_product_id bigint DEFAULT NULL::bigint, p_created_by bigint DEFAULT NULL::bigint, p_note text DEFAULT NULL::text, p_force boolean DEFAULT false)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id bigint; t record; v_anchor date; v_org bigint; v_owner bigint; cfg jsonb; v_live boolean; c record; cu record; v_key text; v_try int := 0; v_progress jsonb := '{}'::jsonb; s jsonb;
begin
  if p_customer_id is null then return null; end if;
  perform pg_advisory_xact_lock(hashtext('sales_opp:' || p_customer_id));

  select id into v_id from public.aka_salesopportunity where customer_id = p_customer_id and status = 'open' limit 1;
  if v_id is not null then
    if p_source_crm_id is not null then
      update public.aka_crm set sales_opportunity_id = v_id where id = p_source_crm_id and sales_opportunity_id is null;
      perform public.fn_opp_ghi_tin_hieu(v_id, p_source_crm_id);
    end if;
    return v_id;
  end if;

  select * into t from public.aka_salesopportunity_type
   where id = coalesce(p_type_id, public.fn_opp_suy_loai(p_customer_id, p_source_crm_id)) and is_active;
  if t.id is null then perform public.fn_opp_log('partial', format('không suy được loại cho khách %s', p_customer_id)); return null; end if;

  cfg := public.fn_opp_config();
  v_live := p_force or (cfg->>'mode' = 'live' and (cfg->'live_types') ? t.code);

  select * into c from public.aka_crm where id = p_source_crm_id;
  select * into cu from public.aka_customer where id = p_customer_id;

  if t.anchor_kind = 'expiration' then
    v_anchor := coalesce(p_anchor_date, c.source_expiration_date, public.fn_opp_ngay_het_han(p_customer_id));
    if v_anchor is null then perform public.fn_opp_log('partial', format('loại %s cần ngày hết hạn, khách %s', t.code, p_customer_id)); return null; end if;
    if public.fn_opp_today_vn() > v_anchor + coalesce(t.window_after_days,30) then v_anchor := public.fn_opp_today_vn() - coalesce(t.window_after_days,30); end if;
  else
    v_anchor := coalesce(p_anchor_date, public.fn_opp_today_vn());
  end if;

  v_owner := coalesce(p_owner_staff_id, c.org_staff_owner_id, cu.org_staff_id_owner, c.created_by);
  if v_owner is null then perform public.fn_opp_log('partial', format('không có NV phụ trách cho khách %s (crm %s)', p_customer_id, p_source_crm_id)); return null; end if;
  v_org := coalesce(c.organization_id, 1);

  if not v_live then
    perform public.fn_opp_log('success', format('DRY-RUN: sẽ tạo cơ hội %s cho khách %s (crm %s, neo %s)', t.code, p_customer_id, p_source_crm_id, v_anchor),
      jsonb_build_object('dry_run', true, 'type_code', t.code, 'customer_id', p_customer_id, 'source_crm_id', p_source_crm_id, 'anchor', v_anchor, 'owner', v_owner));
    return null;
  end if;

  -- bước offset 0 tính từ mốc gốc đã được task nguồn bao phủ
  if p_source_crm_id is not null then
    for s in select * from jsonb_array_elements(public.fn_opp_steps(t.id)) loop
      if coalesce(s->>'from','anchor') = 'anchor' and (s->>'offset')::int = 0 then v_progress := v_progress || jsonb_build_object(s->>'code', p_source_crm_id); end if;
    end loop;
  end if;

  v_key := format('opp:%s:%s:%s', p_customer_id, t.code, v_anchor);
  loop
    begin
      insert into public.aka_salesopportunity
        (title, organization_id, customer_id, owner_org_staff_id, type_id, anchor_date, lifecycle_end_at, trial_start_date,
         source_kind, source_crm_id, product_id, created_by_org_staff_id, next_action_note, idempotency_key, opportunity_type, stage, care_progress)
      values
        ('', v_org, p_customer_id, v_owner, t.id, v_anchor, now(), public.fn_opp_trial_start(p_customer_id),
         coalesce(p_source_kind,'crm'), p_source_crm_id, p_product_id, coalesce(p_created_by, v_owner), p_note, v_key, t.opportunity_type, t.default_stage, v_progress)
      returning id into v_id;
      exit;
    exception when unique_violation then
      v_try := v_try + 1;
      if v_try > 5 then raise; end if;
      v_key := format('opp:%s:%s:%s:r%s', p_customer_id, t.code, v_anchor, v_try);
    end;
  end loop;

  if p_source_crm_id is not null then
    update public.aka_crm set sales_opportunity_id = v_id where id = p_source_crm_id;
    perform public.fn_opp_ghi_tin_hieu(v_id, p_source_crm_id);
  end if;
  perform public.fn_opp_sinh_buoc(v_id, public.fn_opp_today_vn());
  perform public.fn_opp_log('success', format('Tạo cơ hội #%s %s cho khách %s (crm %s)', v_id, t.code, p_customer_id, p_source_crm_id),
    jsonb_build_object('opp_id', v_id, 'type_code', t.code, 'customer_id', p_customer_id, 'source_crm_id', p_source_crm_id), 1);
  return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.fn_upsert_aka_customer_v1(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  -- khóa
  v_phone        text;
  v_phone_raw    text;
  v_uid          text;   -- canonical
  v_uid_raw      text;
  v_url          text;
  v_account_id   integer := coalesce(nullif(p ->> 'account_id', '')::integer, 1001);
  -- hồ sơ
  v_name         text := left(nullif(regexp_replace(btrim(coalesce(p ->> 'name', '')), '[[:space:]]+', ' ', 'g'), ''), 200);
  v_channel      text := nullif(btrim(coalesce(p ->> 'channel', '')), '');
  v_overwrite    boolean := coalesce((p ->> 'overwrite')::boolean, false);
  v_touch_return boolean := coalesce((p ->> 'touch_return')::boolean, false);
  v_use_rules    boolean := coalesce((p ->> 'use_split_rules')::boolean, false);
  v_split_exempt boolean := coalesce((p ->> 'is_split_exempt')::boolean, false);
  v_source_id    bigint;
  v_industry_id  bigint;
  v_custom       jsonb := coalesce(p -> 'custom_fields', '{}'::jsonb);
  v_creation_path text := nullif(btrim(coalesce(p ->> 'creation_path', '')), '');
  -- referral
  v_is_referred  boolean := coalesce((p ->> 'is_referred')::boolean, false);
  v_referrer_id  bigint := nullif(p ->> 'referrer_id', '')::bigint;
  v_referrer_phone text;
  v_referrer_url text := nullif(btrim(coalesce(p ->> 'referrer_pancake_url', '')), '');
  -- owner
  v_owner_id     bigint;
  v_org_id       bigint;
  v_owner_source text := 'none';
  v_keyword      text;
  v_chat_staff   uuid;
  v_contact_id   uuid;
  -- tìm
  v_forced_id    bigint := nullif(p ->> 'customer_id', '')::bigint;
  v_by_phone     bigint;
  v_by_uid       bigint;
  v_by_url       bigint;
  v_customer_id  bigint;
  v_matched_by   text;
  v_is_new       boolean := false;
  v_conflicts    jsonb := '[]'::jsonb;
  v_attach_phone boolean := true;
  v_attach_uid   boolean := true;
  v_attach_url   boolean := true;
  v_row          aka_customer%rowtype;
  v_now          timestamptz := now();
  v_today_vn     date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
  v_days_away    integer := 0;
  v_return_note  text;
  v_updated      text[] := array[]::text[];
  v_result       jsonb;
  v_backend_ctx  boolean;
  r              record;
  v_all_full     boolean;
  v_crm          jsonb;
  v_crm_type     bigint;
begin
  -- ---------- chuẩn hóa khóa ----------
  v_phone_raw := nullif(btrim(coalesce(p ->> 'phone', '')), '');
  v_phone := normalize_phone(v_phone_raw);
  if v_phone !~ '^0[1-9][0-9]{8}$' then v_phone := null; end if;

  v_uid_raw := nullif(btrim(coalesce(p ->> 'zalo_uid', '')), '');
  if v_uid_raw is not null and v_uid_raw !~ '^(pzl_u_[0-9]+_[0-9]+|[0-9]{15,})$' then v_uid_raw := null; end if; -- chỉ nhận uid người dùng (không nhận nhóm pzl_g_)
  v_uid := fn_zalo_referral_canonical_uid_v1(v_uid_raw);
  if v_uid is not null and v_uid !~ '^[[:alnum:]_.@-]{3,100}$' then v_uid := null; end if;

  v_url := nullif(btrim(coalesce(p ->> 'pancake_url', '')), '');
  if v_url is not null and v_url !~* '^https?://(pancake\.vn|pages\.fm)/' then v_url := null; end if;

  if v_phone is null and v_uid is null and v_url is null and v_forced_id is null then
    return jsonb_build_object('ok', false, 'error', 'missing_identifier',
      'message', 'Cần ít nhất 1 trong 3: phone hợp lệ (0xxxxxxxxx), zalo_uid (pzl_u_... hoặc số), pancake_url (pancake.vn/pages.fm)',
      'phone_raw', v_phone_raw, 'zalo_uid_raw', v_uid_raw);
  end if;

  v_referrer_phone := normalize_phone(nullif(btrim(coalesce(p ->> 'referrer_phone', '')), ''));
  if v_referrer_phone !~ '^0[1-9][0-9]{8}$' or v_referrer_phone = v_phone then v_referrer_phone := null; end if;
  if v_referrer_id is null and v_referrer_phone is not null then
    select id into v_referrer_id from aka_customer where normalize_phone(phone) = v_referrer_phone
      and coalesce(record_state, 'active') <> 'merged' order by created_at desc nulls last, id desc limit 1;
  end if;
  v_is_referred := v_is_referred or v_referrer_id is not null or v_referrer_phone is not null or v_referrer_url is not null;

  v_source_id := nullif(p ->> 'source_status_id', '')::bigint;
  if v_source_id is not null and not exists (select 1 from aka_crm_status s where s.id = v_source_id and s.type = 'source' and s.is_active) then v_source_id := null; end if;
  if v_source_id is null and v_is_referred then v_source_id := 50; end if; -- 'được giới thiệu'
  v_industry_id := nullif(p ->> 'industry_status_id', '')::bigint;
  if v_industry_id is not null and not exists (select 1 from aka_crm_status s where s.id = v_industry_id and s.type = 'industry' and s.is_active) then v_industry_id := null; end if;

  begin v_chat_staff := nullif(p ->> 'chat_staff_id', '')::uuid; exception when others then v_chat_staff := null; end;
  begin v_contact_id := nullif(p ->> 'contact_id', '')::uuid; exception when others then v_contact_id := null; end;

  -- cho phép ghi zalo_referral_id (guard protect_zalo_referral_customer_identity_v1)
  v_backend_ctx := private.zalo_referral_backend_context_v1();
  perform set_config('app.aka_customer_upsert_ctx', '1', true);

  -- ---------- khóa giao dịch theo từng khóa ----------
  if v_phone is not null then perform pg_advisory_xact_lock(hashtextextended('zalo-referral-phone:' || v_phone, 0)); end if;
  if v_uid is not null then perform pg_advisory_xact_lock(hashtextextended('zalo-referral-uid:' || v_account_id::text || ':' || lower(v_uid), 0)); end if;
  if v_url is not null then perform pg_advisory_xact_lock(hashtextextended('aka-customer-pancake-url:' || lower(v_url), 0)); end if;

  -- ---------- tìm theo từng khóa ----------
  if v_forced_id is not null then
    select id into v_customer_id from aka_customer where id = v_forced_id;
    if v_customer_id is null then
      perform set_config('app.aka_customer_upsert_ctx', '', true);
      return jsonb_build_object('ok', false, 'error', 'customer_not_found', 'customer_id', v_forced_id);
    end if;
    select coalesce(merged_into_customer_id, id) into v_customer_id from aka_customer where id = v_forced_id;
    v_matched_by := 'customer_id';
  end if;
  if v_phone is not null then
    select coalesce(merged_into_customer_id, id) into v_by_phone from aka_customer
    where normalize_phone(phone) = v_phone
    order by case when coalesce(record_state, 'active') = 'merged' then 1 else 0 end,
             case when account_id = v_account_id then 0 else 1 end, created_at desc nulls last, id desc limit 1;
  end if;
  if v_uid is not null then
    select coalesce(merged_into_customer_id, id) into v_by_uid from aka_customer
    where nullif(btrim(zalo_referral_id), '') is not null and account_id = v_account_id and lower(btrim(zalo_referral_id)) = lower(v_uid)
    order by case when coalesce(record_state, 'active') = 'merged' then 1 else 0 end, id desc limit 1;
    if v_by_uid is null then -- dữ liệu cũ: uid nằm ở cột zalo dạng pzl_u_... / số
      select coalesce(merged_into_customer_id, id) into v_by_uid from aka_customer
      where account_id = v_account_id and zalo ~ '^(pzl_u_[0-9]+_[0-9]+|[0-9]{15,})$'
        and lower(fn_zalo_referral_canonical_uid_v1(zalo)) = lower(v_uid)
      order by case when coalesce(record_state, 'active') = 'merged' then 1 else 0 end, id desc limit 1;
    end if;
  end if;
  if v_url is not null then
    select coalesce(merged_into_customer_id, id) into v_by_url from aka_customer
    where nullif(btrim(pancake_url), '') is not null and lower(btrim(pancake_url)) = lower(v_url)
    order by case when coalesce(record_state, 'active') = 'merged' then 1 else 0 end, id desc limit 1;
    if v_by_url is null then
      select coalesce(merged_into_customer_id, id) into v_by_url from aka_customer
      where custom_fields ? 'pancake_urls' and custom_fields -> 'pancake_urls' ? v_url
      order by id desc limit 1;
    end if;
  end if;

  -- ---------- chọn hồ sơ chính + ghi nhận xung đột ----------
  if v_customer_id is null then
    v_customer_id := coalesce(v_by_phone, v_by_uid, v_by_url);
    v_matched_by := case when v_by_phone is not null then 'phone' when v_by_uid is not null then 'zalo_uid' when v_by_url is not null then 'pancake_url' end;
  end if;
  if v_customer_id is not null then
    if v_by_phone is not null and v_by_phone <> v_customer_id then
      v_conflicts := v_conflicts || jsonb_build_object('key', 'phone', 'value', v_phone, 'other_customer_id', v_by_phone); v_attach_phone := false;
    end if;
    if v_by_uid is not null and v_by_uid <> v_customer_id then
      v_conflicts := v_conflicts || jsonb_build_object('key', 'zalo_uid', 'value', v_uid, 'other_customer_id', v_by_uid); v_attach_uid := false;
    end if;
    if v_by_url is not null and v_by_url <> v_customer_id then
      v_conflicts := v_conflicts || jsonb_build_object('key', 'pancake_url', 'value', v_url, 'other_customer_id', v_by_url); v_attach_url := false;
    end if;
  end if;

  -- ---------- owner ----------
  if v_customer_id is not null then
    select os.id, os.organization_id into v_owner_id, v_org_id
    from aka_customer c join org_staff os on os.id = c.org_staff_id_owner
    where c.id = v_customer_id and os.is_active = true;
    if v_owner_id is not null then v_owner_source := 'existing_owner'; end if;
  end if;
  if v_owner_id is null and nullif(p ->> 'org_staff_id', '') is not null then
    select id, organization_id into v_owner_id, v_org_id from org_staff where id = (p ->> 'org_staff_id')::bigint and is_active = true;
    if v_owner_id is not null then v_owner_source := 'request_org_staff_id'; end if;
  end if;
  if v_owner_id is null and v_customer_id is not null then
    select os.id, os.organization_id into v_owner_id, v_org_id
    from aka_customer c join org_staff os on os.chat_staff_id = c.staff_id
    where c.id = v_customer_id and c.staff_id is not null and os.is_active = true order by os.id limit 1;
    if v_owner_id is not null then v_owner_source := 'existing_staff_id'; end if;
  end if;
  if v_owner_id is null and v_chat_staff is not null then
    select id, organization_id into v_owner_id, v_org_id from org_staff where chat_staff_id = v_chat_staff and is_active = true order by id limit 1;
    if v_owner_id is not null then v_owner_source := 'request_chat_staff_id'; end if;
  end if;
  if v_owner_id is null and nullif(p ->> 'conversation_id', '') is not null then
    select os.id, os.organization_id into v_owner_id, v_org_id
    from message_gom g2 join org_staff os on os.id = g2.answer_org_staff_id
    where g2.conversation_id = p ->> 'conversation_id'
      and (nullif(p ->> 'shop_id', '') is null or g2.shop_id = p ->> 'shop_id')
      and g2.answer_org_staff_id is not null and os.is_active = true
    order by coalesce(g2.answer_first_at, g2.created_at) desc limit 1;
    if v_owner_id is null then
      select os.id, os.organization_id into v_owner_id, v_org_id
      from message_gom g2 join org_staff os on os.chat_staff_id = g2.staff_id
      where g2.conversation_id = p ->> 'conversation_id'
        and (nullif(p ->> 'shop_id', '') is null or g2.shop_id = p ->> 'shop_id')
        and g2.staff_id is not null and os.is_active = true
      order by g2.created_at desc, os.id limit 1;
    end if;
    if v_owner_id is not null then v_owner_source := 'conversation_staff'; end if;
  end if;
  if v_owner_id is null and v_contact_id is not null then
    select os.id, os.organization_id into v_owner_id, v_org_id
    from contacts c cross join lateral unnest(coalesce(c.staff_ids, array[]::text[])) sid(value)
    join org_staff os on os.chat_staff_id::text = sid.value
    where c.id = v_contact_id and os.is_active = true order by os.id limit 1;
    if v_owner_id is not null then v_owner_source := 'contact_staff'; end if;
  end if;
  if v_owner_id is null and v_use_rules then
    -- port từ insert_aka_customer.resolveOwnerFromRules: ứng viên = rule active (org 1) có keyword khớp (hoặc không giới hạn),
    -- sắp theo lần được chia gần nhất (cũ trước); chọn người đầu tiên còn chỗ (max_contact_in_day), tất cả đầy -> người đầu tiên
    v_keyword := coalesce(nullif(btrim(coalesce(p ->> 'akabiz_keyword', '')), ''), nullif(btrim(coalesce(p ->> 'form_title', '')), ''), 'data');
    select coalesce(bool_and(x.max_contact_in_day is not null and x.cnt >= x.max_contact_in_day), false) into v_all_full
    from (
      select rr.org_staff_id, rr.max_contact_in_day,
        (select count(*) from aka_customer c where c.org_staff_id_owner = rr.org_staff_id and c.is_split_exempt is not true
           and c.is_sql_akabiz2 is not true and c.sql_sync_at is null
           and nullif(btrim(c.akabiz_keyword), '') is not null /* split_counter_lead_form_only_v1 */ and c.created_at <= v_now
           and c.created_at >= (v_today_vn::timestamp at time zone 'Asia/Ho_Chi_Minh')) cnt
      from aka_data_split_rules rr join org_staff os on os.id = rr.org_staff_id and os.is_active = true
      where rr.organization_id = 1 and rr.is_active = true
        and (rr.keywords is null or cardinality(rr.keywords) = 0 or v_keyword = any(rr.keywords))
    ) x;
    for r in
      select rr.org_staff_id, rr.max_contact_in_day, os.organization_id,
        (select count(*) from aka_customer c where c.org_staff_id_owner = rr.org_staff_id and c.is_split_exempt is not true
           and c.is_sql_akabiz2 is not true and c.sql_sync_at is null
           and nullif(btrim(c.akabiz_keyword), '') is not null /* split_counter_lead_form_only_v1 */ and c.created_at <= v_now
           and c.created_at >= (v_today_vn::timestamp at time zone 'Asia/Ho_Chi_Minh')) cnt,
        (select max(c.created_at) from aka_customer c where c.org_staff_id_owner = rr.org_staff_id and c.is_split_exempt is not true
           and c.is_sql_akabiz2 is not true and c.sql_sync_at is null
           and nullif(btrim(c.akabiz_keyword), '') is not null /* split_counter_lead_form_only_v1 */ and c.created_at <= v_now) last_at
      from aka_data_split_rules rr join org_staff os on os.id = rr.org_staff_id and os.is_active = true
      where rr.organization_id = 1 and rr.is_active = true
        and (rr.keywords is null or cardinality(rr.keywords) = 0 or v_keyword = any(rr.keywords))
      order by last_at asc nulls first, rr.org_staff_id
    loop
      if v_all_full or r.max_contact_in_day is null or r.cnt < r.max_contact_in_day then
        v_owner_id := r.org_staff_id; v_org_id := r.organization_id;
        v_owner_source := case when v_all_full then 'split_rule_all_full:' else 'split_rule:' end || v_keyword;
        exit;
      end if;
    end loop;
  end if;
  if v_owner_id is null and nullif(p ->> 'shop_id_2', '') is not null then
    select os.id, os.organization_id into v_owner_id, v_org_id
    from shops s join org_staff os on os.id = s.manager_org_staff_id
    where os.is_active = true and s.id = (p ->> 'shop_id_2')::uuid limit 1;
    if v_owner_id is not null then v_owner_source := 'shop_manager'; end if;
  end if;
  if v_owner_id is null then
    select os.id, os.organization_id into v_owner_id, v_org_id
    from org_staff os where os.is_active = true and os.is_data_division = true
    order by (select count(*) from aka_customer owned where owned.org_staff_id_owner = os.id
              and owned.created_at >= (v_today_vn::timestamp at time zone 'Asia/Ho_Chi_Minh')), os.id
    limit 1;
    if v_owner_id is not null then v_owner_source := 'data_division_least_loaded'; end if;
  end if;

  -- ---------- INSERT ----------
  if v_customer_id is null then
    begin
      insert into aka_customer (
        name, name_zalo, phone, zalo, zalo_referral_id, pancake_url, email, city, inbox_url, ref_url, ip_address,
        device_type, browser, form_title, os, product, akabiz_keyword, channel, account_id,
        status, countupdate, countupdate_today, last_update_date,
        industry_status_id, source_status_id, is_referred, referrer_id, referrer_phone, referrer_pancake_url,
        org_staff_id_owner, org_staff_create_id, org_staff_update_id, is_split_exempt, custom_fields
      ) values (
        case when coalesce((p->>'preserve_unknown_name')::boolean,false) then v_name else coalesce(v_name, v_phone, case when v_uid is not null then 'Liên hệ Zalo ' || right(v_uid, 6) end, 'Khách hàng') end,
        coalesce(nullif(btrim(p ->> 'name_zalo'), ''), v_name),
        v_phone, coalesce(v_phone, v_uid_raw), v_uid, v_url,
        nullif(btrim(coalesce(p ->> 'email', '')), ''), nullif(btrim(coalesce(p ->> 'city', '')), ''),
        nullif(btrim(coalesce(p ->> 'inbox_url', '')), ''), nullif(btrim(coalesce(p ->> 'ref_url', '')), ''),
        nullif(btrim(coalesce(p ->> 'ip_address', '')), ''), nullif(btrim(coalesce(p ->> 'device_type', '')), ''),
        nullif(btrim(coalesce(p ->> 'browser', '')), ''), nullif(btrim(coalesce(p ->> 'form_title', '')), ''),
        nullif(btrim(coalesce(p ->> 'os', '')), ''), nullif(btrim(coalesce(p ->> 'product', '')), ''),
        nullif(btrim(coalesce(p ->> 'akabiz_keyword', '')), ''), v_channel, v_account_id,
        coalesce(nullif(p ->> 'status', ''), 'new'), 0, 0, v_today_vn,
        v_industry_id, v_source_id, v_is_referred, v_referrer_id, v_referrer_phone, v_referrer_url,
        v_owner_id, v_owner_id, v_owner_id, v_split_exempt,
        jsonb_strip_nulls(v_custom || jsonb_build_object('creation_path', coalesce(v_creation_path, v_custom ->> 'creation_path'), 'created_via', 'fn_upsert_aka_customer_v1'))
      ) returning id into v_customer_id;
      v_is_new := true; v_matched_by := 'inserted';
    exception when unique_violation then
      -- race: luồng khác vừa tạo -> tìm lại rồi đi nhánh cập nhật
      select coalesce(merged_into_customer_id, id) into v_customer_id from aka_customer
      where (v_phone is not null and normalize_phone(phone) = v_phone)
         or (v_uid is not null and nullif(btrim(zalo_referral_id), '') is not null and account_id = v_account_id and lower(btrim(zalo_referral_id)) = lower(v_uid))
         or (v_url is not null and nullif(btrim(pancake_url), '') is not null and lower(btrim(pancake_url)) = lower(v_url))
      order by id desc limit 1;
      if v_customer_id is null then raise; end if;
      v_matched_by := 'race_refetch';
      v_conflicts := v_conflicts || jsonb_build_object('key', 'race', 'other_customer_id', v_customer_id);
    end;
    if v_referrer_id is not null and v_is_new then
      update aka_customer set referral_count = coalesce(referral_count, 0) + 1, updated_at = v_now where id = v_referrer_id and id <> v_customer_id;
    end if;
  end if;

  -- ---------- UPDATE (bổ sung) ----------
  if not v_is_new then
    select * into v_row from aka_customer where id = v_customer_id for update;

    if v_touch_return then
      v_days_away := greatest(0, (v_today_vn - (coalesce(v_row.return_date, v_row.created_at) at time zone 'Asia/Ho_Chi_Minh')::date));
      v_return_note := case when v_days_away = 0 then 'Khách hàng quay trở lại trong ngày' else 'Khách hàng quay trở lại sau ' || v_days_away || ' ngày' end;
    end if;

    begin
      update aka_customer c set
        phone = case when v_attach_phone and v_phone is not null and nullif(btrim(c.phone), '') is null then v_phone else c.phone end,
        zalo_referral_id = case when v_attach_uid and v_uid is not null and nullif(btrim(c.zalo_referral_id), '') is null then v_uid else c.zalo_referral_id end,
        pancake_url = case when v_attach_url and v_url is not null and nullif(btrim(c.pancake_url), '') is null then v_url else c.pancake_url end,
        zalo = coalesce(nullif(btrim(c.zalo), ''), v_phone, v_uid_raw),
        name = case when coalesce((p->>'preserve_unknown_name')::boolean,false) and v_name is null and (normalize_phone(c.name)=normalize_phone(c.phone) or c.name ~ '^Liên hệ Zalo ' or c.name='Khách hàng') then null when v_name is not null and (v_overwrite or nullif(btrim(c.name), '') is null
                      or normalize_phone(c.name) = normalize_phone(c.phone) or c.name ~ '^Liên hệ Zalo ' or c.name = 'Khách hàng') then v_name else c.name end,
        name_zalo = coalesce(nullif(btrim(c.name_zalo), ''), nullif(btrim(p ->> 'name_zalo'), ''), v_name),
        email = case when v_overwrite then coalesce(nullif(btrim(p ->> 'email'), ''), c.email) else coalesce(nullif(btrim(c.email), ''), nullif(btrim(p ->> 'email'), '')) end,
        city = case when v_overwrite then coalesce(nullif(btrim(p ->> 'city'), ''), c.city) else coalesce(nullif(btrim(c.city), ''), nullif(btrim(p ->> 'city'), '')) end,
        inbox_url = case when v_overwrite then coalesce(nullif(btrim(p ->> 'inbox_url'), ''), c.inbox_url) else coalesce(nullif(btrim(c.inbox_url), ''), nullif(btrim(p ->> 'inbox_url'), '')) end,
        ref_url = case when v_overwrite then coalesce(nullif(btrim(p ->> 'ref_url'), ''), c.ref_url) else coalesce(nullif(btrim(c.ref_url), ''), nullif(btrim(p ->> 'ref_url'), '')) end,
        ip_address = case when v_overwrite then coalesce(nullif(btrim(p ->> 'ip_address'), ''), c.ip_address) else coalesce(nullif(btrim(c.ip_address), ''), nullif(btrim(p ->> 'ip_address'), '')) end,
        device_type = case when v_overwrite then coalesce(nullif(btrim(p ->> 'device_type'), ''), c.device_type) else coalesce(nullif(btrim(c.device_type), ''), nullif(btrim(p ->> 'device_type'), '')) end,
        browser = case when v_overwrite then coalesce(nullif(btrim(p ->> 'browser'), ''), c.browser) else coalesce(nullif(btrim(c.browser), ''), nullif(btrim(p ->> 'browser'), '')) end,
        form_title = case when v_overwrite then coalesce(nullif(btrim(p ->> 'form_title'), ''), c.form_title) else coalesce(nullif(btrim(c.form_title), ''), nullif(btrim(p ->> 'form_title'), '')) end,
        os = case when v_overwrite then coalesce(nullif(btrim(p ->> 'os'), ''), c.os) else coalesce(nullif(btrim(c.os), ''), nullif(btrim(p ->> 'os'), '')) end,
        product = case when v_overwrite then coalesce(nullif(btrim(p ->> 'product'), ''), c.product) else coalesce(nullif(btrim(c.product), ''), nullif(btrim(p ->> 'product'), '')) end,
        akabiz_keyword = case when v_overwrite then coalesce(nullif(btrim(p ->> 'akabiz_keyword'), ''), c.akabiz_keyword) else coalesce(nullif(btrim(c.akabiz_keyword), ''), nullif(btrim(p ->> 'akabiz_keyword'), '')) end,
        channel = case when v_overwrite then coalesce(v_channel, c.channel) else coalesce(nullif(btrim(c.channel), ''), v_channel) end,
        account_id = coalesce(c.account_id, v_account_id),
        industry_status_id = coalesce(c.industry_status_id, v_industry_id),
        source_status_id = coalesce(c.source_status_id, v_source_id),
        is_referred = coalesce(c.is_referred, false) or (v_is_referred and c.referrer_id is null and nullif(btrim(c.referrer_phone), '') is null),
        referrer_id = coalesce(c.referrer_id, case when c.referrer_id is null and nullif(btrim(c.referrer_phone), '') is null and v_referrer_id <> c.id then v_referrer_id end),
        referrer_phone = coalesce(nullif(btrim(c.referrer_phone), ''), case when c.referrer_id is null then v_referrer_phone end),
        referrer_pancake_url = coalesce(nullif(btrim(c.referrer_pancake_url), ''), v_referrer_url),
        org_staff_id_owner = coalesce(c.org_staff_id_owner, v_owner_id),
        org_staff_create_id = coalesce(c.org_staff_create_id, v_owner_id),
        org_staff_update_id = coalesce(v_owner_id, c.org_staff_update_id),
        custom_fields = coalesce(c.custom_fields, '{}'::jsonb)
          || jsonb_strip_nulls(v_custom)
          || case when v_url is not null and nullif(btrim(c.pancake_url), '') is not null and lower(btrim(c.pancake_url)) <> lower(v_url) and v_attach_url
                  then jsonb_build_object('pancake_urls', (
                         select jsonb_agg(distinct x) from jsonb_array_elements_text(coalesce(c.custom_fields -> 'pancake_urls', '[]'::jsonb) || to_jsonb(array[v_url])) x))
                  else '{}'::jsonb end
          || case when v_creation_path is not null and c.custom_fields ->> 'creation_path' is null then jsonb_build_object('creation_path', v_creation_path) else '{}'::jsonb end
          || jsonb_build_object('last_upsert_at', v_now, 'last_upsert_path', coalesce(v_creation_path, v_channel)),
        countupdate = case when v_touch_return then coalesce(c.countupdate, 0) + 1 else c.countupdate end,
        countupdate_today = case when v_touch_return then (case when c.last_update_date = v_today_vn then coalesce(c.countupdate_today, 0) + 1 else 1 end) else c.countupdate_today end,
        last_update_date = case when v_touch_return then v_today_vn else c.last_update_date end,
        return_date = case when v_touch_return then v_now else c.return_date end,
        split_note = case when v_touch_return then v_return_note else c.split_note end,
        updated_at = v_now
      where c.id = v_customer_id
      returning
        array_remove(array[
          case when phone is distinct from v_row.phone then 'phone' end,
          case when zalo_referral_id is distinct from v_row.zalo_referral_id then 'zalo_referral_id' end,
          case when pancake_url is distinct from v_row.pancake_url then 'pancake_url' end,
          case when name is distinct from v_row.name then 'name' end,
          case when email is distinct from v_row.email then 'email' end,
          case when org_staff_id_owner is distinct from v_row.org_staff_id_owner then 'org_staff_id_owner' end,
          case when is_referred is distinct from v_row.is_referred then 'is_referred' end,
          case when source_status_id is distinct from v_row.source_status_id then 'source_status_id' end
        ], null) into v_updated;
    exception when unique_violation then
      -- khóa mới đã thuộc khách khác (chưa lock kịp) -> không đè, ghi xung đột, giữ hồ sơ như cũ
      v_conflicts := v_conflicts || jsonb_build_object('key', 'unique_violation', 'detail', left(sqlerrm, 200));
      update aka_customer c set updated_at = v_now,
        custom_fields = coalesce(c.custom_fields, '{}'::jsonb) || jsonb_build_object('last_upsert_conflict', jsonb_build_object('at', v_now, 'phone', v_phone, 'zalo_uid', v_uid, 'pancake_url', v_url))
      where c.id = v_customer_id;
    end;
    if 'is_referred' = any(v_updated) and v_referrer_id is not null then
      update aka_customer set referral_count = coalesce(referral_count, 0) + 1, updated_at = v_now where id = v_referrer_id and id <> v_customer_id;
    end if;
  end if;

  -- ---------- gắn contact -> customer ----------
  if v_contact_id is not null then
    update contacts set customer_id = v_customer_id where id = v_contact_id and customer_id is null;
  end if;

  perform set_config('app.aka_customer_upsert_ctx', '', true);

  select * into v_row from aka_customer where id = v_customer_id;

  -- ---------- (tuỳ chọn) tạo CRM: is_create_crm + crm_type_id -> gọi nối HÀM CHUNG fn_create_aka_crm_v1 ----------
  -- Lỗi tạo CRM KHÔNG làm hỏng việc tạo/cập nhật khách: kết quả nằm ở khóa 'crm' của output.
  if coalesce((p ->> 'is_create_crm')::boolean, false) then
    v_crm_type := nullif(p ->> 'crm_type_id', '')::bigint;
    if nullif(p ->> 'crm_type_id_returning', '') is not null and not v_is_new then
      -- khách đã có: quay lại sau ≥1 ngày -> loại "khách trở lại"; quay lại trong ngày -> không tạo (đúng logic web form cũ)
      v_crm_type := case when v_days_away > 0 then (p ->> 'crm_type_id_returning')::bigint else null end;
    end if;
    if v_crm_type is null then
      v_crm := jsonb_build_object('ok', true, 'created', false, 'skipped', true,
        'skip_reason', case when nullif(p ->> 'crm_type_id', '') is null then 'crm_type_required' else 'returning_same_day' end);
    else
      begin
        v_crm := fn_create_aka_crm_v1(jsonb_strip_nulls(jsonb_build_object(
          'customer_id', v_customer_id, 'crm_type_id', v_crm_type,
          'org_staff_owner_id', (select os.id from org_staff os where os.id = v_row.org_staff_id_owner and os.is_active = true),
          'organization_id', v_org_id,
          'customer_name', v_row.name,
          'note', coalesce(nullif(btrim(coalesce(p ->> 'crm_note', '')), ''), case when v_is_new then 'Khách hàng mới' else v_return_note end),
          'suggested_channel_id', nullif(p ->> 'crm_suggested_channel_id', ''),
          'suggested_content', nullif(btrim(coalesce(p ->> 'crm_suggested_content', '')), ''),
          'priority', nullif(p ->> 'crm_priority', ''),
          'source_type', nullif(btrim(coalesce(p ->> 'crm_source_type', '')), ''),
          'source_order_id', nullif(p ->> 'crm_source_order_id', ''),
          'gen_agent', nullif(btrim(coalesce(p ->> 'crm_gen_agent', '')), ''),
          'gen_meta', case when jsonb_typeof(p -> 'crm_gen_meta') = 'object' then p -> 'crm_gen_meta' end,
          'lead_id', nullif(p ->> 'crm_lead_id', ''),
          'pancake_url', coalesce(nullif(btrim(coalesce(p ->> 'crm_pancake_url', '')), ''), v_row.pancake_url),
          'allow_same_day', (p ->> 'crm_allow_same_day')::boolean,
          'notify_lark', (p ->> 'crm_notify_lark')::boolean
        )));
      exception when others then
        v_crm := jsonb_build_object('ok', false, 'error', 'crm_exception', 'sqlstate', sqlstate, 'detail', left(sqlerrm, 300));
      end;
    end if;
  end if;

  v_result := jsonb_build_object(
    'ok', true, 'customer_id', v_customer_id, 'is_new', v_is_new, 'matched_by', v_matched_by,
    'name', v_row.name, 'phone', v_row.phone, 'zalo_uid', v_row.zalo_referral_id, 'pancake_url', v_row.pancake_url,
    'org_staff_owner_id', v_row.org_staff_id_owner, 'organization_id', v_org_id, 'owner_source', v_owner_source,
    'updated_fields', to_jsonb(coalesce(v_updated, array[]::text[])), 'conflicts', v_conflicts,
    'days_away', v_days_away, 'backend_ctx', v_backend_ctx, 'crm', v_crm);
  return v_result;
exception when others then
  perform set_config('app.aka_customer_upsert_ctx', '', true);
  raise;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_validate_content_type_ids()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE invalid_ids bigint[];
BEGIN
  IF NEW.content_type_ids IS NULL OR array_length(NEW.content_type_ids, 1) IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT array_agg(x) INTO invalid_ids
  FROM unnest(NEW.content_type_ids) AS x
  WHERE NOT EXISTS (
    SELECT 1 FROM public.aka_crm_status s
    WHERE s.id = x AND s.type = 'content_type'
  );
  IF invalid_ids IS NOT NULL THEN
    RAISE EXCEPTION 'content_type_ids chứa id không hợp lệ (không thuộc content_type): %', invalid_ids;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_zalo_chat_referral_claim_v1(p_message_id uuid, p_evidence_hash text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_claimed uuid;
  v_claim_token uuid := pg_catalog.gen_random_uuid();
  v_current jsonb;
begin
  if current_user not in ('postgres', 'service_role') then
    raise exception using errcode = '42501', message = 'zalo_referral_backend_only';
  end if;
  if coalesce(p_evidence_hash, '') !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023', message = 'invalid_zalo_referral_evidence_hash';
  end if;

  perform 1
  from public.message_gom
  where id = p_message_id
  for update;
  if not found then
    return null;
  end if;

  v_current := public.fn_zalo_chat_referral_evidence_v1(p_message_id);
  if (v_current ->> 'evidence_hash') is distinct from p_evidence_hash then
    return null;
  end if;

  update public.message_gom g
  set zalo_referral_evidence_hash = p_evidence_hash,
      zalo_referral_claim_token = v_claim_token,
      zalo_referral_processing_until = now() + interval '6 minutes',
      zalo_referral_attempt_count = case
        when g.zalo_referral_evidence_hash is distinct from p_evidence_hash then 1
        else coalesce(g.zalo_referral_attempt_count, 0) + 1
      end,
      zalo_referral_last_status = 'processing',
      zalo_referral_processed_at = null
  where g.id = p_message_id
    and g.zalo_referral_enqueued_at is not null
    and public.fn_zalo_chat_referral_message_eligible_v1(g.id)
    and (g.zalo_referral_processing_until is null
         or g.zalo_referral_processing_until < now())
    and (
      g.zalo_referral_evidence_hash is distinct from p_evidence_hash
      or (
        g.zalo_referral_processed_at is null
        and (
          coalesce(g.zalo_referral_attempt_count, 0) < 3
          or (
            coalesce(g.zalo_referral_attempt_count, 0) < 4
            and
            g.zalo_referral_last_status = 'processing'
            and (
              exists (
                select 1
                from public.aka_crm c
                where c.source_type like 'zalo_referral:%'
                  and c.source_type = 'zalo_referral:' || g.id::text
              )
              or exists (
                select 1
                from public.ai_log l
                where l.using_code = 'zalo_chat_referral_verify_v1'
                  and l.block_name = 'zalo-chat-referral-precreate-v1'
                  and l.node_id = 'zalo-referral:' || g.id::text
                  and l.status = 'success'
                  and l.sanitized_request ->> 'evidence_hash' = p_evidence_hash
              )
            )
          )
        )
      )
    )
  returning g.id into v_claimed;

  return case when v_claimed is not null then v_claim_token end;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_zalo_chat_referral_create_crm_v2(p_message_id uuid, p_route text, p_evidence_hash text, p_claim_token uuid, p_target_phone text DEFAULT NULL::text, p_ai_log_id bigint DEFAULT NULL::bigint, p_finalize boolean DEFAULT true, p_create_crm boolean DEFAULT true, p_owner_mode text DEFAULT 'default'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_gom public.message_gom%rowtype;
  v_card jsonb;
  v_info jsonb;
  v_evidence jsonb;
  v_phones text[];
  v_phone_idx integer;
  v_raw_reference_count integer := 0;
  v_raw_locked_count integer := 0;
  v_evidence_hash text;
  v_ai public.ai_log%rowtype;
  v_verdict jsonb;
  v_existing_crm public.aka_crm%rowtype;
  v_upsert_res jsonb;
  v_route text := lower(btrim(coalesce(p_route, '')));
  v_account_id integer;
  v_target_phone text;
  v_target_uid text;
  v_target_name text;
  v_ai_kind text;
  v_ai_confidence numeric;
  v_referred_by_name text;
  v_mention_customer_id bigint;
  v_mention_count integer;
  v_self_phone boolean := false;
  v_phone_customer_id bigint;
  v_uid_customer_id bigint;
  v_customer_id bigint;
  v_customer_is_new boolean := false;
  v_referrer_customer_id bigint;
  v_referrer_name text;
  v_referrer_uid text;
  v_referrer_phone text;
  v_referrer_current_phone text;
  v_pancake_url text;
  v_owner_id bigint;
  v_organization_id bigint;
  v_owner_name text;
  v_customer_owner_id bigint;
  v_customer_organization_id bigint;
  v_customer_owner_name text;
  v_customer_name text;
  v_customer_phone text;
  v_existing_target_phone_raw text;
  v_existing_target_phone text;
  v_existing_target_uid text;
  v_existing_pancake_url text;
  v_crm_type_id bigint;
  v_priority integer;
  v_crm_type_name text;
  v_note text;
  v_source_type text;
  v_due timestamptz;
  v_crm_id bigint;
  v_lead_id bigint;
  v_recent_crm_id bigint;
  v_finalized uuid;
  v_created boolean := false;
  v_is_referral boolean := false;
  v_manual_handled boolean := false;
  v_cust_created_at timestamptz;
  v_cust_path text;
  v_last_staff_id bigint;
  v_last_staff_org bigint;
  v_last_staff_name text;
  v_lead_created boolean := false;
  v_contact_customer_id bigint;
  v_contact_phone text;
  v_contact_name text;
  v_ref_candidate bigint;
  v_cid bigint;
  v_cid_phone text;
  v_cid_uid text;
  v_m record;
  v_card_guid text;
  v_card_cf jsonb := '{}'::jsonb;
begin
  if current_user not in ('postgres', 'service_role') then
    raise exception using errcode = '42501', message = 'zalo_referral_backend_only';
  end if;
  if v_route not in ('zalo_contact', 'phone_intent') then
    raise exception using errcode = '22023', message = 'invalid_zalo_referral_route';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('zalo-referral-message:' || p_message_id::text, 0));

  select * into v_gom from public.message_gom where id = p_message_id for update;
  if not found
     or upper(coalesce(v_gom.initiated_by, '')) <> 'CUSTOMER'
     or lower(btrim(coalesce(v_gom.source, ''))) <> 'pancake'
     or not public.fn_zalo_chat_referral_message_eligible_v1(p_message_id) then
    raise exception using errcode = '22023', message = 'invalid_customer_message';
  end if;

  if p_claim_token is null
     or v_gom.zalo_referral_claim_token is distinct from p_claim_token
     or v_gom.zalo_referral_evidence_hash is distinct from p_evidence_hash
     or v_gom.zalo_referral_last_status is distinct from 'processing'
     or v_gom.zalo_referral_processing_until is null
     or v_gom.zalo_referral_processing_until <= now() then
    raise exception using errcode = '55000', message = 'zalo_referral_processing_lease_invalid';
  end if;

  v_account_id := coalesce(v_gom.account_id, 1001);

  select count(*) into v_raw_reference_count
  from (
    select distinct case when q.raw_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then q.raw_id::uuid end as id
    from jsonb_array_elements_text(case when jsonb_typeof(v_gom.question_message_ids) = 'array' then v_gom.question_message_ids else '[]'::jsonb end) q(raw_id)
  ) refs where refs.id is not null;

  perform m.id
  from public.messages m
  join (
    select distinct case when q.raw_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then q.raw_id::uuid end as id
    from jsonb_array_elements_text(case when jsonb_typeof(v_gom.question_message_ids) = 'array' then v_gom.question_message_ids else '[]'::jsonb end) q(raw_id)
  ) refs on refs.id = m.id
  where refs.id is not null
  order by m.id
  for share of m;
  get diagnostics v_raw_locked_count = row_count;
  if v_raw_locked_count <> v_raw_reference_count then
    raise exception using errcode = '23503', message = 'zalo_referral_raw_message_missing';
  end if;

  v_evidence := public.fn_zalo_chat_referral_evidence_v1(p_message_id);
  v_evidence_hash := nullif(v_evidence ->> 'evidence_hash', '');
  if v_evidence is null
     or (v_evidence ->> 'route') is distinct from v_route
     or v_evidence_hash is null
     or v_evidence_hash is distinct from p_evidence_hash
     or v_evidence_hash !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023', message = 'zalo_referral_evidence_changed';
  end if;
  v_card := v_evidence -> 'card';
  select coalesce(array_agg(x), array[]::text[]) into v_phones
  from jsonb_array_elements_text(coalesce(v_evidence -> 'phones', '[]'::jsonb)) x;

  v_pancake_url := public.fn_zalo_chat_referral_pancake_url_v1(p_message_id);
  if v_pancake_url is null then
    raise exception using errcode = '22023', message = 'pancake_url_missing';
  end if;

  select coalesce(v_gom.aka_customer_id, c.customer_id),
         coalesce(nullif(btrim(v_gom.contact_name), ''), nullif(btrim(c.name), '')),
         nullif(btrim(c.phone), '')
  into v_referrer_customer_id, v_referrer_name, v_referrer_phone
  from (select 1) seed
  left join public.contacts c on c.id = v_gom.contact_id;

  v_referrer_name := left(regexp_replace(coalesce(v_referrer_name, v_card ->> 'sender_name', 'Khách hàng'), '[[:space:]]+', ' ', 'g'), 150);
  v_referrer_uid := nullif(btrim(coalesce(v_card ->> 'sender_uid', '')), '');
  if v_referrer_customer_id is not null then
    select nullif(btrim(ac.phone), '') into v_referrer_current_phone from public.aka_customer ac where ac.id = v_referrer_customer_id;
    v_referrer_phone := coalesce(v_referrer_current_phone, v_referrer_phone);
  end if;
  v_referrer_phone := public.normalize_phone(v_referrer_phone);
  if v_referrer_phone !~ '^0[1-9][0-9]{8}$' then v_referrer_phone := null; end if;

  if v_route = 'zalo_contact' then
    v_crm_type_id := 31; -- CSKH được giới thiệu qua Zalo (danh thiếp)
    v_phone_idx := 1;
    v_source_type := 'zalo_referral:' || p_message_id::text;
    if v_card is not null then
      v_target_uid := nullif(btrim(v_card ->> 'contact_uid'), '');
      v_target_phone := public.normalize_phone(v_card ->> 'phone_number');
      if v_target_phone !~ '^0[1-9][0-9]{8}$' then v_target_phone := null; end if;
      v_target_name := nullif(btrim(v_card ->> 'contact_name'), '');
      v_card_guid := nullif(btrim(v_card ->> 'guid'), '');
      v_card_cf := jsonb_strip_nulls(jsonb_build_object(
        'zalo_guid', v_card_guid,
        'zalo_card_name', v_target_name,
        'zalo_card_avatar', nullif(btrim(v_card ->> 'contact_avatar'), ''),
        'zalo_card_qr_url', nullif(btrim(v_card ->> 'qr_code_url'), ''),
        'zalo_card_message_id', nullif(btrim(v_card ->> 'raw_message_id'), ''),
        'zalo_card_source', nullif(btrim(v_card ->> 'card_source'), '')
      ));
    else
      begin v_info := coalesce(v_gom.zalo_info, '{}')::jsonb; exception when others then v_info := '{}'::jsonb; end;
      if coalesce(v_info ->> 'source', '') <> 'question_content' or coalesce(v_info ->> 'confidence', '') <> 'high' then
        raise exception using errcode = '22023', message = 'zalo_contact_evidence_missing';
      end if;
      if btrim(coalesce(v_gom.zalo_id, '')) ~ '^(0[1-9][0-9]{8}|84[1-9][0-9]{8})$' then
        v_target_phone := public.normalize_phone(v_gom.zalo_id);
      else
        v_target_uid := nullif(btrim(v_gom.zalo_id), '');
      end if;
    end if;
    if v_target_phone is null and (v_target_uid is null or v_target_uid !~ '^[[:alnum:]_.@-]{3,100}$') then
      raise exception using errcode = '22023', message = 'invalid_zalo_contact_identity';
    end if;
    -- Danh thiếp của chính người đang chat không phải giới thiệu (edge xử lý bằng fn_zalo_contact_card_self_update_v1)
    if v_target_uid is not null and v_referrer_uid is not null and lower(v_target_uid) = lower(v_referrer_uid) then
      raise exception using errcode = '22023', message = 'zalo_contact_self_card';
    end if;

    -- AI gate bắt buộc (fail-closed): phán quyết danh thiếp trong ai_log
    if p_ai_log_id is null then
      raise exception using errcode = '22023', message = 'verified_ai_log_required';
    end if;
    select * into v_ai from public.ai_log
    where id = p_ai_log_id
      and using_code = 'zalo_chat_referral_verify_v1'
      and block_name = 'zalo-chat-referral-precreate-v1'
      and node_id = 'zalo-referral:' || p_message_id::text
      and status = 'success';
    if not found
       or (v_ai.sanitized_request ->> 'message_id') is distinct from p_message_id::text
       or (v_ai.sanitized_request ->> 'route') is distinct from 'zalo_contact'
       or (v_ai.sanitized_request ->> 'message_sha256') is distinct from encode(extensions.digest(coalesce(v_gom.question_content, ''), 'sha256'), 'hex')
       or (v_ai.sanitized_request ->> 'evidence_hash') is distinct from v_evidence_hash then
      raise exception using errcode = '22023', message = 'ai_verdict_not_approved';
    end if;
    v_verdict := v_ai.sanitized_response -> 'card_verdict';
    if v_verdict is null
       or jsonb_typeof(v_verdict) <> 'object'
       or coalesce(v_verdict ->> 'kind', '') <> 'REFERRAL_OTHER'
       or jsonb_typeof(v_verdict -> 'confidence') is distinct from 'number' then
      raise exception using errcode = '22023', message = 'ai_verdict_not_approved';
    end if;
    v_ai_kind := 'REFERRAL_OTHER';
    v_ai_confidence := (v_verdict ->> 'confidence')::numeric;
    if v_ai_confidence < 0.80 or v_ai_confidence > 1 then
      raise exception using errcode = '22023', message = 'ai_verdict_not_approved';
    end if;
    -- Tên người được giới thiệu: tên khách gọi trong chat (AI) > tên trên danh thiếp
    v_target_name := coalesce(nullif(btrim(v_verdict ->> 'target_name'), ''), v_target_name);
    v_referred_by_name := null;
  else
    v_crm_type_id := null; -- gán theo v_ai_kind bên dưới: 31 giới thiệu / 32 khách chủ động
    v_target_phone := public.normalize_phone(p_target_phone);
    if v_target_phone is null or v_target_phone !~ '^0[1-9][0-9]{8}$' then
      raise exception using errcode = '22023', message = 'phone_not_from_current_customer_message';
    end if;
    v_phone_idx := array_position(v_phones, v_target_phone);
    if v_phone_idx is null then
      raise exception using errcode = '22023', message = 'phone_not_from_current_customer_message';
    end if;
    v_source_type := 'zalo_referral:' || p_message_id::text || case when v_phone_idx > 1 then ':p' || v_phone_idx::text else '' end;

    if p_ai_log_id is null then
      raise exception using errcode = '22023', message = 'verified_ai_log_required';
    end if;
    select * into v_ai from public.ai_log
    where id = p_ai_log_id
      and using_code = 'zalo_chat_referral_verify_v1'
      and block_name = 'zalo-chat-referral-precreate-v1'
      and node_id = 'zalo-referral:' || p_message_id::text
      and status = 'success';
    if not found
       or (v_ai.sanitized_request ->> 'message_id') is distinct from p_message_id::text
       or (v_ai.sanitized_request ->> 'message_sha256') is distinct from encode(extensions.digest(coalesce(v_gom.question_content, ''), 'sha256'), 'hex')
       or (v_ai.sanitized_request ->> 'evidence_hash') is distinct from v_evidence_hash then
      raise exception using errcode = '22023', message = 'ai_verdict_not_approved';
    end if;

    if jsonb_typeof(v_ai.sanitized_response -> 'verdicts') = 'array' then
      select v into v_verdict
      from jsonb_array_elements(v_ai.sanitized_response -> 'verdicts') v
      where v ->> 'phone_sha256' = encode(extensions.digest(v_target_phone, 'sha256'), 'hex')
      limit 1;
    elsif (v_ai.sanitized_request ->> 'phone_sha256') = encode(extensions.digest(v_target_phone, 'sha256'), 'hex') then
      v_verdict := v_ai.sanitized_response;
    end if;

    if v_verdict is null
       or jsonb_typeof(v_verdict -> 'actionable') is distinct from 'boolean'
       or (v_verdict -> 'actionable') is distinct from 'true'::jsonb
       or coalesce(v_verdict ->> 'kind', '') not in ('REFERRAL_OTHER', 'SELF_CONSULTATION')
       or jsonb_typeof(v_verdict -> 'confidence') is distinct from 'number' then
      raise exception using errcode = '22023', message = 'ai_verdict_not_approved';
    end if;
    v_ai_kind := v_verdict ->> 'kind';
    v_crm_type_id := case v_ai_kind when 'REFERRAL_OTHER' then 31 else 32 end; -- 31 CSKH được giới thiệu qua Zalo / 32 CSKH mới - về từ Zalo
    v_ai_confidence := (v_verdict ->> 'confidence')::numeric;
    if v_ai_confidence < 0.80 or v_ai_confidence > 1 then
      raise exception using errcode = '22023', message = 'ai_verdict_not_approved';
    end if;
    v_target_name := nullif(btrim(v_verdict ->> 'target_name'), '');
    v_referred_by_name := left(nullif(regexp_replace(btrim(coalesce(v_verdict ->> 'referred_by_name', '')), '[[:space:]]+', ' ', 'g'), ''), 150);
  end if;

  if v_ai_kind = 'REFERRAL_OTHER' then
    -- Người giới thiệu = tài khoản Zalo đang chat. contacts.customer_id / message_gom.aka_customer_id có thể đang trỏ
    -- tới hồ sơ của chính SĐT/uid được giới thiệu (NV gắn tay / worker khớp theo SĐT trong tin) -> loại các hồ sơ đó.
    select c.customer_id, nullif(btrim(c.phone), ''), nullif(btrim(c.name), '')
    into v_contact_customer_id, v_contact_phone, v_contact_name
    from public.contacts c where c.id = v_gom.contact_id;
    v_ref_candidate := null;
    foreach v_cid in array array_remove(array[v_contact_customer_id, v_gom.aka_customer_id], null) loop
      select public.normalize_phone(ac.phone), nullif(btrim(ac.zalo_referral_id), '') into v_cid_phone, v_cid_uid from public.aka_customer ac
      where ac.id = v_cid and coalesce(ac.record_state, 'active') <> 'merged';
      if found
         and (v_cid_phone is null or not (v_cid_phone = any(v_phones)))
         and (v_target_uid is null or v_cid_uid is null or lower(v_cid_uid) <> lower(v_target_uid)) then
        v_ref_candidate := v_cid; exit;
      end if;
    end loop;
    v_referrer_customer_id := v_ref_candidate;
    -- SĐT người giới thiệu: hồ sơ người chat > contacts.phone > số NV chú thích trong tên Zalo; phải khác các SĐT trong tin
    v_referrer_phone := null;
    if v_referrer_customer_id is not null then
      select public.normalize_phone(ac.phone) into v_referrer_phone from public.aka_customer ac where ac.id = v_referrer_customer_id;
    end if;
    if v_referrer_phone is null or v_referrer_phone !~ '^0[1-9][0-9]{8}$' or v_referrer_phone = any(v_phones) then
      v_referrer_phone := null;
      for v_m in
        select public.normalize_phone(m[1]) as p
        from regexp_matches(coalesce(v_contact_phone, '') || ' ' || coalesce(v_gom.contact_name, '') || ' ' || coalesce(v_contact_name, ''),
                            '((?:\+?84|0)[0-9][0-9 .-]{7,12}[0-9])', 'g') m
      loop
        if v_m.p ~ '^0[1-9][0-9]{8}$' and not (v_m.p = any(v_phones)) then
          v_referrer_phone := v_m.p; exit;
        end if;
      end loop;
    end if;
    if v_referrer_customer_id is null and v_referrer_phone is not null then
      select id into v_referrer_customer_id from public.aka_customer
      where public.normalize_phone(phone) = v_referrer_phone and coalesce(record_state, 'active') <> 'merged'
      order by case when account_id = v_account_id then 0 else 1 end, created_at desc nulls last, id desc limit 1;
    end if;
    v_referrer_current_phone := v_referrer_phone;
    v_is_referral := v_referrer_customer_id is not null or v_referrer_phone is not null;
  elsif v_route = 'phone_intent' then
    v_is_referral := false;
  end if;

  select c.* into v_existing_crm from public.aka_crm c
  where c.source_type like 'zalo_referral:%' and c.source_type = v_source_type
  order by c.id desc limit 1;
  if found then
    if v_existing_crm.gen_agent is distinct from 'zalo-chat-referral-v1' then
      raise exception using errcode = '23505', message = 'message_already_processed_with_different_evidence';
    end if;
    -- Cùng tin đã được route khác xử lý (VD SĐT trên danh thiếp đã đi route phone trước đây) -> coi là trùng
    if (v_existing_crm.gen_meta ->> 'route') is not distinct from v_route
       and ((v_existing_crm.crm_type_id is distinct from v_crm_type_id
             and not (v_existing_crm.crm_type_id in (1, 5, 31, 32) and v_crm_type_id in (31, 32))) -- 1/5 = type cũ trước 02/09/2026; 31/32 cùng họ Zalo
            or ((v_existing_crm.gen_meta ->> 'evidence_hash') is distinct from v_evidence_hash
                and (v_target_phone is null
                     or public.normalize_phone(v_existing_crm.customer_phone) is distinct from v_target_phone))) then
      raise exception using errcode = '23505', message = 'message_already_processed_with_different_evidence';
    end if;
    v_crm_id := v_existing_crm.id;
    v_customer_id := v_existing_crm.customer_id;
    v_owner_id := v_existing_crm.org_staff_owner_id;
    v_organization_id := v_existing_crm.organization_id;
    v_due := v_existing_crm.cskh_due_date;
    v_crm_type_id := v_existing_crm.crm_type_id;
    select c.name, c.phone into v_customer_name, v_customer_phone from public.aka_customer c where c.id = v_customer_id;
    select t.stt, t.name into v_priority, v_crm_type_name from public.aka_crm_type t where t.id = v_crm_type_id;
    select os.name into v_owner_name from public.org_staff os where os.id = v_owner_id;
    if p_finalize then
      update public.message_gom g
      set zalo_referral_claim_token = null, zalo_referral_processing_until = null,
          zalo_referral_last_status = 'duplicate', zalo_referral_processed_at = now()
      where g.id = p_message_id and g.zalo_referral_evidence_hash = v_evidence_hash
        and g.zalo_referral_claim_token = p_claim_token and g.zalo_referral_last_status = 'processing'
      returning g.id into v_finalized;
      if v_finalized is null then
        raise exception using errcode = '55000', message = 'zalo_referral_atomic_finalize_failed';
      end if;
    end if;
    return jsonb_build_object('ok', true, 'created', false, 'action', 'duplicate', 'crm_id', v_crm_id,
      'customer_id', v_customer_id, 'customer_name', v_customer_name, 'customer_phone', v_customer_phone,
      'crm_type_id', v_crm_type_id, 'crm_type_name', v_crm_type_name, 'org_staff_owner_id', v_owner_id,
      'organization_id', v_organization_id, 'staff_name', v_owner_name, 'cskh_due_date', v_due,
      'route', v_route, 'pancake_url', v_existing_crm.pancake_url, 'lead_id', v_existing_crm.lead_id);
  end if;

  if v_target_phone is not null then
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('zalo-referral-phone:' || v_target_phone, 0));
    select id into v_phone_customer_id from public.aka_customer
    where public.normalize_phone(phone) = v_target_phone
      and coalesce(record_state, 'active') <> 'merged'
    order by case when account_id = v_account_id then 0 else 1 end, created_at desc nulls last, id desc
    limit 1;
  end if;
  if v_target_uid is not null then
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('zalo-referral-uid:' || v_account_id::text || ':' || lower(v_target_uid), 0));
    select id into v_uid_customer_id from public.aka_customer
    where account_id = v_account_id and lower(btrim(zalo_referral_id)) = lower(v_target_uid)
      and coalesce(record_state, 'active') <> 'merged'
    order by id desc limit 1;
    -- Người trên danh thiếp có thể đã chat với shop (contacts.uid) và đã được gắn hồ sơ
    if v_uid_customer_id is null then
      select ct.customer_id into v_uid_customer_id from public.contacts ct
      join public.aka_customer ac on ac.id = ct.customer_id
      where ct.uid = v_target_uid and ct.shop_id = v_gom.shop_id and coalesce(ct.is_group, false) = false
        and ct.customer_id is not null and coalesce(ac.record_state, 'active') <> 'merged'
      order by ct.updated_at desc nulls last, ct.id limit 1;
    end if;
  end if;
  if v_phone_customer_id is not null and v_uid_customer_id is not null and v_phone_customer_id <> v_uid_customer_id then
    raise exception using errcode = '23505', message = 'zalo_phone_uid_customer_conflict';
  end if;

  if v_route = 'phone_intent' and v_ai_kind = 'SELF_CONSULTATION' then
    if v_referrer_customer_id is null then
      -- Người chat chưa có hồ sơ: số này là của chính họ
      v_customer_id := v_phone_customer_id;
      v_self_phone := true;
    elsif v_phone_customer_id is not null and v_phone_customer_id <> v_referrer_customer_id then
      -- Số đã thuộc khách khác: coi như khách được giới thiệu bởi người đang chat (quy ước NV đang làm tay)
      v_customer_id := v_phone_customer_id;
      v_is_referral := true;
    elsif v_referrer_current_phone is not null
          and public.normalize_phone(v_referrer_current_phone) is distinct from v_target_phone then
      -- Khách đã có SĐT khác: mỗi SĐT = một tài khoản, tạo khách mới, referrer = người đang chat
      v_customer_id := null;
      v_is_referral := true;
    else
      v_customer_id := v_referrer_customer_id;
      v_self_phone := true;
    end if;

    -- Khách tự để lại số nhưng hội thoại nói rõ "biết qua X giới thiệu" -> tìm X trong hệ thống (chỉ khi khớp duy nhất)
    if v_self_phone and v_referred_by_name is not null and position(' ' in v_referred_by_name) > 0 then
      select count(distinct cid), min(cid) into v_mention_count, v_mention_customer_id
      from (
        select c.id as cid from public.aka_customer c
        where c.account_id = v_account_id and coalesce(c.record_state, 'active') <> 'merged'
          and lower(regexp_replace(btrim(c.name), '[[:space:]]+', ' ', 'g')) = lower(v_referred_by_name)
        union
        select ct.customer_id from public.contacts ct
        where ct.customer_id is not null
          and lower(regexp_replace(btrim(ct.name), '[[:space:]]+', ' ', 'g')) = lower(v_referred_by_name)
      ) x
      where cid is not null and cid is distinct from v_customer_id and cid is distinct from v_referrer_customer_id;
      if v_mention_count = 1 then
        v_referrer_customer_id := v_mention_customer_id;
        select coalesce(nullif(btrim(ac.name), ''), v_referred_by_name), public.normalize_phone(ac.phone)
        into v_referrer_name, v_referrer_phone
        from public.aka_customer ac where ac.id = v_mention_customer_id;
        if v_referrer_phone !~ '^0[1-9][0-9]{8}$' then v_referrer_phone := null; end if;
        v_is_referral := true;
      end if;
    end if;
  else
    v_customer_id := coalesce(v_phone_customer_id, v_uid_customer_id);
  end if;

  -- Số thuộc chính hồ sơ người đang chat -> không thể tự giới thiệu mình
  if v_customer_id is not null and v_customer_id = v_referrer_customer_id then
    v_is_referral := false;
    v_self_phone := true;
  end if;

  if v_customer_id is not null then
    select nullif(btrim(c.phone), ''), public.normalize_phone(c.phone), nullif(btrim(c.zalo_referral_id), '')
    into v_existing_target_phone_raw, v_existing_target_phone, v_existing_target_uid
    from public.aka_customer c where c.id = v_customer_id;
    if not found then
      raise exception using errcode = '23503', message = 'matched_customer_missing';
    end if;
    if v_target_phone is not null and v_existing_target_phone_raw is not null
       and (v_existing_target_phone is null or v_existing_target_phone is distinct from v_target_phone) then
      raise exception using errcode = '23505', message = 'customer_phone_identity_conflict_review';
    end if;
    if v_target_uid is not null and v_existing_target_uid is not null
       and lower(v_existing_target_uid) is distinct from lower(v_target_uid) then
      raise exception using errcode = '23505', message = 'customer_zalo_identity_conflict_review';
    end if;
  end if;

  if v_customer_id is not null then
    select os.id, os.organization_id, os.name into v_owner_id, v_organization_id, v_owner_name
    from public.aka_customer c join public.org_staff os on os.id = c.org_staff_id_owner
    where c.id = v_customer_id and os.is_active = true;
  end if;
  if v_owner_id is null and p_owner_mode = 'last_staff' and v_gom.conversation_id is not null then
    select os.id, os.organization_id, os.name into v_last_staff_id, v_last_staff_org, v_last_staff_name
    from public.message_gom g2 join public.org_staff os on os.id = g2.answer_org_staff_id
    where g2.conversation_id = v_gom.conversation_id and g2.shop_id is not distinct from v_gom.shop_id
      and g2.answer_org_staff_id is not null and os.is_active = true
    order by coalesce(g2.answer_first_at, g2.created_at) desc limit 1;
    if v_last_staff_id is null then
      select os.id, os.organization_id, os.name into v_last_staff_id, v_last_staff_org, v_last_staff_name
      from public.message_gom g2 join public.org_staff os on os.chat_staff_id = g2.staff_id
      where g2.conversation_id = v_gom.conversation_id and g2.shop_id is not distinct from v_gom.shop_id
        and g2.staff_id is not null and os.is_active = true
      order by g2.created_at desc, os.id limit 1;
    end if;
    if v_last_staff_id is not null then
      v_owner_id := v_last_staff_id; v_organization_id := v_last_staff_org; v_owner_name := v_last_staff_name;
    end if;
  end if;
  if v_owner_id is null and v_referrer_customer_id is not null then
    select os.id, os.organization_id, os.name into v_owner_id, v_organization_id, v_owner_name
    from public.aka_customer c join public.org_staff os on os.id = c.org_staff_id_owner
    where c.id = v_referrer_customer_id and os.is_active = true;
  end if;
  if v_owner_id is null and v_gom.answer_org_staff_id is not null then
    select id, organization_id, name into v_owner_id, v_organization_id, v_owner_name
    from public.org_staff where id = v_gom.answer_org_staff_id and is_active = true;
  end if;
  if v_owner_id is null and v_gom.staff_id is not null then
    select id, organization_id, name into v_owner_id, v_organization_id, v_owner_name
    from public.org_staff where chat_staff_id = v_gom.staff_id and is_active = true order by id limit 1;
  end if;
  if v_owner_id is null and v_gom.contact_id is not null then
    select os.id, os.organization_id, os.name into v_owner_id, v_organization_id, v_owner_name
    from public.contacts c
    cross join lateral unnest(coalesce(c.staff_ids, array[]::text[])) sid(value)
    join public.org_staff os on os.chat_staff_id::text = sid.value
    where c.id = v_gom.contact_id and os.is_active = true order by os.id limit 1;
  end if;
  if v_owner_id is null then
    select os.id, os.organization_id, os.name into v_owner_id, v_organization_id, v_owner_name
    from public.shops s join public.org_staff os on os.id = s.manager_org_staff_id
    where os.is_active = true and (
      s.id = v_gom.shop_id_2
      or (nullif(btrim(v_gom.shop_id), '') is not null and v_gom.shop_id in (s.id::text, nullif(btrim(s.profile_id), ''), nullif(btrim(s.zalo_id), ''), nullif(btrim(s.pancake_page_id), '')))
    )
    order by case when s.id = v_gom.shop_id_2 then 0 else 1 end, s.id limit 1;
  end if;
  if v_owner_id is null then
    select os.id, os.organization_id, os.name into v_owner_id, v_organization_id, v_owner_name
    from public.org_staff os
    where os.is_active = true and os.is_data_division = true
    order by (select count(*) from public.aka_customer owned
              where owned.org_staff_id_owner = os.id
                and owned.created_at >= date_trunc('day', now() at time zone 'Asia/Ho_Chi_Minh') at time zone 'Asia/Ho_Chi_Minh'), os.id
    limit 1;
  end if;
  if v_owner_id is null or v_organization_id is null then
    raise exception using errcode = '22023', message = 'active_owner_not_resolved';
  end if;

  if v_target_name is null then
    if v_ai_kind = 'SELF_CONSULTATION' then v_target_name := v_referrer_name;
    elsif v_target_phone is not null then v_target_name := v_target_phone;
    else v_target_name := 'Liên hệ Zalo ' || right(v_target_uid, 6);
    end if;
  end if;
  if v_self_phone and v_ai_kind = 'SELF_CONSULTATION' then
    -- tên hồ sơ = tên người đang chat (contact) khi khách tự để lại số
    v_target_name := coalesce(nullif(btrim(v_gom.contact_name), ''), v_target_name);
  end if;
  v_target_name := left(regexp_replace(v_target_name, '[[:space:]]+', ' ', 'g'), 200);

  if v_customer_id is null then
-- (HÀM CHUNG) tạo hồ sơ khách qua public.fn_upsert_aka_customer_v1 — khóa phone / zalo_uid / pancake_url duy nhất
    v_upsert_res := public.fn_upsert_aka_customer_v1(jsonb_strip_nulls(jsonb_build_object(
      'phone', v_target_phone,
      'zalo_uid', v_target_uid,
      'pancake_url', case when v_ai_kind = 'SELF_CONSULTATION' or v_self_phone then v_pancake_url end,
      'name', v_target_name, 'name_zalo', v_target_name,
      'channel', 'trigger_from_contact', 'account_id', v_account_id, 'source_status_id', 104,
      'org_staff_id', v_owner_id, 'is_split_exempt', true,
      'is_referred', v_is_referral,
      'referrer_id', case when v_is_referral then v_referrer_customer_id end,
      'referrer_phone', case when v_is_referral then v_referrer_phone end,
      'referrer_pancake_url', case when v_is_referral or v_ai_kind = 'REFERRAL_OTHER' then v_pancake_url end,
      'creation_path', 'zalo_chat_referral_v2',
      'custom_fields', jsonb_strip_nulls(jsonb_build_object(
        'message_gom_id', p_message_id::text,
        'pancake_url', v_pancake_url,
        'conversation_id', v_gom.conversation_id,
        'referrer_contact_id', v_gom.contact_id,
        'referrer_name', case when v_is_referral or v_ai_kind = 'REFERRAL_OTHER' then v_referrer_name end,
        'referrer_zalo_uid', v_referrer_uid,
        'referred_by_name_hint', v_referred_by_name,
        'ai_kind', v_ai_kind,
        'route', v_route)) || v_card_cf
    )));
    if coalesce((v_upsert_res ->> 'ok')::boolean, false) is not true then
      raise exception using errcode = '22023', message = 'upsert_customer_failed:' || coalesce(v_upsert_res ->> 'error', 'unknown');
    end if;
    v_customer_id := (v_upsert_res ->> 'customer_id')::bigint;
    v_customer_is_new := coalesce((v_upsert_res ->> 'is_new')::boolean, false);
  end if;

  if v_customer_id is null then
    raise exception using errcode = '23505', message = 'customer_identity_conflict';
  end if;

  if not v_customer_is_new then
    select nullif(btrim(c.referrer_pancake_url), '') into v_existing_pancake_url from public.aka_customer c where c.id = v_customer_id;
    update public.aka_customer c
    set name = coalesce(nullif(btrim(c.name), ''), v_target_name),
        phone = case when nullif(btrim(c.phone), '') is null then v_target_phone else c.phone end,
        zalo = coalesce(nullif(btrim(c.zalo), ''), v_target_phone, v_target_uid),
        name_zalo = coalesce(nullif(btrim(c.name_zalo), ''), v_target_name),
        zalo_referral_id = case when nullif(btrim(c.zalo_referral_id), '') is null then v_target_uid else c.zalo_referral_id end,
        is_referred = c.is_referred or v_is_referral,
        referrer_id = coalesce(c.referrer_id, case when v_is_referral then v_referrer_customer_id end),
        referrer_phone = coalesce(nullif(btrim(c.referrer_phone), ''), case when v_is_referral then v_referrer_phone end),
        referrer_pancake_url = coalesce(nullif(btrim(c.referrer_pancake_url), ''), case when v_is_referral or v_ai_kind = 'REFERRAL_OTHER' then v_pancake_url end),
        custom_fields = coalesce(c.custom_fields, '{}'::jsonb)
          || jsonb_strip_nulls(jsonb_build_object(
               'pancake_url', coalesce(c.custom_fields ->> 'pancake_url', v_pancake_url),
               'last_pancake_url', v_pancake_url,
               'last_message_gom_id', p_message_id::text,
               'referred_by_name_hint', coalesce(c.custom_fields ->> 'referred_by_name_hint', v_referred_by_name),
               'referrer_name', coalesce(c.custom_fields ->> 'referrer_name', case when (v_is_referral or v_ai_kind = 'REFERRAL_OTHER') and c.referrer_id is null and nullif(btrim(c.referrer_phone), '') is null then v_referrer_name end),
               'referrer_zalo_uid', coalesce(c.custom_fields ->> 'referrer_zalo_uid', case when (v_is_referral or v_ai_kind = 'REFERRAL_OTHER') and c.referrer_id is null and nullif(btrim(c.referrer_phone), '') is null then v_referrer_uid end),
               'referrer_contact_id', coalesce(c.custom_fields ->> 'referrer_contact_id', case when (v_is_referral or v_ai_kind = 'REFERRAL_OTHER') and c.referrer_id is null and nullif(btrim(c.referrer_phone), '') is null then v_gom.contact_id::text end),
               'conversation_id', coalesce(c.custom_fields ->> 'conversation_id', v_gom.conversation_id),
               'zalo_guid', coalesce(c.custom_fields ->> 'zalo_guid', v_card_cf ->> 'zalo_guid'),
               'zalo_card_name', coalesce(c.custom_fields ->> 'zalo_card_name', v_card_cf ->> 'zalo_card_name'),
               'zalo_card_avatar', coalesce(c.custom_fields ->> 'zalo_card_avatar', v_card_cf ->> 'zalo_card_avatar'),
               'zalo_card_qr_url', coalesce(c.custom_fields ->> 'zalo_card_qr_url', v_card_cf ->> 'zalo_card_qr_url'),
               'zalo_card_message_id', coalesce(c.custom_fields ->> 'zalo_card_message_id', v_card_cf ->> 'zalo_card_message_id')))
          || case when v_existing_pancake_url is not null and v_existing_pancake_url <> v_pancake_url
                  then jsonb_build_object('pancake_url_conflict', jsonb_build_object('old', v_existing_pancake_url, 'new', v_pancake_url, 'at', now()))
                  else '{}'::jsonb end,
        org_staff_id_owner = coalesce(c.org_staff_id_owner, v_owner_id),
        org_staff_create_id = coalesce(c.org_staff_create_id, v_owner_id),
        org_staff_update_id = v_owner_id,
        updated_at = now()
    where c.id = v_customer_id;
  end if;

  if not v_customer_is_new then
    perform public.fn_upsert_aka_customer_v1(jsonb_strip_nulls(jsonb_build_object(
      'customer_id', v_customer_id, 'phone', v_target_phone, 'zalo_uid', v_target_uid,
      'pancake_url', case when v_ai_kind = 'SELF_CONSULTATION' or v_self_phone then v_pancake_url end,
      'creation_path', 'zalo_chat_referral_v2')));
  end if;

  select nullif(btrim(c.phone), ''), public.normalize_phone(c.phone), nullif(btrim(c.zalo_referral_id), '')
  into v_existing_target_phone_raw, v_existing_target_phone, v_existing_target_uid
  from public.aka_customer c where c.id = v_customer_id for update;
  if not found then
    raise exception using errcode = '23503', message = 'matched_customer_missing';
  end if;
  if v_target_phone is not null and v_existing_target_phone_raw is not null
     and (v_existing_target_phone is null or v_existing_target_phone is distinct from v_target_phone) then
    raise exception using errcode = '23505', message = 'customer_phone_identity_conflict_review';
  end if;
  if v_target_uid is not null and v_existing_target_uid is not null and lower(v_existing_target_uid) is distinct from lower(v_target_uid) then
    raise exception using errcode = '23505', message = 'customer_zalo_identity_conflict_review';
  end if;

  select os.id, os.organization_id, os.name into v_customer_owner_id, v_customer_organization_id, v_customer_owner_name
  from public.aka_customer c join public.org_staff os on os.id = c.org_staff_id_owner
  where c.id = v_customer_id and os.is_active = true;
  if found then
    v_owner_id := v_customer_owner_id; v_organization_id := v_customer_organization_id; v_owner_name := v_customer_owner_name;
  end if;
  select os.organization_id, os.name into v_organization_id, v_owner_name
  from public.org_staff os where os.id = v_owner_id and os.is_active = true for share of os;
  if not found or v_organization_id is null then
    raise exception using errcode = '55000', message = 'active_owner_changed_during_create';
  end if;

  if v_self_phone and v_gom.contact_id is not null then
    update public.contacts
    set phone = coalesce(nullif(btrim(phone), ''), v_target_phone),
        customer_id = coalesce(customer_id, v_customer_id),
        updated_at = now()
    where id = v_gom.contact_id and (nullif(btrim(phone), '') is null or customer_id is null);
  end if;

  -- Loại CRM cuối cùng: được giới thiệu (AI REFERRAL_OTHER hoặc đã xác định có người giới thiệu) -> 31; khách chủ động -> 32
  v_crm_type_id := case when v_ai_kind = 'REFERRAL_OTHER' or v_is_referral then 31 else 32 end;
  -- (HÀM CHUNG) link hội thoại này là của NGƯỜI GIỚI THIỆU (người đang chat) -> đăng ký vào hồ sơ người giới thiệu
  if v_is_referral and v_referrer_customer_id is not null and v_referrer_customer_id <> v_customer_id then
    perform public.fn_upsert_aka_customer_v1(jsonb_strip_nulls(jsonb_build_object(
      'customer_id', v_referrer_customer_id, 'pancake_url', v_pancake_url, 'zalo_uid', v_referrer_uid, 'contact_id', v_gom.contact_id)));
  end if;
  select c.name, c.phone into v_customer_name, v_customer_phone from public.aka_customer c where c.id = v_customer_id;
  select t.stt, t.name into v_priority, v_crm_type_name from public.aka_crm_type t where t.id = v_crm_type_id and t.is_active = true;
  if not found then
    raise exception using errcode = '22023', message = 'required_crm_type_inactive';
  end if;

  -- Khách đã được NV tạo tay ngay sau tin nhắn này -> coi như đã xử lý, không tạo CRM trùng
  if not v_customer_is_new then
    select c.created_at, c.custom_fields ->> 'creation_path' into v_cust_created_at, v_cust_path
    from public.aka_customer c where c.id = v_customer_id;
    if v_cust_created_at >= coalesce(v_gom.question_first_at, v_gom.created_at) - interval '1 hour'
       and v_cust_created_at <= coalesce(v_gom.question_first_at, v_gom.created_at) + interval '3 days'
       and coalesce(v_cust_path, '') not like 'zalo_chat_referral%' then
      v_manual_handled := true;
    end if;
  end if;

  if p_create_crm then
  select c.id into v_recent_crm_id from public.aka_crm c
  where c.customer_id = v_customer_id and c.gen_agent = 'zalo-chat-referral-v1'
    and c.created_at > now() - interval '14 days'
  order by c.created_at desc limit 1;
  end if;
  if v_recent_crm_id is not null or v_manual_handled then
    if p_finalize then
      update public.message_gom g
      set zalo_referral_claim_token = null, zalo_referral_processing_until = null,
          zalo_referral_last_status = 'duplicate', zalo_referral_processed_at = now()
      where g.id = p_message_id and g.zalo_referral_evidence_hash = v_evidence_hash
        and g.zalo_referral_claim_token = p_claim_token and g.zalo_referral_last_status = 'processing'
      returning g.id into v_finalized;
      if v_finalized is null then
        raise exception using errcode = '55000', message = 'zalo_referral_atomic_finalize_failed';
      end if;
    end if;
    return jsonb_build_object('ok', true, 'created', false, 'action', case when v_manual_handled then 'duplicate_manual' else 'duplicate_recent' end, 'crm_id', v_recent_crm_id,
      'customer_id', v_customer_id, 'customer_name', v_customer_name, 'customer_phone', v_customer_phone,
      'crm_type_id', v_crm_type_id, 'crm_type_name', v_crm_type_name, 'org_staff_owner_id', v_owner_id,
      'organization_id', v_organization_id, 'staff_name', v_owner_name, 'route', v_route,
      'pancake_url', v_pancake_url, 'customer_is_new', v_customer_is_new);
  end if;

  if v_route = 'zalo_contact' then
    v_note := 'Khách hàng được giới thiệu qua danh thiếp Zalo - Người giới thiệu: ' || v_referrer_name;
  elsif v_ai_kind = 'SELF_CONSULTATION' and not v_is_referral then
    v_note := 'Khách hàng để lại SĐT yêu cầu tư vấn qua Zalo chat - Người chat: ' || v_referrer_name;
  elsif v_ai_kind = 'SELF_CONSULTATION' and v_self_phone then
    v_note := 'Khách hàng để lại SĐT yêu cầu tư vấn qua Zalo chat - Được giới thiệu bởi: ' || v_referrer_name;
  else
    v_note := 'Khách hàng được giới thiệu thông qua Zalo chat - Người giới thiệu: ' || v_referrer_name;
  end if;
  v_note := v_note || E'\nLink Pancake: ' || v_pancake_url;
  v_due := private.zalo_referral_due_date_v1(now());

  insert into public.aka_lead (
    name, phone, phone_norm, type_source, source, akacustomer_id, organization_id, status, refe, note,
    pancake_url, raw_payload, source_occurred_at
  ) values (
    v_target_name, v_target_phone, v_target_phone, 'zalo_chat_referral', 'pancake', v_customer_id, v_organization_id, 'new',
    case when v_is_referral then v_referrer_name else v_referred_by_name end, v_note, v_pancake_url,
    jsonb_strip_nulls(jsonb_build_object(
      'source_type', v_source_type,
      'message_gom_id', p_message_id::text,
      'route', v_route,
      'ai_kind', v_ai_kind,
      'ai_confidence', v_ai_confidence,
      'ai_log_id', p_ai_log_id,
      'referrer_customer_id', case when v_is_referral then v_referrer_customer_id end,
      'referrer_phone', case when v_is_referral then v_referrer_phone end,
      'referred_by_name_hint', v_referred_by_name,
      'pancake_url', v_pancake_url,
      'conversation_id', v_gom.conversation_id,
      'target_zalo_uid', v_target_uid,
      'target_zalo_guid', v_card_guid
    )),
    coalesce(v_gom.question_first_at, v_gom.created_at)
  )
  on conflict do nothing
  returning id into v_lead_id;
  v_lead_created := v_lead_id is not null;
  if v_lead_id is null then
    select id into v_lead_id from public.aka_lead
    where type_source = 'zalo_chat_referral' and raw_payload ->> 'source_type' = v_source_type
    order by id desc limit 1;
  end if;

  if p_create_crm then
  insert into public.aka_crm (
    customer_id, customer_name, customer_phone, crm_type_id, priority, org_staff_owner_id, organization_id,
    created_by, note, cskh_due_date, is_read, source_order_id, source_type, sql_account_id,
    gen_agent, gen_status, gen_at, gen_meta, pancake_url, lead_id, suggested_channel_id
  ) values (
    v_customer_id, v_customer_name, v_customer_phone, v_crm_type_id, v_priority, v_owner_id, v_organization_id,
    v_owner_id, v_note, v_due, false, v_customer_id, v_source_type, v_account_id,
    'zalo-chat-referral-v1', 'created', now(),
    jsonb_strip_nulls(jsonb_build_object(
      'version', 'v2',
      'message_gom_id', p_message_id::text,
      'route', v_route,
      'evidence_hash', v_evidence_hash,
      'phone_index', v_phone_idx,
      'phones_total', cardinality(v_phones),
      'ai_log_id', p_ai_log_id,
      'ai_kind', v_ai_kind,
      'ai_confidence', v_ai_confidence,
      'referrer_customer_id', case when v_is_referral then v_referrer_customer_id end,
      'referrer_contact_id', v_gom.contact_id,
      'referrer_name', case when v_is_referral then v_referrer_name end,
      'referrer_phone_last4', case when v_is_referral and v_referrer_phone is not null then right(v_referrer_phone, 4) end,
      'referred_by_name_hint', v_referred_by_name,
      'referrer_zalo_uid', v_referrer_uid,
      'target_zalo_uid', v_target_uid,
      'target_zalo_guid', v_card_guid,
      'target_phone_last4', case when v_target_phone is not null then right(v_target_phone, 4) end,
      'pancake_url', v_pancake_url,
      'lead_id', v_lead_id,
      'customer_is_new', v_customer_is_new,
      'raw_card_message_id', v_card ->> 'raw_message_id'
    )),
    v_pancake_url, v_lead_id, 8 -- suggested_channel_id: inbox_zalo (bắt buộc nhắn Zalo)
  )
  on conflict do nothing
  returning id into v_crm_id;

  if v_crm_id is not null then
    v_created := true;
  else
    select * into v_existing_crm from public.aka_crm
    where source_type like 'zalo_referral:%' and source_type = v_source_type order by id desc limit 1;
    if found then
      if v_existing_crm.customer_id is distinct from v_customer_id
         or (v_existing_crm.crm_type_id is distinct from v_crm_type_id and v_existing_crm.crm_type_id not in (1, 5, 31, 32))
         or (v_existing_crm.gen_meta ->> 'evidence_hash') is distinct from v_evidence_hash then
        raise exception using errcode = '23505', message = 'crm_idempotency_identity_conflict';
      end if;
      v_crm_id := v_existing_crm.id;
    end if;
  end if;
  if v_crm_id is null then
    raise exception using errcode = '23505', message = 'crm_idempotency_conflict';
  end if;
  else
    -- Chế độ backfill: chỉ Lead + Customer, không tạo CRM
    v_created := v_lead_created;
  end if;

  if v_created and v_is_referral and v_referrer_customer_id is not null and v_referrer_customer_id <> v_customer_id then
    update public.aka_customer r
    set referral_count = coalesce(r.referral_count, 0) + 1,
        custom_fields = coalesce(r.custom_fields, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
          'last_referral_at', now(),
          'last_referral_pancake_url', v_pancake_url,
          'last_referred_customer_id', v_customer_id,
          'last_referral_message_gom_id', p_message_id::text,
          'pancake_url', coalesce(r.custom_fields ->> 'pancake_url', v_pancake_url))),
        updated_at = now()
    where r.id = v_referrer_customer_id;
  end if;

  if p_finalize then
    update public.message_gom g
    set zalo_referral_claim_token = null, zalo_referral_processing_until = null,
        zalo_referral_last_status = case when v_created then 'created' else 'duplicate' end,
        zalo_referral_processed_at = now()
    where g.id = p_message_id and g.zalo_referral_evidence_hash = v_evidence_hash
      and g.zalo_referral_claim_token = p_claim_token and g.zalo_referral_last_status = 'processing'
    returning g.id into v_finalized;
    if v_finalized is null then
      raise exception using errcode = '55000', message = 'zalo_referral_atomic_finalize_failed';
    end if;
  end if;

  return jsonb_build_object(
    'ok', true, 'created', v_created, 'action', case when v_created then 'created' else 'duplicate' end,
    'crm_id', v_crm_id, 'lead_id', v_lead_id, 'customer_id', v_customer_id, 'customer_is_new', v_customer_is_new,
    'customer_name', v_customer_name, 'customer_phone', v_customer_phone,
    'crm_type_id', v_crm_type_id, 'crm_type_name', v_crm_type_name,
    'org_staff_owner_id', v_owner_id, 'organization_id', v_organization_id, 'staff_name', v_owner_name,
    'cskh_due_date', v_due, 'route', v_route, 'ai_kind', v_ai_kind,
    'pancake_url', v_pancake_url, 'phone_index', v_phone_idx,
    'referrer_customer_id', case when v_is_referral then v_referrer_customer_id end,
    'referred_by_name_hint', v_referred_by_name,
    'lead_created', v_lead_created,
    'create_crm', p_create_crm,
    'owner_mode', p_owner_mode,
    'target_zalo_uid', v_target_uid
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_zalo_chat_referral_create_crm_v3(p_message_id uuid, p_route text, p_evidence_hash text, p_claim_token uuid, p_target_phone text DEFAULT NULL::text, p_ai_log_id bigint DEFAULT NULL::bigint, p_finalize boolean DEFAULT true, p_create_crm boolean DEFAULT true, p_owner_mode text DEFAULT 'default'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_gom public.message_gom%rowtype;
  v_card jsonb;
  v_info jsonb;
  v_evidence jsonb;
  v_phones text[];
  v_phone_idx integer;
  v_raw_reference_count integer := 0;
  v_raw_locked_count integer := 0;
  v_evidence_hash text;
  v_ai public.ai_log%rowtype;
  v_verdict jsonb;
  v_existing_crm public.aka_crm%rowtype;
  v_upsert_res jsonb;
  v_route text := lower(btrim(coalesce(p_route, '')));
  v_account_id integer;
  v_target_phone text;
  v_target_uid text;
  v_target_name text;
  v_target_name_source text := null;
  v_target_name_verified boolean := true;
  v_target_name_conf numeric := null;
  v_db_name text;
  v_ai_kind text;
  v_ai_confidence numeric;
  v_ai_note text;
  v_relationship text;
  v_repeat boolean := false;
  v_referrer_self_name text;
  v_referred_by_name text;
  v_mention_customer_id bigint;
  v_mention_count integer;
  v_self_phone boolean := false;
  v_phone_customer_id bigint;
  v_uid_customer_id bigint;
  v_customer_id bigint;
  v_customer_is_new boolean := false;
  v_referrer_customer_id bigint;
  v_referrer_name text;
  v_referrer_uid text;            -- Zalo UID chuẩn hoá của người đang chat
  v_referrer_pancake_uid text;    -- contacts.uid nguyên bản (pzl_u_...)
  v_referrer_phone text;
  v_referrer_current_phone text;
  v_referrer_current_name text;
  v_pancake_url text;
  v_owner_id bigint;
  v_organization_id bigint;
  v_owner_name text;
  v_customer_owner_id bigint;
  v_customer_organization_id bigint;
  v_customer_owner_name text;
  v_customer_name text;
  v_customer_phone text;
  v_existing_target_phone_raw text;
  v_existing_target_phone text;
  v_existing_target_uid text;
  v_existing_pancake_url text;
  v_crm_type_id bigint;
  v_priority integer;
  v_crm_type_name text;
  v_note text;
  v_source_type text;
  v_due timestamptz;
  v_crm_id bigint;
  v_lead_id bigint;
  v_recent_crm_id bigint;
  v_finalized uuid;
  v_created boolean := false;
  v_is_referral boolean := false;
  v_manual_handled boolean := false;
  v_cust_created_at timestamptz;
  v_cust_path text;
  v_last_staff_id bigint;
  v_last_staff_org bigint;
  v_last_staff_name text;
  v_lead_created boolean := false;
  v_contact_customer_id bigint;
  v_contact_phone text;
  v_contact_name text;
  v_contact_uid text;
  v_ref_candidate bigint;
  v_cid bigint;
  v_cid_phone text;
  v_cid_uid text;
  v_m record;
  v_uid_taken boolean := false;
  v_referrer_updates jsonb := '{}'::jsonb;
begin
  if current_user not in ('postgres', 'service_role') then
    raise exception using errcode = '42501', message = 'zalo_referral_backend_only';
  end if;
  if v_route not in ('zalo_contact', 'phone_intent') then
    raise exception using errcode = '22023', message = 'invalid_zalo_referral_route';
  end if;
  -- v3 chỉ phục vụ route SĐT trong tin; route danh thiếp Zalo dùng fn_zalo_chat_referral_create_crm_v2 (card AI gate)
  if v_route <> 'phone_intent' then
    raise exception using errcode = '22023', message = 'create_crm_v3_phone_intent_only';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('zalo-referral-message:' || p_message_id::text, 0));

  select * into v_gom from public.message_gom where id = p_message_id for update;
  if not found
     or upper(coalesce(v_gom.initiated_by, '')) <> 'CUSTOMER'
     or lower(btrim(coalesce(v_gom.source, ''))) <> 'pancake'
     or not public.fn_zalo_chat_referral_message_eligible_v1(p_message_id) then
    raise exception using errcode = '22023', message = 'invalid_customer_message';
  end if;

  if p_claim_token is null
     or v_gom.zalo_referral_claim_token is distinct from p_claim_token
     or v_gom.zalo_referral_evidence_hash is distinct from p_evidence_hash
     or v_gom.zalo_referral_last_status is distinct from 'processing'
     or v_gom.zalo_referral_processing_until is null
     or v_gom.zalo_referral_processing_until <= now() then
    raise exception using errcode = '55000', message = 'zalo_referral_processing_lease_invalid';
  end if;

  v_account_id := coalesce(v_gom.account_id, 1001);

  select count(*) into v_raw_reference_count
  from (
    select distinct case when q.raw_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then q.raw_id::uuid end as id
    from jsonb_array_elements_text(case when jsonb_typeof(v_gom.question_message_ids) = 'array' then v_gom.question_message_ids else '[]'::jsonb end) q(raw_id)
  ) refs where refs.id is not null;

  perform m.id
  from public.messages m
  join (
    select distinct case when q.raw_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then q.raw_id::uuid end as id
    from jsonb_array_elements_text(case when jsonb_typeof(v_gom.question_message_ids) = 'array' then v_gom.question_message_ids else '[]'::jsonb end) q(raw_id)
  ) refs on refs.id = m.id
  where refs.id is not null
  order by m.id
  for share of m;
  get diagnostics v_raw_locked_count = row_count;
  if v_raw_locked_count <> v_raw_reference_count then
    raise exception using errcode = '23503', message = 'zalo_referral_raw_message_missing';
  end if;

  v_evidence := public.fn_zalo_chat_referral_evidence_v1(p_message_id);
  v_evidence_hash := nullif(v_evidence ->> 'evidence_hash', '');
  if v_evidence is null
     or (v_evidence ->> 'route') is distinct from v_route
     or v_evidence_hash is null
     or v_evidence_hash is distinct from p_evidence_hash
     or v_evidence_hash !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023', message = 'zalo_referral_evidence_changed';
  end if;
  v_card := v_evidence -> 'card';
  select coalesce(array_agg(x), array[]::text[]) into v_phones
  from jsonb_array_elements_text(coalesce(v_evidence -> 'phones', '[]'::jsonb)) x;

  v_pancake_url := public.fn_zalo_chat_referral_pancake_url_v1(p_message_id);
  if v_pancake_url is null then
    raise exception using errcode = '22023', message = 'pancake_url_missing';
  end if;

  -- Người đang chat (referrer tiềm năng) + Zalo UID từ contacts.uid
  select coalesce(v_gom.aka_customer_id, c.customer_id),
         coalesce(nullif(btrim(v_gom.contact_name), ''), nullif(btrim(c.name), '')),
         nullif(btrim(c.phone), ''),
         nullif(btrim(c.uid), '')
  into v_referrer_customer_id, v_referrer_name, v_referrer_phone, v_contact_uid
  from (select 1) seed
  left join public.contacts c on c.id = v_gom.contact_id;

  v_referrer_name := left(regexp_replace(coalesce(v_referrer_name, v_card ->> 'sender_name', 'Khách hàng'), '[[:space:]]+', ' ', 'g'), 150);
  v_referrer_pancake_uid := v_contact_uid;
  v_referrer_uid := coalesce(
    public.fn_zalo_referral_canonical_uid_v1(v_card ->> 'sender_uid'),
    public.fn_zalo_referral_canonical_uid_v1(v_contact_uid)
  );
  if v_referrer_uid is not null and v_referrer_uid !~ '^[[:alnum:]_.@-]{3,100}$' then v_referrer_uid := null; end if;
  if v_referrer_customer_id is not null then
    select nullif(btrim(ac.phone), '') into v_referrer_current_phone from public.aka_customer ac where ac.id = v_referrer_customer_id;
    v_referrer_phone := coalesce(v_referrer_current_phone, v_referrer_phone);
  end if;
  v_referrer_phone := public.normalize_phone(v_referrer_phone);
  if v_referrer_phone !~ '^0[1-9][0-9]{8}$' then v_referrer_phone := null; end if;

  if v_route = 'zalo_contact' then
    v_crm_type_id := 31; -- CSKH được giới thiệu qua Zalo (danh thiếp)
    v_phone_idx := 1;
    v_source_type := 'zalo_referral:' || p_message_id::text;
    if v_card is not null then
      v_target_uid := nullif(btrim(v_card ->> 'contact_uid'), '');
      v_target_phone := public.normalize_phone(v_card ->> 'phone_number');
      if v_target_phone !~ '^0[1-9][0-9]{8}$' then v_target_phone := null; end if;
      v_target_name := public.fn_zalo_referral_clean_person_name_v1(v_card ->> 'contact_name');
      if v_target_name is not null then v_target_name_source := 'zalo_card'; end if;
    else
      begin v_info := coalesce(v_gom.zalo_info, '{}')::jsonb; exception when others then v_info := '{}'::jsonb; end;
      if coalesce(v_info ->> 'source', '') <> 'question_content' or coalesce(v_info ->> 'confidence', '') <> 'high' then
        raise exception using errcode = '22023', message = 'zalo_contact_evidence_missing';
      end if;
      if btrim(coalesce(v_gom.zalo_id, '')) ~ '^(0[1-9][0-9]{8}|84[1-9][0-9]{8})$' then
        v_target_phone := public.normalize_phone(v_gom.zalo_id);
      else
        v_target_uid := nullif(btrim(v_gom.zalo_id), '');
      end if;
    end if;
    if v_target_phone is null and (v_target_uid is null or v_target_uid !~ '^[[:alnum:]_.@-]{3,100}$') then
      raise exception using errcode = '22023', message = 'invalid_zalo_contact_identity';
    end if;
    v_ai_kind := 'REFERRAL_OTHER';
    v_is_referral := v_referrer_customer_id is not null or v_referrer_uid is not null;
  else
    v_crm_type_id := null; -- gán theo v_ai_kind bên dưới: 31 giới thiệu / 32 khách chủ động
    v_target_phone := public.normalize_phone(p_target_phone);
    if v_target_phone is null or v_target_phone !~ '^0[1-9][0-9]{8}$' then
      raise exception using errcode = '22023', message = 'phone_not_from_current_customer_message';
    end if;
    v_phone_idx := array_position(v_phones, v_target_phone);
    if v_phone_idx is null then
      raise exception using errcode = '22023', message = 'phone_not_from_current_customer_message';
    end if;
    v_source_type := 'zalo_referral:' || p_message_id::text || case when v_phone_idx > 1 then ':p' || v_phone_idx::text else '' end;

    if p_ai_log_id is null then
      raise exception using errcode = '22023', message = 'verified_ai_log_required';
    end if;
    select * into v_ai from public.ai_log
    where id = p_ai_log_id
      and using_code = 'zalo_chat_referral_verify_v1'
      and block_name = 'zalo-chat-referral-precreate-v1'
      and node_id = 'zalo-referral:' || p_message_id::text
      and status = 'success';
    if not found
       or (v_ai.sanitized_request ->> 'message_id') is distinct from p_message_id::text
       or (v_ai.sanitized_request ->> 'message_sha256') is distinct from encode(extensions.digest(coalesce(v_gom.question_content, ''), 'sha256'), 'hex')
       or (v_ai.sanitized_request ->> 'evidence_hash') is distinct from v_evidence_hash then
      raise exception using errcode = '22023', message = 'ai_verdict_not_approved';
    end if;

    if jsonb_typeof(v_ai.sanitized_response -> 'verdicts') = 'array' then
      select v into v_verdict
      from jsonb_array_elements(v_ai.sanitized_response -> 'verdicts') v
      where v ->> 'phone_sha256' = encode(extensions.digest(v_target_phone, 'sha256'), 'hex')
      limit 1;
    elsif (v_ai.sanitized_request ->> 'phone_sha256') = encode(extensions.digest(v_target_phone, 'sha256'), 'hex') then
      v_verdict := v_ai.sanitized_response;
    end if;

    if v_verdict is null
       or jsonb_typeof(v_verdict -> 'actionable') is distinct from 'boolean'
       or (v_verdict -> 'actionable') is distinct from 'true'::jsonb
       or coalesce(v_verdict ->> 'kind', '') not in ('REFERRAL_OTHER', 'SELF_CONSULTATION')
       or jsonb_typeof(v_verdict -> 'confidence') is distinct from 'number' then
      raise exception using errcode = '22023', message = 'ai_verdict_not_approved';
    end if;
    v_ai_kind := v_verdict ->> 'kind';
    v_crm_type_id := case v_ai_kind when 'REFERRAL_OTHER' then 31 else 32 end; -- 31 CSKH được giới thiệu qua Zalo / 32 CSKH mới - về từ Zalo
    v_ai_confidence := (v_verdict ->> 'confidence')::numeric;
    if v_ai_confidence < 0.80 or v_ai_confidence > 1 then
      raise exception using errcode = '22023', message = 'ai_verdict_not_approved';
    end if;

    -- Tên chủ số do AI đưa: chỉ nhận khi edge đã đánh dấu verified (có bằng chứng trong hội thoại, confidence >= 0.8).
    -- Verdict cũ (v4) không có cờ -> coi như verified (edge v4 đã kiểm tra tên nằm trong tin).
    if v_verdict ? 'target_name_verified' then
      v_target_name_verified := (v_verdict -> 'target_name_verified') = 'true'::jsonb;
    else
      v_target_name_verified := true;
    end if;
    if jsonb_typeof(v_verdict -> 'target_name_confidence') = 'number' then
      v_target_name_conf := (v_verdict ->> 'target_name_confidence')::numeric;
    end if;
    v_target_name := public.fn_zalo_referral_clean_person_name_v1(v_verdict ->> 'target_name');
    if v_target_name is not null and v_target_name_verified then
      v_target_name_source := 'ai_verified';
    else
      v_target_name := null;
    end if;

    v_ai_note := left(nullif(regexp_replace(btrim(coalesce(v_verdict ->> 'note', '')), '[[:space:]]+', ' ', 'g'), ''), 600);
    v_relationship := left(nullif(btrim(coalesce(v_verdict ->> 'relationship', '')), ''), 60);
    v_repeat := coalesce((v_verdict -> 'repeat_of_earlier') = 'true'::jsonb, false);
    v_referrer_self_name := public.fn_zalo_referral_clean_person_name_v1(v_verdict ->> 'referrer_self_name');
    v_referred_by_name := left(nullif(regexp_replace(btrim(coalesce(v_verdict ->> 'referred_by_name', '')), '[[:space:]]+', ' ', 'g'), ''), 150);

    if v_ai_kind = 'REFERRAL_OTHER' then
      -- Người giới thiệu = tài khoản Zalo đang chat. contacts.customer_id / message_gom.aka_customer_id có thể đang trỏ
      -- tới hồ sơ của chính SĐT được giới thiệu (NV gắn tay / worker khớp theo SĐT trong tin) -> loại các hồ sơ đó.
      select c.customer_id, nullif(btrim(c.phone), ''), nullif(btrim(c.name), '')
      into v_contact_customer_id, v_contact_phone, v_contact_name
      from public.contacts c where c.id = v_gom.contact_id;
      v_ref_candidate := null;
      foreach v_cid in array array_remove(array[v_contact_customer_id, v_gom.aka_customer_id], null) loop
        select public.normalize_phone(ac.phone), nullif(btrim(ac.zalo_referral_id), '') into v_cid_phone, v_cid_uid from public.aka_customer ac
        where ac.id = v_cid and coalesce(ac.record_state, 'active') <> 'merged';
        if found
           and (v_cid_phone is null or not (v_cid_phone = any(v_phones)))
           and (v_target_uid is null or v_cid_uid is null or lower(v_cid_uid) <> lower(v_target_uid)) then
          v_ref_candidate := v_cid; exit;
        end if;
      end loop;
      v_referrer_customer_id := v_ref_candidate;
      -- Chưa khớp hồ sơ theo contact -> thử khớp theo Zalo UID (hồ sơ tạo trước đó bởi pipeline)
      if v_referrer_customer_id is null and v_referrer_uid is not null then
        select ac.id into v_referrer_customer_id from public.aka_customer ac
        where ac.account_id = v_account_id and lower(btrim(ac.zalo_referral_id)) = lower(v_referrer_uid)
          and coalesce(ac.record_state, 'active') <> 'merged'
          and (public.normalize_phone(ac.phone) is null or not (public.normalize_phone(ac.phone) = any(v_phones)))
        order by ac.id desc limit 1;
      end if;
      -- SĐT người giới thiệu: hồ sơ người chat > contacts.phone > số NV chú thích trong tên Zalo; phải khác các SĐT trong tin
      v_referrer_phone := null;
      if v_referrer_customer_id is not null then
        select public.normalize_phone(ac.phone) into v_referrer_phone from public.aka_customer ac where ac.id = v_referrer_customer_id;
      end if;
      if v_referrer_phone is null or v_referrer_phone !~ '^0[1-9][0-9]{8}$' or v_referrer_phone = any(v_phones) then
        v_referrer_phone := null;
        for v_m in
          select public.normalize_phone(m[1]) as p
          from regexp_matches(coalesce(v_contact_phone, '') || ' ' || coalesce(v_gom.contact_name, '') || ' ' || coalesce(v_contact_name, ''),
                              '((?:\+?84|0)[0-9][0-9 .-]{7,12}[0-9])', 'g') m
        loop
          if v_m.p ~ '^0[1-9][0-9]{8}$' and not (v_m.p = any(v_phones)) then
            v_referrer_phone := v_m.p; exit;
          end if;
        end loop;
      end if;
      if v_referrer_customer_id is null and v_referrer_phone is not null then
        select id into v_referrer_customer_id from public.aka_customer
        where public.normalize_phone(phone) = v_referrer_phone and coalesce(record_state, 'active') <> 'merged'
        order by case when account_id = v_account_id then 0 else 1 end, created_at desc nulls last, id desc limit 1;
      end if;
      v_referrer_current_phone := v_referrer_phone;
      v_is_referral := v_referrer_customer_id is not null or v_referrer_phone is not null or v_referrer_uid is not null;
    else
      v_is_referral := false;
    end if;
  end if;

  -- Tên người giới thiệu: nếu tên hiển thị không dùng được (rỗng / chỉ số / placeholder) mà khách tự xưng tên -> dùng tên tự xưng
  if v_ai_kind = 'REFERRAL_OTHER' and v_referrer_self_name is not null
     and (public.fn_zalo_referral_clean_person_name_v1(v_referrer_name) is null or v_referrer_name = 'Khách hàng') then
    v_referrer_name := v_referrer_self_name;
  end if;

  select c.* into v_existing_crm from public.aka_crm c
  where c.source_type like 'zalo_referral:%' and c.source_type = v_source_type
  order by c.id desc limit 1;
  if found then
    if v_existing_crm.gen_agent is distinct from 'zalo-chat-referral-v1' then
      raise exception using errcode = '23505', message = 'message_already_processed_with_different_evidence';
    end if;
    -- Cùng tin đã được route khác xử lý (VD SĐT trên danh thiếp đã đi route card trước đây) -> coi là trùng
    if (v_existing_crm.gen_meta ->> 'route') is not distinct from v_route
       and ((v_existing_crm.crm_type_id is distinct from v_crm_type_id
             and not (v_existing_crm.crm_type_id in (1, 5, 31, 32) and v_crm_type_id in (31, 32))) -- 1/5 = type cũ trước 02/09/2026; 31/32 cùng họ Zalo
            or ((v_existing_crm.gen_meta ->> 'evidence_hash') is distinct from v_evidence_hash
                and (v_target_phone is null
                     or public.normalize_phone(v_existing_crm.customer_phone) is distinct from v_target_phone))) then
      raise exception using errcode = '23505', message = 'message_already_processed_with_different_evidence';
    end if;
    v_crm_id := v_existing_crm.id;
    v_customer_id := v_existing_crm.customer_id;
    v_owner_id := v_existing_crm.org_staff_owner_id;
    v_organization_id := v_existing_crm.organization_id;
    v_due := v_existing_crm.cskh_due_date;
    v_crm_type_id := v_existing_crm.crm_type_id;
    select c.name, c.phone into v_customer_name, v_customer_phone from public.aka_customer c where c.id = v_customer_id;
    select t.stt, t.name into v_priority, v_crm_type_name from public.aka_crm_type t where t.id = v_crm_type_id;
    select os.name into v_owner_name from public.org_staff os where os.id = v_owner_id;
    if p_finalize then
      update public.message_gom g
      set zalo_referral_claim_token = null, zalo_referral_processing_until = null,
          zalo_referral_last_status = 'duplicate', zalo_referral_processed_at = now()
      where g.id = p_message_id and g.zalo_referral_evidence_hash = v_evidence_hash
        and g.zalo_referral_claim_token = p_claim_token and g.zalo_referral_last_status = 'processing'
      returning g.id into v_finalized;
      if v_finalized is null then
        raise exception using errcode = '55000', message = 'zalo_referral_atomic_finalize_failed';
      end if;
    end if;
    return jsonb_build_object('ok', true, 'created', false, 'action', 'duplicate', 'crm_id', v_crm_id,
      'customer_id', v_customer_id, 'customer_name', v_customer_name, 'customer_phone', v_customer_phone,
      'crm_type_id', v_crm_type_id, 'crm_type_name', v_crm_type_name, 'org_staff_owner_id', v_owner_id,
      'organization_id', v_organization_id, 'staff_name', v_owner_name, 'cskh_due_date', v_due,
      'route', v_route, 'pancake_url', v_existing_crm.pancake_url, 'lead_id', v_existing_crm.lead_id);
  end if;

  if v_target_phone is not null then
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('zalo-referral-phone:' || v_target_phone, 0));
    select id into v_phone_customer_id from public.aka_customer
    where public.normalize_phone(phone) = v_target_phone
      and coalesce(record_state, 'active') <> 'merged'
    order by case when account_id = v_account_id then 0 else 1 end, created_at desc nulls last, id desc
    limit 1;
  end if;
  if v_target_uid is not null then
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('zalo-referral-uid:' || v_account_id::text || ':' || lower(v_target_uid), 0));
    select id into v_uid_customer_id from public.aka_customer
    where account_id = v_account_id and lower(btrim(zalo_referral_id)) = lower(v_target_uid)
    order by id desc limit 1;
  end if;
  if v_phone_customer_id is not null and v_uid_customer_id is not null and v_phone_customer_id <> v_uid_customer_id then
    raise exception using errcode = '23505', message = 'zalo_phone_uid_customer_conflict';
  end if;

  if v_route = 'phone_intent' and v_ai_kind = 'SELF_CONSULTATION' then
    if v_referrer_customer_id is null then
      v_customer_id := v_phone_customer_id;
      v_self_phone := true;
    elsif v_phone_customer_id is not null and v_phone_customer_id <> v_referrer_customer_id then
      v_customer_id := v_phone_customer_id;
      v_is_referral := true;
    elsif v_referrer_current_phone is not null
          and public.normalize_phone(v_referrer_current_phone) is distinct from v_target_phone then
      v_customer_id := null;
      v_is_referral := true;
    else
      v_customer_id := v_referrer_customer_id;
      v_self_phone := true;
    end if;

    if v_self_phone and v_referred_by_name is not null and position(' ' in v_referred_by_name) > 0 then
      select count(distinct cid), min(cid) into v_mention_count, v_mention_customer_id
      from (
        select c.id as cid from public.aka_customer c
        where c.account_id = v_account_id and coalesce(c.record_state, 'active') <> 'merged'
          and lower(regexp_replace(btrim(c.name), '[[:space:]]+', ' ', 'g')) = lower(v_referred_by_name)
        union
        select ct.customer_id from public.contacts ct
        where ct.customer_id is not null
          and lower(regexp_replace(btrim(ct.name), '[[:space:]]+', ' ', 'g')) = lower(v_referred_by_name)
      ) x
      where cid is not null and cid is distinct from v_customer_id and cid is distinct from v_referrer_customer_id;
      if v_mention_count = 1 then
        v_referrer_customer_id := v_mention_customer_id;
        select coalesce(nullif(btrim(ac.name), ''), v_referred_by_name), public.normalize_phone(ac.phone)
        into v_referrer_name, v_referrer_phone
        from public.aka_customer ac where ac.id = v_mention_customer_id;
        if v_referrer_phone !~ '^0[1-9][0-9]{8}$' then v_referrer_phone := null; end if;
        v_referrer_uid := null; v_referrer_pancake_uid := null; -- người giới thiệu là bên thứ ba, không phải người đang chat
        v_is_referral := true;
      end if;
    end if;
  else
    v_customer_id := coalesce(v_phone_customer_id, v_uid_customer_id);
  end if;

  if v_customer_id is not null and v_customer_id = v_referrer_customer_id then
    v_is_referral := false;
    v_self_phone := true;
  end if;

  if v_customer_id is not null then
    select nullif(btrim(c.phone), ''), public.normalize_phone(c.phone), nullif(btrim(c.zalo_referral_id), '')
    into v_existing_target_phone_raw, v_existing_target_phone, v_existing_target_uid
    from public.aka_customer c where c.id = v_customer_id;
    if not found then
      raise exception using errcode = '23503', message = 'matched_customer_missing';
    end if;
    if v_target_phone is not null and v_existing_target_phone_raw is not null
       and (v_existing_target_phone is null or v_existing_target_phone is distinct from v_target_phone) then
      raise exception using errcode = '23505', message = 'customer_phone_identity_conflict_review';
    end if;
    if v_target_uid is not null and v_existing_target_uid is not null
       and lower(v_existing_target_uid) is distinct from lower(v_target_uid) then
      raise exception using errcode = '23505', message = 'customer_zalo_identity_conflict_review';
    end if;
  end if;

  if v_customer_id is not null then
    select os.id, os.organization_id, os.name into v_owner_id, v_organization_id, v_owner_name
    from public.aka_customer c join public.org_staff os on os.id = c.org_staff_id_owner
    where c.id = v_customer_id and os.is_active = true;
  end if;
  if v_owner_id is null and p_owner_mode = 'last_staff' and v_gom.conversation_id is not null then
    select os.id, os.organization_id, os.name into v_last_staff_id, v_last_staff_org, v_last_staff_name
    from public.message_gom g2 join public.org_staff os on os.id = g2.answer_org_staff_id
    where g2.conversation_id = v_gom.conversation_id and g2.shop_id is not distinct from v_gom.shop_id
      and g2.answer_org_staff_id is not null and os.is_active = true
    order by coalesce(g2.answer_first_at, g2.created_at) desc limit 1;
    if v_last_staff_id is null then
      select os.id, os.organization_id, os.name into v_last_staff_id, v_last_staff_org, v_last_staff_name
      from public.message_gom g2 join public.org_staff os on os.chat_staff_id = g2.staff_id
      where g2.conversation_id = v_gom.conversation_id and g2.shop_id is not distinct from v_gom.shop_id
        and g2.staff_id is not null and os.is_active = true
      order by g2.created_at desc, os.id limit 1;
    end if;
    if v_last_staff_id is not null then
      v_owner_id := v_last_staff_id; v_organization_id := v_last_staff_org; v_owner_name := v_last_staff_name;
    end if;
  end if;
  if v_owner_id is null and v_referrer_customer_id is not null then
    select os.id, os.organization_id, os.name into v_owner_id, v_organization_id, v_owner_name
    from public.aka_customer c join public.org_staff os on os.id = c.org_staff_id_owner
    where c.id = v_referrer_customer_id and os.is_active = true;
  end if;
  if v_owner_id is null and v_gom.answer_org_staff_id is not null then
    select id, organization_id, name into v_owner_id, v_organization_id, v_owner_name
    from public.org_staff where id = v_gom.answer_org_staff_id and is_active = true;
  end if;
  if v_owner_id is null and v_gom.staff_id is not null then
    select id, organization_id, name into v_owner_id, v_organization_id, v_owner_name
    from public.org_staff where chat_staff_id = v_gom.staff_id and is_active = true order by id limit 1;
  end if;
  if v_owner_id is null and v_gom.contact_id is not null then
    select os.id, os.organization_id, os.name into v_owner_id, v_organization_id, v_owner_name
    from public.contacts c
    cross join lateral unnest(coalesce(c.staff_ids, array[]::text[])) sid(value)
    join public.org_staff os on os.chat_staff_id::text = sid.value
    where c.id = v_gom.contact_id and os.is_active = true order by os.id limit 1;
  end if;
  if v_owner_id is null then
    select os.id, os.organization_id, os.name into v_owner_id, v_organization_id, v_owner_name
    from public.shops s join public.org_staff os on os.id = s.manager_org_staff_id
    where os.is_active = true and (
      s.id = v_gom.shop_id_2
      or (nullif(btrim(v_gom.shop_id), '') is not null and v_gom.shop_id in (s.id::text, nullif(btrim(s.profile_id), ''), nullif(btrim(s.zalo_id), ''), nullif(btrim(s.pancake_page_id), '')))
    )
    order by case when s.id = v_gom.shop_id_2 then 0 else 1 end, s.id limit 1;
  end if;
  if v_owner_id is null then
    select os.id, os.organization_id, os.name into v_owner_id, v_organization_id, v_owner_name
    from public.org_staff os
    where os.is_active = true and os.is_data_division = true
    order by (select count(*) from public.aka_customer owned
              where owned.org_staff_id_owner = os.id
                and owned.created_at >= date_trunc('day', now() at time zone 'Asia/Ho_Chi_Minh') at time zone 'Asia/Ho_Chi_Minh'), os.id
    limit 1;
  end if;
  if v_owner_id is null or v_organization_id is null then
    raise exception using errcode = '22023', message = 'active_owner_not_resolved';
  end if;

  -- ---------------- XÁC MINH TÊN CHỦ SỐ ----------------
  -- Thứ tự: (1) AI verified / danh thiếp Zalo  (2) hồ sơ đã có trong DB theo SĐT (contacts, zalo_users)
  --         (3) SELF: tên người đang chat  (4) fallback = SĐT
  if v_target_name is null and v_target_phone is not null and v_ai_kind = 'REFERRAL_OTHER' then
    select public.fn_zalo_referral_clean_person_name_v1(c.name) into v_db_name
    from public.contacts c
    where c.id is distinct from v_gom.contact_id
      and (public.normalize_phone(c.phone) = v_target_phone
           or exists (select 1 from unnest(coalesce(c.phone_list, array[]::text[])) pl where public.normalize_phone(pl) = v_target_phone))
      and public.fn_zalo_referral_clean_person_name_v1(c.name) is not null
    order by c.updated_at desc nulls last, c.id desc
    limit 1;
    if v_db_name is not null then
      v_target_name := v_db_name; v_target_name_source := 'contacts_by_phone';
    else
      select public.fn_zalo_referral_clean_person_name_v1(coalesce(zu.display_name, zu.zalo_name, zu.username)) into v_db_name
      from public.zalo_users zu
      where public.normalize_phone(zu.phone_number) = v_target_phone
        and public.fn_zalo_referral_clean_person_name_v1(coalesce(zu.display_name, zu.zalo_name, zu.username)) is not null
      order by zu.updated_at desc nulls last, zu.id desc
      limit 1;
      if v_db_name is not null then
        v_target_name := v_db_name; v_target_name_source := 'zalo_users_by_phone';
      end if;
    end if;
  end if;

  if v_target_name is null then
    if v_ai_kind = 'SELF_CONSULTATION' then v_target_name := v_referrer_name; v_target_name_source := 'contact_display_name';
    elsif v_target_phone is not null then v_target_name := v_target_phone; v_target_name_source := 'phone';
    else v_target_name := 'Liên hệ Zalo ' || right(v_target_uid, 6); v_target_name_source := 'zalo_uid';
    end if;
  end if;
  if v_self_phone and v_ai_kind = 'SELF_CONSULTATION' then
    v_target_name := coalesce(nullif(btrim(v_gom.contact_name), ''), v_target_name);
    v_target_name_source := coalesce(v_target_name_source, 'contact_display_name');
  end if;
  v_target_name := left(regexp_replace(v_target_name, '[[:space:]]+', ' ', 'g'), 200);

  if v_customer_id is null then
-- (HÀM CHUNG) tạo hồ sơ khách qua public.fn_upsert_aka_customer_v1 — khóa phone / zalo_uid / pancake_url duy nhất
    v_upsert_res := public.fn_upsert_aka_customer_v1(jsonb_strip_nulls(jsonb_build_object(
      'phone', v_target_phone,
      'zalo_uid', v_target_uid,
      'pancake_url', case when v_ai_kind = 'SELF_CONSULTATION' or v_self_phone then v_pancake_url end,
      'name', v_target_name, 'name_zalo', v_target_name,
      'channel', 'trigger_from_contact', 'account_id', v_account_id, 'source_status_id', 104,
      'org_staff_id', v_owner_id, 'is_split_exempt', true,
      'is_referred', v_is_referral,
      'referrer_id', case when v_is_referral then v_referrer_customer_id end,
      'referrer_phone', case when v_is_referral then v_referrer_phone end,
      'referrer_pancake_url', case when v_is_referral or v_ai_kind = 'REFERRAL_OTHER' then v_pancake_url end,
      'creation_path', 'zalo_chat_referral_v3',
      'custom_fields', jsonb_strip_nulls(jsonb_build_object(
        'message_gom_id', p_message_id::text,
        'pancake_url', v_pancake_url,
        'conversation_id', v_gom.conversation_id,
        'referrer_contact_id', v_gom.contact_id,
        'referrer_name', case when v_is_referral or v_ai_kind = 'REFERRAL_OTHER' then v_referrer_name end,
        'referrer_zalo_uid', case when v_is_referral or v_ai_kind = 'REFERRAL_OTHER' then v_referrer_uid end,
        'referrer_pancake_uid', case when v_is_referral or v_ai_kind = 'REFERRAL_OTHER' then v_referrer_pancake_uid end,
        'referrer_self_name', v_referrer_self_name,
        'referred_by_name_hint', v_referred_by_name,
        'referral_relationship', v_relationship,
        'referral_note', v_ai_note,
        'name_source', v_target_name_source,
        'name_verified', v_target_name_source in ('ai_verified', 'zalo_card', 'contacts_by_phone', 'zalo_users_by_phone'),
        'ai_kind', v_ai_kind,
        'route', v_route))
    )));
    if coalesce((v_upsert_res ->> 'ok')::boolean, false) is not true then
      raise exception using errcode = '22023', message = 'upsert_customer_failed:' || coalesce(v_upsert_res ->> 'error', 'unknown');
    end if;
    v_customer_id := (v_upsert_res ->> 'customer_id')::bigint;
    v_customer_is_new := coalesce((v_upsert_res ->> 'is_new')::boolean, false);
  end if;

  if v_customer_id is null then
    raise exception using errcode = '23505', message = 'customer_identity_conflict';
  end if;

  if not v_customer_is_new then
    select nullif(btrim(c.referrer_pancake_url), '') into v_existing_pancake_url from public.aka_customer c where c.id = v_customer_id;
    update public.aka_customer c
    set name = case
                 -- hồ sơ cũ đang lấy SĐT làm tên mà nay đã xác minh được tên -> cập nhật
                 when (nullif(btrim(c.name), '') is null or public.normalize_phone(c.name) = public.normalize_phone(c.phone) or c.name ~ '^Liên hệ Zalo ')
                      and v_target_name_source in ('ai_verified', 'zalo_card', 'contacts_by_phone', 'zalo_users_by_phone')
                   then v_target_name
                 else coalesce(nullif(btrim(c.name), ''), v_target_name)
               end,
        phone = case when nullif(btrim(c.phone), '') is null then v_target_phone else c.phone end,
        zalo = coalesce(nullif(btrim(c.zalo), ''), v_target_phone, v_target_uid),
        name_zalo = coalesce(nullif(btrim(c.name_zalo), ''), v_target_name),
        zalo_referral_id = case when nullif(btrim(c.zalo_referral_id), '') is null then v_target_uid else c.zalo_referral_id end,
        is_referred = c.is_referred or v_is_referral,
        referrer_id = coalesce(c.referrer_id, case when v_is_referral then v_referrer_customer_id end),
        referrer_phone = coalesce(nullif(btrim(c.referrer_phone), ''), case when v_is_referral then v_referrer_phone end),
        referrer_pancake_url = coalesce(nullif(btrim(c.referrer_pancake_url), ''), case when v_is_referral or v_ai_kind = 'REFERRAL_OTHER' then v_pancake_url end),
        custom_fields = coalesce(c.custom_fields, '{}'::jsonb)
          || jsonb_strip_nulls(jsonb_build_object(
               'pancake_url', coalesce(c.custom_fields ->> 'pancake_url', v_pancake_url),
               'last_pancake_url', v_pancake_url,
               'last_message_gom_id', p_message_id::text,
               'referred_by_name_hint', coalesce(c.custom_fields ->> 'referred_by_name_hint', v_referred_by_name),
               'referrer_name', coalesce(c.custom_fields ->> 'referrer_name', case when (v_is_referral or v_ai_kind = 'REFERRAL_OTHER') and c.referrer_id is null and nullif(btrim(c.referrer_phone), '') is null then v_referrer_name end),
               'referrer_zalo_uid', coalesce(c.custom_fields ->> 'referrer_zalo_uid', case when (v_is_referral or v_ai_kind = 'REFERRAL_OTHER') and (c.referrer_id is null or c.referrer_id = v_referrer_customer_id) then v_referrer_uid end),
               'referrer_pancake_uid', coalesce(c.custom_fields ->> 'referrer_pancake_uid', case when (v_is_referral or v_ai_kind = 'REFERRAL_OTHER') and (c.referrer_id is null or c.referrer_id = v_referrer_customer_id) then v_referrer_pancake_uid end),
               'referrer_contact_id', coalesce(c.custom_fields ->> 'referrer_contact_id', case when (v_is_referral or v_ai_kind = 'REFERRAL_OTHER') and c.referrer_id is null and nullif(btrim(c.referrer_phone), '') is null then v_gom.contact_id::text end),
               'conversation_id', coalesce(c.custom_fields ->> 'conversation_id', v_gom.conversation_id),
               'referral_note', coalesce(c.custom_fields ->> 'referral_note', v_ai_note),
               'last_referral_note', v_ai_note,
               'referral_relationship', coalesce(c.custom_fields ->> 'referral_relationship', v_relationship),
               'name_source', case when v_target_name_source in ('ai_verified', 'zalo_card', 'contacts_by_phone', 'zalo_users_by_phone') then v_target_name_source else c.custom_fields ->> 'name_source' end))
          || case when v_existing_pancake_url is not null and v_existing_pancake_url <> v_pancake_url
                  then jsonb_build_object('pancake_url_conflict', jsonb_build_object('old', v_existing_pancake_url, 'new', v_pancake_url, 'at', now()))
                  else '{}'::jsonb end,
        org_staff_id_owner = coalesce(c.org_staff_id_owner, v_owner_id),
        org_staff_create_id = coalesce(c.org_staff_create_id, v_owner_id),
        org_staff_update_id = v_owner_id,
        updated_at = now()
    where c.id = v_customer_id;
  end if;

  if not v_customer_is_new then
    perform public.fn_upsert_aka_customer_v1(jsonb_strip_nulls(jsonb_build_object(
      'customer_id', v_customer_id, 'phone', v_target_phone, 'zalo_uid', v_target_uid,
      'pancake_url', case when v_ai_kind = 'SELF_CONSULTATION' or v_self_phone then v_pancake_url end,
      'creation_path', 'zalo_chat_referral_v3')));
  end if;

  select nullif(btrim(c.phone), ''), public.normalize_phone(c.phone), nullif(btrim(c.zalo_referral_id), '')
  into v_existing_target_phone_raw, v_existing_target_phone, v_existing_target_uid
  from public.aka_customer c where c.id = v_customer_id for update;
  if not found then
    raise exception using errcode = '23503', message = 'matched_customer_missing';
  end if;
  if v_target_phone is not null and v_existing_target_phone_raw is not null
     and (v_existing_target_phone is null or v_existing_target_phone is distinct from v_target_phone) then
    raise exception using errcode = '23505', message = 'customer_phone_identity_conflict_review';
  end if;
  if v_target_uid is not null and v_existing_target_uid is not null and lower(v_existing_target_uid) is distinct from lower(v_target_uid) then
    raise exception using errcode = '23505', message = 'customer_zalo_identity_conflict_review';
  end if;

  select os.id, os.organization_id, os.name into v_customer_owner_id, v_customer_organization_id, v_customer_owner_name
  from public.aka_customer c join public.org_staff os on os.id = c.org_staff_id_owner
  where c.id = v_customer_id and os.is_active = true;
  if found then
    v_owner_id := v_customer_owner_id; v_organization_id := v_customer_organization_id; v_owner_name := v_customer_owner_name;
  end if;
  select os.organization_id, os.name into v_organization_id, v_owner_name
  from public.org_staff os where os.id = v_owner_id and os.is_active = true for share of os;
  if not found or v_organization_id is null then
    raise exception using errcode = '55000', message = 'active_owner_changed_during_create';
  end if;

  if v_self_phone and v_gom.contact_id is not null then
    update public.contacts
    set phone = coalesce(nullif(btrim(phone), ''), v_target_phone),
        customer_id = coalesce(customer_id, v_customer_id),
        updated_at = now()
    where id = v_gom.contact_id and (nullif(btrim(phone), '') is null or customer_id is null);
  end if;

  -- ---------------- CẬP NHẬT HỒ SƠ NGƯỜI GIỚI THIỆU (Zalo UID, tên) ----------------
  -- Chạy cả khi CRM trùng: mục tiêu là làm giàu hồ sơ người giới thiệu, không phụ thuộc việc tạo CRM.
  if v_is_referral and v_referrer_customer_id is not null and v_referrer_customer_id <> v_customer_id then
    select nullif(btrim(ac.name), '') into v_referrer_current_name from public.aka_customer ac where ac.id = v_referrer_customer_id;
    v_uid_taken := false;
    if v_referrer_uid is not null then
      select exists (
        select 1 from public.aka_customer x
        where x.account_id = v_account_id and x.id <> v_referrer_customer_id
          and lower(btrim(x.zalo_referral_id)) = lower(v_referrer_uid)
      ) into v_uid_taken;
    end if;
    update public.aka_customer r
    set zalo_referral_id = case when nullif(btrim(r.zalo_referral_id), '') is null and v_referrer_uid is not null and not v_uid_taken
                                then v_referrer_uid else r.zalo_referral_id end,
        zalo = case when nullif(btrim(r.zalo), '') is null and v_referrer_uid is not null then v_referrer_uid else r.zalo end,
        name = case when (nullif(btrim(r.name), '') is null or public.normalize_phone(r.name) = public.normalize_phone(r.phone) or r.name ~ '^Liên hệ Zalo ')
                         and v_referrer_self_name is not null
                    then v_referrer_self_name else r.name end,
        name_zalo = coalesce(nullif(btrim(r.name_zalo), ''), nullif(btrim(v_gom.contact_name), '')),
        custom_fields = coalesce(r.custom_fields, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
          'zalo_uid', coalesce(r.custom_fields ->> 'zalo_uid', v_referrer_uid),
          'pancake_uid', coalesce(r.custom_fields ->> 'pancake_uid', v_referrer_pancake_uid),
          'pancake_contact_id', coalesce(r.custom_fields ->> 'pancake_contact_id', v_gom.contact_id::text),
          'zalo_uid_source', case when r.custom_fields ->> 'zalo_uid' is null and v_referrer_uid is not null then 'pancake_contact' end,
          'zalo_uid_conflict', case when v_uid_taken then v_referrer_uid end,
          'pancake_url', coalesce(r.custom_fields ->> 'pancake_url', v_pancake_url))),
        updated_at = now()
    where r.id = v_referrer_customer_id
    returning jsonb_build_object('zalo_referral_id', r.zalo_referral_id, 'name', r.name) into v_referrer_updates;
  end if;

  -- Loại CRM cuối cùng: được giới thiệu (AI REFERRAL_OTHER hoặc đã xác định có người giới thiệu) -> 31; khách chủ động -> 32
  v_crm_type_id := case when v_ai_kind = 'REFERRAL_OTHER' or v_is_referral then 31 else 32 end;
  -- (HÀM CHUNG) link hội thoại này là của NGƯỜI GIỚI THIỆU (người đang chat) -> đăng ký vào hồ sơ người giới thiệu
  if v_is_referral and v_referrer_customer_id is not null and v_referrer_customer_id <> v_customer_id then
    perform public.fn_upsert_aka_customer_v1(jsonb_strip_nulls(jsonb_build_object(
      'customer_id', v_referrer_customer_id, 'pancake_url', v_pancake_url, 'zalo_uid', v_referrer_uid, 'contact_id', v_gom.contact_id)));
  end if;
  select c.name, c.phone into v_customer_name, v_customer_phone from public.aka_customer c where c.id = v_customer_id;
  select t.stt, t.name into v_priority, v_crm_type_name from public.aka_crm_type t where t.id = v_crm_type_id and t.is_active = true;
  if not found then
    raise exception using errcode = '22023', message = 'required_crm_type_inactive';
  end if;

  if not v_customer_is_new then
    select c.created_at, c.custom_fields ->> 'creation_path' into v_cust_created_at, v_cust_path
    from public.aka_customer c where c.id = v_customer_id;
    if v_cust_created_at >= coalesce(v_gom.question_first_at, v_gom.created_at) - interval '1 hour'
       and v_cust_created_at <= coalesce(v_gom.question_first_at, v_gom.created_at) + interval '3 days'
       and coalesce(v_cust_path, '') not like 'zalo_chat_referral%' then
      v_manual_handled := true;
    end if;
  end if;

  if p_create_crm then
  select c.id into v_recent_crm_id from public.aka_crm c
  where c.customer_id = v_customer_id and c.gen_agent = 'zalo-chat-referral-v1'
    and c.created_at > now() - interval '14 days'
  order by c.created_at desc limit 1;
  end if;
  if v_recent_crm_id is not null or v_manual_handled then
    if p_finalize then
      update public.message_gom g
      set zalo_referral_claim_token = null, zalo_referral_processing_until = null,
          zalo_referral_last_status = 'duplicate', zalo_referral_processed_at = now()
      where g.id = p_message_id and g.zalo_referral_evidence_hash = v_evidence_hash
        and g.zalo_referral_claim_token = p_claim_token and g.zalo_referral_last_status = 'processing'
      returning g.id into v_finalized;
      if v_finalized is null then
        raise exception using errcode = '55000', message = 'zalo_referral_atomic_finalize_failed';
      end if;
    end if;
    return jsonb_build_object('ok', true, 'created', false, 'action', case when v_manual_handled then 'duplicate_manual' else 'duplicate_recent' end, 'crm_id', v_recent_crm_id,
      'customer_id', v_customer_id, 'customer_name', v_customer_name, 'customer_phone', v_customer_phone,
      'crm_type_id', v_crm_type_id, 'crm_type_name', v_crm_type_name, 'org_staff_owner_id', v_owner_id,
      'organization_id', v_organization_id, 'staff_name', v_owner_name, 'route', v_route,
      'pancake_url', v_pancake_url, 'customer_is_new', v_customer_is_new,
      'referrer_customer_id', case when v_is_referral then v_referrer_customer_id end,
      'referrer_zalo_uid', case when v_is_referral then v_referrer_uid end,
      'target_name_source', v_target_name_source, 'repeat_of_earlier', v_repeat);
  end if;

  if v_route = 'zalo_contact' then
    v_note := 'Khách hàng được giới thiệu qua danh thiếp Zalo - Người giới thiệu: ' || v_referrer_name;
  elsif v_ai_kind = 'SELF_CONSULTATION' and not v_is_referral then
    v_note := 'Khách hàng để lại SĐT yêu cầu tư vấn qua Zalo chat - Người chat: ' || v_referrer_name;
  elsif v_ai_kind = 'SELF_CONSULTATION' and v_self_phone then
    v_note := 'Khách hàng để lại SĐT yêu cầu tư vấn qua Zalo chat - Được giới thiệu bởi: ' || v_referrer_name;
  else
    v_note := 'Khách hàng được giới thiệu thông qua Zalo chat - Người giới thiệu: ' || v_referrer_name;
  end if;
  if v_relationship is not null and v_ai_kind = 'REFERRAL_OTHER' then
    v_note := v_note || ' (quan hệ: ' || v_relationship || ')';
  end if;
  if v_target_name_source = 'phone' then
    v_note := v_note || E'\nChưa xác minh được tên chủ số - tạm lấy SĐT làm tên.';
  elsif v_target_name_source in ('contacts_by_phone', 'zalo_users_by_phone') then
    v_note := v_note || E'\nTên chủ số lấy từ hồ sơ Zalo đã có trong hệ thống.';
  end if;
  if v_ai_note is not null then
    v_note := v_note || E'\nGhi chú AI: ' || v_ai_note;
  end if;
  if v_repeat then
    v_note := v_note || E'\nLưu ý: số/yêu cầu này đã xuất hiện trước đó trong hội thoại.';
  end if;
  v_note := v_note || E'\nLink Pancake: ' || v_pancake_url;
  v_due := private.zalo_referral_due_date_v1(now());

  insert into public.aka_lead (
    name, phone, phone_norm, type_source, source, akacustomer_id, organization_id, status, refe, note,
    pancake_url, raw_payload, source_occurred_at
  ) values (
    v_target_name, v_target_phone, v_target_phone, 'zalo_chat_referral', 'pancake', v_customer_id, v_organization_id, 'new',
    case when v_is_referral then v_referrer_name else v_referred_by_name end, v_note, v_pancake_url,
    jsonb_strip_nulls(jsonb_build_object(
      'source_type', v_source_type,
      'message_gom_id', p_message_id::text,
      'route', v_route,
      'ai_kind', v_ai_kind,
      'ai_confidence', v_ai_confidence,
      'ai_log_id', p_ai_log_id,
      'referrer_customer_id', case when v_is_referral then v_referrer_customer_id end,
      'referrer_phone', case when v_is_referral then v_referrer_phone end,
      'referrer_zalo_uid', case when v_is_referral then v_referrer_uid end,
      'referred_by_name_hint', v_referred_by_name,
      'relationship', v_relationship,
      'target_name_source', v_target_name_source,
      'pancake_url', v_pancake_url,
      'conversation_id', v_gom.conversation_id,
      'target_zalo_uid', v_target_uid
    )),
    coalesce(v_gom.question_first_at, v_gom.created_at)
  )
  on conflict do nothing
  returning id into v_lead_id;
  v_lead_created := v_lead_id is not null;
  if v_lead_id is null then
    select id into v_lead_id from public.aka_lead
    where type_source = 'zalo_chat_referral' and raw_payload ->> 'source_type' = v_source_type
    order by id desc limit 1;
  end if;

  if p_create_crm then
  insert into public.aka_crm (
    customer_id, customer_name, customer_phone, crm_type_id, priority, org_staff_owner_id, organization_id,
    created_by, note, cskh_due_date, is_read, source_order_id, source_type, sql_account_id,
    gen_agent, gen_status, gen_at, gen_meta, pancake_url, lead_id, suggested_channel_id
  ) values (
    v_customer_id, v_customer_name, v_customer_phone, v_crm_type_id, v_priority, v_owner_id, v_organization_id,
    v_owner_id, v_note, v_due, false, v_customer_id, v_source_type, v_account_id,
    'zalo-chat-referral-v1', 'created', now(),
    jsonb_strip_nulls(jsonb_build_object(
      'version', 'v3',
      'message_gom_id', p_message_id::text,
      'route', v_route,
      'evidence_hash', v_evidence_hash,
      'phone_index', v_phone_idx,
      'phones_total', cardinality(v_phones),
      'ai_log_id', p_ai_log_id,
      'ai_kind', v_ai_kind,
      'ai_confidence', v_ai_confidence,
      'ai_note', v_ai_note,
      'relationship', v_relationship,
      'repeat_of_earlier', v_repeat,
      'target_name_source', v_target_name_source,
      'target_name_confidence', v_target_name_conf,
      'referrer_customer_id', case when v_is_referral then v_referrer_customer_id end,
      'referrer_contact_id', v_gom.contact_id,
      'referrer_name', case when v_is_referral then v_referrer_name end,
      'referrer_phone_last4', case when v_is_referral and v_referrer_phone is not null then right(v_referrer_phone, 4) end,
      'referred_by_name_hint', v_referred_by_name,
      'referrer_zalo_uid', v_referrer_uid,
      'referrer_pancake_uid', v_referrer_pancake_uid,
      'target_zalo_uid', v_target_uid,
      'target_phone_last4', case when v_target_phone is not null then right(v_target_phone, 4) end,
      'pancake_url', v_pancake_url,
      'lead_id', v_lead_id,
      'customer_is_new', v_customer_is_new,
      'raw_card_message_id', v_card ->> 'raw_message_id'
    )),
    v_pancake_url, v_lead_id, 8 -- suggested_channel_id: inbox_zalo (bắt buộc nhắn Zalo)
  )
  on conflict do nothing
  returning id into v_crm_id;

  if v_crm_id is not null then
    v_created := true;
  else
    select * into v_existing_crm from public.aka_crm
    where source_type like 'zalo_referral:%' and source_type = v_source_type order by id desc limit 1;
    if found then
      if v_existing_crm.customer_id is distinct from v_customer_id
         or (v_existing_crm.crm_type_id is distinct from v_crm_type_id and v_existing_crm.crm_type_id not in (1, 5, 31, 32))
         or (v_existing_crm.gen_meta ->> 'evidence_hash') is distinct from v_evidence_hash then
        raise exception using errcode = '23505', message = 'crm_idempotency_identity_conflict';
      end if;
      v_crm_id := v_existing_crm.id;
    end if;
  end if;
  if v_crm_id is null then
    raise exception using errcode = '23505', message = 'crm_idempotency_conflict';
  end if;
  else
    v_created := v_lead_created;
  end if;

  if v_created and v_is_referral and v_referrer_customer_id is not null and v_referrer_customer_id <> v_customer_id then
    update public.aka_customer r
    set referral_count = coalesce(r.referral_count, 0) + 1,
        custom_fields = coalesce(r.custom_fields, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
          'last_referral_at', now(),
          'last_referral_pancake_url', v_pancake_url,
          'last_referred_customer_id', v_customer_id,
          'last_referral_message_gom_id', p_message_id::text,
          'pancake_url', coalesce(r.custom_fields ->> 'pancake_url', v_pancake_url))),
        updated_at = now()
    where r.id = v_referrer_customer_id;
  end if;

  if p_finalize then
    update public.message_gom g
    set zalo_referral_claim_token = null, zalo_referral_processing_until = null,
        zalo_referral_last_status = case when v_created then 'created' else 'duplicate' end,
        zalo_referral_processed_at = now()
    where g.id = p_message_id and g.zalo_referral_evidence_hash = v_evidence_hash
      and g.zalo_referral_claim_token = p_claim_token and g.zalo_referral_last_status = 'processing'
    returning g.id into v_finalized;
    if v_finalized is null then
      raise exception using errcode = '55000', message = 'zalo_referral_atomic_finalize_failed';
    end if;
  end if;

  return jsonb_build_object(
    'ok', true, 'created', v_created, 'action', case when v_created then 'created' else 'duplicate' end,
    'crm_id', v_crm_id, 'lead_id', v_lead_id, 'customer_id', v_customer_id, 'customer_is_new', v_customer_is_new,
    'customer_name', v_customer_name, 'customer_phone', v_customer_phone,
    'crm_type_id', v_crm_type_id, 'crm_type_name', v_crm_type_name,
    'org_staff_owner_id', v_owner_id, 'organization_id', v_organization_id, 'staff_name', v_owner_name,
    'cskh_due_date', v_due, 'route', v_route, 'ai_kind', v_ai_kind,
    'pancake_url', v_pancake_url, 'phone_index', v_phone_idx,
    'referrer_customer_id', case when v_is_referral then v_referrer_customer_id end,
    'referrer_zalo_uid', case when v_is_referral then v_referrer_uid end,
    'referrer_updates', v_referrer_updates,
    'referred_by_name_hint', v_referred_by_name,
    'target_name_source', v_target_name_source,
    'repeat_of_earlier', v_repeat,
    'lead_created', v_lead_created,
    'create_crm', p_create_crm,
    'owner_mode', p_owner_mode,
    'target_zalo_uid', v_target_uid
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_zalo_contact_card_self_update_v1(p_message_id uuid, p_evidence_hash text, p_claim_token uuid, p_ai_log_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_gom public.message_gom%rowtype;
  v_evidence jsonb;
  v_card jsonb;
  v_ai public.ai_log%rowtype;
  v_verdict jsonb;
  v_uid text;
  v_phone text;
  v_name text;
  v_customer_id bigint;
  v_contact_customer_id bigint;
  v_phone_owner_id bigint;
  v_existing_uid text;
  v_existing_phone text;
  v_updated boolean := false;
  v_reason text;
  v_finalized uuid;
begin
  if current_user not in ('postgres', 'service_role') then
    raise exception using errcode = '42501', message = 'zalo_referral_backend_only';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('zalo-referral-message:' || p_message_id::text, 0));

  select * into v_gom from public.message_gom where id = p_message_id for update;
  if not found or upper(coalesce(v_gom.initiated_by, '')) <> 'CUSTOMER' or lower(btrim(coalesce(v_gom.source, ''))) <> 'pancake' then
    raise exception using errcode = '22023', message = 'invalid_customer_message';
  end if;
  if p_claim_token is null
     or v_gom.zalo_referral_claim_token is distinct from p_claim_token
     or v_gom.zalo_referral_evidence_hash is distinct from p_evidence_hash
     or v_gom.zalo_referral_last_status is distinct from 'processing'
     or v_gom.zalo_referral_processing_until is null
     or v_gom.zalo_referral_processing_until <= now() then
    raise exception using errcode = '55000', message = 'zalo_referral_processing_lease_invalid';
  end if;

  v_evidence := public.fn_zalo_chat_referral_evidence_v1(p_message_id);
  if v_evidence is null or (v_evidence ->> 'route') is distinct from 'zalo_contact'
     or (v_evidence ->> 'evidence_hash') is distinct from p_evidence_hash then
    raise exception using errcode = '22023', message = 'zalo_referral_evidence_changed';
  end if;
  v_card := v_evidence -> 'card';
  v_uid := nullif(btrim(v_card ->> 'contact_uid'), '');
  v_phone := public.normalize_phone(v_card ->> 'phone_number');
  if v_phone !~ '^0[1-9][0-9]{8}$' then v_phone := null; end if;
  v_name := left(regexp_replace(coalesce(nullif(btrim(v_card ->> 'contact_name'), ''), ''), '[[:space:]]+', ' ', 'g'), 200);
  if v_uid is null then
    raise exception using errcode = '22023', message = 'invalid_zalo_contact_identity';
  end if;

  select * into v_ai from public.ai_log
  where id = p_ai_log_id
    and using_code = 'zalo_chat_referral_verify_v1'
    and block_name = 'zalo-chat-referral-precreate-v1'
    and node_id = 'zalo-referral:' || p_message_id::text
    and status = 'success';
  if not found
     or (v_ai.sanitized_request ->> 'message_id') is distinct from p_message_id::text
     or (v_ai.sanitized_request ->> 'route') is distinct from 'zalo_contact'
     or (v_ai.sanitized_request ->> 'evidence_hash') is distinct from p_evidence_hash then
    raise exception using errcode = '22023', message = 'ai_verdict_not_approved';
  end if;
  v_verdict := v_ai.sanitized_response -> 'card_verdict';
  if v_verdict is null or coalesce(v_verdict ->> 'kind', '') <> 'SELF_CARD'
     or jsonb_typeof(v_verdict -> 'confidence') is distinct from 'number'
     or (v_verdict ->> 'confidence')::numeric < 0.80 then
    raise exception using errcode = '22023', message = 'ai_verdict_not_approved';
  end if;

  -- Hồ sơ người đang chat: message_gom.aka_customer_id > contacts.customer_id > hồ sơ có SĐT trên danh thiếp
  select c.customer_id into v_contact_customer_id from public.contacts c where c.id = v_gom.contact_id;
  v_customer_id := coalesce(v_gom.aka_customer_id, v_contact_customer_id);
  if v_customer_id is not null then
    perform 1 from public.aka_customer where id = v_customer_id and coalesce(record_state, 'active') <> 'merged';
    if not found then v_customer_id := null; end if;
  end if;
  if v_customer_id is null and v_phone is not null then
    select id into v_customer_id from public.aka_customer
    where public.normalize_phone(phone) = v_phone and coalesce(record_state, 'active') <> 'merged'
    order by case when account_id = coalesce(v_gom.account_id, 1001) then 0 else 1 end, created_at desc nulls last, id desc limit 1;
  end if;
  if v_customer_id is null and v_uid is not null then
    select id into v_customer_id from public.aka_customer
    where lower(btrim(zalo_referral_id)) = lower(v_uid) and coalesce(record_state, 'active') <> 'merged'
    order by id desc limit 1;
  end if;

  if v_customer_id is null then
    v_reason := 'sender_customer_missing';
  else
    select nullif(btrim(zalo_referral_id), ''), public.normalize_phone(phone) into v_existing_uid, v_existing_phone
    from public.aka_customer where id = v_customer_id for update;
    if v_existing_uid is not null and lower(v_existing_uid) <> lower(v_uid) then
      -- không ghi đè; ghi nhận xung đột để review
      update public.aka_customer c
      set custom_fields = coalesce(c.custom_fields, '{}'::jsonb) || jsonb_build_object('zalo_uid_conflict',
            jsonb_build_object('existing', v_existing_uid, 'card', v_uid, 'message_gom_id', p_message_id::text, 'at', now())),
          updated_at = now()
      where c.id = v_customer_id;
      v_reason := 'zalo_uid_conflict';
    else
      -- SĐT trên danh thiếp chỉ điền khi hồ sơ chưa có số và không hồ sơ nào khác đang giữ số đó
      if v_phone is not null then
        select id into v_phone_owner_id from public.aka_customer
        where public.normalize_phone(phone) = v_phone and coalesce(record_state, 'active') <> 'merged' and id <> v_customer_id limit 1;
      end if;
      update public.aka_customer c
      set zalo_referral_id = coalesce(nullif(btrim(c.zalo_referral_id), ''), v_uid),
          zalo = coalesce(nullif(btrim(c.zalo), ''), v_phone, v_uid),
          name_zalo = coalesce(nullif(btrim(c.name_zalo), ''), nullif(v_name, '')),
          phone = case when nullif(btrim(c.phone), '') is null and v_phone is not null and v_phone_owner_id is null then v_phone else c.phone end,
          custom_fields = coalesce(c.custom_fields, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
            'zalo_guid', coalesce(c.custom_fields ->> 'zalo_guid', nullif(btrim(v_card ->> 'guid'), '')),
            'zalo_card_name', coalesce(c.custom_fields ->> 'zalo_card_name', nullif(v_name, '')),
            'zalo_card_avatar', coalesce(c.custom_fields ->> 'zalo_card_avatar', nullif(btrim(v_card ->> 'contact_avatar'), '')),
            'zalo_card_qr_url', coalesce(c.custom_fields ->> 'zalo_card_qr_url', nullif(btrim(v_card ->> 'qr_code_url'), '')),
            'zalo_self_card_message_gom_id', p_message_id::text,
            'zalo_self_card_at', now(),
            'zalo_self_card_ai_log_id', p_ai_log_id)),
          updated_at = now()
      where c.id = v_customer_id;
      v_updated := true;
      if v_gom.contact_id is not null then
        update public.contacts
        set customer_id = coalesce(customer_id, v_customer_id),
            phone = coalesce(nullif(btrim(phone), ''), case when v_phone_owner_id is null then v_phone end),
            updated_at = now()
        where id = v_gom.contact_id and (customer_id is null or nullif(btrim(phone), '') is null);
      end if;
    end if;
  end if;

  update public.message_gom g
  set zalo_referral_claim_token = null, zalo_referral_processing_until = null,
      zalo_referral_last_status = 'self_card', zalo_referral_processed_at = now()
  where g.id = p_message_id and g.zalo_referral_evidence_hash = p_evidence_hash
    and g.zalo_referral_claim_token = p_claim_token and g.zalo_referral_last_status = 'processing'
  returning g.id into v_finalized;
  if v_finalized is null then
    raise exception using errcode = '55000', message = 'zalo_referral_atomic_finalize_failed';
  end if;

  return jsonb_build_object('ok', true, 'action', 'self_card', 'updated', v_updated, 'customer_id', v_customer_id,
    'reason', v_reason, 'zalo_uid', v_uid, 'has_phone', v_phone is not null);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_staff_zalo_runtime_mode(p_staff_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_organization_id bigint;
  v_mode record;
BEGIN
  IF p_staff_id IS NULL OR p_staff_id <= 0 THEN
    RAISE EXCEPTION 'Staff ID must be a positive integer';
  END IF;

  SELECT staff.organization_id
  INTO v_organization_id
  FROM public.aka_agent_staff_runtime_profile AS staff
  WHERE staff.id = p_staff_id
    AND staff.is_active = true AND public.aka_agent_staff_time_allowed(staff.id);

  IF NOT FOUND OR v_organization_id IS NULL THEN
    RAISE EXCEPTION 'Active staff % was not found', p_staff_id;
  END IF;

  SELECT * INTO v_mode
  FROM public.resolve_organization_zalo_runtime_mode(v_organization_id);

  RETURN jsonb_build_object(
    'staff_id', p_staff_id,
    'is_zalo_server', COALESCE(v_mode.is_zalo_server, false),
    'is_zalo_show_web', COALESCE(v_mode.web_enabled, false),
    'zalo_qr_enabled', COALESCE(v_mode.qr_enabled, false),
    'zalo_web_enabled', COALESCE(v_mode.web_enabled, false),
    'revision', COALESCE(v_mode.mode_revision, 'none:' || v_organization_id::text)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.lock_auto_account_control_resources()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_old_account_group_id bigint;
  v_old_proxy_id bigint;
  v_lock_key bigint;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    v_old_account_group_id := OLD.account_group_id;
    v_old_proxy_id := OLD.proxy_id;
  END IF;

  FOR v_lock_key IN
    SELECT DISTINCT resource.lock_key
    FROM (
      VALUES
        (CASE WHEN v_old_account_group_id IS NULL THEN NULL ELSE hashtextextended(
          'control-zalo-account-group:' || v_old_account_group_id::text, 0
        ) END),
        (CASE WHEN NEW.account_group_id IS NULL THEN NULL ELSE hashtextextended(
          'control-zalo-account-group:' || NEW.account_group_id::text, 0
        ) END),
        (CASE WHEN v_old_proxy_id IS NULL THEN NULL ELSE hashtextextended(
          'control-zalo-proxy:' || v_old_proxy_id::text, 0
        ) END),
        (CASE WHEN NEW.proxy_id IS NULL THEN NULL ELSE hashtextextended(
          'control-zalo-proxy:' || NEW.proxy_id::text, 0
        ) END)
    ) AS resource(lock_key)
    WHERE resource.lock_key IS NOT NULL
    ORDER BY resource.lock_key
  LOOP
    PERFORM pg_advisory_xact_lock_shared(v_lock_key);
  END LOOP;

  -- A reference that waited behind a soft delete must fail rather than attach
  -- to a resource that became invisible while it was blocked on the lock.
  IF NOT COALESCE(NEW.is_delete, false)
    AND NEW.account_group_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.auto_account_groups AS account_group
      WHERE account_group.id = NEW.account_group_id
        AND COALESCE(account_group.is_delete, false) = false
    )
  THEN
    RAISE EXCEPTION 'account_group_not_found';
  END IF;
  IF NOT COALESCE(NEW.is_delete, false)
    AND NEW.proxy_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.auto_proxies AS proxy
      WHERE proxy.id = NEW.proxy_id
        AND COALESCE(proxy.is_delete, false) = false
    )
  THEN
    RAISE EXCEPTION 'proxy_not_found';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.populate_crm_expiration_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_date_text text;
  v_match text[];
  v_day integer;
  v_month integer;
  v_year integer;
begin
  if tg_op = 'UPDATE'
     and old.source_expiration_date is not null
     and new.source_expiration_date is distinct from old.source_expiration_date then
    raise exception using
      errcode = 'P0001',
      message = 'crm_source_expiration_snapshot_immutable';
  end if;

  if new.crm_type_id not in (3, 4)
     or new.source_expiration_date is not null then
    return new;
  end if;

  if new.source_order_id is not null then
    select (source_order.date_expiration at time zone 'Asia/Ho_Chi_Minh')::date
    into new.source_expiration_date
    from public.aka_order as source_order
    where source_order.id = new.source_order_id
      and source_order.date_expiration is not null;

    if new.source_expiration_date is not null then
      new.source_expiration_source := case
        when tg_op = 'INSERT' then 'aka_order_snapshot'
        else 'aka_order_backfill'
      end;
      return new;
    end if;
  end if;

  if new.org_organization_product_id is not null then
    select (source_product.expiration_date at time zone 'Asia/Ho_Chi_Minh')::date
    into new.source_expiration_date
    from public.org_organization_product as source_product
    where source_product.id = new.org_organization_product_id
      and source_product.expiration_date is not null;

    if new.source_expiration_date is not null then
      new.source_expiration_source := case
        when tg_op = 'INSERT' then 'org_product_snapshot'
        else 'org_product_backfill'
      end;
      return new;
    end if;
  end if;

  -- Only parse a date immediately following the explicit Vietnamese label.
  -- This avoids treating payment dates, due dates or arbitrary note numbers as
  -- the product expiration snapshot.
  v_match := pg_catalog.regexp_match(
    coalesce(new.note, ''),
    '(?i)ngày[[:space:]]+hết[[:space:]]+hạn[[:space:]]*:[[:space:]]*([0-9]{1,2}/[0-9]{1,2}/[0-9]{4}|[0-9]{4}-[0-9]{1,2}-[0-9]{1,2})'
  );
  v_date_text := v_match[1];

  if v_date_text is null then
    return new;
  end if;

  begin
    if v_date_text ~ '^[0-9]{4}-' then
      v_year := pg_catalog.split_part(v_date_text, '-', 1)::integer;
      v_month := pg_catalog.split_part(v_date_text, '-', 2)::integer;
      v_day := pg_catalog.split_part(v_date_text, '-', 3)::integer;
    else
      v_day := pg_catalog.split_part(v_date_text, '/', 1)::integer;
      v_month := pg_catalog.split_part(v_date_text, '/', 2)::integer;
      v_year := pg_catalog.split_part(v_date_text, '/', 3)::integer;
    end if;

    new.source_expiration_date := pg_catalog.make_date(v_year, v_month, v_day);
    new.source_expiration_source := case
      when tg_op = 'INSERT' then 'note_label_snapshot'
      else 'note_label_backfill'
    end;
  exception
    when datetime_field_overflow or invalid_datetime_format then
      new.source_expiration_date := null;
      new.source_expiration_source := null;
  end;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.prevent_delete_account_group_with_accounts()
