CREATE OR REPLACE FUNCTION public.reassign_org_staff_chat_staff(p_target_org_staff_id bigint, p_chat_staff_id uuid)
 RETURNS TABLE(status text, target_org_staff_id bigint, previous_org_staff_ids bigint[], chat_staff_id uuid)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  c_akabiz_organization_id constant bigint := 1;
  c_chat_account_id constant integer := 1001;
  v_current_chat_staff_id uuid;
  v_previous_org_staff_ids bigint[] := '{}'::bigint[];
  v_status text;
  v_updated_at timestamp with time zone := pg_catalog.statement_timestamp();
begin
  -- Fail before taking the UUID-scoped lock when the target cannot be valid.
  if not exists (
    select 1
    from public.org_staff as target
    where target.id = p_target_org_staff_id
      and target.organization_id = c_akabiz_organization_id
  ) then
    raise exception using
      errcode = 'P0002',
      message = 'org_staff_target_not_found';
  end if;

  if p_chat_staff_id is not null then
    -- Serialize every reassignment of the same chat UUID, including requests
    -- whose source and target org_staff rows differ.
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'org_staff_chat_staff:' || p_chat_staff_id::text,
        0
      )
    );

    -- Hold the selected staffs row through the org_staff updates so its
    -- account/deleted eligibility cannot change after validation.
    perform chat_staff.id
    from public.staffs as chat_staff
    where chat_staff.id = p_chat_staff_id
      and chat_staff.account_id = c_chat_account_id
      and coalesce(chat_staff.is_delete, false) = false
    for update of chat_staff;

    if not found then
      raise exception using
        errcode = '22023',
        message = 'chat_staff_not_found_or_ineligible';
    end if;
  end if;

  -- Every transaction locks the same affected set in ascending primary-key
  -- order. UUID ownership is global, while the target remains scoped to the
  -- akaBiz organization.
  perform staff.id
  from public.org_staff as staff
  where (
      staff.id = p_target_org_staff_id
      and staff.organization_id = c_akabiz_organization_id
    )
    or (
      p_chat_staff_id is not null
      and staff.chat_staff_id = p_chat_staff_id
    )
  order by staff.id
  for update of staff;

  -- Recheck after the row locks in case the target was removed between the
  -- initial validation and lock acquisition.
  select target.chat_staff_id
  into v_current_chat_staff_id
  from public.org_staff as target
  where target.id = p_target_org_staff_id
    and target.organization_id = c_akabiz_organization_id;

  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'org_staff_target_not_found';
  end if;

  if p_chat_staff_id is null then
    if v_current_chat_staff_id is null then
      v_status := 'unchanged';
    else
      v_previous_org_staff_ids := array[p_target_org_staff_id]::bigint[];

      update public.org_staff as target
      set
        chat_staff_id = null,
        updated_at = v_updated_at
      where target.id = p_target_org_staff_id
        and target.organization_id = c_akabiz_organization_id;

      v_status := 'cleared';
    end if;
  elsif v_current_chat_staff_id = p_chat_staff_id then
    v_status := 'unchanged';
  else
    select coalesce(
      pg_catalog.array_agg(owner.id order by owner.id),
      '{}'::bigint[]
    )
    into v_previous_org_staff_ids
    from public.org_staff as owner
    where owner.chat_staff_id = p_chat_staff_id
      and owner.id <> p_target_org_staff_id;

    update public.org_staff as owner
    set
      chat_staff_id = null,
      updated_at = v_updated_at
    where owner.chat_staff_id = p_chat_staff_id
      and owner.id <> p_target_org_staff_id;

    update public.org_staff as target
    set
      chat_staff_id = p_chat_staff_id,
      updated_at = v_updated_at
    where target.id = p_target_org_staff_id
      and target.organization_id = c_akabiz_organization_id;

    v_status := 'reassigned';
  end if;

  return query
  select
    v_status,
    p_target_org_staff_id,
    v_previous_org_staff_ids,
    p_chat_staff_id;
end
$function$

CREATE OR REPLACE FUNCTION public.reconcile_auto_automation_enqueue_failures(p_staff_id bigint, p_organization_id bigint, p_worker_id text, p_limit integer DEFAULT 100, p_auth_username text DEFAULT NULL::text, p_auth_password text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_base jsonb;
  v_detail record;
  v_outcome jsonb;
  v_processed integer := 0;
  v_completed integer := 0;
  v_skipped integer := 0;
  v_failed integer := 0;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 500);
BEGIN
  v_base := public.reconcile_auto_automation_enqueue_failures_v185_internal(
    p_staff_id, p_organization_id, p_worker_id, p_limit,
    p_auth_username, p_auth_password
  );

  FOR v_detail IN
    SELECT detail.id
    FROM public.auto_automation_detail AS detail
    WHERE detail.staff_id = p_staff_id AND detail.organization_id = p_organization_id
      AND detail.status = 'đã thêm'
      AND detail.target_data_group_id IS NOT NULL
      AND detail.target_data_group_member_id IS NULL
      AND COALESCE(detail.target_data_group_sync_status, 'pending') IN ('pending', 'failed')
    ORDER BY detail.processed_at, detail.id
    LIMIT v_limit
  LOOP
    v_processed := v_processed + 1;
    v_outcome := public.aka_agent_ingest_automation_data_group_result(
      p_staff_id, p_organization_id, v_detail.id
    );
    CASE v_outcome ->> 'code'
      WHEN 'completed' THEN v_completed := v_completed + 1;
      WHEN 'skipped' THEN v_skipped := v_skipped + 1;
      ELSE v_failed := v_failed + 1;
    END CASE;
  END LOOP;

  RETURN COALESCE(v_base, '{}'::jsonb) || jsonb_build_object(
    'data_group_processed', v_processed,
    'data_group_completed', v_completed,
    'data_group_skipped', v_skipped,
    'data_group_failed', v_failed
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_auto_automation_enqueue_failures_v185_internal(p_staff_id bigint, p_organization_id bigint, p_worker_id text, p_limit integer DEFAULT 100, p_auth_username text DEFAULT NULL::text, p_auth_password text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_failure record;
  v_processed integer := 0;
  v_resolved integer := 0;
  v_failed integer := 0;
  v_pending integer := 0;
  v_success boolean;
  v_error text;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 500);
BEGIN
  PERFORM public.auto_assert_automation_identity(
    p_staff_id,
    p_organization_id,
    p_auth_username,
    p_auth_password
  );

  IF NULLIF(btrim(COALESCE(p_worker_id, '')), '') IS NULL
    OR length(btrim(p_worker_id)) > 200 THEN
    RAISE EXCEPTION 'invalid_automation_worker_id';
  END IF;

  FOR v_failure IN
    SELECT failure.id
    FROM public.auto_automation_enqueue_failures AS failure
    WHERE failure.staff_id = p_staff_id
      AND failure.organization_id = p_organization_id
      AND failure.status = 'pending'
      AND failure.next_attempt_at <= clock_timestamp()
    ORDER BY failure.event_at ASC, failure.id ASC
    FOR UPDATE OF failure SKIP LOCKED
    LIMIT v_limit
  LOOP
    v_processed := v_processed + 1;

    UPDATE public.auto_automation_enqueue_failures AS failure
    SET
      attempt_count = failure.attempt_count + 1,
      updated_at = clock_timestamp()
    WHERE failure.id = v_failure.id;

    BEGIN
      v_success := public.auto_retry_automation_enqueue_failure_internal(
        v_failure.id
      );

      IF v_success THEN
        v_resolved := v_resolved + 1;
      ELSE
        v_failed := v_failed + 1;
        UPDATE public.auto_automation_enqueue_failures AS failure
        SET
          next_attempt_at = clock_timestamp() + interval '30 seconds',
          updated_at = clock_timestamp()
        WHERE failure.id = v_failure.id
          AND failure.status = 'pending';
      END IF;
    EXCEPTION
      WHEN OTHERS THEN
        v_error := SQLERRM;
        v_failed := v_failed + 1;
        UPDATE public.auto_automation_enqueue_failures AS failure
        SET
          status = 'pending',
          next_attempt_at = clock_timestamp() + interval '30 seconds',
          last_error = left(v_error, 2000),
          resolved_at = NULL,
          updated_at = clock_timestamp()
        WHERE failure.id = v_failure.id;
    END;
  END LOOP;

  SELECT count(*)::integer
  INTO v_pending
  FROM public.auto_automation_enqueue_failures AS failure
  WHERE failure.staff_id = p_staff_id
    AND failure.organization_id = p_organization_id
    AND failure.status = 'pending';

  RETURN jsonb_build_object(
    'processed', v_processed,
    'resolved', v_resolved,
    'failed', v_failed,
    'pending', v_pending,
    'worker_id', btrim(p_worker_id)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_renewal_crm_pending(p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_customer bigint;
  v_owner bigint;
  v_source bigint;
  v_crm_id bigint;
  v_expiration date;
  v_offset integer;
  v_type integer;
  v_event text;
  v_pending public.aka_app_settings%rowtype;
  v_crm public.aka_crm%rowtype;
  v_order public.aka_order%rowtype;
  v_customer_row public.aka_customer%rowtype;
  v_staff public.org_staff%rowtype;
  v_count integer;
begin
  if current_user not in ('postgres','supabase_admin','service_role') then raise exception 'renewal_reconcile_service_role_required' using errcode='42501'; end if;
  if not exists(select 1 from public.aka_app_settings where key='renewal_crm' and value->>'enabled'='true') then
    return jsonb_build_object('status','disabled');
  end if;
  if jsonb_typeof(p_request) is distinct from 'object' or jsonb_typeof(p_request->'expectedPending') is distinct from 'object'
    or coalesce(p_request->>'customerId','')!~'^[1-9][0-9]{0,15}$' or coalesce(p_request->>'ownerId','')!~'^[1-9][0-9]{0,15}$'
    or coalesce(p_request->>'sourceId','')!~'^[1-9][0-9]{0,15}$' or coalesce(p_request->>'crmId','')!~'^[1-9][0-9]{0,15}$'
    or coalesce(p_request->>'expirationDay','')!~'^\d{4}-\d{2}-\d{2}$'
    or coalesce(p_request->>'offsetDays','') not in ('-7','0') or coalesce(p_request->>'crmTypeId','') not in ('3','4') then
    return jsonb_build_object('status','review','reason','reconcile_invalid_request');
  end if;
  v_customer:=(p_request->>'customerId')::bigint;v_owner:=(p_request->>'ownerId')::bigint;
  v_source:=(p_request->>'sourceId')::bigint;v_crm_id:=(p_request->>'crmId')::bigint;
  begin
    v_expiration:=(p_request->>'expirationDay')::date;
  exception when datetime_field_overflow or invalid_datetime_format then
    return jsonb_build_object('status','review','reason','reconcile_invalid_request');
  end;
  v_offset:=(p_request->>'offsetDays')::integer;v_type:=(p_request->>'crmTypeId')::integer;
  v_event:='renewal_crm_v1:sql:'||v_source||':'||v_expiration||':'||case when v_type=4 then 'paid' else 'demo' end||':'||v_offset;
  if p_request->>'pendingKey' is distinct from 'renewal:pending:sql:'||v_source or p_request->>'eventKey' is distinct from v_event
    or (v_type=3 and v_offset<>0) or v_expiration+v_offset>(statement_timestamp() at time zone 'Asia/Ho_Chi_Minh')::date then
    return jsonb_build_object('status','review','reason','reconcile_event_mismatch');
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('renewal-crm-customer:'||v_customer,0));
  select * into v_customer_row from public.aka_customer where id=v_customer for share;
  if not found or v_customer_row.record_state is distinct from 'verified' or v_customer_row.merged_into_customer_id is not null
    or v_customer_row.custormer_id_old is null or v_customer_row.custormer_id_old<=0 then
    return jsonb_build_object('status','review','reason','reconcile_customer_changed');
  end if;
  select * into v_staff from public.org_staff where id=v_owner for share;
  if not found or v_staff.is_active is distinct from true or v_staff.deleted_at is not null then
    return jsonb_build_object('status','review','reason','reconcile_owner_changed');
  end if;
  select count(*) into v_count from public.aka_order o where o.account_id_old=v_source
    or (o.source_system='sql_account' and o.source_record_id=v_source);
  if v_count<>1 then return jsonb_build_object('status','review','reason','reconcile_source_ambiguous'); end if;
  select * into v_order from public.aka_order o where o.source_system='sql_account'
    and o.account_id_old=v_source and o.source_record_id=v_source for share;
  if not found or v_order.customer_id is distinct from v_customer
    or v_order.customer_id_old is distinct from v_customer_row.custormer_id_old
    or (private.aka_order_owner_state(v_order)->>'ownerId')::bigint is distinct from v_owner
    or v_order.source_snapshot#>>'{account,id}' is distinct from v_source::text
    or v_order.source_snapshot#>>'{account,contact_id}' is distinct from v_customer_row.custormer_id_old::text
    or v_order.source_snapshot#>>'{account,staff_manage_id}' is distinct from v_order.staff_manage_id_old::text
    or (v_order.date_expiration at time zone 'UTC')::date is distinct from v_expiration
    or coalesce(v_order.is_deleted,false) or coalesce(v_order.is_lock,false)
    or v_order.is_paid is distinct from (v_type=4) or v_order.is_demo is distinct from (v_type=3)
    or (case when v_type=4 then lower(btrim(v_order.package_type)) in ('month','year') else lower(btrim(v_order.package_type))='demo' end) is distinct from true then
    return jsonb_build_object('status','review','reason','reconcile_source_changed');
  end if;
  select * into v_crm from public.aka_crm where id=v_crm_id for share;
  if not found or v_crm.customer_id is distinct from v_customer or v_crm.org_staff_owner_id is distinct from v_owner
    or v_crm.crm_type_id is distinct from v_type or v_crm.sql_account_id is distinct from v_source
    or coalesce(v_crm.source_type,'')<>'' or v_crm.source_order_id is not null or v_crm.org_organization_product_id is not null
    or v_crm.source_expiration_source is distinct from 'sql_account_snapshot' or v_crm.source_expiration_date is distinct from v_expiration
    or (v_crm.created_at at time zone 'Asia/Ho_Chi_Minh')::date is distinct from v_expiration+v_offset
    or v_crm.gen_meta#>>'{renewal_duplicate_v1,archived}'='true'
    or not starts_with(coalesce(v_crm.note,''),case when v_offset=-7 then '[CS hết hạn 7 ngày]' else '[CS hết hạn]' end) then
    return jsonb_build_object('status','review','reason','reconcile_crm_provenance_changed');
  end if;
  select * into v_pending from public.aka_app_settings where key=p_request->>'pendingKey' for update;
  if not found or v_pending.value->>'customer_id' is distinct from v_customer::text
    or v_pending.value->>'entitlement_key' is distinct from 'sql:'||v_source
    or v_pending.value->>'expiration_day' is distinct from v_expiration::text
    or v_pending.value->>'event_key' is distinct from v_event
    or v_pending.value->'paid' is distinct from to_jsonb(v_type=4) then
    return jsonb_build_object('status','review','reason','reconcile_pending_changed');
  end if;
  if v_pending.value->>'status'='reconciled_existing' and v_pending.value->>'crm_id'=v_crm_id::text
    and v_pending.value->>'reconciled_event_key'=v_event then
    return jsonb_build_object('status','already_reconciled','crm_id',v_crm_id,'event_key',v_event);
  end if;
  if v_pending.value->>'status' is distinct from 'pending' or v_pending.value is distinct from p_request->'expectedPending' then
    return jsonb_build_object('status','review','reason','reconcile_pending_cas_changed');
  end if;
  update public.aka_app_settings set value=value||jsonb_build_object('status','reconciled_existing','crm_id',v_crm_id,
    'reconciled_event_key',v_event,'reconciled_owner_id',v_owner,'reconciled_at',statement_timestamp(),
    'reconciliation_reason','verified_existing_legacy_milestone'),updated_at=statement_timestamp()
    where key=v_pending.key;
  return jsonb_build_object('status','reconciled_existing','crm_id',v_crm_id,'event_key',v_event);
end
$function$

CREATE OR REPLACE FUNCTION public.release_non_zalo_account_runtime_operation(p_account_id bigint, p_staff_id bigint, p_platform text, p_previous_status text, p_claim_token uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_account public.auto_accounts%ROWTYPE;
  v_organization_id bigint;
  v_platform text := lower(btrim(COALESCE(p_platform, '')));
  v_previous_status text := btrim(COALESCE(p_previous_status, ''));
BEGIN
  IF p_account_id IS NULL OR p_account_id <= 0 OR p_staff_id IS NULL OR p_staff_id <= 0 THEN
    RAISE EXCEPTION 'Account and staff IDs must be positive integers';
  END IF;
  IF v_platform NOT IN ('facebook', 'email') THEN
    RAISE EXCEPTION 'Non-Zalo runtime platform must be Facebook or Email';
  END IF;
  IF v_previous_status NOT IN ('chờ xử lý', 'tạm dừng') THEN
    RAISE EXCEPTION 'Previous account status must be pending or paused';
  END IF;
  IF p_claim_token IS NULL THEN
    RAISE EXCEPTION 'Runtime claim token is required';
  END IF;

  SELECT staff.organization_id INTO v_organization_id
  FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share') AS staff
  WHERE staff.id = p_staff_id
  ;
  IF NOT FOUND OR v_organization_id IS NULL THEN RETURN false; END IF;

  SELECT account.* INTO v_account
  FROM public.auto_accounts AS account
  WHERE account.id = p_account_id
    AND account.staff_id = p_staff_id
    AND (account.organization_id IS NULL OR account.organization_id = v_organization_id)
    AND lower(btrim(COALESCE(account.flatform_type, ''))) = v_platform
  FOR UPDATE OF account;
  IF NOT FOUND THEN RETURN false; END IF;

  UPDATE public.auto_accounts AS account
  SET
    status = v_previous_status,
    runtime_operation_claim_token = NULL,
    updated_at = now()
  WHERE account.id = p_account_id
    AND account.status = 'đang chạy'
    AND account.runtime_operation_claim_token = p_claim_token;
  RETURN FOUND;
END;
$function$

CREATE OR REPLACE FUNCTION public.release_zalo_account_runtime_operation(p_account_id bigint, p_staff_id bigint, p_runtime_target text, p_previous_status text, p_claim_token uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_organization_id bigint;
  v_runtime_target text := lower(btrim(COALESCE(p_runtime_target, '')));
  v_previous_status text := btrim(COALESCE(p_previous_status, ''));
BEGIN
  IF p_account_id IS NULL OR p_account_id <= 0
    OR p_staff_id IS NULL OR p_staff_id <= 0
  THEN RAISE EXCEPTION 'Account and staff IDs must be positive integers'; END IF;
  IF v_runtime_target NOT IN ('desktop', 'server') THEN
    RAISE EXCEPTION 'Runtime target must be desktop or server';
  END IF;
  IF v_previous_status NOT IN ('chờ xử lý', 'tạm dừng') THEN
    RAISE EXCEPTION 'Previous account status must be pending or paused';
  END IF;
  IF p_claim_token IS NULL THEN
    RAISE EXCEPTION 'Runtime claim token is required';
  END IF;

  SELECT staff.organization_id INTO v_organization_id
  FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share') AS staff
  WHERE staff.id = p_staff_id
  ;
  IF NOT FOUND OR v_organization_id IS NULL THEN RETURN false; END IF;

  UPDATE public.auto_accounts AS account
  SET
    status = v_previous_status,
    runtime_operation_claim_token = NULL,
    updated_at = now()
  WHERE account.id = p_account_id
    AND account.staff_id = p_staff_id
    AND (account.organization_id IS NULL OR account.organization_id = v_organization_id)
    AND lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
    AND account.status = 'đang chạy'
    AND account.runtime_operation_claim_token = p_claim_token;
  RETURN FOUND;
END;
$function$

CREATE OR REPLACE FUNCTION public.release_zalo_account_runtime_operation(p_account_id bigint, p_staff_id bigint, p_runtime_target text, p_previous_status text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_account public.auto_accounts%ROWTYPE;
  v_organization_id bigint;
  v_runtime_target text := lower(btrim(COALESCE(p_runtime_target, '')));
  v_previous_status text := btrim(COALESCE(p_previous_status, ''));
  v_is_web boolean;
  v_is_server boolean;
BEGIN
  IF p_account_id IS NULL OR p_account_id <= 0 OR p_staff_id IS NULL OR p_staff_id <= 0 THEN
    RAISE EXCEPTION 'Account and staff IDs must be positive integers';
  END IF;
  IF v_runtime_target NOT IN ('desktop', 'server') THEN
    RAISE EXCEPTION 'Runtime target must be desktop or server';
  END IF;
  IF v_previous_status NOT IN ('chờ xử lý', 'tạm dừng') THEN
    RAISE EXCEPTION 'Previous account status must be pending or paused';
  END IF;

  SELECT staff.organization_id INTO v_organization_id
  FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share') AS staff
  WHERE staff.id = p_staff_id AND staff.is_active = true
  ;
  IF NOT FOUND OR v_organization_id IS NULL THEN RETURN false; END IF;

  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('aka-agent-zalo-runtime-entitlement-mutation', 0)
  );
  SELECT account.* INTO v_account
  FROM public.auto_accounts AS account
  WHERE account.id = p_account_id
    AND account.staff_id = p_staff_id
    AND lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
    AND COALESCE(account.is_delete, false) = false
  FOR UPDATE OF account;
  IF NOT FOUND THEN RETURN false; END IF;

  v_is_web := COALESCE(v_account.is_zalo_show_web, false);
  v_is_server := COALESCE(v_account.is_zalo_server, false);
  -- Release is cleanup, not a new operation. Capability loss does not prevent
  -- either runtime from releasing its own subtype.
  IF (v_runtime_target = 'server' AND (v_is_web OR NOT v_is_server))
    OR (v_runtime_target = 'desktop' AND v_is_server)
  THEN RETURN false; END IF;

  UPDATE public.auto_accounts
  SET status = v_previous_status, updated_at = now()
  WHERE id = p_account_id AND status = 'đang chạy';
  RETURN FOUND;
END;
$function$

CREATE OR REPLACE FUNCTION public.staff_transfer_batch(p_actor bigint, p_from bigint, p_to bigint, p_cutoff timestamp with time zone, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare i jsonb; o public.aka_order; c public.aka_crm;
  owner_id bigint; matched boolean; result text; skip_reason text; expected jsonb; owner_state jsonb; results jsonb:='[]';
begin
  perform private.staff_transfer_validate(p_actor,p_from,p_to);
  if p_cutoff is null or jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items)>500 then
    raise exception using errcode='22023',message='Lô chuyển không hợp lệ';
  end if;
  for i in select value from jsonb_array_elements(p_items) loop
    if i->>'kind' is null or i->>'kind' not in ('organizations','orders','customers','crm') or (i->>'id')::bigint is null then
      raise exception using errcode='22023',message='Bản ghi chuyển không hợp lệ';
    end if;
    result:='skipped'; skip_reason:='Dữ liệu đã đổi chủ hoặc không còn tồn tại'; owner_id:=null; matched:=false;
    if i->>'kind'='organizations' then
      select staff_id_owner into owner_id from public.org_organization where id=(i->>'id')::bigint for update;
      matched:=found;
      if matched and owner_id is not distinct from p_from then
        update public.org_organization set staff_id_owner=p_to where id=(i->>'id')::bigint; result:='transferred';
      end if;
    elsif i->>'kind'='orders' then
      select * into o from public.aka_order where id=(i->>'id')::bigint for update;
      matched:=found;
      if matched then
        owner_state:=private.aka_order_owner_state(o); owner_id:=(owner_state->>'ownerId')::bigint;
        expected:=jsonb_build_object('org',o.org_staff_id,'sql',o.staff_manage_id_old,'chat',o.staff_id,'source',o.source_system,'product',o.org_organization_product_id,'organization',o.organization_id);
        if owner_id is not distinct from p_from and owner_state->>'issue' is null and expected=(i->'expected') then
          update public.aka_order set org_staff_id=p_to where id=(i->>'id')::bigint; result:='transferred';
        end if;
      end if;
    elsif i->>'kind'='customers' then
      select org_staff_id_owner into owner_id from public.aka_customer where id=(i->>'id')::bigint for update;
      matched:=found;
      if matched and owner_id is not distinct from p_from then
        update public.aka_customer set org_staff_id_owner=p_to,org_staff_update_id=p_actor where id=(i->>'id')::bigint; result:='transferred';
      end if;
    elsif i->>'kind'='crm' then
      select * into c from public.aka_crm where id=(i->>'id')::bigint for update;
      matched:=found; owner_id:=c.org_staff_owner_id;
      if matched and owner_id is not distinct from p_from and private.staff_transfer_crm_eligible(c,p_cutoff) then
        update public.aka_crm set org_staff_owner_id=p_to,org_staff_updated_id=p_actor where id=(i->>'id')::bigint; result:='transferred';
      else skip_reason:='CRM đã đổi chủ, hoàn thành hoặc không còn đủ điều kiện'; end if;
    end if;
    if result='skipped' and matched and owner_id=p_to then result:='already_target'; end if;

    results:=results||jsonb_build_array(jsonb_build_object('id',(i->>'id')::bigint,'kind',i->>'kind','status',result,
      'reason',case when result='skipped' then skip_reason else null end));
  end loop;
  return results;
end $function$

CREATE OR REPLACE FUNCTION public.staff_transfer_preview(p_actor bigint, p_from bigint, p_to bigint, p_mode text, p_crm boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare day date := (statement_timestamp() at time zone 'Asia/Ho_Chi_Minh')::date;
  cutoff timestamptz; n_orders bigint:=0; n_org bigint:=0; n_customers bigint:=0; n_crm bigint:=0; excluded_crm bigint:=0; ambiguous bigint:=0;
begin
  perform private.staff_transfer_validate(p_actor,p_from,p_to);
  if p_mode not in ('orders','customers') then raise exception using errcode='22023',message='Chế độ không hợp lệ'; end if;
  cutoff := day::timestamp at time zone 'Asia/Ho_Chi_Minh';
  if p_mode='orders' then
    select count(*) into n_orders from public.aka_order o where not coalesce(o.source_system='org_product' or o.org_organization_product_id is not null,false) and private.aka_order_owner_state(o)->>'issue' is null and (private.aka_order_owner_state(o)->>'ownerId')::bigint is not distinct from p_from;
    select count(*) into n_org from public.org_organization where staff_id_owner=p_from;
    select count(*) into ambiguous from public.aka_order o where private.aka_order_owner_state(o)->>'issue' is not null
      and (p_from is null or org_staff_id=p_from or exists(select 1 from public.org_staff s where s.id=p_from and (s.sql_staff_id=staff_manage_id_old or s.chat_staff_id=staff_id)));
  else
    select count(*) into n_customers from public.aka_customer where org_staff_id_owner is not distinct from p_from;
  end if;
  if p_crm then
    select count(*) filter(where private.staff_transfer_crm_eligible(c,cutoff)),
      count(*) filter(where not coalesce(private.staff_transfer_crm_eligible(c,cutoff),false))
      into n_crm,excluded_crm from public.aka_crm c where org_staff_owner_id is not distinct from p_from;
  end if;
  return jsonb_build_object('previewDate',day,'cutoff',cutoff,'counts',jsonb_build_object('orders',n_orders,'organizations',n_org,'customers',n_customers,'crm',n_crm,'sql',0),
    'excluded',jsonb_build_object('crm',excluded_crm,'ambiguousOrders',ambiguous));
end $function$

CREATE OR REPLACE FUNCTION public.staff_transfer_snapshot(p_actor bigint, p_from bigint, p_to bigint, p_mode text, p_crm boolean, p_day date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare cutoff timestamptz; items jsonb;
begin
  perform public.staff_transfer_validate_request(p_actor,p_from,p_to,p_day);
  if p_day is null or p_mode not in ('orders','customers') or p_crm is null then raise exception using errcode='22023',message='Yêu cầu không hợp lệ'; end if;
  cutoff:=p_day::timestamp at time zone 'Asia/Ho_Chi_Minh';
  select coalesce(jsonb_agg(x),'[]'::jsonb) into items from (
    select 'organizations' kind,id,'{}'::jsonb expected from public.org_organization where p_mode='orders' and staff_id_owner=p_from
    union all
    select 'orders',o.id,jsonb_build_object('org',o.org_staff_id,'sql',o.staff_manage_id_old,'chat',o.staff_id,'source',o.source_system,'product',o.org_organization_product_id,'organization',o.organization_id)
      from public.aka_order o where p_mode='orders' and not coalesce(o.source_system='org_product' or o.org_organization_product_id is not null,false)
      and private.aka_order_owner_state(o)->>'issue' is null and (private.aka_order_owner_state(o)->>'ownerId')::bigint is not distinct from p_from
    union all
    select 'customers',id,'{}'::jsonb from public.aka_customer where p_mode='customers' and org_staff_id_owner is not distinct from p_from
    union all
    select 'crm',id,'{}'::jsonb from public.aka_crm c where p_crm and org_staff_owner_id is not distinct from p_from and private.staff_transfer_crm_eligible(c,cutoff)
  ) x;
  return jsonb_build_object('cutoff',cutoff,'items',items);
end $function$

CREATE OR REPLACE FUNCTION public.trg_aka_crm_sales_opportunity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare cfg jsonb; ct record; v_opp bigint; v_status_changed boolean; v_purchased boolean;
begin
  begin
    if new.customer_id is null or coalesce(new.source_type,'') = 'sales_opp' then return new; end if;
    cfg := public.fn_opp_config();
    if coalesce(cfg->>'mode','off') = 'off' then return new; end if;

    if tg_op = 'INSERT' then
      select auto_create_opportunity, opportunity_type_id into ct from public.aka_crm_type where id = new.crm_type_id;
      if coalesce(ct.auto_create_opportunity, false) then
        perform public.fn_tao_co_hoi_ban_hang(new.customer_id, ct.opportunity_type_id, 'crm', new.id, new.org_staff_owner_id, new.source_expiration_date, new.interest_product_ids[1], new.created_by);
      end if;
      return new;
    end if;

    -- UPDATE
    v_purchased := (new.purchase_date is not null and old.purchase_date is null) or (new.pipeline_status_id = 4 and old.pipeline_status_id is distinct from 4);
    if v_purchased and coalesce((cfg->>'sale_order_won_enabled')::boolean, true) then
      select id into v_opp from public.aka_salesopportunity where customer_id = new.customer_id and status = 'open' limit 1;
      if v_opp is not null then perform public.fn_dong_co_hoi_ban_hang(v_opp, 'won', 'crm_purchase', nullif(new.revenue,0), new.sale_order_id); end if;
      return new;
    end if;

    v_status_changed := (new.pipeline_status_id in (2,3,105) and new.pipeline_status_id is distinct from old.pipeline_status_id)
                     or (new.interest_date is not null and old.interest_date is null)
                     or (new.demo_date is not null and old.demo_date is null)
                     or (new.negotiation_date is not null and old.negotiation_date is null);
    if v_status_changed and coalesce((cfg->>'pipeline_trigger_enabled')::boolean, true) then
      perform public.fn_tao_co_hoi_ban_hang(new.customer_id, null, 'crm', new.id, new.org_staff_owner_id, new.source_expiration_date, coalesce(new.negotiation_product_ids[1], new.demo_product_ids[1], new.interest_product_ids[1]), new.org_staff_updated_id);
    end if;

    if coalesce((cfg->>'auto_close_lost_enabled')::boolean,false) and new.decline_reason_id in (21,30,31) and old.decline_reason_id is distinct from new.decline_reason_id then
      select id into v_opp from public.aka_salesopportunity where customer_id = new.customer_id and status = 'open' limit 1;
      if v_opp is not null then perform public.fn_dong_co_hoi_ban_hang(v_opp, 'lost', (select name from public.aka_crm_status where id = new.decline_reason_id)); end if;
    end if;
    if coalesce((cfg->>'auto_close_disqualified_enabled')::boolean,false) and new.error_reason_id in (16,17,56) and old.error_reason_id is distinct from new.error_reason_id then
      select id into v_opp from public.aka_salesopportunity where customer_id = new.customer_id and status = 'open' limit 1;
      if v_opp is not null then perform public.fn_dong_co_hoi_ban_hang(v_opp, 'disqualified', 'data_error'); end if;
    end if;
    return new;
  exception when others then
    perform public.fn_opp_log('failed', format('trigger aka_crm #%s: %s', new.id, left(sqlerrm, 300)), jsonb_build_object('crm_id', new.id, 'op', tg_op), 0, 0, 1);
    return new;
  end;
end $function$

CREATE OR REPLACE FUNCTION public.trg_aka_salesopportunity_fill()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare t record; v_end timestamptz; cu_name text;
begin
  select * into t from public.aka_salesopportunity_type where id = new.type_id;
  if t.id is null then return new; end if;
  if tg_op = 'INSERT' then
    new.opportunity_type := coalesce(nullif(new.opportunity_type,''), t.opportunity_type);
    if new.stage is null or new.stage = 'qualification' then new.stage := coalesce(t.default_stage, 'qualification'); end if;
    if new.probability is null or new.probability = 10 then new.probability := t.default_probability; end if;
    if new.priority_score is null or new.priority_score = 0 then new.priority_score := t.default_priority_score; end if;
    if new.trial_start_date is null then new.trial_start_date := public.fn_opp_trial_start(new.customer_id); end if;
  end if;
  if t.anchor_kind = 'expiration' then
    v_end := ((new.anchor_date + coalesce(t.window_after_days, 30) + 1)::text || ' 00:00')::timestamp at time zone 'Asia/Ho_Chi_Minh';
  else
    v_end := ((new.anchor_date + t.lifecycle_days + 1)::text || ' 00:00')::timestamp at time zone 'Asia/Ho_Chi_Minh';
    if coalesce((t.care_process->>'lifecycle_extends_with_trial')::boolean, false) and new.trial_start_date is not null then
      v_end := greatest(v_end, ((new.trial_start_date + t.lifecycle_days + 1)::text || ' 00:00')::timestamp at time zone 'Asia/Ho_Chi_Minh');
    end if;
  end if;
  if tg_op = 'INSERT' or new.trial_start_date is distinct from old.trial_start_date or new.anchor_date is distinct from old.anchor_date then
    new.lifecycle_end_at := v_end;
    new.expected_close_at := v_end;
  end if;
  if tg_op = 'INSERT' and coalesce(btrim(new.title),'') = '' then
    select name into cu_name from public.aka_customer where id = new.customer_id;
    new.title := left(format('%s · %s%s', t.name, coalesce(cu_name, 'KH #'||new.customer_id),
                  case when t.anchor_kind='expiration' then ' · hạn '||to_char(new.anchor_date,'DD/MM') else '' end), 250);
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.update_aka_crm_customer_phone(p_crm_id bigint, p_phone text, p_actor_org_staff_id bigint, p_confirmed_customer_id bigint)
 RETURNS aka_crm
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_crm public.aka_crm%rowtype;
  v_staff public.org_staff%rowtype;
  v_source public.aka_customer%rowtype;
  v_target public.aka_customer%rowtype;
  v_row public.aka_customer%rowtype;
  v_match_count integer := 0;
  v_owner_name text;
  v_phone text;
  v_purchase boolean := false;
  v_order public.aka_sale_order%rowtype;
  v_item public.aka_sale_order_item%rowtype;
  v_order_count integer := 0;
  v_contact_id bigint;
  v_owner_id bigint;
  v_meta jsonb;
  v_cleanup jsonb;
  v_audit jsonb;
  v_order_before jsonb;
  v_crm_identity_before jsonb;
  v_purchase_date timestamptz;
  v_items_before jsonb;
  v_snapshots_before jsonb;
  v_snapshots_after jsonb;
  v_now timestamptz;
begin
  v_phone := pg_catalog.regexp_replace(p_phone, '[[:space:].()\-]', '', 'g');
  if v_phone like '+84%' then v_phone := '0' || pg_catalog.substr(v_phone, 4);
  elsif v_phone like '84%' then v_phone := '0' || pg_catalog.substr(v_phone, 3);
  end if;
  if v_phone is null or v_phone !~ '^0[1-9][0-9]{8}$'
     or (p_confirmed_customer_id is not null and p_confirmed_customer_id <= 0) then
    raise exception using errcode='22023', message='crm_phone.invalid_input';
  end if;

  select * into v_staff from public.org_staff where id=p_actor_org_staff_id;
  if not found then raise exception using errcode='42501', message='crm_phone.staff_not_found'; end if;
  select * into v_crm from public.aka_crm where id=p_crm_id for update;
  if not found then raise exception using errcode='P0002', message='crm_phone.crm_not_found'; end if;
  if not coalesce(v_staff.is_super_admin, false)
     and v_crm.org_staff_owner_id is distinct from p_actor_org_staff_id
     and v_crm.org_staff_support_id is distinct from p_actor_org_staff_id then
    raise exception using errcode='42501', message='crm_phone.forbidden';
  end if;
  if v_crm.customer_id is null then
    raise exception using errcode='22023', message='crm_phone.customer_required';
  end if;

  -- Serialize this operation for a phone; uniqueness constraints also guard other writers.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('crm_phone:' || v_phone, 0));
  -- Lock source and matches in deterministic order. Recheck on every confirmation/retry.
  for v_row in
    select * from public.aka_customer
    where id=v_crm.customer_id or public.normalize_phone(phone)=v_phone
    order by id for update
  loop
    if v_row.id=v_crm.customer_id then v_source := v_row; end if;
    if public.normalize_phone(v_row.phone)=v_phone then
      v_match_count := v_match_count + 1;
      v_target := v_row;
    end if;
  end loop;
  if v_source.id is null then raise exception using errcode='P0002', message='crm_phone.customer_not_found'; end if;
  if v_match_count > 1 then raise exception using errcode='PT409', message='CUSTOMER_PHONE_AMBIGUOUS'; end if;

  if v_match_count = 1 then
    if v_target.record_state='merged' or v_target.merged_into_customer_id is not null then
      raise exception using errcode='PT409', message='CUSTOMER_MERGED';
    end if;
    if v_target.id is distinct from v_source.id then
      -- Same customer visibility rules as aka_customer (owner, creator, chat staff, admin).
      if not coalesce(v_staff.is_super_admin, false) and not coalesce(v_staff.is_admin, false)
         and v_target.org_staff_id_owner is distinct from p_actor_org_staff_id
         and v_target.org_staff_create_id is distinct from p_actor_org_staff_id
         and not (v_staff.chat_staff_id is not null and v_target.staff_id::text is not distinct from v_staff.chat_staff_id::text) then
        raise exception using errcode='42501', message='crm_phone.target_forbidden';
      end if;
    end if;
    if (v_target.id is distinct from v_source.id and p_confirmed_customer_id is distinct from v_target.id)
       or (p_confirmed_customer_id is not null and p_confirmed_customer_id is distinct from v_target.id) then
      select coalesce(nullif(pg_catalog.btrim(name), ''), username) into v_owner_name
      from public.org_staff where id=v_target.org_staff_id_owner;
      -- Raising before any write guarantees the preview cannot change business data.
      raise exception using errcode='PT409', message='CUSTOMER_CONFIRMATION_REQUIRED',
        detail=pg_catalog.jsonb_build_object(
          'id', v_target.id, 'name', v_target.name, 'name_zalo', v_target.name_zalo,
          'phone', v_phone, 'owner_name', v_owner_name
        )::text;
    end if;
  else
    if p_confirmed_customer_id is not null then
      raise exception using errcode='PT409', message='CUSTOMER_CONFIRMATION_EXPIRED';
    end if;
    v_target := v_source;
    if v_target.record_state='merged' or v_target.merged_into_customer_id is not null then
      raise exception using errcode='PT409', message='CUSTOMER_MERGED';
    end if;
  end if;

  v_purchase := v_crm.purchase_date is not null and v_crm.cskh_completed_date is not null;
  if v_purchase and v_target.id is distinct from v_source.id then
    -- A payment allocation or product transition is an independent purchase
    -- contract. Relinking its CRM cannot transfer ownership/revenue implicitly.
    if v_crm.payment_source_sale_order_id is not null
       or coalesce(v_crm.gen_meta->'product_transition', 'null'::jsonb) <> 'null'::jsonb then
      raise exception using errcode='PT409', message='PURCHASE_CUSTOMER_RELINK_CONFLICT',
        detail='payment_allocation_or_product_transition_requires_review';
    end if;
    if pg_catalog.to_jsonb(v_crm)->>'sale_order_edit_sync_token' is not null then
      raise exception using errcode='PT409', message='PURCHASE_CUSTOMER_RELINK_CONFLICT', detail='purchase_edit_sync_in_progress';
    end if;
    if v_crm.gen_meta is not null and pg_catalog.jsonb_typeof(v_crm.gen_meta) <> 'object' then
      raise exception using errcode='PT409', message='PURCHASE_CUSTOMER_RELINK_CONFLICT', detail='invalid_purchase_metadata';
    end if;
    v_meta := coalesce(v_crm.gen_meta, '{}'::jsonb);
    v_cleanup := v_meta->'purchase_cleanup';
    if (v_cleanup is not null and pg_catalog.jsonb_typeof(v_cleanup) <> 'object')
       or (v_meta ? 'purchase_customer_relinks' and pg_catalog.jsonb_typeof(v_meta->'purchase_customer_relinks') <> 'array') then
      raise exception using errcode='PT409', message='PURCHASE_CUSTOMER_RELINK_CONFLICT', detail='invalid_purchase_metadata';
    end if;
    -- A prior mismatched cleanup belongs to a historical repair manifest, not
    -- an ordinary phone correction. Never silently adopt another customer's scope.
    if v_cleanup ? 'customer_id' and v_cleanup->>'customer_id' is distinct from v_source.id::text then
      raise exception using errcode='PT409', message='PURCHASE_CUSTOMER_RELINK_CONFLICT', detail='cleanup_customer_mismatch';
    end if;
    if v_crm.organization_id is not null and not exists (
      select 1 from public.org_organization o where o.id=v_crm.organization_id and o.customer_id=v_target.id for share
    ) then
      raise exception using errcode='PT409', message='PURCHASE_CUSTOMER_RELINK_CONFLICT', detail='organization_owner_mismatch';
    end if;
    if v_crm.source_order_id is not null and not exists (
      select 1 from public.aka_order o where o.id=v_crm.source_order_id and o.customer_id=v_target.id for share
    ) then
      raise exception using errcode='PT409', message='PURCHASE_CUSTOMER_RELINK_CONFLICT', detail='entitlement_owner_mismatch';
    end if;
    if v_crm.sql_account_id is not null and not exists (
      select 1 from public.aka_order o where o.account_id_old=v_crm.sql_account_id
        and o.source_system='sql_account' and o.customer_id=v_target.id for share
    ) then
      raise exception using errcode='PT409', message='PURCHASE_CUSTOMER_RELINK_CONFLICT', detail='entitlement_owner_mismatch';
    end if;
    if v_crm.org_organization_product_id is not null and not exists (
      select 1 from public.org_organization_product p join public.org_organization o on o.id=p.organization_id
      where p.id=v_crm.org_organization_product_id and o.customer_id=v_target.id for share of p,o
    ) then
      raise exception using errcode='PT409', message='PURCHASE_CUSTOMER_RELINK_CONFLICT', detail='entitlement_owner_mismatch';
    end if;

    -- Follow both directions, including an orphan header created before the
    -- final CRM sync. Lock ordering matches sync_crm_sale_order_items_if_owner:
    -- CRM first, then its order header, then items.
    for v_order in
      select * from public.aka_sale_order o
      where o.crm_id=p_crm_id or o.id=v_crm.sale_order_id order by o.id for update
    loop
      v_order_count := v_order_count+1;
      if v_order_count > 1 or v_order.source is distinct from 'crm_purchase'
         or v_order.crm_id is distinct from p_crm_id or v_order.status is distinct from 'completed'
         or v_order.customer_id is distinct from v_source.id or v_order.upgrade_lock_token is not null
         or (v_order.sql_contact_id is not null and v_order.sql_contact_id::text is distinct from v_source.custormer_id_old::text)
         or (v_crm.sale_order_id is not null and v_crm.sale_order_id <> v_order.id)
         or exists (select 1 from public.aka_crm c where c.id<>p_crm_id
           and (c.sale_order_id=v_order.id or c.payment_source_sale_order_id=v_order.id)) then
        raise exception using errcode='PT409', message='PURCHASE_CUSTOMER_RELINK_CONFLICT', detail='sale_order_not_exclusive';
      end if;
      v_order_before := pg_catalog.jsonb_build_object('id',v_order.id,'customer_id',v_order.customer_id,
        'sql_contact_id',v_order.sql_contact_id,'customer_name',v_order.customer_name,'customer_phone',v_order.customer_phone);
      v_items_before := '[]'::jsonb;
      for v_item in select * from public.aka_sale_order_item where sale_order_id=v_order.id order by id for update
      loop
        -- A completely empty legacy line inherits the header. A line carrying
        -- a snapshot must have an exact customer ID; phone/name guesses cannot
        -- authorize moving financial allocations between customer profiles.
        if (v_item.customer_id is not null or v_item.sql_contact_id is not null
              or v_item.customer_name is not null or v_item.customer_phone is not null)
             and v_item.customer_id is distinct from v_source.id then
          raise exception using errcode='PT409', message='PURCHASE_CUSTOMER_RELINK_CONFLICT', detail='item_customer_allocation_ambiguous';
        end if;
        if v_item.sql_contact_id is not null
             and v_item.sql_contact_id::text is distinct from v_source.custormer_id_old::text then
          raise exception using errcode='PT409', message='PURCHASE_CUSTOMER_RELINK_CONFLICT', detail='item_contact_allocation_ambiguous';
        end if;
        if v_item.sql_account_id is not null then
          select o.customer_id into v_owner_id from public.aka_order o
          where o.account_id_old=v_item.sql_account_id and o.source_system='sql_account' for share;
          if v_owner_id is distinct from v_target.id then
            raise exception using errcode='PT409', message='PURCHASE_CUSTOMER_RELINK_CONFLICT', detail='item_entitlement_owner_mismatch';
          end if;
        end if;
        if v_item.org_organization_product_id is not null then
          select o.customer_id into v_owner_id from public.org_organization_product p
            join public.org_organization o on o.id=p.organization_id where p.id=v_item.org_organization_product_id for share of p,o;
          if v_owner_id is distinct from v_target.id then
            raise exception using errcode='PT409', message='PURCHASE_CUSTOMER_RELINK_CONFLICT', detail='item_entitlement_owner_mismatch';
          end if;
        end if;
        v_items_before := v_items_before || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
          'id',v_item.id,'customer_id',v_item.customer_id,'sql_contact_id',v_item.sql_contact_id,
          'customer_name',v_item.customer_name,'customer_phone',v_item.customer_phone));
      end loop;
    end loop;
    if v_crm.sale_order_id is not null and v_order_count=0 then
      raise exception using errcode='PT409', message='PURCHASE_CUSTOMER_RELINK_CONFLICT', detail='linked_sale_order_missing';
    end if;

    -- All checks above are read-only. From here every write, queue entry and
    -- lifecycle trigger is in this RPC's transaction and rolls back on failure.
    v_crm_identity_before := pg_catalog.jsonb_build_object('customer_id',v_crm.customer_id,
      'customer_name',v_crm.customer_name,'customer_phone',v_crm.customer_phone);
    v_purchase_date := v_crm.purchase_date;
    v_now := pg_catalog.clock_timestamp();
    v_contact_id := case when v_target.custormer_id_old::text ~ '^[1-9][0-9]*$'
      then v_target.custormer_id_old::bigint else null end;
    select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('id',c.id,'purchase_date',c.purchase_date) order by c.id)
      into v_snapshots_before from public.aka_customer c where c.id in (v_source.id,v_target.id);
    if v_order_count=1 then
      update public.aka_sale_order set customer_id=v_target.id, sql_contact_id=v_contact_id,
        customer_name=v_target.name, customer_phone=v_phone, updated_at=v_now
        where id=(v_order_before->>'id')::bigint;
      update public.aka_sale_order_item set customer_id=v_target.id, sql_contact_id=v_contact_id,
        customer_name=v_target.name, customer_phone=v_phone, updated_at=v_now
        where sale_order_id=(v_order_before->>'id')::bigint;
    end if;
    -- Preserve the original cutoff; changing the target must never broaden
    -- cleanup to unrelated or newly-created post-purchase tasks.
    v_meta := v_meta || pg_catalog.jsonb_build_object('purchase_cleanup',
      coalesce(v_cleanup,'{}'::jsonb) || pg_catalog.jsonb_build_object(
        'customer_id',v_target.id,'cutoff_at',coalesce(v_cleanup->>'cutoff_at',v_crm.cskh_completed_date::text),
        'scope','product','policy','trial_care_v1'));
    update public.aka_crm set customer_id=v_target.id, customer_phone=v_phone, customer_name=v_target.name,
      org_staff_updated_id=p_actor_org_staff_id, gen_meta=v_meta,
      updated_at=greatest(v_now, v_crm.updated_at+interval '1 microsecond')
      where id=p_crm_id returning * into v_crm;
    if not found then raise exception using errcode='P0002', message='crm_phone.crm_not_updated'; end if;
    -- Recompute the legacy snapshot from purchases that still belong to each
    -- profile, including QR payments/upgrades not yet captured in a completed
    -- CRM. Preserve unrelated pre-existing snapshots conservatively. Only the
    -- source's exact moved date can be cleared when no other paid evidence exists.
    update public.aka_customer c set purchase_date=(
      select max(e.purchased_at) from (
        select r.purchase_date as purchased_at from public.aka_crm r where r.customer_id=c.id
          and r.purchase_date is not null and r.cskh_completed_date is not null
        union all
        select (s.paid_at at time zone 'Asia/Ho_Chi_Minh')::date::timestamp at time zone 'Asia/Ho_Chi_Minh'
          from public.aka_sale_order s where s.amount>0 and s.paid_at is not null and s.source is distinct from 'crm_purchase'
          and s.status in ('paid','upgrading','completed','upgrade_failed')
          and (exists(select 1 from public.aka_sale_order_item i where i.sale_order_id=s.id and i.customer_id=c.id)
            or (s.customer_id=c.id and not exists(select 1 from public.aka_sale_order_item i where i.sale_order_id=s.id
              and (i.customer_id is not null or i.sql_contact_id is not null or i.customer_phone is not null or i.customer_name is not null))))
        union all
        select o.purchase_date from public.aka_order o where o.customer_id=c.id and o.is_paid is true
          and not coalesce(o.is_deleted,false)
        union all
        select p.purchase_date from public.org_organization_product p join public.org_organization o on o.id=p.organization_id
          where o.customer_id=c.id and p.is_paid is true and not coalesce(p.is_deleted,false)
        union all
        select c.purchase_date where c.id=v_target.id or c.purchase_date is distinct from v_purchase_date
      ) e),
      org_staff_update_id=p_actor_org_staff_id, updated_at=v_now
      where c.id in (v_source.id,v_target.id);
    select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('id',c.id,'purchase_date',c.purchase_date) order by c.id)
      into v_snapshots_after from public.aka_customer c where c.id in (v_source.id,v_target.id);
    v_audit := pg_catalog.jsonb_build_object('version',1,'at',v_now,'actor_org_staff_id',p_actor_org_staff_id,
      'from_customer_id',v_source.id,'to_customer_id',v_target.id,
      'crm_identity_before',v_crm_identity_before,
      'sale_order_identity_before',v_order_before,'sale_order_items_identity_before',coalesce(v_items_before,'[]'::jsonb),
      'purchase_cleanup_before',v_cleanup,'purchase_cleanup_after',v_meta->'purchase_cleanup',
      'customer_purchase_snapshots_before',v_snapshots_before,'customer_purchase_snapshots_after',v_snapshots_after);
    update public.aka_crm set gen_meta=gen_meta || pg_catalog.jsonb_build_object('purchase_customer_relinks',
      coalesce(v_meta->'purchase_customer_relinks','[]'::jsonb) || pg_catalog.jsonb_build_array(v_audit))
      where id=p_crm_id returning * into v_crm;
    -- Durable queue is transactional. Do not reconcile synchronously while
    -- holding CRM/order locks; the care worker acquires customer locks first.
    perform public.crm_enqueue_trial_care_v1(v_source.id,'purchase_customer_relink_source');
    perform public.crm_enqueue_trial_care_v1(v_target.id,'purchase_customer_relink');
    return v_crm;
  end if;

  if v_target.id=v_source.id then
    update public.aka_customer set phone=v_phone, org_staff_update_id=p_actor_org_staff_id
    where id=v_source.id;
    if not found then raise exception using errcode='P0002', message='crm_phone.customer_not_updated'; end if;
  end if;
  -- Relink only this CRM; preserve customer identities and sibling CRM rows.
  -- Existing lifecycle triggers continue maintaining derived customer state.
  if v_target.id is distinct from v_source.id then
    update public.aka_crm set customer_id=v_target.id, customer_phone=v_phone,
      org_staff_updated_id=p_actor_org_staff_id where id=p_crm_id returning * into v_crm;
  else
    -- Do not fire UPDATE OF customer_id triggers for a phone-only correction.
    update public.aka_crm set customer_phone=v_phone, org_staff_updated_id=p_actor_org_staff_id
    where id=p_crm_id returning * into v_crm;
  end if;
  if not found then raise exception using errcode='P0002', message='crm_phone.crm_not_updated'; end if;
  return v_crm;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_control_campaign_atomic(p_staff_id bigint, p_organization_id bigint, p_campaign_id bigint, p_expected_updated_at timestamp with time zone, p_campaign_patch jsonb, p_sms_inputs jsonb DEFAULT NULL::jsonb, p_update_sms_schedule boolean DEFAULT false, p_append_idempotency_key text DEFAULT NULL::text, p_expected_input_count integer DEFAULT NULL::integer, p_append_inputs jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_campaign public.auto_campaigns%ROWTYPE;
  v_account_platform text;
  v_target_action_id text;
  v_payload_input_count integer := 0;
  v_payload_unique_input_count integer := 0;
  v_eligible_input_count integer := 0;
  v_current_eligible_input_count integer := 0;
  v_updated_inputs integer := 0;
  v_append_key text := NULLIF(btrim(COALESCE(p_append_idempotency_key, '')), '');
  v_append_input_count integer := 0;
  v_existing_append_count integer := 0;
  v_current_input_count integer := 0;
  v_appended_inputs integer := 0;
BEGIN
  IF jsonb_typeof(COALESCE(p_campaign_patch, '{}'::jsonb)) <> 'object'
    OR (p_sms_inputs IS NOT NULL AND jsonb_typeof(p_sms_inputs) <> 'array')
    OR (p_append_inputs IS NOT NULL AND jsonb_typeof(p_append_inputs) <> 'array') THEN
    RAISE EXCEPTION 'invalid_control_campaign_update_payload';
  END IF;

  IF p_append_inputs IS NOT NULL THEN
    v_append_input_count := jsonb_array_length(p_append_inputs);
    IF v_append_input_count < 1 OR v_append_input_count > 5000
      OR v_append_key IS NULL OR length(v_append_key) > 200
      OR p_expected_input_count IS NULL OR p_expected_input_count < 0 THEN
      RAISE EXCEPTION 'invalid_control_campaign_append_payload';
    END IF;
  ELSIF v_append_key IS NOT NULL OR p_expected_input_count IS NOT NULL THEN
    RAISE EXCEPTION 'orphan_control_campaign_append_metadata';
  END IF;

  SELECT campaign.*
  INTO v_campaign
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account ON account.id = campaign.account_id
  WHERE campaign.id = p_campaign_id
    AND campaign.staff_id = p_staff_id
    AND campaign.organization_id = p_organization_id
    AND COALESCE(campaign.is_delete, false) = false
    AND account.staff_id = p_staff_id
    AND account.organization_id = p_organization_id
    AND (
      (
        COALESCE(account.is_delete, false) = false
        AND (
          account.flatform_type = 'sms'
          OR (
            account.flatform_type = 'zalo'
            AND COALESCE(account.is_zalo_show_web, false) = false
            AND COALESCE(account.is_zalo_server, false) = true
            AND COALESCE(account.is_active, true) = true
          )
        )
      )
      OR (
        COALESCE(account.is_delete, false) = true
        AND p_campaign_patch ? 'account_id'
        AND EXISTS (
          SELECT 1
          FROM public.auto_accounts AS target_account
          WHERE target_account.id = NULLIF(p_campaign_patch->>'account_id', '')::bigint
            AND target_account.staff_id = p_staff_id
            AND target_account.organization_id = p_organization_id
            AND target_account.flatform_type = account.flatform_type
            AND (
              target_account.flatform_type = 'sms'
              OR (
                target_account.flatform_type = 'zalo'
                AND COALESCE(target_account.is_zalo_show_web, false) = false
                AND COALESCE(target_account.is_zalo_server, false) = true
                AND COALESCE(target_account.is_active, true) = true
              )
            )
            AND COALESCE(target_account.is_delete, false) = false
        )
      )
    );

  IF NOT FOUND THEN
    RETURN jsonb_build_object('updated', false, 'reason', 'not_found');
  END IF;

  SELECT account.flatform_type
  INTO v_account_platform
  FROM public.auto_accounts AS account
  WHERE account.id = v_campaign.account_id;

  -- A network retry after the transaction committed still carries the stale
  -- version. The durable append key proves that this exact edit already won.
  IF p_append_inputs IS NOT NULL THEN
    SELECT count(*)::integer INTO v_existing_append_count
    FROM public.auto_campaign_input_data
    WHERE campaign_id = p_campaign_id
      AND control_append_idempotency_key = v_append_key;
    IF v_existing_append_count > 0 THEN
      IF v_existing_append_count <> v_append_input_count THEN
        RETURN jsonb_build_object('updated', false, 'reason', 'append_idempotency_conflict');
      END IF;
      RETURN jsonb_build_object(
        'updated', true,
        'campaign_id', p_campaign_id,
        'updated_input_count', 0,
        'appended_input_count', v_existing_append_count,
        'updated_at', v_campaign.updated_at,
        'idempotent', true
      );
    END IF;
  END IF;

  IF v_campaign.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RETURN jsonb_build_object('updated', false, 'reason', 'version_conflict');
  END IF;
  IF v_campaign.status = 'đang chạy' THEN
    RETURN jsonb_build_object('updated', false, 'reason', 'campaign_running');
  END IF;
  IF p_append_inputs IS NOT NULL AND v_campaign.status = 'hoàn thành' THEN
    RETURN jsonb_build_object('updated', false, 'reason', 'campaign_completed');
  END IF;
  IF p_sms_inputs IS NOT NULL AND v_account_platform <> 'sms' THEN
    RAISE EXCEPTION 'control_sms_materialization_platform_mismatch';
  END IF;

  PERFORM public.aka_agent_lock_campaign_input_serialization(p_campaign_id);

  IF p_sms_inputs IS NOT NULL OR p_append_inputs IS NOT NULL THEN
    -- SMS status recording locks an input row before it may complete the
    -- campaign. Lock every current row before taking the campaign lock so an
    -- update+append cannot commit below a concurrently completed campaign.
    PERFORM input_data.id
    FROM public.auto_campaign_input_data AS input_data
    WHERE input_data.campaign_id = p_campaign_id
      AND COALESCE(input_data.is_delete, false) = false
    ORDER BY input_data.id
    FOR UPDATE OF input_data;
  END IF;

  IF p_sms_inputs IS NOT NULL THEN
    SELECT count(*)::integer INTO v_eligible_input_count
    FROM public.auto_campaign_input_data AS input_data
    WHERE input_data.campaign_id = p_campaign_id
      AND COALESCE(input_data.is_delete, false) = false
      AND input_data.status IN ('chờ xử lý', 'tạm dừng');

    SELECT
      count(*)::integer,
      count(DISTINCT NULLIF(item->>'id', '')::bigint)::integer
    INTO v_payload_input_count, v_payload_unique_input_count
    FROM jsonb_array_elements(p_sms_inputs) AS item;

    IF v_payload_input_count <> v_payload_unique_input_count
      OR v_payload_unique_input_count <> v_eligible_input_count
      OR EXISTS (
        SELECT 1
        FROM jsonb_array_elements(p_sms_inputs) AS item
        WHERE NOT EXISTS (
          SELECT 1
          FROM public.auto_campaign_input_data AS input_data
          WHERE input_data.id = NULLIF(item->>'id', '')::bigint
            AND input_data.campaign_id = p_campaign_id
            AND COALESCE(input_data.is_delete, false) = false
            AND input_data.status IN ('chờ xử lý', 'tạm dừng')
        )
      ) THEN
      RETURN jsonb_build_object('updated', false, 'reason', 'sms_inputs_changed');
    END IF;
  END IF;

  -- Mobile status recording locks input rows before it may complete the campaign;
  -- take the campaign lock only after the SMS input locks to keep that order.
  SELECT campaign.*
  INTO v_campaign
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account ON account.id = campaign.account_id
  WHERE campaign.id = p_campaign_id
    AND campaign.staff_id = p_staff_id
    AND campaign.organization_id = p_organization_id
    AND COALESCE(campaign.is_delete, false) = false
    AND account.staff_id = p_staff_id
    AND account.organization_id = p_organization_id
    AND (
      (
        COALESCE(account.is_delete, false) = false
        AND (
          account.flatform_type = 'sms'
          OR (
            account.flatform_type = 'zalo'
            AND COALESCE(account.is_zalo_show_web, false) = false
            AND COALESCE(account.is_zalo_server, false) = true
            AND COALESCE(account.is_active, true) = true
          )
        )
      )
      OR (
        COALESCE(account.is_delete, false) = true
        AND p_campaign_patch ? 'account_id'
        AND EXISTS (
          SELECT 1
          FROM public.auto_accounts AS target_account
          WHERE target_account.id = NULLIF(p_campaign_patch->>'account_id', '')::bigint
            AND target_account.staff_id = p_staff_id
            AND target_account.organization_id = p_organization_id
            AND target_account.flatform_type = account.flatform_type
            AND (
              target_account.flatform_type = 'sms'
              OR (
                target_account.flatform_type = 'zalo'
                AND COALESCE(target_account.is_zalo_show_web, false) = false
                AND COALESCE(target_account.is_zalo_server, false) = true
                AND COALESCE(target_account.is_active, true) = true
              )
            )
            AND COALESCE(target_account.is_delete, false) = false
        )
      )
    )
  FOR UPDATE OF campaign, account;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('updated', false, 'reason', 'not_found');
  END IF;

  SELECT account.flatform_type
  INTO v_account_platform
  FROM public.auto_accounts AS account
  WHERE account.id = v_campaign.account_id;

  IF p_append_inputs IS NOT NULL THEN
    SELECT count(*)::integer INTO v_existing_append_count
    FROM public.auto_campaign_input_data
    WHERE campaign_id = p_campaign_id
      AND control_append_idempotency_key = v_append_key;
    IF v_existing_append_count > 0 THEN
      IF v_existing_append_count <> v_append_input_count THEN
        RETURN jsonb_build_object('updated', false, 'reason', 'append_idempotency_conflict');
      END IF;
      RETURN jsonb_build_object(
        'updated', true,
        'campaign_id', p_campaign_id,
        'updated_input_count', 0,
        'appended_input_count', v_existing_append_count,
        'updated_at', v_campaign.updated_at,
        'idempotent', true
      );
    END IF;
  END IF;

  IF v_campaign.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RETURN jsonb_build_object('updated', false, 'reason', 'version_conflict');
  END IF;
  IF v_campaign.status = 'đang chạy' THEN
    RETURN jsonb_build_object('updated', false, 'reason', 'campaign_running');
  END IF;
  IF p_append_inputs IS NOT NULL AND v_campaign.status = 'hoàn thành' THEN
    RETURN jsonb_build_object('updated', false, 'reason', 'campaign_completed');
  END IF;
  IF p_sms_inputs IS NOT NULL AND v_account_platform <> 'sms' THEN
    RAISE EXCEPTION 'control_sms_materialization_platform_mismatch';
  END IF;

  IF p_campaign_patch ? 'account_id' THEN
    PERFORM account.id
    FROM public.auto_accounts AS account
    WHERE account.id = NULLIF(p_campaign_patch->>'account_id', '')::bigint
      AND account.staff_id = p_staff_id
      AND account.organization_id = p_organization_id
      AND account.flatform_type = v_account_platform
      AND (
        account.flatform_type = 'sms'
        OR (
          account.flatform_type = 'zalo'
          AND COALESCE(account.is_zalo_show_web, false) = false
          AND COALESCE(account.is_zalo_server, false) = true
          AND COALESCE(account.is_active, true) = true
        )
      )
      AND COALESCE(account.is_delete, false) = false
    FOR UPDATE OF account;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'control_account_not_found';
    END IF;
  END IF;

  v_target_action_id := v_campaign.action_id;
  IF p_campaign_patch ? 'action_id' THEN
    v_target_action_id := NULLIF(btrim(COALESCE(p_campaign_patch->>'action_id', '')), '');
    IF v_target_action_id IS NULL THEN
      RAISE EXCEPTION 'control_action_not_allowed';
    END IF;

    PERFORM action.id
    FROM public.auto_campaign_actions AS action
    WHERE action.id = v_target_action_id
      AND action.flatform_type = v_account_platform
      AND COALESCE(action.is_active, true) = true
      AND COALESCE(action.is_delete, false) = false
    FOR SHARE OF action;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'control_action_not_allowed';
    END IF;
  END IF;

  IF p_sms_inputs IS NOT NULL THEN
    SELECT count(*)::integer INTO v_current_eligible_input_count
    FROM public.auto_campaign_input_data AS input_data
    WHERE input_data.campaign_id = p_campaign_id
      AND COALESCE(input_data.is_delete, false) = false
      AND input_data.status IN ('chờ xử lý', 'tạm dừng');
    IF v_current_eligible_input_count <> v_payload_unique_input_count THEN
      RETURN jsonb_build_object('updated', false, 'reason', 'sms_inputs_changed');
    END IF;
  END IF;

  IF p_append_inputs IS NOT NULL THEN
    SELECT count(*)::integer INTO v_current_input_count
    FROM public.auto_campaign_input_data AS input_data
    WHERE input_data.campaign_id = p_campaign_id
      AND COALESCE(input_data.is_delete, false) = false;
    IF v_current_input_count <> p_expected_input_count THEN
      RETURN jsonb_build_object('updated', false, 'reason', 'input_count_conflict');
    END IF;
  END IF;

  UPDATE public.auto_campaigns AS campaign
  SET
    name = CASE WHEN p_campaign_patch ? 'name' THEN p_campaign_patch->>'name' ELSE campaign.name END,
    action_id = v_target_action_id,
    account_id = CASE WHEN p_campaign_patch ? 'account_id' THEN NULLIF(p_campaign_patch->>'account_id', '')::bigint ELSE campaign.account_id END,
    schedule = CASE WHEN p_campaign_patch ? 'schedule' THEN NULLIF(p_campaign_patch->>'schedule', '')::timestamptz ELSE campaign.schedule END,
    original_schedule = CASE WHEN p_campaign_patch ? 'original_schedule' THEN NULLIF(p_campaign_patch->>'original_schedule', '')::timestamptz ELSE campaign.original_schedule END,
    content = CASE WHEN p_campaign_patch ? 'content' THEN COALESCE(p_campaign_patch->>'content', '') ELSE campaign.content END,
    schedule_type = CASE WHEN p_campaign_patch ? 'schedule_type' THEN p_campaign_patch->>'schedule_type' ELSE campaign.schedule_type END,
    schedule_end_date = CASE WHEN p_campaign_patch ? 'schedule_end_date' THEN NULLIF(p_campaign_patch->>'schedule_end_date', '')::timestamptz ELSE campaign.schedule_end_date END,
    daily_stop_time = CASE WHEN p_campaign_patch ? 'daily_stop_time' THEN NULLIF(p_campaign_patch->>'daily_stop_time', '')::time ELSE campaign.daily_stop_time END,
    schedule_days = CASE WHEN p_campaign_patch ? 'schedule_days' THEN NULLIF(p_campaign_patch->>'schedule_days', '') ELSE campaign.schedule_days END,
    schedule_week_days = CASE WHEN p_campaign_patch ? 'schedule_week_days' THEN NULLIF(p_campaign_patch->>'schedule_week_days', '') ELSE campaign.schedule_week_days END,
    continue_next_day = CASE WHEN p_campaign_patch ? 'continue_next_day' THEN (p_campaign_patch->>'continue_next_day')::boolean ELSE campaign.continue_next_day END,
    refresh_data = CASE WHEN p_campaign_patch ? 'refresh_data' THEN (p_campaign_patch->>'refresh_data')::boolean ELSE campaign.refresh_data END,
    extra_settings = CASE WHEN p_campaign_patch ? 'extra_settings' THEN p_campaign_patch->'extra_settings' ELSE campaign.extra_settings END,
    images = CASE WHEN p_campaign_patch ? 'images' THEN p_campaign_patch->'images' ELSE campaign.images END,
    status = CASE
      WHEN v_account_platform = 'zalo' THEN campaign.status
      WHEN p_campaign_patch ? 'status' THEN p_campaign_patch->>'status'
      ELSE campaign.status
    END,
    updated_at = now()
  WHERE campaign.id = p_campaign_id
    AND campaign.staff_id = p_staff_id
    AND campaign.organization_id = p_organization_id
    AND campaign.updated_at IS NOT DISTINCT FROM p_expected_updated_at
  RETURNING * INTO v_campaign;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('updated', false, 'reason', 'version_conflict');
  END IF;

  IF p_sms_inputs IS NOT NULL THEN
    WITH materialized AS (
      SELECT
        NULLIF(item->>'id', '')::bigint AS id,
        NULLIF(item->>'phone', '') AS phone,
        NULLIF(item->>'phoneCarrier', '') AS phone_carrier,
        NULLIF(item->>'content', '') AS content,
        NULLIF(item->>'schedule', '')::timestamptz AS schedule
      FROM jsonb_array_elements(p_sms_inputs) AS item
    )
    UPDATE public.auto_campaign_input_data AS input_data
    SET
      phone = materialized.phone,
      phone_carrier = materialized.phone_carrier,
      content = materialized.content,
      schedule = CASE WHEN p_update_sms_schedule THEN materialized.schedule ELSE input_data.schedule END
    FROM materialized
    WHERE input_data.id = materialized.id
      AND input_data.campaign_id = p_campaign_id
      AND COALESCE(input_data.is_delete, false) = false
      AND input_data.status IN ('chờ xử lý', 'tạm dừng');
    GET DIAGNOSTICS v_updated_inputs = ROW_COUNT;
    IF v_updated_inputs <> v_eligible_input_count THEN
      RAISE EXCEPTION 'control_sms_inputs_changed';
    END IF;
  END IF;

  IF p_append_inputs IS NOT NULL THEN
    INSERT INTO public.auto_campaign_input_data (
      campaign_id, input_id, name, phone, phone_carrier, uid, email,
      info1, info2, info3, info4, info5, content,
      status, note, schedule, is_delete, created_at,
      control_append_idempotency_key, control_append_row_index
    )
    SELECT
      p_campaign_id,
      NULL,
      NULLIF(item.value->>'name', ''),
      NULLIF(item.value->>'phone', ''),
      NULLIF(item.value->>'phoneCarrier', ''),
      NULLIF(item.value->>'uid', ''),
      NULLIF(item.value->>'email', ''),
      NULLIF(item.value->>'info1', ''),
      NULLIF(item.value->>'info2', ''),
      NULLIF(item.value->>'info3', ''),
      NULLIF(item.value->>'info4', ''),
      NULLIF(item.value->>'info5', ''),
      NULLIF(item.value->>'content', ''),
      'chờ xử lý',
      NULLIF(item.value->>'note', ''),
      NULLIF(item.value->>'schedule', '')::timestamptz,
      false,
      now(),
      v_append_key,
      (item.ordinality - 1)::integer
    FROM jsonb_array_elements(p_append_inputs) WITH ORDINALITY AS item(value, ordinality);
    GET DIAGNOSTICS v_appended_inputs = ROW_COUNT;
    IF v_appended_inputs <> v_append_input_count THEN
      RAISE EXCEPTION 'control_campaign_append_incomplete';
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'updated', true,
    'campaign_id', p_campaign_id,
    'updated_input_count', v_updated_inputs,
    'appended_input_count', v_appended_inputs,
    'updated_at', v_campaign.updated_at
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.update_control_campaign_by_config_version_atomic(p_staff_id bigint, p_organization_id bigint, p_campaign_id bigint, p_expected_updated_at timestamp with time zone, p_campaign_patch jsonb, p_sms_inputs jsonb DEFAULT NULL::jsonb, p_update_sms_schedule boolean DEFAULT false, p_append_idempotency_key text DEFAULT NULL::text, p_expected_input_count integer DEFAULT NULL::integer, p_append_inputs jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_campaign public.auto_campaigns%ROWTYPE;
  v_expected_config_version text := lower(
    NULLIF(btrim(COALESCE(p_campaign_patch->>'_expected_config_version', '')), '')
  );
  v_campaign_patch jsonb := COALESCE(p_campaign_patch, '{}'::jsonb)
    - '_expected_config_version';
  v_result jsonb;
  v_attempt integer;
BEGIN
  IF v_expected_config_version IS NULL
    OR v_expected_config_version !~ '^[0-9a-f]{32}$' THEN
    RAISE EXCEPTION 'invalid_campaign_config_version';
  END IF;

  -- Preserve the core RPC's durable append-idempotency fast path. A retry of
  -- an already committed append must succeed even though its config digest is
  -- necessarily stale after the first transaction.
  IF p_append_inputs IS NOT NULL THEN
    v_result := public.update_control_campaign_atomic(
      p_staff_id,
      p_organization_id,
      p_campaign_id,
      p_expected_updated_at,
      v_campaign_patch,
      p_sms_inputs,
      p_update_sms_schedule,
      p_append_idempotency_key,
      p_expected_input_count,
      p_append_inputs
    );

    IF COALESCE((v_result->>'updated')::boolean, false)
      OR v_result->>'reason' IS DISTINCT FROM 'version_conflict' THEN
      RETURN v_result;
    END IF;
  END IF;

  -- Runtime log/note/status writes also advance auto_campaigns.updated_at.
  -- Retry those timestamp-only races while the editable config digest stays
  -- equal to the version that the user loaded.
  FOR v_attempt IN 1..5 LOOP
    SELECT campaign.*
    INTO v_campaign
    FROM public.auto_campaigns AS campaign
    WHERE campaign.id = p_campaign_id
      AND campaign.staff_id = p_staff_id
      AND campaign.organization_id = p_organization_id
      AND COALESCE(campaign.is_delete, false) = false;

    IF NOT FOUND THEN
      RETURN jsonb_build_object('updated', false, 'reason', 'not_found');
    END IF;

    IF public.aka_agent_campaign_config_version(v_campaign)
      IS DISTINCT FROM v_expected_config_version THEN
      RETURN jsonb_build_object('updated', false, 'reason', 'version_conflict');
    END IF;

    v_result := public.update_control_campaign_atomic(
      p_staff_id,
      p_organization_id,
      p_campaign_id,
      v_campaign.updated_at,
      v_campaign_patch,
      p_sms_inputs,
      p_update_sms_schedule,
      p_append_idempotency_key,
      p_expected_input_count,
      p_append_inputs
    );

    IF COALESCE((v_result->>'updated')::boolean, false)
      OR v_result->>'reason' IS DISTINCT FROM 'version_conflict' THEN
      RETURN v_result;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('updated', false, 'reason', 'version_conflict');
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_current_data_type_category_item_id()
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_value text := NULLIF(
    current_setting('aka_agent.data_type_category_item_id', true),
    ''
  );
BEGIN
  IF v_value IS NULL THEN
    RETURN NULL;
  END IF;
  IF lower(v_value) = 'null' THEN
    RETURN NULL;
  END IF;
  IF v_value !~ '^[1-9][0-9]*$' THEN
    RAISE EXCEPTION 'invalid_data_type_category_context';
  END IF;
  RETURN v_value::bigint;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_internal_normalize_facebook_identity(p_value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'public'
AS $function$
DECLARE
  v_raw text := btrim(p_value);
  v_clean text;
  v_id text;
BEGIN
  IF v_raw = '' THEN RETURN ''; END IF;
  -- Numeric IDs are already canonical.
  IF v_raw ~ '^[0-9]+$' THEN RETURN v_raw; END IF;
  -- profile.php?id=... must be extracted before query removal.
  v_id := substring(lower(v_raw) FROM '[?&]id=([0-9]+)');
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;
  v_clean := regexp_replace(v_raw, '^(https?://)?((www|m|mbasic)\.)?facebook\.com/', '', 'i');
  v_clean := regexp_replace(v_clean, '[?#].*$', '');
  v_clean := regexp_replace(v_clean, '/+$', '');
  v_clean := regexp_replace(v_clean, '^(groups|people|pages)/', '', 'i');
  IF v_clean ~ '/' THEN
    -- /people/name/123 and /pages/name/123 use the final numeric component.
    v_id := substring(v_clean FROM '([0-9]+)$');
    IF v_id IS NOT NULL THEN RETURN v_id; END IF;
    v_clean := split_part(v_clean, '/', 1);
  END IF;
  RETURN lower(v_clean);
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_lock_campaign_input_serialization(p_campaign_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF p_campaign_id IS NULL OR p_campaign_id <= 0 THEN
    RAISE EXCEPTION 'campaign_input_serialization_id_invalid';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'aka-agent-campaign-input-serialization:' || p_campaign_id::text, 0
  ));
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_sheet_identity(p_type text, p_row jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v text; v_id text; v_path text;
BEGIN
  IF p_type='phone' THEN
    -- Same precedence as ingest/campaign extraction: primary field, legacy
    -- extra_data, then UID only for a contact whose identity is a phone/email.
    v:=public.aka_agent_internal_normalize_phone(COALESCE(
      NULLIF(p_row->>'phone',''),NULLIF(p_row->'extra_data'->>'phone',''),
      CASE WHEN p_row->>'contact_type'='phone' THEN p_row->>'uid' END,''));
    RETURN CASE WHEN v ~ '^0[35789][0-9]{8}$' THEN v ELSE NULL END;
  ELSIF p_type='email' THEN
    v:=lower(btrim(COALESCE(NULLIF(p_row->>'email',''),NULLIF(p_row->'extra_data'->>'email',''),
      CASE WHEN p_row->>'contact_type'='email' THEN p_row->>'uid' END,'')));
    RETURN CASE WHEN length(v)<=254 AND v ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN v ELSE NULL END;
  ELSIF p_type='facebook_search_keyword' THEN
    RETURN NULLIF(lower(regexp_replace(btrim(COALESCE(p_row->>'uid','')),'[[:space:]]+',' ','g')),'');
  ELSIF p_type='zalo_person' THEN
    v:=btrim(COALESCE(p_row->>'uid','')); RETURN CASE WHEN v ~ '^[0-9]+$' AND length(v)<=100 THEN v ELSE NULL END;
  ELSIF p_type='zalo_group' THEN
    v:=COALESCE(NULLIF(p_row->>'url',''),p_row->>'uid','');
    v_id:=substring(v from '^(?:https?://)?(?:www\.)?(?:zalo\.me/g/|zaloapp\.com/qr/g/)([A-Za-z0-9_-]+)(?:[/?#].*)?$');
    RETURN CASE WHEN v_id IS NOT NULL THEN 'zalo.me/g/'||v_id ELSE NULL END;
  ELSIF p_type IN ('facebook_person','facebook_group','facebook_page','facebook_post_url') THEN
    -- Existing post contacts may carry a numeric UID as well as the post URL.
    -- Sheet rows map the URL, so both sides must choose that same identity.
    IF p_type='facebook_post_url' THEN
      v:=COALESCE(NULLIF(btrim(p_row->>'url'),''),btrim(p_row->>'uid'),'');
    ELSE
      v:=btrim(COALESCE(NULLIF(p_row->>'uid',''),p_row->>'url',''));
    END IF;
    IF v ~ '^[0-9]+$' AND p_type<>'facebook_post_url' THEN RETURN v; END IF;
    IF v !~* '^(https?://)?(www\.|m\.|mbasic\.)?(facebook\.com|fb\.com)/[^[:space:]]+$' THEN RETURN NULL; END IF;
    v:=regexp_replace(v,'^(https?://)?(www\.|m\.|mbasic\.)?(facebook\.com|fb\.com)/','','i');
    v:=split_part(v,'#',1); v_path:=regexp_replace(split_part(v,'?',1),'/$','');
    IF p_type='facebook_group' THEN
      v_id:=substring(v_path from '^groups/([^/]+)'); RETURN lower(v_id);
    ELSIF p_type='facebook_post_url' THEN
      -- Support raw legacy contact URLs as well as the mapper's canonical URL.
      IF v_path ~ '^groups/[^/]+' AND v ~ '[?&]multi_permalinks=' THEN
        v_id:=substring(v from '[?&]multi_permalinks=([A-Za-z0-9_-]+)(?:&|$)');
        RETURN CASE WHEN v_id IS NOT NULL THEN 'post:'||v_id ELSE NULL END;
      END IF;
      IF v_path IN ('watch','watch/live','video.php') THEN
        v_id:=substring(v from '[?&]v=([A-Za-z0-9_-]+)(?:&|$)');
        RETURN CASE WHEN v_id IS NOT NULL THEN 'post:'||v_id ELSE NULL END;
      END IF;
      -- A group landing page has no post identity (including links already
      -- stripped by an older client); never import it as a valid post.
      IF v_path ~ '^groups/[^/]+$' THEN RETURN NULL; END IF;
      -- Opaque pfbid values are case-sensitive; never truncate to a numeric
      -- prefix or collapse every story.php/permalink.php URL to one key.
      v_id:=substring(v from '[?&](?:story_fbid|fbid)=([A-Za-z0-9_-]+)(?:&|$)');
      IF v_id IS NOT NULL THEN RETURN 'post:'||v_id; END IF;
      v_id:=substring(v_path from '(?:^|/)(?:posts|permalink|videos|reel)/([A-Za-z0-9_-]+)(?:/|$)');
      IF v_id IS NOT NULL THEN RETURN 'post:'||v_id; END IF;
      RETURN lower(v_path);
    ELSE
      -- Reuse the campaign canonicalizer for /people/name/UID and /pages/name/UID.
      -- The host was validated and stripped above, including the fb.com alias.
      RETURN NULLIF(public.aka_agent_internal_normalize_facebook_identity('https://www.facebook.com/'||v),'');
    END IF;
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.normalize_phone(p text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog'
AS $function$
declare
  d text;
begin
  if p is null then
    return null;
  end if;
  d := regexp_replace(p, '[^0-9]', '', 'g');
  if d = '' then
    return '';
  end if;
  if d like '0084%' and length(d) >= 13 then
    d := '0' || substr(d, 5);
  elsif d like '84%' and length(d) >= 11 then
    d := '0' || substr(d, 3);
  end if;
  if length(d) = 9 and left(d, 1) in ('3','5','7','8','9') then
    d := '0' || d;
  end if;
  if length(d) = 11 and left(d, 1) = '0' then
    d := case left(d, 4)
      when '0162' then '032' when '0163' then '033' when '0164' then '034' when '0165' then '035'
      when '0166' then '036' when '0167' then '037' when '0168' then '038' when '0169' then '039'
      when '0120' then '070' when '0121' then '079' when '0122' then '077' when '0126' then '076'
      when '0128' then '078' when '0123' then '083' when '0124' then '084' when '0125' then '085'
      when '0127' then '081' when '0129' then '082' when '0186' then '056' when '0188' then '058'
      when '0199' then '059'
      else left(d, 4)
    end || substr(d, 5);
  end if;
  return d;
end;
$function$

CREATE OR REPLACE FUNCTION public.normalize_legacy_zalo_account_server_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_organization_id bigint;
  v_legacy_is_zalo_server boolean := false;
BEGIN
  -- Explicit true/false is a new-client subtype decision. Only omitted/NULL
  -- values use the legacy v218 organization-wide owner.
  IF NEW.is_zalo_server IS NOT NULL THEN
    RETURN NEW;
  END IF;

  IF lower(btrim(COALESCE(NEW.flatform_type, ''))) <> 'zalo'
    OR COALESCE(NEW.is_zalo_show_web, false)
  THEN
    NEW.is_zalo_server := false;
    RETURN NEW;
  END IF;

  v_organization_id := NEW.organization_id;
  IF v_organization_id IS NULL AND NEW.staff_id IS NOT NULL THEN
    SELECT staff.organization_id
    INTO v_organization_id
    FROM public.aka_agent_staff_runtime_profile AS staff
    WHERE staff.id = NEW.staff_id;
  END IF;

  IF v_organization_id IS NOT NULL THEN
    SELECT COALESCE(mode.is_zalo_server, false)
    INTO v_legacy_is_zalo_server
    FROM public.resolve_organization_zalo_runtime_mode(v_organization_id) AS mode;
  END IF;

  NEW.is_zalo_server := COALESCE(v_legacy_is_zalo_server, false);
  RETURN NEW;
END;
$function$
